-- ---------- rest-c.js ----------
INSERT INTO question (knowledge_id, type, title, options, answer, analysis, score) VALUES
(66,'single','设有定义 int a[5] = {10,20,30,40,50}; int *p = a + 2; 则表达式 *(p + 1) - *(p - 1) 的值是？',
 '[{"key":"A","text":"10"},{"key":"B","text":"20"},{"key":"C","text":"30"},{"key":"D","text":"-20"}]',
 'B','p 指向 a[2]（值为 30），*(p+1) 是 a[3]=40，*(p-1) 是 a[1]=20，相减得 20。指针算术的单位是指向类型的大小，p+1 前进 4 字节而非 1 字节，不能按字节数臆算。',5),
(66,'single','若有 double a[3]; double *p = a; 且 p 当前存放的地址值为 0x1000，执行 p++ 后 p 的地址值是（设 double 占 8 字节）？',
 '[{"key":"A","text":"0x1001"},{"key":"B","text":"0x1004"},{"key":"C","text":"0x1008"},{"key":"D","text":"由编译器随机决定"}]',
 'C','指针加 1 前进的是"一个所指对象"的字节数，即 sizeof(double)=8，故为 0x1008。若 p 是 char* 才是 0x1001、int* 才是 0x1004，这是指针算术最容易记错的一点。',5),
(66,'single','在 64 位环境下有全局定义 int a[10]; 则 sizeof(a) 与 sizeof(a[0]) 的值分别是？',
 '[{"key":"A","text":"8 和 4"},{"key":"B","text":"40 和 4"},{"key":"C","text":"4 和 4"},{"key":"D","text":"40 和 8"}]',
 'B','sizeof(a) 求整个数组的字节数 10×4=40，sizeof(a[0]) 是一个 int 即 4。数组名只有在作为函数形参、或参与指针运算时才会退化成指针，sizeof 作用于数组名时仍是数组。',5),
(66,'single','下列代码片段中，最可能导致程序运行时崩溃的是？',
 '[{"key":"A","text":"int *p = NULL; if (p) *p = 1;"},{"key":"B","text":"int x = 1; int *p = &x; *p = 2;"},{"key":"C","text":"int *p; *p = 5;"},{"key":"D","text":"int a[3] = {0}; int *p = a; *p = 5;"}]',
 'C','局部指针 p 未初始化，其值是栈上的随机垃圾，*p = 5 会向未知地址写入，属于野指针写操作，极易段错误。A 有判空保护，B 和 D 的指针都指向合法对象。',5),
(66,'single','声明 const int *p 的正确理解是？',
 '[{"key":"A","text":"p 本身不可修改，不能指向别的地址"},{"key":"B","text":"不能通过 p 修改它所指向的对象"},{"key":"C","text":"p 和它指向的对象都不可修改"},{"key":"D","text":"p 必须在定义的同时初始化"}]',
 'B','const int *p 是指向常量的指针：p 的值可以改，但 *p 不能作左值。int * const p 才是指针本身不可变，const int * const p 则两者都不可变。记忆法：const 在 * 左边修饰数据，在 * 右边修饰指针。',5),
(66,'single','int a[10]; int *p = &a[2]; int *q = &a[7]; 则表达式 q - p 的值是？',
 '[{"key":"A","text":"5"},{"key":"B","text":"20"},{"key":"C","text":"4"},{"key":"D","text":"非法，编译报错"}]',
 'A','两指针相减的结果是二者之间相隔的元素个数（ptrdiff_t 类型），7-2=5，而不是字节差 20。只有指向同一个数组（或尾后一个位置）的指针相减才有定义，跨数组相减是未定义行为。',5),
(66,'judge','void 型指针可以不经转换直接进行加减算术运算和解引用。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。void * 没有具体类型，编译器不知道步长也无法确定解引用结果的类型，标准 C 不允许；GNU 扩展把 sizeof(void) 当作 1，但不可移植。必须先强制转换成具体类型指针再运算。',5),
(66,'judge','数组名 a 与 &a 的值相同，因此二者的类型也相同，可以互换使用。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。地址值相同但类型不同：a 退化为指向首元素的 int*，&a 是指向整个数组的 int (*)[10]。做算术时 a+1 前进 4 字节，&a+1 前进 40 字节，二者绝不能混用。',5),
(66,'single','下列 swap 函数中，能真正交换调用者两个 int 变量值的是？',
 '[{"key":"A","text":"void swap(int a, int b){ int t = a; a = b; b = t; }"},{"key":"B","text":"void swap(int *a, int *b){ int t = *a; *a = *b; *b = t; }"},{"key":"C","text":"void swap(int *a, int *b){ int *t = a; a = b; b = t; }"},{"key":"D","text":"void swap(int *a, int *b){ int *t; *t = *a; *a = *b; *b = *t; }"}]',
 'B','只有 B 通过解引用改写调用者的内存。C 交换的只是形参指针的副本，调用者不受影响；D 中的 t 未初始化就 *t 赋值，是野指针写；A 是纯值传递，出了函数就失效。',5),
(66,'single','在 64 位环境下定义 char *s[] = {"apple", "banana", "cherry"}; 则 sizeof(s) 与 s + 1 前进的字节数分别是？',
 '[{"key":"A","text":"24 和 8"},{"key":"B","text":"24 和 24"},{"key":"C","text":"20 和 1"},{"key":"D","text":"8 和 8"}]',
 'A','s 是指针数组（3 个 char* 元素，每个 8 字节），sizeof 为 24；s+1 跨越一个 char* 元素即 8 字节，而不是跳过整个字符串。字符串本身存放在只读数据段，不计入 sizeof(s)。',5),
(66,'single','定义 int a[3][4]; 则表达式 *(a + 1) + 3 的含义是？',
 '[{"key":"A","text":"a[1][3] 的值"},{"key":"B","text":"&a[1][3]"},{"key":"C","text":"&a[1][3] 之后再偏移一个数组"},{"key":"D","text":"非法表达式"}]',
 'B','a 退化为 int (*)[4]，a+1 指向第 1 行，*(a+1) 即 a[1]，类型为 int* 指向 a[1][0]，+3 得到 &a[1][3]。它仍是地址，要取值需写成 *(*(a+1)+3)，漏掉一层解引用是常见错误。',5),
(66,'single','若有 int *p; 下列写法中一定符合标准 C 语法的是？',
 '[{"key":"A","text":"p = 1000;"},{"key":"B","text":"p = (int *)1000;"},{"key":"C","text":"p = 1000.0;"},{"key":"D","text":"p = p / 2;"}]',
 'B','整数不能隐式赋给指针，但显式强制转换 (int *)1000 语法上合法（地址是否有意义另说，属于实现相关）。指针不能做乘除运算，也不能用浮点值赋值。',5),
(66,'multi','下列关于 C 指针的说法中，正确的有？（多选）',
 '[{"key":"A","text":"指向同一数组元素的两个指针可以比较大小"},{"key":"B","text":"指针作函数参数可实现被调函数改写调用者变量的效果"},{"key":"C","text":"对 NULL 指针解引用属于未定义行为"},{"key":"D","text":"指针变量占用的字节数一定等于它指向类型的大小"}]',
 'ABC','A 正确，关系比较仅对同一数组内的指针有定义；B 正确，传地址是 C 实现双向数据传递的唯一手段；C 正确，NULL 解引用通常直接段错误；D 错，指针大小由实现和寻址宽度决定（64 位多为 8 字节），与所指类型无关。',8),
(66,'multi','下列哪些操作会产生未定义行为？（多选）',
 '[{"key":"A","text":"读写数组 a[10]（a 定义为 int a[10]）"},{"key":"B","text":"两个指向不同数组的指针相减"},{"key":"C","text":"把指针与 NULL 做相等性比较"},{"key":"D","text":"对已 free 的内存再次读写"}]',
 'ABD','A 越界读写越过对象边界即 UB；B 只有同一数组内（含尾后）相减才有定义；D 是典型的 use-after-free。C 完全合法，判空正是最常规的指针用法。',8),
(66,'judge','把 float 变量 x 的地址强制转换成 int * 后读写，属于类型双关，在严格别名规则下是未定义行为。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。严格别名规则要求只能通过对象的有效类型（或兼容类型、字符类型）访问该对象，用 int* 读写 float 违反该规则，在 -O2 下可能被重排优化而产生诡异结果。安全做法是用 memcpy 或联合体。',5),
(66,'judge','用 char *p 指向一个字符串字面量后，可以通过 p 修改其中的字符。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。字符串字面量存放在只读数据段，修改它属于未定义行为，多数平台会段错误。应写成 const char *p 让编译器帮忙检查；确实需要修改内容时用字符数组 char p[] = "hello" 在栈上拷贝一份。',5),
(67,'single','函数 char *f(void){ char buf[16] = "ok"; return buf; } 存在的问题是？',
 '[{"key":"A","text":"语法错误，编译不通过"},{"key":"B","text":"返回了栈上局部数组的地址，函数返回后该地址失效，形成悬垂指针"},{"key":"C","text":"返回值类型应改为 char"},{"key":"D","text":"没有任何问题，buf 内容可继续使用"}]',
 'B','buf 是自动存储期的局部数组，位于栈帧内，函数返回后栈帧被回收，返回的地址成为悬垂指针，内容随时会被下一次函数调用覆盖。可改为返回 static 数组、malloc 缓冲区或由调用者传入缓冲区。',5),
(67,'single','定义 void g(int *q){ q = NULL; } 调用 int *p = &x; g(p); 之后，p 的情况是？',
 '[{"key":"A","text":"p 变成 NULL"},{"key":"B","text":"p 保持不变，仍指向 x"},{"key":"C","text":"p 变成野指针"},{"key":"D","text":"编译报错"}]',
 'B','q 是 p 的一份拷贝，把 q 改成 NULL 只影响副本，调用者的 p 不受影响；只有 *q = ... 才会改写被指对象。若想让被调函数改掉调用者的指针本身，需要传二级指针 int **。',5),
(67,'single','缺少正确终止条件的递归函数最可能导致的后果是？',
 '[{"key":"A","text":"编译错误"},{"key":"B","text":"栈溢出，程序崩溃"},{"key":"C","text":"堆内存耗尽"},{"key":"D","text":"死锁"}]',
 'B','每次递归调用都要压入新的栈帧，无限递归会迅速耗尽线程栈空间（Linux 默认约 8MB、Windows 约 1MB），触发栈溢出。堆耗尽是内存泄漏或无限分配的后果，与递归无必然联系。',5),
(67,'single','对于函数调用 f(i++, i++)，标准 C 的规定是？',
 '[{"key":"A","text":"从左到右求值，结果确定"},{"key":"B","text":"从右到左求值，结果确定"},{"key":"C","text":"实参求值顺序未指定，且同一对象被两次无序列修改属于未定义行为"},{"key":"D","text":"编译器保证先算左边的实参"}]',
 'C','C 标准未规定实参的求值顺序，只保证进入函数体前有一个序列点；i++ 两次修改同一对象且无序列点分隔，构成未定义行为，不同编译器可能给出不同结果。应拆成两条独立语句。',5),
(67,'judge','C 语言只有值传递，因此在被调函数中修改形参不会影响调用者的实参变量。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。形参永远是实参值的一份副本。想让被调函数改变调用者变量，必须传该变量的地址并在函数内解引用改写，这只是"模拟"按引用传递，本质仍是值传递（传的是地址值）。',5),
(67,'judge','递归函数被多次调用时，各层调用共享同一份局部变量。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。每次调用都会建立独立的栈帧，包含各自的形参、局部变量和返回地址，各层同名变量互不干扰；返回时按后进先出销毁，这正是递归能正确回退的原因。',5),
(67,'single','函数内有 static int count = 0; count++; 多次调用该函数时 count 的行为是？',
 '[{"key":"A","text":"每次调用都从 0 开始计数"},{"key":"B","text":"只在程序启动时初始化一次为 0，之后保持上次调用结束时的值"},{"key":"C","text":"值不确定"},{"key":"D","text":"每次调用重新初始化为随机值"}]',
 'B','static 局部变量具有静态存储期，存放在数据段而非栈帧，初始化只在程序加载时执行一次，函数返回后不销毁，因此能跨调用累积计数；但它不是线程安全的，多线程下需加锁或用原子类型。',5),
(67,'single','关于栈帧中保存的返回地址，下列说法正确的是？',
 '[{"key":"A","text":"记录被调函数结束后应回到调用者的哪条指令"},{"key":"B","text":"记录函数返回值的存放地址"},{"key":"C","text":"由调用者在编译期写进代码段"},{"key":"D","text":"递归的各层共享同一个返回地址"}]',
 'A','调用指令会把下一条指令的地址压入栈帧，被调函数返回时据此跳回，属于控制流信息，与返回值无关。递归每层都有自己的返回地址，所以能逐层正确返回。',5),
(67,'single','函数形参写成 void f(int a[10])，在函数体内 sizeof(a) 的结果是？',
 '[{"key":"A","text":"40"},{"key":"B","text":"指针的大小（64 位下为 8）"},{"key":"C","text":"编译错误"},{"key":"D","text":"0"}]',
 'B','数组形参会退化为指针，void f(int a[10]) 完全等价于 void f(int *a)，方括号中的 10 只是给程序员看的注释。因此必须额外传一个长度参数，在函数内无法用 sizeof 推出数组长度。',5),
(67,'single','有 void f(int n){ if (n > 0) { printf("%d", n); f(n - 1); printf("%d", n); } }，调用 f(2) 的输出是？',
 '[{"key":"A","text":"2121"},{"key":"B","text":"2112"},{"key":"C","text":"1221"},{"key":"D","text":"2211"}]',
 'B','结构是先打印、再深入、返回后再打印：f(2) 输出 2 后进入 f(1)，f(1) 输出 1，f(0) 条件不成立无输出，回到 f(1) 再输出 1，最后回到 f(2) 输出 2，拼起来是 2112。printf 没有分隔符，数字紧挨着输出。',5),
(67,'single','关于函数返回结构体与返回局部结构体指针，正确的是？',
 '[{"key":"A","text":"返回结构体是安全的，调用者得到一份值拷贝"},{"key":"B","text":"返回结构体同样危险，因为结构体建在栈上"},{"key":"C","text":"返回局部结构体指针是安全的"},{"key":"D","text":"两者都安全，因为结构体较大时会自动在堆上分配"}]',
 'A','返回结构体时，函数返回的是值的副本（ABI 上常通过调用者传入的隐藏指针写入），调用者拿到独立拷贝；返回局部结构体指针则指向已销毁的栈帧，是悬垂指针。C 不会自动把任何东西放到堆上。',5),
(67,'judge','在函数内定义很大的局部数组（如 char buf[10*1024*1024]）容易导致栈溢出，应改为静态或堆分配。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。大数组直接撑大栈帧，超过线程栈上限就会崩溃，而且这种崩溃往往在进入函数瞬间发生、难以定位。改用 static、全局或 malloc 放到数据段/堆即可避免，这也是嵌入式开发的常见注意点。',5),
(67,'judge','函数调用时实参个数或类型与形参不匹配，C 编译器一定会报错。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。若调用前没有可见原型，旧式规则允许隐式声明并做默认实参提升，编译器可能只给警告；即便有原型，部分类型不兼容也可能只是警告。这正是必须先声明函数原型、并开启 -Wall 的原因。',5),
(67,'multi','下列哪些返回方式会使调用者拿到的指针失效或出错？（多选）',
 '[{"key":"A","text":"返回局部数组的首地址"},{"key":"B","text":"返回局部变量 i 的地址 &i"},{"key":"C","text":"返回字符串字面量的地址"},{"key":"D","text":"返回 static 局部数组的地址"}]',
 'AB','A 和 B 都指向栈帧中的自动对象，函数返回后栈帧被回收，指针即悬垂。字符串字面量与 static 数组具有静态存储期，生存期与程序同长，返回它们的地址完全合法且常见。',8),
(67,'multi','关于递归与迭代，下列说法正确的有？（多选）',
 '[{"key":"A","text":"任何递归都可以改写成迭代，必要时借助显式栈"},{"key":"B","text":"尾递归可被优化为循环，从而不增加栈深度"},{"key":"C","text":"递归的时间复杂度一定高于等价的迭代写法"},{"key":"D","text":"递归层数越深，栈空间消耗越大"}]',
 'ABD','A 正确，用显式栈即可模拟调用栈；B 正确，现代编译器在开启优化时常做尾调用优化，但 C 标准并不保证；C 错，复杂度取决于算法本身，二分、归并等递归与迭代同阶；D 正确，每层栈帧都要占用栈空间。',8),
(67,'single','同一函数连续被调用两次，内部未初始化的局部 int 变量 v 打印出的值常常相同，原因是？',
 '[{"key":"A","text":"编译器把未初始化变量自动清零"},{"key":"B","text":"两次调用复用了同一块栈地址区间，读到上一次留下的残留值"},{"key":"C","text":"操作系统保证了结果确定"},{"key":"D","text":"v 存放在数据段"}]',
 'B','未初始化的自动变量读到的是栈上的垃圾；两次调用的栈帧布局相同、落在同一地址区间，所以常看到"相同的随机数"。这完全不可依赖，换编译器、加一个中间调用或开优化后就会变化。',5),
(68,'single','在 int 占 4 字节、按 4 字节对齐的常见平台上，struct S { char c; int i; }; 的 sizeof 是？',
 '[{"key":"A","text":"5"},{"key":"B","text":"8"},{"key":"C","text":"6"},{"key":"D","text":"由编译器随机决定"}]',
 'B','c 占 1 字节后需填充 3 字节，才能让 int 落在 4 的倍数地址上，i 再占 4 字节，共 8。结构体总大小还必须是其最大成员对齐值的整数倍，尾部也可能补填充。',5),
(68,'single','struct T { char a; double b; }; 在 double 按 8 字节对齐的平台上，b 相对结构体首地址的偏移量通常是？',
 '[{"key":"A","text":"1"},{"key":"B","text":"4"},{"key":"C","text":"8"},{"key":"D","text":"16"}]',
 'C','b 需要 8 字节对齐，a 之后必须填充 7 字节，故 offsetof(struct T, b) 为 8，sizeof(struct T) 为 16。可用 <stddef.h> 中的 offsetof 宏在代码中验证，不要靠心算。',5),
(68,'judge','结构体成员在内存中的排列顺序一定与声明顺序一致。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。C 标准保证成员按声明顺序分配地址递增的空间，允许在中间插入填充字节，但不允许编译器重排顺序。这也正是"把对齐要求大的成员往前放"能省空间的依据。',5),
(68,'judge','结构体的大小一定大于其所有成员大小之和，因为总要插入填充字节。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。是否需要填充取决于成员对齐需求：struct { int a; int b; }; 各成员自然对齐，无需任何填充，总大小正好 8。只有当后一成员的对齐要求与当前偏移不匹配时才插填充。',5),
(68,'single','为尽量减小结构体的内存占用，下列做法合理的是？',
 '[{"key":"A","text":"把成员按占用字节数从小到大排列"},{"key":"B","text":"把对齐要求大的成员尽量排在前面"},{"key":"C","text":"在成员之间手动插入 char 占位"},{"key":"D","text":"用 #pragma pack(1) 总是最优且没有代价"}]',
 'B','按对齐要求降序排列可把填充集中到尾部，通常最省空间；按字节数升序反而可能产生更多空洞。#pragma pack(1) 虽能压掉填充，但会造成非对齐访问，在部分架构上性能下降甚至触发硬件异常，且不可移植。',5),
(68,'single','struct P { int x; char s[20]; }; struct P a, b; 执行 b = a; 的结果是？',
 '[{"key":"A","text":"编译错误，结构体不能直接赋值"},{"key":"B","text":"按成员整体拷贝（含数组内容），a 与 b 相互独立"},{"key":"C","text":"只拷贝指针，两者共享同一份数据"},{"key":"D","text":"只拷贝第一个成员"}]',
 'B','C 允许结构体整体赋值，编译器生成逐成员拷贝，数组成员也会被完整复制，两者是彼此独立的对象。只有当结构体含指针成员时才会出现浅拷贝共享同一块内存的问题。',5),
(68,'single','若有 struct Node *p; 要访问其 next 成员，正确的写法是？',
 '[{"key":"A","text":"p.next"},{"key":"B","text":"p->next"},{"key":"C","text":"*p.next"},{"key":"D","text":"p::next"}]',
 'B','-> 是"先解引用再取成员"的语法糖，p->next 等价于 (*p).next。*p.next 因 . 的优先级高于 *，实际被解释为 *(p.next)，对指针用 . 会直接报错；:: 是 C++ 的作用域解析符，C 中没有。',5),
(68,'single','判断两个结构体变量的内容是否相等，正确做法是？',
 '[{"key":"A","text":"用 == 直接比较"},{"key":"B","text":"用 memcmp 逐字节比较"},{"key":"C","text":"逐个成员比较"},{"key":"D","text":"用 strcmp 比较"}]',
 'C','C 不支持对结构体整体使用 ==；memcmp 也不可靠，因为填充字节的内容未定义（可能是上次使用的垃圾），成员相等时 memcmp 也可能返回非 0。正确做法是逐成员比较，数组成员再用循环或 memcmp。',5),
(68,'single','关于结构体的位域（bit-field），下列说法正确的是？',
 '[{"key":"A","text":"可以对位域成员取地址"},{"key":"B","text":"位域成员只能是整型（如 int、unsigned int、_Bool），具体支持由实现决定"},{"key":"C","text":"位域一定按位紧邻排列，绝不浪费空间"},{"key":"D","text":"位域的跨字节布局由标准严格规定"}]',
 'B','位域成员必须是整型，且不能对其取地址（它可能不从字节边界开始）；是否跨存储单元、按何种字节序排布都由实现定义，因此绝不能用位域直接做跨平台的数据传输格式，应改为手工移位封包。',5),
(68,'single','struct H { int len; char data[]; }; 这种柔性数组成员的用法正确的是？',
 '[{"key":"A","text":"sizeof(struct H) 为 4，使用时 malloc(sizeof(struct H) + n) 一次性分配"},{"key":"B","text":"data 可直接当长度为 n 的数组使用，无需分配"},{"key":"C","text":"该写法在 C99 中非法"},{"key":"D","text":"data 自动指向一块静态缓冲区"}]',
 'A','C99 允许最后一個成员为不完整数组类型，sizeof 不计其大小（只有 len 的 4 字节）；使用时一次性分配头 + n 字节，使头与数据连续，比"指针成员 + 二次分配"少一次分配、少一次间接访问，缓存也更友好。',5),
(68,'single','union U { int i; char c[4]; }; 在 32 位平台上，sizeof(union U) 与成员关系是？',
 '[{"key":"A","text":"4，所有成员从同一地址开始重叠存放"},{"key":"B","text":"8，成员顺序存放"},{"key":"C","text":"5，取各成员大小之和"},{"key":"D","text":"1，由最小成员决定"}]',
 'A','联合体的所有成员共享起始地址，总大小至少等于最大成员并满足其对齐要求，故为 4。同一时刻只有一个成员有效，写入 i 后读 c[0] 属于实现相关行为，常被用来探测机器的字节序。',5),
(68,'single','struct A { char c; short s; }; 在 short 按 2 字节对齐的平台上，sizeof(struct A) 是？',
 '[{"key":"A","text":"3"},{"key":"B","text":"4"},{"key":"C","text":"6"},{"key":"D","text":"2"}]',
 'B','c 占 1 字节，填充 1 字节使 s 对齐到 2 的倍數，s 再占 2 字节，共 4；同时总大小须为最大对齐值 2 的倍数，4 满足。若再追加一个 char 成员则变为 6（尾部补 1 字节对齐）。',5),
(68,'judge','typedef struct { int x; } S; 之后，S 既是类型名也可以当作结构体标签写 struct S。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。匿名结构体的 typedef 只产生类型别名 S，不存在 struct S 这个标签，写 struct S 会报"不完整类型"。只有 typedef struct S { int x; } S; 这种写法才同时拥有标签和别名。',5),
(68,'judge','把结构体变量传给函数时，默认会把整个结构体拷贝一份给形参。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。结构体同样遵循值传递，形参获得完整副本，函数内修改不影响实参。结构体较大时应传 const 指针以避免拷贝开销，需要修改时传普通指针。',5),
(68,'multi','关于结构体内存布局与对齐，下列说法正确的有？（多选）',
 '[{"key":"A","text":"每个成员的偏移量必须满足自身类型的对齐要求"},{"key":"B","text":"结构体总大小是其最大成员对齐值的整数倍"},{"key":"C","text":"调整成员声明顺序可以改变结构体的总大小"},{"key":"D","text":"各平台对齐规则完全相同，可以放心硬编码 sizeof 的结果"}]',
 'ABC','A、B 是自然对齐的两条基本规则；C 正确，重排成员能改变填充量（如 char,double,char 为 24，改成 double,char,char 可降到 16）；D 错，类型宽度与对齐由 ABI 决定，跨平台传输必须序列化而不能直接 memcpy 结构体。',8),
(68,'multi','关于结构体与指针运算，下列说法正确的有？（多选）',
 '[{"key":"A","text":"p->m 与 (*p).m 完全等价"},{"key":"B","text":"对结构体指针 p 执行 p + 1，地址前进 sizeof(*p) 个字节"},{"key":"C","text":"结构体数组名 arr 在多数表达式中退化为指向 arr[0] 的指针"},{"key":"D","text":"成员地址 &s.m 一定等于 (char *)&s"}]',
 'ABC','A 是 -> 的定义；B 是指针算术按所指对象大小步进；C 是数组退化规则；D 错，成员地址等于基址加上 offsetof，只有第一个成员才可能等于 (char *)&s，对后续成员不成立。',8),
(69,'single','对局部数组 int a[4]; 执行 a[4] = 10; 的后果是？',
 '[{"key":"A","text":"编译器一定会报错"},{"key":"B","text":"未定义行为：可能覆盖相邻栈变量、破坏栈结构，也可能被优化掉"},{"key":"C","text":"数组自动扩容为 5 个元素"},{"key":"D","text":"等价于 a[3] = 10"}]',
 'B','C 不做下标检查，越界写就是未定义行为：轻则改坏相邻变量，重则覆盖保存的寄存器或返回地址，触发栈保护直接崩溃；开了优化后这段代码还可能被整段删掉。编译器至多给警告，绝不保证拦截。',5),
(69,'single','char s[] = "abc"; 则 strlen(s) 与 sizeof(s) 的值分别是？',
 '[{"key":"A","text":"3 和 3"},{"key":"B","text":"3 和 4"},{"key":"C","text":"4 和 4"},{"key":"D","text":"4 和 3"}]',
 'B','strlen 统计结尾空字符之前的字符数即 3，sizeof 求整个数组的字节数即 4（含结尾的空字符）。若写成 char *s = "abc"，sizeof(s) 就变成指针大小 8，这是最容易踩的坑。',5),
(69,'single','char d[8]; strcpy(d, "abcdefgh"); 存在的问题是？',
 '[{"key":"A","text":"完全安全，刚好放下"},{"key":"B","text":"需要 9 字节（含结尾空字符），超出 8 字节缓冲区造成越界写"},{"key":"C","text":"strcpy 会自动截断多余字符"},{"key":"D","text":"strcpy 会自动分配更大的空间"}]',
 'B','8 个字符的字符串需要 9 字节存放，越界的那 1 字节就可能踩坏相邻变量，是经典的 off-by-one。安全写法是 strncpy(d, s, sizeof(d) - 1); d[sizeof(d) - 1] = 0; 或直接用 snprintf。',5),
(69,'single','定义 int a[][3] = {1,2,3,4,5}; 则数组的行数与 a[1][2] 的值分别是？',
 '[{"key":"A","text":"2 行，0"},{"key":"B","text":"2 行，6"},{"key":"C","text":"1 行，0"},{"key":"D","text":"5 行，0"}]',
 'A','列数固定为 3，5 个初值填不满两行，编译器按向上取整确定为 2 行，未显式初始化的元素自动置 0，故 a[1][2] 为 0。只有第一维可以省略，第二维必须给出。',5),
(69,'single','已有 char a[10]; 下列操作合法的是？',
 '[{"key":"A","text":"a = \\"hello\\";"},{"key":"B","text":"strcpy(a, \\"hello\\");"},{"key":"C","text":"a++;"},{"key":"D","text":"a = b;（b 是另一个 char 数组）"}]',
 'B','数组名是常量地址，属于不可修改的左值，不能整体赋值也不能自增；要写入内容必须用 strcpy/memcpy 之类逐字节拷贝。若确实需要整体赋值语义，可把数组包进结构体里再赋值。',5),
(69,'single','执行 char s[5] = "hello"; 后，下列说法正确的是？',
 '[{"key":"A","text":"编译报错，数组太小"},{"key":"B","text":"s 中不含结尾空字符，用 %s 打印会越界读"},{"key":"C","text":"s 自动扩容到 6 字节"},{"key":"D","text":"strlen(s) 一定返回 5 且完全安全"}]',
 'B','用字面量初始化且数组长度恰好等于字符个数时，C 允许省略结尾空字符（C++ 则直接报错），此时 s 不是合法 C 字符串，printf 用 %s 会一直读到碰巧遇到 0 为止，属于越界读。',5),
(69,'judge','C 语言在编译期和运行期都会检查数组下标，越界访问必被拦截。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。C 不做任何下标检查，越界读写属于未定义行为；编译期最多给警告，运行期往往要等到踩到只读页或触发栈 canary 才被发现，而那时破坏已经造成。',5),
(69,'judge','strcmp(a, b) 返回 0 表示两个字符串的内容相同。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。strcmp 按字典序比较，前者小于、等于、大于后者时分别返回负数、0、正数。常见误区是用 == 比较两个字符串（那比较的是首地址），或把 if (strcmp(a,b)) 当成相等判断，实际含义正好相反。',5),
(69,'single','有 int a[3][4]; 则表达式 a[2] 的类型是？',
 '[{"key":"A","text":"int"},{"key":"B","text":"int *，指向 a[2][0]"},{"key":"C","text":"int (*)[4]"},{"key":"D","text":"int **"}]',
 'B','二维数组是"数组的数组"，a[2] 是第 2 行这个一维数组，在表达式中退化为 int* 指向 a[2][0]；而 a 本身退化为 int (*)[4]。int ** 与二维数组内存布局完全不同，不能当作形参互换。',5),
(69,'single','执行 char *p = "abcdef"; p += 2; printf("%c", *p); 输出的是？',
 '[{"key":"A","text":"a"},{"key":"B","text":"b"},{"key":"C","text":"c"},{"key":"D","text":"d"}]',
 'C','p 初值指向字符 a，p += 2 前进两个 char 指向 c，*p 就是字符 c。这里只是移动指针读取单个字符，并没有修改字符串字面量的内容，因此完全合法。',5),
(69,'single','在某些编译器下 for (int i = 0; i <= 10; i++) { a[i] = 0; }（a 为局部 int a[10]）会死循环，原因是？',
 '[{"key":"A","text":"循环条件写错，本应写成 i < 10"},{"key":"B","text":"越界写 a[10] 恰好落在变量 i 的位置，把 i 重新清零"},{"key":"C","text":"i 溢出变成负数"},{"key":"D","text":"编译器把循环优化掉了"}]',
 'B','栈向低地址增长时，局部数组 a 与 i 相邻，a[10] 可能正好覆盖 i 的存储，赋值 0 使 i 归零从而循环重新开始。根源仍是 i <= 10 造成的越界写，属于未定义行为，换编译器或开 -O2 就未必复现。',5),
(69,'judge','数组下标可以是负数，int a[10]; 中的 a[-1] 一定合法。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。a[-1] 等价于 *(a - 1)，指向首元素之前，属于越界访问。只有当指针指向数组中部时负偏移才合法，例如 p = &a[5]; p[-1] 就是合法的 a[4]。',5),
(69,'judge','char buf[10]; scanf("%s", buf); 是安全的写法，不会造成缓冲区溢出。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。%s 会一直读到空白符为止，输入长度完全不受 buf 容量限制，等同于 gets 的危险程度。应写成 scanf("%9s", buf) 指定最大宽度，或改用 fgets(buf, sizeof buf, stdin) 再去掉行尾换行。',5),
(69,'multi','下列哪些用法容易导致缓冲区溢出？（多选）',
 '[{"key":"A","text":"strcpy / strcat 写入固定大小的缓冲区"},{"key":"B","text":"gets(buf)"},{"key":"C","text":"sprintf(buf, ...) 不限长度"},{"key":"D","text":"snprintf(buf, sizeof buf, ...)"}]',
 'ABC','strcpy、strcat、gets、sprintf 都不检查目标容量，gets 甚至无法限制长度（已在 C11 中被移除）；应统一换成带长度限制的版本，snprintf 会按容量截断并保证结尾空字符，其返回值还能告诉你需要多少字节。',8),
(69,'multi','关于 C 字符串与字符数组，下列说法正确的有？（多选）',
 '[{"key":"A","text":"字符串以空字符作为结束标志"},{"key":"B","text":"strlen 的时间复杂度是 O(n)，在循环条件里反复调用会让程序变慢"},{"key":"C","text":"字符数组的内容可以修改，字符串字面量不可以"},{"key":"D","text":"char *s = \\"abc\\"; 与 char s[] = \\"abc\\"; 在任何方面都等价"}]',
 'ABC','A 是 C 字符串的定义；B 正确，strlen 每次都从头扫描，写在 for 条件里会退化成 O(n²)；C 正确，字面量位于只读段；D 错，前者是指针（sizeof 为 8，改内容 UB），后者是数组（sizeof 为 4，可修改）。',8),
(70,'single','关于 malloc 的返回值，正确的处理方式是？',
 '[{"key":"A","text":"直接使用，无需检查"},{"key":"B","text":"先判断是否 NULL 再使用，且不必强制转换返回值"},{"key":"C","text":"必须强制转换成目标类型，否则无法编译"},{"key":"D","text":"malloc 失败时会抛出异常"}]',
 'B','malloc 分配失败返回 NULL，使用前必须判空。C 中 void* 可隐式转换为任意对象指针，强行转换不仅多余，还会掩盖"忘了包含 stdlib.h 导致返回值被当成 int"的错误（C++ 中则必须强转）。',5),
(70,'single','执行 free(p); 之后，下列做法正确的是？',
 '[{"key":"A","text":"p 自动变成 NULL，可安全再次 free"},{"key":"B","text":"p 成为悬垂指针，应立即置 NULL，避免重复释放或误用"},{"key":"C","text":"可继续读写该内存直到程序结束"},{"key":"D","text":"free 会把内存内容清零"}]',
 'B','free 只是把块归还给分配器，既不修改 p 的值也不清零内容，p 随即变成悬垂指针；再次 free(p) 是 double free，读写则是 use-after-free。置 NULL 后 free(NULL) 是安全的空操作，这是推荐的防御写法。',5),
(70,'single','执行 p = malloc(0); 的标准行为是？',
 '[{"key":"A","text":"一定返回 NULL"},{"key":"B","text":"可能返回 NULL，也可能返回一个可传给 free 的非空指针，但绝不能解引用"},{"key":"C","text":"返回指向 1 字节内存的指针"},{"key":"D","text":"编译报错"}]',
 'B','C 标准把 malloc(0) 交由实现决定：glibc 通常返回一个最小块的非空地址，有些实现则返回 NULL。两种结果都必须视为合法，唯一确定的是不能向其中写入任何数据，返回值只能用于 free 或比较。',5),
(70,'single','要为 n 个 int 分配空间，正确的写法是？',
 '[{"key":"A","text":"malloc(n)"},{"key":"B","text":"malloc(n * sizeof(int))"},{"key":"C","text":"malloc(sizeof(int))"},{"key":"D","text":"malloc(n * 4) 在任何平台都正确"}]',
 'B','必须乘以元素大小，malloc(n) 只分配 n 个字节；写死 4 不可移植。更稳妥的写法是 p = malloc(n * sizeof *p)，它直接以指针所指类型为依据，将来把 int 改成 long 也不会漏改。',5),
(70,'single','calloc(n, size) 与 malloc(n * size) 的主要区别是？',
 '[{"key":"A","text":"calloc 分配得更快"},{"key":"B","text":"calloc 会把内存全部清零，并通常检查 n * size 是否溢出"},{"key":"C","text":"calloc 在栈上分配"},{"key":"D","text":"malloc 会把内存初始化为 0"}]',
 'B','calloc 保证内容为全 0 字节，且多数实现会检查 n*size 的整数溢出；malloc 返回的内容是未初始化的垃圾。注意全 0 字节只保证空字符和整数 0，并不保证指针等于 NULL 或浮点等于 0.0。',5),
(70,'judge','free 一块不是由 malloc/calloc/realloc 返回的指针（例如栈变量地址）属于未定义行为。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。free 的参数必须是此前分配函数返回的指针（或 NULL），传栈地址、字符串字面量地址或块内偏移都会破坏堆的元数据，通常立刻 abort，也可能埋下很久以后才爆发的隐患。',5),
(70,'judge','realloc(p, n) 一定在原地址上扩展内存，因此原来的所有指针仍然有效。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。若原位置后方空间不足，realloc 会另找一块、拷贝数据并释放旧块，返回新地址，此时指向旧块的所有指针（含 p 的其它副本）全部失效。必须写 tmp = realloc(p, n) 先判空再赋回 p，否则失败时会丢失原指针造成泄漏。',5),
(70,'single','下列代码片段中存在内存泄漏的是？',
 '[{"key":"A","text":"char *p = malloc(10); free(p);"},{"key":"B","text":"char *p = malloc(10); p = malloc(20); free(p);"},{"key":"C","text":"char *p = malloc(10); free(p); p = NULL;"},{"key":"D","text":"char *p = malloc(10); strcpy(p, \\"hi\\"); free(p);"}]',
 'B','B 中第一块内存的唯一地址被第二次 malloc 的返回值覆盖，永远无法再释放，是典型泄漏；A、C、D 都正常释放（C 释放后置空是好习惯，D 只写了 3 字节但在 10 字节内合法）。',5),
(70,'single','要把字符串 src 复制到新分配的空间，正确的分配长度是？',
 '[{"key":"A","text":"strlen(src)"},{"key":"B","text":"strlen(src) + 1"},{"key":"C","text":"sizeof(src)"},{"key":"D","text":"strlen(src) + 2"}]',
 'B','必须给结尾空字符多留 1 字节，否则 strcpy 会越界写 1 字节，这正是最经典的 off-by-one 堆溢出。注意 src 为指针时 sizeof(src) 等于 8，完全错误；用 strdup 可一步完成分配与拷贝。',5),
(70,'single','为 struct Node 分配空间，最推荐的写法是？',
 '[{"key":"A","text":"struct Node *p = (struct Node *)malloc(sizeof(struct Node));"},{"key":"B","text":"struct Node *p = malloc(sizeof *p);"},{"key":"C","text":"struct Node *p = malloc(sizeof(struct Node *));"},{"key":"D","text":"struct Node p = malloc(sizeof(struct Node));"}]',
 'B','sizeof *p 以指针所指类型为依据，以后改类型不会忘记同步大小，是最不易出错的写法；C 只分配了 8 字节（一个指针的大小）是经典 bug，后续写成员就是堆溢出；D 类型不匹配。C 语言无需对 malloc 结果强制转换。',5),
(70,'single','要一次性得到一块连续的、可用 a[i][j] 访问的 3 行 4 列 int 空间，正确的声明与分配是？',
 '[{"key":"A","text":"int (*a)[4] = malloc(3 * sizeof *a);"},{"key":"B","text":"int **a = malloc(3 * sizeof(int *)); 然后逐行 malloc"},{"key":"C","text":"int *a[4] = malloc(12 * sizeof(int));"},{"key":"D","text":"int a[3][4] = malloc(48);"}]',
 'A','a 是指向含 4 个 int 的数组的指针，3 * sizeof *a 即 48 字节连续空间，a[i][j] 的偏移由编译器算出。B 是指针数组方案，各行未必连续且要多 3 次分配与释放；C 类型不对；D 数组不能接收指针赋值。',5),
(70,'judge','malloc 得到的内存若不主动 free，也会在进程结束时被操作系统回收。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。堆内存的生存期由程序员控制，直到 free 或进程终止；进程退出时操作系统会回收它分配的全部资源。但这绝不等于可以不写 free——长期运行的服务程序中不释放会持续累积，最终耗尽内存。',5),
(70,'judge','free(p) 之后 p 指向的内容立刻被清零，因此再读取会得到 0。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。free 只把块归还给分配器并改写块头元数据，用户数据通常原样保留一段时间，所以 use-after-free 常常"看起来还能跑"，这正是它最危险的地方；标准上属于未定义行为，绝不能依赖。',5),
(70,'multi','下列哪些情况会造成堆内存泄漏或破坏？（多选）',
 '[{"key":"A","text":"分配之后所有执行路径上都没有 free"},{"key":"B","text":"对同一块内存 free 两次"},{"key":"C","text":"写入数据超出 malloc 申请的长度"},{"key":"D","text":"free 之后把指针置为 NULL"}]',
 'ABC','A 是泄漏；B 是 double free，会破坏空闲链表，常导致后续分配时崩溃；C 是堆溢出，踩坏相邻块的元数据，往往在很远之后才暴露；D 是推荐的防御做法，free(NULL) 是安全的空操作。',8),
(70,'multi','关于 malloc/free，下列说法正确的有？（多选）',
 '[{"key":"A","text":"malloc 分配的内存位于堆区，生存期由程序员控制"},{"key":"B","text":"malloc 返回的内存内容是未初始化的"},{"key":"C","text":"可以用 free 释放由 new 或 mmap 得到的内存"},{"key":"D","text":"分配与释放应成对出现在同一抽象层级，谁分配谁释放"}]',
 'ABD','A、B 是堆分配的基本常识；C 错，new/delete、malloc/free、mmap/munmap 必须严格配套，混用是未定义行为；D 是工程惯例，明确所有权能显著降低泄漏和重复释放的概率，C++ 中进一步用智能指针自动化。',8);

-- ---------- rest-cp.js ----------
INSERT INTO question (knowledge_id, type, title, options, answer, analysis, score) VALUES
(113,'single','词法分析器的输出通常是什么？',
 '[{"key":"A","text":"一棵语法树"},{"key":"B","text":"单词（token）序列，每个单词含种别码与属性值"},{"key":"C","text":"优化后的中间代码"},{"key":"D","text":"符号表"}]',
 'B','词法分析把字符流扫描成单词序列，如 (标识符, "sum")、(运算符, "+")；语法树由语法分析生成，符号表与中间代码是后续阶段产物。',5),
(113,'single','扫描到字符序列 ">=" 时，词法分析器一般把它识别为一个「大于等于」单词而不是两个单词，依据的是？',
 '[{"key":"A","text":"最长匹配原则（优先匹配能构成的最长单词）"},{"key":"B","text":"最短匹配原则"},{"key":"C","text":"随机决定"},{"key":"D","text":"关键字表优先原则"}]',
 'A','最长匹配要求一直向前读直到再读一个字符就不能构成合法单词为止，于是 ">" 与 "=" 被合成 ">="；该原则也解释了 "==" 与 "=" 的区分。',5),
(113,'single','区分用户标识符与保留关键字，通常采用的办法是？',
 '[{"key":"A","text":"预先把关键字填入保留字表，识别出的标识符先查表，命中则为关键字"},{"key":"B","text":"关键字一定比标识符短"},{"key":"C","text":"靠大小写区分"},{"key":"D","text":"语法分析阶段才能区分"}]',
 'A','设计时把关键字预先登记在符号表中，词法分析识别出一个标识符后先查表判断其种别；也有"超前搜索"的做法（如 FORTRAN 的 DO 需看后面是否有逗号）来消歧。',5),
(113,'single','把正则表达式转换为等价的 NFA，应采用哪种构造法？',
 '[{"key":"A","text":"Thompson 构造法"},{"key":"B","text":"子集构造法"},{"key":"C","text":"Hu-Tucker 算法"},{"key":"D","text":"CYK 算法"}]',
 'A','Thompson 构造法把正则式按结构递归拼成带 ε 边的 NFA；子集构造（子集法）用于把 NFA 确定化为 DFA，二者方向不同，不要混用。',5),
(113,'single','把 NFA 确定化为 DFA，通常采用的算法是？',
 '[{"key":"A","text":"子集构造法（子集法）"},{"key":"B","text":"Thompson 构造法"},{"key":"C","text":"Hopcroft 划分法"},{"key":"D","text":"LR 分析法"}]',
 'A','子集法用 ε-闭包与 move 计算，把 NFA 的状态集合当作 DFA 的一个状态；Hopcroft 算法用于 DFA 最小化。',5),
(113,'single','DFA 最小化的基本思想是？',
 '[{"key":"A","text":"先把状态划分为终态集与非终态集，再依据输入字符反复细分，直到不可再分，最后合并等价状态"},{"key":"B","text":"直接删除所有终态"},{"key":"C","text":"把状态数减半"},{"key":"D","text":"合并所有入度为 1 的状态"}]',
 'A','最小化依据状态等价：两个状态对任意输入串都同时到达接受或拒绝。先粗分成终态/非终态两个等价类，再迭代细分直到稳定，同类中状态可合并。',5),
(113,'single','关于 DFA 与 NFA 的区别，正确的是？',
 '[{"key":"A","text":"NFA 允许同一字符引出多条边并允许 ε 边，DFA 每个状态对同一字符至多一条边且无 ε 边"},{"key":"B","text":"DFA 能识别的语言严格多于 NFA"},{"key":"C","text":"NFA 不能识别任何正则语言"},{"key":"D","text":"DFA 一定有 ε 边"}]',
 'A','二者识别能力完全相同（都恰是正则语言），差别在表示形式：NFA 更紧凑但有不确定性，DFA 适合直接高速模拟，这正是先造 NFA 再确定化的原因。',5),
(113,'single','源程序中的空格、换行与注释，通常由词法分析器如何处理？',
 '[{"key":"A","text":"直接滤掉，不生成单词"},{"key":"B","text":"每个都生成一个单词"},{"key":"C","text":"交给语法分析器处理"},{"key":"D","text":"保留到目标代码中"}]',
 'A','它们只是分隔或说明性的信息，对语法结构无意义，词法分析器跳过即可；但换行号等信息要正确维护，以便报错时给出准确的行列位置。',5),
(113,'single','描述大多数语言中「标识符」的正规式是？',
 '[{"key":"A","text":"letter (letter | digit)*"},{"key":"B","text":"digit (letter | digit)*"},{"key":"C","text":"letter* digit*"},{"key":"D","text":"(letter | digit)+"}]',
 'A','标识符必须以字母（或下划线）开头，其后可跟任意个字母或数字；选项 D 会把纯数字串也当成合法标识符，选项 B 允许数字开头。',5),
(113,'single','下列错误中，属于词法分析阶段能够发现的是？',
 '[{"key":"A","text":"源程序中出现了非法字符，如 @"},{"key":"B","text":"括号不匹配"},{"key":"C","text":"标识符未声明"},{"key":"D","text":"函数调用实参类型不匹配"}]',
 'A','词法分析只按单词的构词规则检查，能发现非法字符、不闭合的字符串常量等；括号匹配属语法分析，未声明与类型不匹配属语义分析。',5),
(113,'judge','任何 NFA 都能转换为与之等价的 DFA，二者识别的语言类相同。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。子集构造给出了构造性证明：NFA 与 DFA、正则表达式三者在表达能力上完全等价，只是 DFA 的状态数可能指数级膨胀。',5),
(113,'judge','词法分析器可以发现括号不匹配这类错误。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。括号匹配涉及嵌套结构，属于上下文无关文法范畴，要由语法分析器检查；词法分析只看线性字符序列能否构成单词。',5),
(113,'judge','最小化后得到的 DFA，其状态数一定不多于原 DFA 的状态数。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。最小化只是合并等价状态，不会新增状态；若原 DFA 已是最小的，则状态数不变。',5),
(113,'judge','同一个正规集（单词集）只能用唯一的一个正规式来描述。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。正规式不唯一，例如 a* 与 (a*)*、a | aa* 都描述同一集合；这也是可以做正规式等价化简的前提。',5),
(113,'multi','词法分析器的主要任务包括？',
 '[{"key":"A","text":"扫描源程序字符流，识别出一个个单词"},{"key":"B","text":"滤掉空白符、换行与注释"},{"key":"C","text":"把识别出的单词写成种别码与属性值交给语法分析器"},{"key":"D","text":"生成中间代码"}]',
 'ABC','识别与输出单词（含填符号表的词法部分、报错与恢复）都是词法分析职责；生成中间代码是语义分析与中间代码生成阶段的工作。',8),
(113,'multi','关于单词（token）的表示，下列说法正确的有？',
 '[{"key":"A","text":"种别码用来区分单词的类别，如关键字、标识符、运算符"},{"key":"B","text":"属性值用于区分同类中不同的具体单词"},{"key":"C","text":"关键字可以一类一个种别码，也可以统一一个种别码加属性值区分"},{"key":"D","text":"单词必须包含源程序的行号才能被语法分析器使用"}]',
 'ABC','行号等位置信息一般单独记录用于报错，不是语法分析必需的；语法分析只关心种别码（如"标识符"）与必要时看属性值。',8),
(113,'multi','关于正规式与有穷自动机，下列说法正确的有？',
 '[{"key":"A","text":"正规式可经 Thompson 构造得到 NFA"},{"key":"B","text":"NFA 可经子集构造确定化为 DFA"},{"key":"C","text":"DFA 可经状态划分最小化"},{"key":"D","text":"最小化 DFA 与原 DFA 识别的语言相同"}]',
 'ABCD','这正是词法分析程序自动生成（如 Lex/Flex）的完整流水线：正规式 → NFA → DFA → 最小 DFA → 驱动程序。',8),
(114,'single','一个文法是 LL(1) 文法的充要条件可以表述为：对每个非终结符 A 的任意两条候选式 α、β，必须满足？',
 '[{"key":"A","text":"FIRST(α) ∩ FIRST(β) = ∅，且若 α 能推出 ε 则 FIRST(β) ∩ FOLLOW(A) = ∅"},{"key":"B","text":"FIRST(α) = FIRST(β)"},{"key":"C","text":"两者 FOLLOW 集相等"},{"key":"D","text":"A 不能出现在自身推导中"}]',
 'A','这保证分析器只需看当前一个输入符号就能唯一选定候选式，因此叫 LL(1)：第一个 L 指从左向右扫描，第二个 L 指最左推导，1 指前瞻一个符号。',5),
(114,'single','文法中的直接左递归产生式 A → A α | β 应改写为？',
 '[{"key":"A","text":"A → β A′，A′ → α A′ | ε"},{"key":"B","text":"A → α A′，A′ → β A′ | ε"},{"key":"C","text":"A → A′ β，A′ → A′ α | ε"},{"key":"D","text":"A → β | α"}]',
 'A','左递归改写是"把递归放到右端"：原来的 Aα...α 由 A′ 的右递归生成，最后以 ε 结束。带左递归的文法无法用自顶向下分析，因为会无限循环。',5),
(114,'single','已知文法 G: S → a S b | ε，则 FIRST(S) 是？',
 '[{"key":"A","text":"{ a }"},{"key":"B","text":"{ a, ε }"},{"key":"C","text":"{ a, b }"},{"key":"D","text":"{ ε }"}]',
 'B','S 可推出以 a 开头的串，也可推出空串 ε，故 FIRST(S) = { a, ε }；再由 S 是开始符号得 FOLLOW(S) 含 #，且 b 也是 FOLLOW(S) 的元素。',5),
(114,'single','关于 LL(1) 与 LR(1) 文法类之间的关系，正确的是？',
 '[{"key":"A","text":"LL(1) 文法是 LR(1) 文法的真子集，LR 能分析的文法更多"},{"key":"B","text":"两者等价"},{"key":"C","text":"LR(1) 是 LL(1) 的真子集"},{"key":"D","text":"两者互不相交"}]',
 'A','自底向上的 LR 分析看的是"已归约出的历史 + 前瞻符号"，信息量大于只看前瞻符号的 LL，故 LR(1) 覆盖更广；常见语言大多可用 LALR(1) 描述。',5),
(114,'single','LR(0)、SLR(1)、LALR(1)、LR(1) 四种分析法的分析能力强弱顺序是？',
 '[{"key":"A","text":"LR(0) ⊂ SLR(1) ⊂ LALR(1) ⊂ LR(1)"},{"key":"B","text":"LR(1) ⊂ LALR(1) ⊂ SLR(1) ⊂ LR(0)"},{"key":"C","text":"四者能力完全相同"},{"key":"D","text":"SLR(1) ⊂ LR(0) ⊂ LALR(1) ⊂ LR(1)"}]',
 'A','差别在于处理冲突时使用的前瞻信息：LR(0) 完全不用、SLR 用 FOLLOW 集、LALR 合并同心项目集、LR(1) 用精确的搜索符，能力递增而状态数也随之增多。',5),
(114,'single','在自底向上分析中，句柄指的是？',
 '[{"key":"A","text":"最左直接短语，即某产生式右部经一步归约即可得到的最左子串"},{"key":"B","text":"任意短语"},{"key":"C","text":"句型中最右边的符号"},{"key":"D","text":"文法的开始符号"}]',
 'A','规范归约每次都归约当前句型的句柄，即"最左的直接短语"；它是某产生式 A → β 的右部，且该 β 位于句型最左可直接归约的位置。',5),
(114,'single','LR 分析表中同一状态下同时存在移进动作与归约动作，称为？',
 '[{"key":"A","text":"移进-归约冲突"},{"key":"B","text":"归约-归约冲突"},{"key":"C","text":"二义性错误"},{"key":"D","text":"栈溢出"}]',
 'A','移进-归约冲突说明该状态下无法仅凭当前信息决定继续读入还是归约；典型例子是悬空 else（dangling-else）造成的二义性。',5),
(114,'single','递归下降分析法的基本做法是？',
 '[{"key":"A","text":"为每个非终结符编写一个子程序，遇终结符则匹配并读下一符号，遇非终结符则调用相应子程序"},{"key":"B","text":"为每个终结符编写一个子程序"},{"key":"C","text":"把文法转成 NFA 再模拟"},{"key":"D","text":"一次性把整个输入读入内存后倒序分析"}]',
 'A','递归下降是最直观的自顶向下分析，要求文法无左递归、候选 FIRST 集不相交，否则子程序无法确定分支；预测分析法是它的表驱动版本。',5),
(114,'single','关于二义性文法，下列说法正确的是？',
 '[{"key":"A","text":"二义文法存在某个句子对应两棵不同的语法树，因此不可能是 LL(1) 或 LR 文法"},{"key":"B","text":"二义文法一定是 LL(1) 文法"},{"key":"C","text":"二义文法可以用 LR(0) 分析"},{"key":"D","text":"二义性可以在词法分析阶段消除"}]',
 'A','二义文法必然导致分析表冲突，无法构造确定的 LL/LR 分析表；处理办法是改写文法（如为 else 引入配对规则）或借助优先级与结合性规则消歧。',5),
(114,'single','文法 E → E + T | T 最突出的问题是？',
 '[{"key":"A","text":"含有直接左递归，不能用于自顶向下的递归下降或 LL(1) 分析"},{"key":"B","text":"含有二义性"},{"key":"C","text":"没有终结符"},{"key":"D","text":"产生式个数太多"}]',
 'A','E 出现在自身产生式右部的最左端，递归下降时会立刻再次调用 E 而永不读入符号，导致无限递归；必须先消除左递归再提取左公因子。',5),
(114,'judge','任何 LL(1) 文法都是无二义性的。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。LL(1) 要求每个选择唯一，二义文法必然在某处出现选择冲突，因而不可能是 LL(1)。反之，无二义的文法也未必是 LL(1)。',5),
(114,'judge','LR 分析法能够处理所有上下文无关文法，包括二义文法。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。LR 能处理的是全部非二义（确定）的上下文无关文法，二义文法会产生无法用优先级彻底消除的表冲突。',5),
(114,'judge','语法分析阶段能够发现「变量未声明」「运算对象类型不匹配」这类错误。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。这两类属于静态语义错误，由语义分析（符号表与类型检查）发现；语法分析只判断句子是否符合文法结构。',5),
(114,'judge','算符优先分析法是一种自底向上分析法，它依靠终结符之间的优先关系确定归约时机。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。它为每个终结符对定义 <、=、> 关系，寻找最左素短语归约；优点是简单，缺点是对文法限制较严且可能误归约非句型。',5),
(114,'multi','下列哪些情况会导致文法不适用于自顶向下的 LL(1) 分析？',
 '[{"key":"A","text":"存在左递归"},{"key":"B","text":"同一非终结符的候选式 FIRST 集相交"},{"key":"C","text":"某候选能推出 ε 且其 FIRST 与该非终结符的 FOLLOW 相交"},{"key":"D","text":"文法中含有终结符"}]',
 'ABC','这三条正是 LL(1) 的三个判定条件；对应处理手段分别是消除左递归、提取左公因子、改写文法或改用 LR 分析法。',8),
(114,'multi','关于 LR 分析器的组成，下列说法正确的有？',
 '[{"key":"A","text":"分析栈中存放状态与文法符号"},{"key":"B","text":"ACTION 表决定移进或归约，GOTO 表决定归约后转到的状态"},{"key":"C","text":"分析动作由栈顶状态与当前输入符号共同决定"},{"key":"D","text":"LR 分析器采用最左归约"}]',
 'ABC','LR 分析做的是规范归约，即最右推导的逆过程，因此是"最左归约"（每次归约最左的句柄），不能说最右归约。',8),
(114,'multi','关于短语与句柄，下列说法正确的有？',
 '[{"key":"A","text":"短语是某非终结符经若干步推导得到的子串"},{"key":"B","text":"直接短语是某产生式右部经一步推导得到的子串"},{"key":"C","text":"句柄是最左的直接短语"},{"key":"D","text":"一个句型的句柄一定唯一"}]',
 'ABCD','对非二义文法，规范归约每步的句柄是唯一的，这正是 LR 分析能确定工作的依据；借助语法树可直观找出各层短语。',8),
(115,'single','表达式 a + b * c 的逆波兰式（后缀式）是？',
 '[{"key":"A","text":"a b c * +"},{"key":"B","text":"a b + c *"},{"key":"C","text":"+ a * b c"},{"key":"D","text":"a * b + c"}]',
 'A','按运算优先级先处理 b * c，写成 b c *，再处理 a + (结果)，写成 a b c * +。后缀式的运算顺序由操作数与运算符的出现次序唯一确定，无需括号。',5),
(115,'single','赋值语句 x = a + b * c 对应的四元式序列是？',
 '[{"key":"A","text":"(*, b, c, T1) (+, a, T1, T2) (=, T2, _, x)"},{"key":"B","text":"(+, a, b, T1) (*, T1, c, T2) (=, T2, _, x)"},{"key":"C","text":"(*, a, b, T1) (+, T1, c, T2) (=, T2, _, x)"},{"key":"D","text":"(=, a, b, T1) (*, T1, c, x)"}]',
 'A','四元式形如 (op, arg1, arg2, result)，先算优先级高的乘法生成临时变量 T1，再算加法得 T2，最后赋值；单目运算或复制用「_」占位。',5),
(115,'single','与三地址码相比，后缀式（逆波兰式）的主要缺点是？',
 '[{"key":"A","text":"不便于直接做代码优化与寄存器分配，缺少显式的目标变量"},{"key":"B","text":"长度更长"},{"key":"C","text":"无法表示表达式"},{"key":"D","text":"只能用于布尔表达式"}]',
 'A','后缀式紧凑、可用栈求值，但优化需要明确"结果放到哪里"，因此编译器内部更常用四元式/三地址码这类带结果名的形式。',5),
(115,'single','关于综合属性与继承属性，正确的是？',
 '[{"key":"A","text":"综合属性自下而上传递（由子结点算出），继承属性自上而下传递（由父结点与左兄弟给出）"},{"key":"B","text":"综合属性自上而下传递"},{"key":"C","text":"继承属性只能是终结符的属性"},{"key":"D","text":"两者都需要一遍单独扫描"}]',
 'A','终结符只有综合属性（由词法分析给出），开始符号的继承属性为已知；S-属性文法只含综合属性，可在自底向上归约时顺便计算。',5),
(115,'single','S-属性文法的特点是？',
 '[{"key":"A","text":"只含综合属性，可在自底向上归约时与分析同步计算"},{"key":"B","text":"必须多遍扫描"},{"key":"C","text":"只含继承属性"},{"key":"D","text":"不能用于 LR 分析"}]',
 'A','属性与文法符号一一对应地放在分析栈里，每次归约就把子结点的综合属性合成为父结点属性，因此 LR 分析器可一趟完成翻译。',5),
(115,'single','L-属性文法的定义是？',
 '[{"key":"A","text":"每个继承属性只依赖其父结点的属性与左边兄弟的属性，综合属性可依赖任意属性"},{"key":"B","text":"所有属性都只能依赖自身"},{"key":"C","text":"只允许综合属性"},{"key":"D","text":"只允许继承属性"}]',
 'A','L 指"从左到右"，该限制保证在预扫描/递归下降分析时属性已经准备好，因此 L-属性文法既能用自顶向下也能改造后用自底向上实现。',5),
(115,'single','翻译布尔表达式时采用回填（backpatching）技术，主要解决的问题是？',
 '[{"key":"A","text":"翻译跳转语句时目标地址尚未确定，先记录待填位置，待地址确定后再回填"},{"key":"B","text":"把代码填进缓冲区"},{"key":"C","text":"优化布尔表达式"},{"key":"D","text":"删除无用跳转"}]',
 'A','生成 if-then-else 时，真假出口标号在生成跳转指令时还不知道，于是把这类指令链起来（真链、假链），等到出口确定后沿链回填标号。',5),
(115,'single','对二维数组 A[1..10, 1..20]，每个元素占 w 个字节，按行优先存放，元素 A[i, j] 的地址是？',
 '[{"key":"A","text":"base + ((i - 1) × 20 + (j - 1)) × w"},{"key":"B","text":"base + ((j - 1) × 10 + (i - 1)) × w"},{"key":"C","text":"base + (i × j) × w"},{"key":"D","text":"base + (i + j - 2) × w"}]',
 'A','行优先时第 i 行之前有 (i-1) 整行、每行 20 个元素，再加上本行前面的 (j-1) 个元素；列优先则把 20 换成每行长度对应的另一维，如 B 是按列优先的写法。',5),
(115,'single','引入中间代码的主要好处不包括下列哪一项？',
 '[{"key":"A","text":"与目标机器无关，便于把编译器移植到不同机器"},{"key":"B","text":"便于在其上进行与机器无关的代码优化"},{"key":"C","text":"使编译程序结构更清晰、前后端分离"},{"key":"D","text":"使源程序的可读性更好"}]',
 'D','中间代码是编译器内部表示，与源程序可读性无关；它的价值在于可移植、可优化以及把编译过程清晰地分成前端与后端。',5),
(115,'single','处理声明语句时，语法制导翻译的主要工作是？',
 '[{"key":"A","text":"把名字、类型、相对地址等信息填入符号表，并为局部变量分配存储"},{"key":"B","text":"生成跳转指令"},{"key":"C","text":"直接生成机器指令"},{"key":"D","text":"进行寄存器分配"}]',
 'A','声明不产生可执行代码，只建立环境：填类型与偏移量、累计本过程的存储宽度；后续引用标识符时再由符号表查出类型与地址用于生成代码。',5),
(115,'judge','三地址码中每条语句最多涉及三个地址（两个操作数与一个结果）。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。典型形式为 x = y op z，另有单目赋值、复制、无条件/条件跳转、过程调用等变体，都不超过三个地址。',5),
(115,'judge','逆波兰表达式在求值时不需要括号即可唯一确定运算次序。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。操作数与运算符的出现次序已隐含了运算树结构，用栈从左到右扫描即可求得结果，这也是早期计算器采用后缀式的原因。',5),
(115,'judge','继承属性可以在自底向上归约时像综合属性一样直接计算。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。继承属性依赖父结点或左兄弟，需要额外机制（如把继承属性放入分析栈、改造文法或改用递归下降）才能计算，不能一概而论。',5),
(115,'judge','语法制导定义（SDD）与语法制导翻译方案（SDT）的区别在于后者明确规定了语义动作在产生式中的执行位置。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。SDD 只说明属性间的依赖关系（抽象），SDT 进一步把动作嵌入产生式右部的具体位置（可实现），实现时需保证动作执行时相关属性已可用。',5),
(115,'multi','下列哪些属于常见的中间代码表示形式？',
 '[{"key":"A","text":"后缀式（逆波兰式）"},{"key":"B","text":"三地址码（含四元式、三元式）"},{"key":"C","text":"抽象语法树与 DAG"},{"key":"D","text":"绝对地址的机器指令"}]',
 'ABC','机器指令是目标代码而非中间代码；三元式用编号引用结果，四元式用临时变量名，间接三元式则便于做代码移动优化。',8),
(115,'multi','关于属性文法，下列说法正确的有？',
 '[{"key":"A","text":"终结符只有综合属性，由词法分析器提供"},{"key":"B","text":"开始符号的继承属性通常作为已知初值"},{"key":"C","text":"S-属性文法是 L-属性文法的特例"},{"key":"D","text":"带继承属性的翻译仍可用一遍扫描完成，只要它是 L-属性的"}]',
 'ABCD','S-属性只含综合属性，自然是 L-属性；L-属性保证从左到右分析时依赖已就绪，因此递归下降或 LL 分析可一趟实现翻译。',8),
(115,'multi','关于布尔表达式与控制流语句的翻译，下列说法正确的有？',
 '[{"key":"A","text":"常用短路求值，只生成必要的跳转序列而不计算整个表达式的值"},{"key":"B","text":"真假出口在跳转指令生成时往往未知，需要回填"},{"key":"C","text":"回填时把待填指令用链表串起来，待标号确定后逐个填写"},{"key":"D","text":"布尔表达式必须先完整求值成 0/1 才能翻译"}]',
 'ABC','短路翻译既符合语言语义（如 Java、C 的 && 与 ||）又能避免无谓计算，因此现代编译器普遍采用跳转代码 + 回填的方式。',8),
(116,'single','划分基本块时，下列哪一条语句应作为一个新基本块的入口（首指令）？',
 '[{"key":"A","text":"紧跟在条件或无条件转移语句之后的那条语句"},{"key":"B","text":"任意一条赋值语句"},{"key":"C","text":"位于程序中间的三地址码"},{"key":"D","text":"紧跟在另一条赋值语句之后的语句"}]',
 'A','首指令有三类：程序的第一条语句、任何转移语句的目标语句、紧跟在转移语句（含条件转移）之后的那条语句。它们把程序切成单入口单出口的块。',5),
(116,'single','利用 DAG 对基本块进行优化，不能实现下列哪一项？',
 '[{"key":"A","text":"循环不变运算外提"},{"key":"B","text":"删除公共子表达式"},{"key":"C","text":"合并已知量（常量折叠）"},{"key":"D","text":"删除无用赋值"}]',
 'A','DAG 只描述一个基本块内的值与依赖关系，因此只能做块内优化；循环不变运算外提涉及跨块的循环结构，属于循环优化。',5),
(116,'single','把循环中的乘法 i * 4 改写成用加法递增的等价形式，这类优化称为？',
 '[{"key":"A","text":"强度削弱"},{"key":"B","text":"代码外提"},{"key":"C","text":"复写传播"},{"key":"D","text":"常量折叠"}]',
 'A','强度削弱用代价低的运算（加、移位）替代代价高的运算（乘），常与删除归纳变量配合使用：下标变量地址随循环变量线性增长时尤为有效。',5),
(116,'single','循环优化的三项主要内容是？',
 '[{"key":"A","text":"代码外提、强度削弱、删除归纳变量"},{"key":"B","text":"常量折叠、复写传播、死代码删除"},{"key":"C","text":"公共子表达式删除、寄存器分配、指令调度"},{"key":"D","text":"窥孔优化、合并已知量、复写传播"}]',
 'A','循环是程序的热点，针对它的三种经典优化分别减少循环体内计算量、降低运算代价、减少变量个数；常量折叠等属于基本块内的局部优化。',5),
(116,'single','把循环中不随循环执行而改变的运算移到循环外，这种优化要求该运算满足什么条件？',
 '[{"key":"A","text":"其运算对象都是循环不变量，且所在基本块是循环所有出口的必经结点"},{"key":"B","text":"只要它出现在循环体内即可"},{"key":"C","text":"只要它不含乘法"},{"key":"D","text":"只要它只执行一次"}]',
 'A','外提首先要确认运算对象在循环内不变（到达定值分析），其次不能改变语义：外提后原本不执行的路径也会执行它，因此通常要求放在所有出口的必经块中。',5),
(116,'single','复写传播（copy propagation）指的是？',
 '[{"key":"A","text":"把 x = y 之后对 x 的引用替换为对 y 的引用，为删除无用赋值创造条件"},{"key":"B","text":"把变量复制到寄存器中"},{"key":"C","text":"把代码复制到循环外"},{"key":"D","text":"把一个变量改名为另一个变量"}]',
 'A','复写传播本身不一定减少指令，但它常常使 "x = y" 成为无用赋值而被删除，因此常与死代码删除配合使用。',5),
(116,'single','活跃变量分析的数据流方程与方向是？',
 '[{"key":"A","text":"LiveIn(B) = LiveUse(B) ∪ (LiveOut(B) − Def(B))，从出口向入口反向分析"},{"key":"B","text":"LiveOut(B) = LiveIn(B) − Def(B)，正向分析"},{"key":"C","text":"LiveIn(B) = Def(B) ∪ LiveOut(B)，正向分析"},{"key":"D","text":"只需在基本块内计算，与块间无关"}]',
 'A','一个变量在某点活跃意味着从该点出发存在一条路径会用到它的当前值，因此信息由后继向前驱传播，属于后向（backward）分析。',5),
(116,'single','删除全局公共子表达式需要依赖哪种数据流分析？',
 '[{"key":"A","text":"可用表达式分析（正向分析）"},{"key":"B","text":"活跃变量分析"},{"key":"C","text":"到达定值分析的反向版本"},{"key":"D","text":"支配结点分析"}]',
 'A','可用表达式沿控制流正向传播：在程序点 p，表达式 x + y 可用当且仅当所有到达 p 的路径都已计算过它且之后 x、y 未被重新定值。',5),
(116,'single','窥孔优化（peephole optimization）的特点是？',
 '[{"key":"A","text":"在目标代码上滑动一个小窗口，对窗口内的几条指令做局部替换与删除"},{"key":"B","text":"在源代码上做全局重排"},{"key":"C","text":"只能删除注释"},{"key":"D","text":"必须遍历整个控制流图"}]',
 'A','典型手法有删除冗余存取、合并连续的 push/pop、用移位代替乘 2、利用代数恒等式化简等，实现简单、在生成目标代码后作为最后一道工序。',5),
(116,'single','删除归纳变量的目的是？',
 '[{"key":"A","text":"用循环控制变量之间的线性关系去掉多余的变量及其计算，减少循环内的运算"},{"key":"B","text":"把所有变量换成常量"},{"key":"C","text":"删除循环中所有赋值"},{"key":"D","text":"减少基本块个数"}]',
 'A','当数组下标变量 j 与循环变量 i 满足 j = 4i + c 时，可把 j 的递增改为加法并在循环测试中改用 j 的终值判断，从而删掉 i，减少循环内的运算。',5),
(116,'judge','基本块是单入口单出口的语句序列，除最后一条外不含任何转移或停机的可能。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。控制流只能从第一条语句进入、从最后一条语句离开，块内一旦执行就必然顺序执行到底，这为块内的局部优化提供了安全前提。',5),
(116,'judge','代码优化可以改变程序的运行结果，只要效率得到提升。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。优化的首要原则是保持语义等价（可观察行为不变），任何改变输出、异常或副作用的"优化"都是错误变换。',5),
(116,'judge','循环不变运算外提后，程序在任何输入下的执行结果都不变。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。若循环体可能一次都不执行，或外提的运算在有副作用（如除零、越界、浮点异常）时，外提会把它变成无条件执行，从而改变行为，因此需加前置块等安全措施。',5),
(116,'judge','常量传播与常量折叠属于基本块内的局部优化，也可以在全局范围内进行。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。块内折叠最简单，全局版本需要到达定值分析判断某变量在各点是否只有一个常量定值，从而跨块传播常量。',5),
(116,'multi','下列哪些属于基本块内的局部优化？',
 '[{"key":"A","text":"合并已知量（常量折叠）"},{"key":"B","text":"删除公共子表达式"},{"key":"C","text":"删除无用赋值（死代码）"},{"key":"D","text":"循环不变代码外提"}]',
 'ABC','前三项只需块内的值依赖信息（DAG）即可完成；代码外提必须跨越基本块分析循环结构，属于循环优化。',8),
(116,'multi','关于数据流分析，下列说法正确的有？',
 '[{"key":"A","text":"到达定值分析用于判断某点的变量值由哪些语句定值，是正向分析"},{"key":"B","text":"活跃变量分析是反向分析"},{"key":"C","text":"可用表达式分析用于公共子表达式删除"},{"key":"D","text":"数据流分析通常以基本块为结点在流图上迭代求解"}]',
 'ABCD','流图上迭代直到不动点，是全局优化的基础工具；正向分析信息沿控制流向前传，反向分析（如活跃变量）从出口往入口传。',8),
(116,'multi','关于 DAG 在基本块优化中的作用，下列说法正确的有？',
 '[{"key":"A","text":"相同运算对象的同一运算只建一个结点，可消除公共子表达式"},{"key":"B","text":"叶结点带变量名标记，可识别出重复定值"},{"key":"C","text":"没有附加标记的结点对应的赋值可删除"},{"key":"D","text":"DAG 可以直接表达循环结构"}]',
 'ABC','DAG 只覆盖一个基本块的直线代码，无法表达控制流与循环；构造时把常量运算直接求值（合并已知量），最后按结点顺序重写代码。',8),
(117,'single','目标代码生成阶段的三项主要任务是？',
 '[{"key":"A","text":"指令选择、寄存器分配与指令调度"},{"key":"B","text":"词法分析、语法分析、语义分析"},{"key":"C","text":"代码外提、强度削弱、删除归纳变量"},{"key":"D","text":"建立符号表、填符号表、查符号表"}]',
 'A','指令选择决定用哪些机器指令实现中间代码，寄存器分配决定哪些值驻留在寄存器，指令调度重排指令以充分利用流水线和减少等待。',5),
(117,'single','现代编译器常用的寄存器分配方法是？',
 '[{"key":"A","text":"基于干扰图（寄存器冲突图）的图着色算法，冲突变量不能共用寄存器"},{"key":"B","text":"总是把第一个变量放入 R0"},{"key":"C","text":"按字母顺序分配"},{"key":"D","text":"随机分配"}]',
 'A','先做活跃变量分析得到各变量的活跃区间，再构造干扰图：两个变量在某点同时活跃则连边，用 k 种颜色着色即可用 k 个寄存器；颜色不够时需溢出到内存。',5),
(117,'single','一个典型的活动记录（栈帧）中通常不包含下列哪一项？',
 '[{"key":"A","text":"源程序的注释文本"},{"key":"B","text":"返回地址"},{"key":"C","text":"局部变量与临时变量"},{"key":"D","text":"控制链（指向调用者的活动记录）"}]',
 'A','活动记录保存一次过程调用所需的运行时信息：实参、返回地址、控制链（动态链）、访问链（静态链）、保存的寄存器、局部与临时数据；注释在词法分析时已丢弃。',5),
(117,'single','支持递归调用的语言，其局部变量的存储分配必须采用？',
 '[{"key":"A","text":"栈式动态分配"},{"key":"B","text":"静态分配"},{"key":"C","text":"堆式分配"},{"key":"D","text":"寄存器分配"}]',
 'A','递归意味着同一过程的多个活动同时存在，每个活动要有独立的一份局部变量，只有随调用压栈、返回弹栈的栈式分配能满足；静态分配在编译期就定死地址，无法支持递归。',5),
(117,'single','访问链（静态链）的作用是？',
 '[{"key":"A","text":"在非局部名字访问时，沿静态嵌套层次找到定义该名字的外层过程的活动记录"},{"key":"B","text":"指向调用者的活动记录"},{"key":"C","text":"保存返回地址"},{"key":"D","text":"记录数组下标"}]',
 'A','控制链（动态链）指向调用者，用于返回时恢复栈；访问链按词法嵌套层次链接，用于 Pascal 这类允许过程嵌套的语言访问外层变量。C 语言不支持嵌套定义，故不需要访问链。',5),
(117,'single','关于参数传递的「复制恢复」（copy-restore）方式，正确的是？',
 '[{"key":"A","text":"调用时把实参值复制给形参，过程返回时再把形参终值写回实参"},{"key":"B","text":"全程共享同一存储单元"},{"key":"C","text":"实参必须是表达式"},{"key":"D","text":"只在 C 语言中使用"}]',
 'A','它也称值-结果调用，效果类似引用传递，但若同一变量被作为两个形参传入（别名），各自的修改会互相覆盖，最终以某个写回顺序为准，这点与真正的引用传递不同。',5),
(117,'single','指令调度的主要目的是？',
 '[{"key":"A","text":"重排指令顺序以减少数据相关与资源冲突造成的流水线停顿"},{"key":"B","text":"减少指令条数"},{"key":"C","text":"减少寄存器个数"},{"key":"D","text":"把指令放到内存"}]',
 'A','调度不改变指令集合（或减少不了多少），只是把互不相关的指令插进等待间隙，提高指令级并行度；它与寄存器分配相互影响，是后端优化的重点。',5),
(117,'single','运行时存储空间通常划分为目标代码区、静态数据区、栈区和堆区，其中堆区主要用于？',
 '[{"key":"A","text":"存放用户动态申请的内存（如 malloc/new 出来的对象）"},{"key":"B","text":"存放活动记录"},{"key":"C","text":"存放全局常量"},{"key":"D","text":"存放编译后的指令"}]',
 'A','栈按后进先出自动管理过程活动，堆则由程序员显式申请释放或由垃圾收集器回收，其分配与回收策略（空闲链表、标记-清除等）是运行时系统的核心之一。',5),
(117,'single','过程的调用序列与返回序列通常由谁完成？',
 '[{"key":"A","text":"由调用者与被调用者分工协作完成，如调用者传参、被调用者保存寄存器与建立活动记录"},{"key":"B","text":"全部由被调用者完成"},{"key":"C","text":"全部由调用者完成"},{"key":"D","text":"由操作系统在编译期完成"}]',
 'A','典型分工：调用者把实参写入活动记录并跳转，被调用者保存返回地址与寄存器、建立局部区；返回时反向执行，两套序列必须严格约定一致（这就是调用约定 ABI）。',5),
(117,'single','决定一个变量的值是否需要保留在寄存器中的关键依据是？',
 '[{"key":"A","text":"该变量在程序某点是否活跃（后续是否还会被使用）"},{"key":"B","text":"变量名长度"},{"key":"C","text":"变量声明的位置"},{"key":"D","text":"变量是否被赋过值"}]',
 'A','活跃变量分析给出每个变量的活跃区间：某值在定义点之后不再被使用（不活跃）就不必占用寄存器，可直接丢弃或复用其寄存器。',5),
(117,'judge','静态存储分配允许过程递归调用。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。静态分配在编译期为每名变量确定唯一地址，递归时同一变量会被多个活动共享而互相覆盖；递归、动态数组等必须用栈式动态分配。',5),
(117,'judge','过程调用时会在栈顶压入一个活动记录，过程返回时将其弹出。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。活动记录随调用/返回成对地压栈弹栈，栈顶指针与当前活动记录指针共同维护运行栈，这正好匹配过程的嵌套调用结构。',5),
(117,'judge','目标代码生成可以完全不考虑目标机器的指令系统与寄存器数量。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。正是机器细节（指令集、寻址方式、寄存器个数与用途约定）决定了指令选择与寄存器分配，这也是编译后端难以移植的根源。',5),
(117,'judge','采用引用传递时，在被调用过程中修改形参会直接影响调用者的实参变量。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。引用传递把实参地址传给形参，二者共享同一存储单元；值传递则只复制值，修改形参不影响实参。',5),
(117,'multi','活动记录中通常包含下列哪些信息？',
 '[{"key":"A","text":"实参（实在参数）区"},{"key":"B","text":"返回地址"},{"key":"C","text":"控制链（动态链）与访问链（静态链）"},{"key":"D","text":"局部变量与临时工作单元"}]',
 'ABCD','此外还包括被保存的机器寄存器状态与临时变量区；具体布局由编译器与 ABI 约定，但这些信息项是通用的。',8),
(117,'multi','关于常见的存储分配策略，下列说法正确的有？',
 '[{"key":"A","text":"静态分配在编译期即可确定所有数据的地址"},{"key":"B","text":"栈式分配支持递归，随调用与返回自动管理"},{"key":"C","text":"堆式分配用于生存期不受调用结构约束的数据"},{"key":"D","text":"栈式分配的空间必须由程序员显式释放"}]',
 'ABC','栈空间由调用序列自动回收，不需要也不允许手动释放；需要手动管理（或由 GC 管理）的是堆空间，这也是内存泄漏与悬垂指针的来源。',8),
(117,'multi','关于参数传递方式，下列说法正确的有？',
 '[{"key":"A","text":"值传递把实参的值复制给形参，形参修改不影响实参"},{"key":"B","text":"引用传递把实参地址传入，形参与实参共享单元"},{"key":"C","text":"复制恢复在返回时把形参终值写回实参"},{"key":"D","text":"传名调用在每次用到形参时按实参的原文重新求值"}]',
 'ABCD','传名（call-by-name）等价于宏替换式的惰性求值，在实参含有带副作用的表达式时行为与其它方式明显不同，现代语言很少采用。',8);

-- ---------- rest-cpp.js ----------
INSERT INTO question (knowledge_id, type, title, options, answer, analysis, score) VALUES
(71,'single','类中已经定义了带参数的构造函数，此时再写 MyClass a; 会怎样？',
 '[{"key":"A","text":"调用编译器生成的默认构造函数"},{"key":"B","text":"编译错误：不再隐式生成默认构造函数"},{"key":"C","text":"a 的成员全部被初始化为 0"},{"key":"D","text":"调用带参构造并传入默认值"}]',
 'B','只要用户声明了任何构造函数，编译器就不再隐式提供默认构造函数，MyClass a; 因找不到可调用的构造函数而报错。解决办法是写 MyClass() = default; 或给带参构造的全部形参加默认实参。',5),
(71,'single','下列哪些成员必须使用构造函数初始化列表，而不能只在构造函数体内赋值？（选最完整的一项）',
 '[{"key":"A","text":"const 成员"},{"key":"B","text":"引用成员"},{"key":"C","text":"没有默认构造函数的类类型成员"},{"key":"D","text":"以上全部"}]',
 'D','进入构造函数体时，所有成员已经完成了初始化：const 成员与引用成员此后不能再赋值，没有默认构造的成员也无法先默认构造再赋值。这三类都只能（且应该）在初始化列表中完成，同时还能省掉一次多余的默认构造。',5),
(71,'single','下列情形中，不会调用拷贝构造函数的是？',
 '[{"key":"A","text":"MyClass b(a);"},{"key":"B","text":"把对象按值传给函数形参"},{"key":"C","text":"对已存在的对象执行 b = a"},{"key":"D","text":"函数按值返回对象（未发生拷贝省略时）"}]',
 'C','b = a 中的两个对象都已存在，调用的是拷贝赋值运算符而非拷贝构造；判断口诀是"初始化用构造，赋值用 operator="。其余三种都是用一个既有对象初始化新对象的场景。',5),
(71,'single','创建派生类对象时，构造与析构的执行顺序是？',
 '[{"key":"A","text":"先派生后基类；析构先基类后派生"},{"key":"B","text":"先基类后派生；析构先派生后基类"},{"key":"C","text":"只构造派生类部分"},{"key":"D","text":"顺序由编译器自由决定"}]',
 'B','构造从基类开始逐层向下（基类子对象必须先就绪，派生部分才可能用到它），析构则严格相反、自派生向基类回溯。多重继承时基类按其在本类基列表中的声明顺序构造，与初始化列表的书写顺序无关。',5),
(71,'single','C++11 中要禁止类的拷贝行为，推荐的写法是？',
 '[{"key":"A","text":"把拷贝构造函数声明为 private 且不定义"},{"key":"B","text":"MyClass(const MyClass&) = delete;"},{"key":"C","text":"把析构函数声明为 private"},{"key":"D","text":"继承一个空基类即可自动禁止"}]',
 'B','= delete 明确把函数标记为弃置，任何调用（包括友元与成员函数内部）都会在编译期报错，意图清晰；老式的 private 不定义只能挡住外部调用，且错误发生在链接期。禁止移动同理写作 = delete。',5),
(71,'single','类中成员的声明顺序是 int a; int b;，构造函数初始化列表写成 : b(1), a(b)，实际初始化顺序是？',
 '[{"key":"A","text":"b 先于 a"},{"key":"B","text":"a 先于 b，且 a 拿到的是未初始化的 b"},{"key":"C","text":"由初始化列表的书写顺序决定"},{"key":"D","text":"由编译器优化决定"}]',
 'B','成员初始化的唯一依据是类中的声明顺序，与初始化列表的书写次序无关，编译器往往还会对此给出警告。上例中 a 先被初始化，读到的 b 是未初始化的垃圾值，应改成 a(1), b(a) 之类的自洽写法。',5),
(71,'judge','在析构函数中抛出异常是危险的：若它发生在栈展开过程中，程序会直接终止。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。析构函数默认隐含 noexcept，异常从析构中逸出且正处于另一个异常导致的栈展开时，会调用 std::terminate。正确做法是在析构内部捕获并处理所有异常，绝不向外抛（容器的析构尤其要注意）。',5),
(71,'judge','未定义任何构造函数的类含有 int 成员，执行 MyClass a; 后该 int 成员一定被初始化为 0。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。隐式默认构造函数只负责调用类类型成员的默认构造，内置类型成员执行默认初始化，其值是不确定的垃圾。要清零需写 int m = 0; 的类内初始化，或用 MyClass a{}; 做值初始化（静态存储期对象例外，会被零初始化）。',5),
(71,'single','单参数构造函数前加 explicit 的作用是？',
 '[{"key":"A","text":"禁止该函数被隐式调用做类型转换"},{"key":"B","text":"强制编译器内联该函数"},{"key":"C","text":"使该函数成为虚函数"},{"key":"D","text":"禁止该函数被继承"}]',
 'A','explicit 阻止由实参到类类型的隐式转换（如 f(MyClass) 被 f(10) 调用），只允许直接初始化或显式转换，可避免大量难以察觉的临时对象与重载误匹配。C++11 起 explicit 也可用于转换运算符和多参数构造。',5),
(71,'single','语句 MyClass a(); 的实际含义是？',
 '[{"key":"A","text":"定义对象 a 并调用默认构造函数"},{"key":"B","text":"声明了一个名为 a、返回 MyClass 且无参数的函数"},{"key":"C","text":"语法错误"},{"key":"D","text":"定义对象 a 并调用带参构造"}]',
 'B','这是著名的"最令人烦恼的解析"：凡能被解释为函数声明的写法都按声明处理。想用默认构造定义对象应写 MyClass a;，C++11 起亦可用大括号 MyClass a{}; 彻底避免歧义。',5),
(71,'judge','若类的析构函数中释放了资源，通常还必须自定义拷贝构造与拷贝赋值运算符（三法则）。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。合成版本只做逐成员浅拷贝，两个对象会指向同一资源，析构时造成重复释放。因此管理资源的类必须同时定义析构、拷贝构造、拷贝赋值；C++11 起再加上移动构造与移动赋值，合称五法则。',5),
(71,'multi','关于构造函数，下列说法正确的有？（多选）',
 '[{"key":"A","text":"构造函数没有返回值类型，也不能声明为 virtual"},{"key":"B","text":"构造函数可以重载"},{"key":"C","text":"在构造函数中调用虚函数，只会绑定到当前正在构造的类中的版本"},{"key":"D","text":"构造函数可以用 const 修饰以保证不修改成员"}]',
 'ABC','A 正确，构造期间对象尚未成型，虚函数表也还没最终确定，因此不存在虚构造（需要"虚拷贝"时用 clone 惯用法）；B 正确；C 正确，构造时对象的动态类型被视为当前类，虚调用不会下沉到派生类；D 错，构造函数不能被 cv 限定。',8),
(71,'multi','关于析构函数，下列说法正确的有？（多选）',
 '[{"key":"A","text":"析构函数没有参数，因此不能被重载"},{"key":"B","text":"可能通过基类指针删除派生对象时，基类析构应为 virtual"},{"key":"C","text":"对象离开作用域或被 delete 时析构函数自动调用"},{"key":"D","text":"析构函数不能是纯虚函数，抽象类无法声明析构"}]',
 'ABC','A 正确；B 正确，否则 delete 基类指针只析构基类子对象，属未定义行为；C 正确；D 错，析构函数可以声明为纯虚函数，只是必须同时给出函数体定义，否则派生析构回溯到基类时链接失败。',8),
(71,'judge','静态成员函数可以直接访问类的非静态成员变量。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。静态成员函数没有 this 指针，只能访问静态成员；要访问非静态成员必须显式传入对象（引用或指针）。同样，静态成员函数也不能是 const 或 virtual，但可以是类的普通成员函数被对象调用。',5),
(71,'single','C++11 引入的委托构造函数的作用是？',
 '[{"key":"A","text":"在初始化列表中调用本类的另一个构造函数"},{"key":"B","text":"调用基类的构造函数"},{"key":"C","text":"把构造过程交给友元函数完成"},{"key":"D","text":"自动生成拷贝构造函数"}]',
 'A','委托构造允许一个构造函数把初始化工作转交给同类的另一个构造函数（如 MyClass() : MyClass(0) {}），消除重复的初始化代码；调用基类构造要写基类名。若委托形成环，编译器会报错。',5),
(72,'single','要让虚函数调用真正发生动态绑定，必须满足的条件是？',
 '[{"key":"A","text":"成员函数在基类中声明为 virtual 即可"},{"key":"B","text":"该函数是虚函数，且通过基类的指针或引用调用"},{"key":"C","text":"对象必须用 new 在堆上创建"},{"key":"D","text":"派生类必须重写该函数"}]',
 'B','动态绑定需要两个条件同时成立：函数是 virtual，且调用经由指针或引用。Base b; b.f(); 用对象本身调用时编译期即定死，不查虚表；对象是否在堆上与绑定方式无关；派生类不重写则自然调用基类版本。',5),
(72,'single','通过基类指针 delete 派生类对象时，为避免只析构基类部分，基类应该？',
 '[{"key":"A","text":"把析构函数声明为 virtual"},{"key":"B","text":"把析构函数声明为 protected"},{"key":"C","text":"重载 operator delete"},{"key":"D","text":"把析构函数设为纯虚且不定义"}]',
 'A','虚析构使 delete 通过虚表找到派生类析构函数，派生部分析构完后编译器自动回溯调用基类析构，资源被完整释放；否则只析构基类子对象，是未定义行为。作为基类的类通常都应提供虚析构。',5),
(72,'single','关于含有纯虚函数的类，下列说法正确的是？',
 '[{"key":"A","text":"可以创建对象，但不能调用纯虚函数"},{"key":"B","text":"该类是抽象类，不能实例化；派生类实现全部纯虚函数后才能实例化"},{"key":"C","text":"该类不能有构造函数"},{"key":"D","text":"只能被 final 继承"}]',
 'B','含纯虚函数的类是抽象类，不能定义对象（但可以有指针和引用，这正是接口的意义）。派生类必须重写所有纯虚函数，否则自身仍是抽象类；抽象类可以有构造函数、数据成员和普通成员函数。',5),
(72,'judge','含有虚函数的类，其每个对象都会额外占用至少一个指针大小的空间用于存放虚表指针。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。典型实现中每个多态对象内含一个 vptr 指向本类的虚表（64 位下 8 字节），这是运行期多态最主要的空间代价；虚表本身由同类对象共享，不计入对象大小。多重继承时一个对象可能有多个 vptr。',5),
(72,'single','C++11 中在成员函数声明末尾写 override 的作用是？',
 '[{"key":"A","text":"提高调用效率"},{"key":"B","text":"让编译器检查该函数确实重写了基类的虚函数，签名不符时报错"},{"key":"C","text":"禁止派生类继续重写"},{"key":"D","text":"使该函数成为纯虚函数"}]',
 'B','override 是编译期断言：若基类中没有签名一致的虚函数（参数、const、引用限定都必须匹配），编译器立刻报错，能抓出"因签名笔误而意外隐藏"的经典 bug。final 才是禁止继续重写。',5),
(72,'single','在基类构造函数中调用虚函数，实际执行的是哪个版本？',
 '[{"key":"A","text":"派生类的重写版本"},{"key":"B","text":"基类自己的版本，不会下沉到派生类"},{"key":"C","text":"由对象最终类型决定"},{"key":"D","text":"运行期随机决定"}]',
 'B','构造基类子对象时，对象的动态类型被视为基类，虚表也指向基类的表，因此虚调用解析到基类版本；此时派生部分尚未初始化，若真调用派生版本会访问未初始化的成员。析构函数中同理。',5),
(72,'single','基类虚函数声明为 void f(int x = 1)，派生类重写为 void f(int x = 2)，通过基类指针调用 p->f() 时使用的默认值是？',
 '[{"key":"A","text":"1"},{"key":"B","text":"2"},{"key":"C","text":"随机值"},{"key":"D","text":"编译错误"}]',
 'A','默认实参在编译期按调用表达式的静态类型绑定，所以基类指针调用时取基类的 1，而函数体却执行派生类的重写版本。这种"默认参数静态、函数体动态"的错位极易酿成 bug，重写时不要改动默认实参。',5),
(72,'judge','虚函数可以是静态成员函数。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。静态成员函数没有 this 指针，也不参与虚表，无法动态派发；virtual 只能用于非静态成员函数（析构函数例外，它可以是虚的）。静态成员函数也不能加 const 或 override。',5),
(72,'judge','派生类中函数签名与基类虚函数不一致（参数不同）时，会变成隐藏而非重写，动态绑定不会生效。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。重写要求函数名、参数列表完全一致（返回类型可协变），签名不同则派生类的同名函数隐藏基类的整个重载集，通过基类指针调用仍走基类版本。加 override 可让编译器立即发现这类错误。',5),
(72,'single','用 Base arr[3] 这样的数组存放派生类对象，再用 delete[] 释放，结果是？',
 '[{"key":"A","text":"完全正确，是常用写法"},{"key":"B","text":"未定义行为：数组下标按 Base 的大小步进，派生部分被截断"},{"key":"C","text":"只会泄漏内存，不会出错"},{"key":"D","text":"编译不通过"}]',
 'B','数组元素是 Base 类型，按值存放会发生对象切片，且指针算术按 sizeof(Base) 计算，一旦派生类更大就会错位。正确做法是存放指针（推荐 vector<unique_ptr<Base>>）并逐个 delete，且基类析构为虚。',5),
(72,'multi','关于虚函数与多态的实现，下列说法正确的有？（多选）',
 '[{"key":"A","text":"虚函数调用比普通成员函数调用多一次间接寻址"},{"key":"B","text":"虚表属于类，虚表指针属于对象"},{"key":"C","text":"声明为虚函数就一定会被内联展开"},{"key":"D","text":"通过对象名调用虚函数仍是静态绑定"}]',
 'ABD','A 正确，需先取 vptr 再查表跳转；B 正确，虚表由同类对象共享，每个对象只存指针；C 错，只有编译器能确定动态类型时才可能内联；D 正确，Base b; b.f(); 在编译期就能定死。',8),
(72,'multi','下列哪些做法可以实现运行期多态？（多选）',
 '[{"key":"A","text":"基类声明虚函数，派生类重写"},{"key":"B","text":"通过基类的引用调用虚函数"},{"key":"C","text":"用 std::function 包装不同的可调用对象"},{"key":"D","text":"用对象本身（非指针非引用）调用成员函数"}]',
 'ABC','A、B 是基于继承的经典多态；C 通过类型擦除在运行期选择目标（std::function 内部通常也用虚函数实现）；D 错，对象值调用在编译期就已确定，永远不会发生动态派发。',8),
(72,'judge','基类析构函数声明为 virtual 后，通过基类指针 delete 派生对象会先析构派生部分再析构基类部分。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。虚析构让 delete 经由虚表找到派生类析构函数，派生析构体执行完毕后编译器自动插入基类析构调用，顺序与构造相反，从而保证派生类自己申请的资源也被释放。',5),
(72,'single','菱形继承中为避免顶层基类出现两份副本，应采用？',
 '[{"key":"A","text":"普通多重继承"},{"key":"B","text":"虚继承（virtual public Base）"},{"key":"C","text":"把基类成员声明为 static"},{"key":"D","text":"私有继承"}]',
 'B','虚继承使最底层派生类只保留一份共享的虚基类子对象，消除数据冗余与访问二义性。代价是对象布局更复杂、访问虚基类成员需额外间接，且由最底层派生类负责初始化虚基类（初始化列表中直写虚基类名）。',5),
(72,'single','执行 Base b = d;（d 是 Derived 对象）会发生什么？',
 '[{"key":"A","text":"完整拷贝，多态仍然生效"},{"key":"B","text":"对象切片：只拷贝 Base 子对象，派生特有的成员被丢弃"},{"key":"C","text":"编译错误"},{"key":"D","text":"自动调用虚拷贝构造"}]',
 'B','按值初始化/赋值只拷贝基类子对象，派生部分被"切掉"，此后 b 的动态类型就是 Base，虚调用也只会走到基类版本。需要多态语义时必须通过指针或引用传递，这也是容器里要存指针的原因。',5),
(73,'single','函数模板 template <class T> T add(T a, T b); 用 add(1, 2.0) 调用的结果是？',
 '[{"key":"A","text":"推导出 T 为 double，正常调用"},{"key":"B","text":"推导失败：同一个 T 被推成 int 与 double，互相冲突"},{"key":"C","text":"T 被推为 int，2.0 被截断"},{"key":"D","text":"运行期报错"}]',
 'B','模板实参推导要求同一参数的多个推导结果一致，且推导阶段不做算术类型转换（只接受极少数如数组退化为指针、加 const 的调整）。解决：显式指定 add<double>(1, 2.0)，或改用两个模板参数。',5),
(73,'single','要把类模板变成真正的类型，通常必须怎么做？',
 '[{"key":"A","text":"任何 C++ 版本都由编译器按构造实参自动推导"},{"key":"B","text":"显式写出模板实参，如 std::vector<int>"},{"key":"C","text":"不需要，模板参数可以省略"},{"key":"D","text":"用 typedef 让编译器推导"}]',
 'B','类模板不会像函数模板那样自动推导实参，必须显式写出（C++17 起才支持 CTAD，如 std::vector v{1,2,3} 推为 vector<int>）。typedef 与 using 只能给已有类型起别名，不能做推导。',5),
(73,'single','函数模板的定义通常必须放在头文件中，根本原因是？',
 '[{"key":"A","text":"模板不能被声明，只能定义"},{"key":"B","text":"编译器必须在实例化点看到完整定义才能生成具体代码"},{"key":"C","text":"链接器要求所有函数在头文件"},{"key":"D","text":"为了减小目标文件体积"}]',
 'B','模板不是可直接编译的代码，编译器只有见到定义才能按实参类型实例化出具体函数；定义藏在 .cpp 中会链接报未定义引用。可用显式实例化绕开，但通用库几乎都把模板写在头文件里。',5),
(73,'single','在模板中写 T::iterator it; 时常需改成 typename T::iterator it;，原因是？',
 '[{"key":"A","text":"告诉编译器 T::iterator 是一个类型，而不是静态成员或值"},{"key":"B","text":"typename 只是风格建议，没有实际作用"},{"key":"C","text":"为了启用模板特化"},{"key":"D","text":"为了让编译器做两阶段查找"}]',
 'A','实例化前编译器不知道 T 的内容，无法判断 T::iterator 是嵌套类型还是静态数据成员，标准规定默认按"非类型"解析，必须加 typename 明确它是类型（C++20 起部分上下文可省略）。',5),
(73,'single','以 template <> 开头的声明表示什么？',
 '[{"key":"A","text":"偏特化"},{"key":"B","text":"全特化：为某个具体类型提供专门实现"},{"key":"C","text":"模板的前置声明"},{"key":"D","text":"一次显式实例化"}]',
 'B','template<> 表示显式（完全）特化，模板实参列表为空、具体类型写在名字后面，可为该类型提供完全不同的实现。偏特化写作 template <class T> class X<T*>，只约束部分参数模式，且函数模板不支持偏特化。',5),
(73,'single','template <int N> class Buf; 中的 N 属于什么，对实参有何要求？',
 '[{"key":"A","text":"类型参数，实参可以是任意类型"},{"key":"B","text":"非类型模板参数，实参必须是编译期常量表达式"},{"key":"C","text":"运行期变量"},{"key":"D","text":"宏参数，由预处理器展开"}]',
 'B','非类型模板参数可用整型、枚举、指针、引用（C++20 起允许部分类类型），实参必须在编译期确定，如 Buf<10>；不能用运行期计算的变量。std::array<int, N> 就是它的典型应用。',5),
(73,'single','SFINAE 的含义是？',
 '[{"key":"A","text":"模板实参替换失败时，该候选被从重载集中剔除而不算编译错误"},{"key":"B","text":"模板实例化失败会自动退回到默认实现"},{"key":"C","text":"编译器在实例化时自动修正类型"},{"key":"D","text":"一种静态断言机制"}]',
 'A','SFINAE（替换失败不是错误）让不符合条件的模板候选静默退出重载决议，enable_if、void_t 检测成员函数是否存在都依赖它。它只作用于"替换"阶段的直接失败，函数体内部的错误仍会报错；C++20 可用 concepts 表达得更清楚。',5),
(73,'judge','在可变参数模板中，sizeof...(Args) 在编译期返回参数包中元素的个数。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。它是编译期常量表达式，常用于递归展开的终止条件、static_assert 或数组维度等非类型实参；注意它不是 sizeof 运算符，不能用来求某个类型的字节大小，二者形似而义不同。',5),
(73,'judge','函数模板可以像类模板那样进行偏特化。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。C++ 只允许类模板偏特化；函数模板只能全特化，所谓"偏特化"实际是通过提供另一个重载（如 template <class T> void f(T*)）并由重载决议挑选实现，这与偏特化机制不同，且容易因重载顺序产生意外。',5),
(73,'judge','模板代码在实例化之前不做完整的语义检查，错误往往要到实例化时才暴露。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。定义阶段只检查与模板参数无关的部分，涉及参数的检查推迟到实例化（两阶段查找），因此未使用的成员函数中的错误可能一直不被发现。这也是模板报错信息冗长、定位困难的原因。',5),
(73,'single','template <class T> void f(T x){ x.foo(); } 对一个没有 foo 成员的类型实例化会怎样？',
 '[{"key":"A","text":"链接期报未定义引用"},{"key":"B","text":"实例化点编译错误：模板是编译期强类型检查"},{"key":"C","text":"运行期抛出异常"},{"key":"D","text":"静默忽略该调用"}]',
 'B','模板采用隐式接口：只要实例化时该类型支持被用到的操作即可，不支持就在实例化点报编译错误，没有运行期开销。这与 Java 泛型的类型擦除思路不同，C++ 模板在编译期即完成全部类型检查。',5),
(73,'multi','关于 C++ 模板，下列说法正确的有？（多选）',
 '[{"key":"A","text":"模板可用于编译期计算，是模板元编程的基础"},{"key":"B","text":"每种不同的模板实参组合都会生成一份代码，可能造成代码膨胀"},{"key":"C","text":"模板参数既可以是类型，也可以是非类型的值"},{"key":"D","text":"模板在运行期根据对象类型动态生成代码"}]',
 'ABC','A 正确（编译期阶乘、if constexpr 等）；B 正确，这是模板导致编译慢、二进制变大的主因；C 正确；D 错，模板机制完全在编译期工作，运行期没有任何类型判断或代码生成开销。',8),
(73,'multi','下列关于模板特化的说法中，正确的有？（多选）',
 '[{"key":"A","text":"类模板既可以全特化也可以偏特化"},{"key":"B","text":"函数模板只能全特化，偏特化需用重载模拟"},{"key":"C","text":"全特化时 template 后的尖括号为空"},{"key":"D","text":"特化可以写在任意位置，编译器会自动修正之前生成的实例"}]',
 'ABC','A、B、C 均为标准规定；D 错，若某处已经用主模板实例化过该类型，之后再声明其特化属于病式程序（通常直接报错），因此特化必须声明在首次会导致该实例化的使用点之前。',8),
(73,'judge','std::vector<int> 与 std::vector<double> 是两个完全无关的类型，彼此不能赋值或隐式转换。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。模板实参不同即产生不同的类，二者之间没有继承关系也不提供转换，只能逐元素拷贝构造。这正是模板优于"用 void* 或公共基类实现泛型"之处：类型信息完全保留，由编译器检查。',5),
(73,'single','类 Derived 继承自模板基类 Base<T>，其中调用基类成员写成 this->f() 的必要性是？',
 '[{"key":"A","text":"没有必要，直接写 f() 即可"},{"key":"B","text":"基类是依赖类型，非依赖名查找会跳过它，需 this-> 或 using 使其成为依赖名"},{"key":"C","text":"为了触发运行期多态"},{"key":"D","text":"为了强制实例化基类"}]',
 'B','模板基类是依赖类型，两阶段查找的第一阶段不会进入依赖基类查找名字，直接写 f() 会报未声明。加 this-> 或 using Base<T>::f; 可把该名字变成依赖名，推迟到实例化时查找，问题即消失。',5),
(73,'single','C++11 引入的别名模板写法是？',
 '[{"key":"A","text":"typedef T* Ptr;"},{"key":"B","text":"template <class T> using Ptr = T*;"},{"key":"C","text":"#define Ptr(T) T*"},{"key":"D","text":"using Ptr = T*;（在模板内部）"}]',
 'B','别名模板支持参数化，取代了"嵌套 typedef + ::type"的老写法，标准库中的 enable_if_t、remove_const_t 等 _t 系列正是它的产物；typedef 无法模板化，宏则完全没有类型检查且易污染。',5),
(74,'single','std::vector 因 push_back 触发扩容时，通常发生什么？',
 '[{"key":"A","text":"在原地址后方续接一块内存"},{"key":"B","text":"分配更大的空间并搬移（或移动）全部元素，原有迭代器、引用、指针全部失效"},{"key":"C","text":"只把新元素挂到链表尾部"},{"key":"D","text":"扩容一倍且不失效任何迭代器"}]',
 'B','vector 必须保持元素连续，扩容只能另开辟空间并把元素搬过去（能移动则移动，否则拷贝），旧空间随即释放，此前取得的所有迭代器、引用和指针都失效。这是"遍历中 push_back 崩溃"的根源。',5),
(74,'single','对 std::vector 执行 erase(it) 之后，正确的做法是？',
 '[{"key":"A","text":"继续使用 it，它会自动指向下一个元素"},{"key":"B","text":"使用 erase 返回的新迭代器，it 及其之后的迭代器均已失效"},{"key":"C","text":"先 it++ 再使用"},{"key":"D","text":"调用 v.begin() 重新定位即可，无需接收返回值"}]',
 'B','erase 会使被删位置及之后的所有迭代器失效（元素整体前移），标准规定它返回指向被删元素之后的新迭代器，循环删除必须写成 it = v.erase(it);，否则解引用失效迭代器即未定义行为。',5),
(74,'single','关于 std::map 与 std::unordered_map 的区别，正确的是？',
 '[{"key":"A","text":"map 基于哈希表，查找 O(1)"},{"key":"B","text":"map 基于红黑树、按键有序、操作 O(log n)；unordered_map 基于哈希表、平均 O(1) 但无序"},{"key":"C","text":"二者底层相同，只是名字不同"},{"key":"D","text":"unordered_map 保证按插入顺序遍历"}]',
 'B','map 用红黑树实现，键值有序、复杂度稳定为 O(log n) 且迭代器稳定；unordered_map 用哈希桶，平均 O(1) 但最坏 O(n)，rehash 时迭代器失效，且不保证任何遍历顺序。需要有序遍历或范围查询应选 map。',5),
(74,'single','std::vector<bool> 与其它 vector 的关键差异是？',
 '[{"key":"A","text":"它不能存放 bool"},{"key":"B","text":"它是空间优化的特化版本，按位存储，operator[] 返回代理对象而非常规引用"},{"key":"C","text":"它的迭代器是随机访问迭代器中的最快一种"},{"key":"D","text":"它自动去重"}]',
 'B','vector<bool> 为节省空间按位存放，operator[] 返回的是代理（proxy）对象，因此不能取元素地址、不能直接绑定到 bool&，与泛型代码（要求 T&）配合时也常出问题。需要真正的 bool 引用可用 vector<char> 或 deque<bool>。',5),
(74,'single','需要在序列两端高效插入和删除时，优先选择？',
 '[{"key":"A","text":"std::vector"},{"key":"B","text":"std::deque"},{"key":"C","text":"std::set"},{"key":"D","text":"std::array"}]',
 'B','deque 是分段连续的双端队列，首尾插入删除均为 O(1)（优于 vector 头部插入要移动全部元素），且支持下标随机访问；只在中间插入时才应考虑 list，因为 deque 中间插入仍需搬移元素。',5),
(74,'single','std::list 的迭代器属于哪一类，带来什么限制？',
 '[{"key":"A","text":"随机访问迭代器，支持 it + n"},{"key":"B","text":"双向迭代器，只支持 ++ 和 --，不支持 it + n 与 <"},{"key":"C","text":"输入迭代器，只能读一次"},{"key":"D","text":"输出迭代器"}]',
 'B','list 是双向链表，迭代器只能逐节点移动，因此不能用 std::sort（要求随机访问迭代器），应使用成员函数 list::sort；也不支持下标访问和大小比较，只有 == 与 !=。',5),
(74,'single','要删除 vector 中所有满足某条件的元素，推荐的写法是？',
 '[{"key":"A","text":"遍历并逐个调用 erase"},{"key":"B","text":"v.erase(remove_if(v.begin(), v.end(), pred), v.end())"},{"key":"C","text":"先 v.clear() 再重新插入"},{"key":"D","text":"用 find 循环配合 erase(it++)"}]',
 'B','remove_if 并不真的删除元素，只是把保留的元素前移并返回新的逻辑尾，再交给 erase 一次性裁掉尾部，这称为 erase-remove 惯用法；它只需线性一趟，避免了逐个 erase 的反复搬移和迭代器失效风险。',5),
(74,'judge','调用 std::vector::reserve(n) 会把元素个数 size() 改为 n。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。reserve 只提升容量 capacity，不构造任何元素，size 保持不变；改变元素个数应使用 resize（会构造或析构元素）。混淆二者会导致"以为已初始化就直接 v[0] = x"的越界写。',5),
(74,'judge','对 std::map 用 operator[] 访问一个不存在的键，会插入一个值初始化的元素。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。map::operator[] 的语义是"不存在就插入默认值再返回引用"，因此纯查询也会改变容器大小和结构。只读场景应使用 find、count，或 C++20 的 contains。',5),
(74,'single','执行 std::vector<int> v; v.reserve(10); 之后，v.size() 与 v.capacity() 分别是？',
 '[{"key":"A","text":"10 和 10"},{"key":"B","text":"0 和 不小于 10 的值"},{"key":"C","text":"0 和 0"},{"key":"D","text":"10 和 0"}]',
 'B','reserve 只保证容量至少为 10（实现可分配更多），不构造任何元素，故 size 为 0。此时 v[0] = 1 仍是越界，因为下标必须小于 size；正确做法是 push_back 或先 resize。',5),
(74,'judge','对 const std::vector<int> 调用 begin() 返回的是 const_iterator，不能通过它修改元素。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。const 容器的 begin/end 返回 const_iterator，解引用得到 const 引用；非 const 容器可用 cbegin() 显式取得 const 版本（C++11 引入），让只读意图在代码中一目了然，也便于配合 auto 使用。',5),
(74,'multi','下列哪些操作会使 std::vector 的迭代器失效？（多选）',
 '[{"key":"A","text":"push_back 触发扩容"},{"key":"B","text":"在中间位置 insert 元素"},{"key":"C","text":"erase 删除某个元素（该位置及之后的迭代器）"},{"key":"D","text":"对已 reserve 好容量的 vector 继续 push_back 且不超容量"}]',
 'ABC','扩容、中间插入、删除都会搬移元素，从而使部分或全部迭代器、引用、指针失效；D 中容量充足、不发生搬移时，只有 end() 迭代器失效，指向已有元素的迭代器仍然有效。',8),
(74,'multi','关于 STL 容器，下列说法正确的有？（多选）',
 '[{"key":"A","text":"vector 的元素在内存中连续，支持 O(1) 下标访问"},{"key":"B","text":"list 在已知位置插入删除为 O(1)，且不影响其它元素的迭代器"},{"key":"C","text":"deque 支持首尾 O(1) 插入，内存分段连续"},{"key":"D","text":"set 的遍历顺序可以任意由实现决定"}]',
 'ABC','A、B、C 均为各容器的基本性质；D 错，set/multiset 按比较器有序（默认升序）遍历，这一性质也是它能做 lower_bound 范围查询的前提，需要保持插入顺序就得另想办法。',8),
(74,'judge','std::unordered_map 的遍历顺序与元素的插入顺序一致。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。元素按哈希值落入不同桶，遍历顺序取决于哈希函数、桶数量与冲突情况，rehash 后还会整体变化，标准不作任何保证。需要稳定顺序应用 map（按键有序）或自行维护顺序索引。',5),
(74,'single','排序时需要保持相等元素的原有相对次序，应使用？',
 '[{"key":"A","text":"std::sort"},{"key":"B","text":"std::stable_sort"},{"key":"C","text":"std::partial_sort"},{"key":"D","text":"std::nth_element"}]',
 'B','stable_sort 保证相等元素的相对次序不变（通常用归并排序实现，可能额外分配内存），复杂度 O(n log n) 或在内存不足时退化为 O(n log² n)；sort 用内省排序，不保证稳定但一般更快且无需额外内存。',5),
(75,'single','下列引用声明中，合法的是？',
 '[{"key":"A","text":"int &r = 10;"},{"key":"B","text":"const int &r = 10;"},{"key":"C","text":"int &r = (int)10;"},{"key":"D","text":"int &&r = x;（x 是一个 int 变量）"}]',
 'B','非常量左值引用不能绑定右值（字面量、临时对象），const 左值引用可以，且会把临时对象的生存期延长到引用的生存期；右值引用 int&& 只能绑定右值，绑定具名变量必须写 std::move(x)。',5),
(75,'single','std::move(x) 的实际作用是？',
 '[{"key":"A","text":"立刻把 x 的内容搬走到目标对象"},{"key":"B","text":"仅把 x 无条件转换为右值引用，真正的搬移由移动构造/赋值完成"},{"key":"C","text":"把 x 置为空并释放其资源"},{"key":"D","text":"触发一次深拷贝"}]',
 'B','std::move 不做任何移动，本质上是 static_cast<T&&>，只是给重载决议一个"可以被搬走"的许可；实际搬移动作由随后调用的移动构造或移动赋值执行。命名容易误导，它只负责类型转换。',5),
(75,'single','下列哪种写法会调用移动构造函数（假设已定义）？',
 '[{"key":"A","text":"MyClass b = a;（a 为具名左值）"},{"key":"B","text":"MyClass b = std::move(a);"},{"key":"C","text":"b = a;（a 为具名左值，b 已存在）"},{"key":"D","text":"MyClass b(ca);（ca 为 const MyClass）"}]',
 'B','只有实参是右值时移动构造才参与重载并被选中；A、C 的左值只能匹配拷贝版本，const 对象更是无法移动（移动构造要修改源）。std::move(a) 把 a 转成右值，从而选中移动构造。',5),
(75,'single','对象被移动之后，它的状态是？',
 '[{"key":"A","text":"立即失效，不能再以任何方式使用"},{"key":"B","text":"有效但未指定：可以析构或赋予新值，但不能假设其内容"},{"key":"C","text":"被自动置为默认构造出的新对象"},{"key":"D","text":"由编译器保证全部成员清零"}]',
 'B','标准只要求移动后对象处于可析构、可赋值的"有效但未指定"状态，例如被移动的 string 可能为空也可能保留内容，vector 通常变空但不保证。因此移动后要么重新赋值，要么直接让它析构，切勿读取。',5),
(75,'single','template <class T> void f(T&& x) 中的 T&& 被称为？',
 '[{"key":"A","text":"右值引用，只能绑定右值"},{"key":"B","text":"转发引用（万能引用），配合 std::forward 可完美转发左右值属性"},{"key":"C","text":"常量引用"},{"key":"D","text":"悬垂引用"}]',
 'B','当 T 是模板参数（或 auto）时，T&& 发生引用折叠：传左值推导为 T& 得到左值引用，传右值推导为 T 得到右值引用，因此能同时绑定两者；配合 std::forward<T> 保持原值类别传给下层，即完美转发。',5),
(75,'single','std::unique_ptr 的核心特性是？',
 '[{"key":"A","text":"可共享所有权，引用计数归零时释放"},{"key":"B","text":"独占所有权，不可拷贝但可移动，离开作用域自动释放所指对象"},{"key":"C","text":"可拷贝，但最后一个析构时释放"},{"key":"D","text":"只能指向栈上对象"}]',
 'B','unique_ptr 通过删除拷贝构造与拷贝赋值实现独占，所有权只能靠 std::move 转移；它几乎零开销（大小等同裸指针），析构时自动 delete，是 RAII 管理动态内存的首选。需要共享时才用 shared_ptr。',5),
(75,'single','两个对象互相持有指向对方的 std::shared_ptr，会造成什么问题？',
 '[{"key":"A","text":"没有任何问题，引用计数会正确归零"},{"key":"B","text":"循环引用：两者计数都降不到 0，资源永不释放（泄漏）"},{"key":"C","text":"编译错误"},{"key":"D","text":"运行期抛异常"}]',
 'B','互相持有使双方的引用计数至少为 1，谁都不会先析构，形成内存泄漏。标准解法是把"非拥有"的一方（如子节点指向父节点、观察者）改成 weak_ptr，它不增加计数，使用时再 lock() 临时提升为 shared_ptr。',5),
(75,'judge','引用在定义时必须初始化，此后不能再绑定到其它对象，也不存在空引用。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。引用是对象的别名，一经绑定不可更改；指针则可改指向、可为 nullptr。因此含引用成员的类无法默认赋值，把函数返回类型写成局部对象的引用会产生悬垂引用。',5),
(75,'single','函数 MyClass f(){ MyClass a; return a; } 返回时通常发生什么？',
 '[{"key":"A","text":"必定调用一次拷贝构造"},{"key":"B","text":"通常被优化为直接在调用者空间构造（NRVO/拷贝省略），C++17 起对纯右值不再产生拷贝"},{"key":"C","text":"必定调用移动构造"},{"key":"D","text":"返回悬垂引用"}]',
 'B','编译器可把返回对象直接构造在调用者的存储中从而省掉拷贝/移动（NRVO）；C++17 起返回纯右值时这种省略成为语言保证。此时写 return std::move(a); 反而会禁止 NRVO，是典型的负优化。',5),
(75,'single','推荐使用 std::make_shared 而非直接 new 的主要原因不包括？',
 '[{"key":"A","text":"一次分配完成对象与控制块，减少分配次数"},{"key":"B","text":"异常安全，避免\\"new 之后、构造 shared_ptr 之前抛异常\\"导致的泄漏"},{"key":"C","text":"代码更简洁且少写一次类型名"},{"key":"D","text":"它会自动解决循环引用问题"}]',
 'D','make_shared 的优势是单次分配、异常安全和写法简洁；但它对循环引用毫无帮助，那必须用 weak_ptr 打破。另外它的缺点是对象与控制块同生共死，若还有 weak_ptr 存活，对象占用的内存会延迟释放。',5),
(75,'judge','只读的大对象用 const std::string& 传参，可以避免一次不必要的拷贝。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。const 左值引用既能避免拷贝又能绑定临时对象（如字符串字面量），是只读传参的标准写法；按值传递则必定构造一份。需要保存副本时按值接收再 std::move，需要修改时用普通引用。',5),
(75,'judge','调用 std::move 之后，源对象立即失效，不能再对它做任何操作。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。std::move 只做类型转换，真正的搬移发生在随后调用的移动构造或移动赋值中；移动完成后源对象处于"有效但未指定"状态，仍可安全析构或重新赋值，只是不能假设它保持原来的值。',5),
(75,'judge','std::shared_ptr 的引用计数是原子操作，因此被它管理的对象本身也一定是线程安全的。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。原子性只覆盖控制块的计数增减，即"多线程各自持有同一 shared_ptr 副本时生命周期安全"；被管理对象的读写仍需外部同步，而且同一个 shared_ptr 实例的并发读写（如赋值）本身也需要加锁。',5),
(75,'multi','关于 RAII，下列说法正确的有？（多选）',
 '[{"key":"A","text":"资源的获取放在构造函数，释放放在析构函数"},{"key":"B","text":"对象离开作用域时自动释放，异常路径也能正确清理"},{"key":"C","text":"std::lock_guard、std::fstream、std::unique_ptr 都是 RAII 的典型应用"},{"key":"D","text":"RAII 要求在每个 return 前显式调用释放函数"}]',
 'ABC','A、B 是 RAII 的核心：借助栈对象析构时机的确定性，把清理责任交给编译器，天然异常安全；C 正确，锁、文件句柄、动态内存都适合封装成对象；D 错，显式释放正是 RAII 要消除的写法，早退和异常分支最容易漏掉。',8),
(75,'multi','下列哪些做法有助于避免不必要的拷贝？（多选）',
 '[{"key":"A","text":"只读大对象用 const 引用传参"},{"key":"B","text":"返回局部对象时依赖返回值优化，不要画蛇添足加 std::move"},{"key":"C","text":"确实要转移所有权时用 std::move 触发移动构造"},{"key":"D","text":"把成员声明为引用类型以便延迟绑定"}]',
 'ABC','A、C 是常规手段；B 正确，对具名局部对象 return std::move(a) 会阻止 NRVO，反而多一次移动；D 错，引用成员必须在构造时绑定，还会使类失去赋值能力，与减少拷贝毫无关系。',8),
(75,'multi','关于智能指针，下列说法正确的有？（多选）',
 '[{"key":"A","text":"unique_ptr 不可拷贝，但可通过 std::move 转移所有权"},{"key":"B","text":"用 make_unique/make_shared 创建比直接 new 传给构造函数更安全"},{"key":"C","text":"weak_ptr 不增加引用计数，可用于打破循环引用"},{"key":"D","text":"把同一个裸指针分别交给两个 shared_ptr 管理是安全的"}]',
 'ABC','A、B、C 均正确；D 错，两个独立的 shared_ptr 会各自建立控制块，最终对同一地址 delete 两次，属 double free。共享必须通过在已有 shared_ptr 之间拷贝实现，类内部可用 enable_shared_from_this 获取。',8),
(75,'single','若类中只声明了移动构造函数，编译器对拷贝构造函数的处理是？',
 '[{"key":"A","text":"照常隐式生成拷贝构造函数"},{"key":"B","text":"拷贝构造与拷贝赋值被定义为 delete，该类变为只可移动"},{"key":"C","text":"自动补上移动赋值运算符"},{"key":"D","text":"自动补上默认构造函数"}]',
 'B','一旦用户声明了移动构造或移动赋值，隐式拷贝构造与拷贝赋值就被定义为弃置，对象只能移动不能拷贝；同时也不再隐式生成默认构造。若仍需拷贝能力，必须显式声明并定义（五法则）。',5);

-- ---------- rest-css.js ----------
INSERT INTO question (knowledge_id, type, title, options, answer, analysis, score) VALUES
(91,'single','CSS 中 box-sizing 的默认值以及 content-box 的含义分别是？',
 '[{"key":"A","text":"content-box；width 只包含内容区，padding 与 border 另算在外面"},{"key":"B","text":"border-box；width 包含 padding 与 border"},{"key":"C","text":"padding-box；width 包含 padding"},{"key":"D","text":"inherit；由父元素的宽度决定"}]',
 'A','默认 content-box 下元素实际占宽等于 width 加 padding 加 border，写 width: 100px 再写 padding: 10px 会变成 120px，常导致布局溢出。border-box 让 width 包含 padding 与 border，更符合直觉，所以很多项目会全局设置 box-sizing: border-box。',5),
(91,'single','设 box-sizing: content-box，width: 200px，padding: 10px，border: 5px solid，margin: 20px，该元素在水平方向占据的总空间是？',
 '[{"key":"A","text":"270px"},{"key":"B","text":"250px"},{"key":"C","text":"230px"},{"key":"D","text":"200px"}]',
 'A','content-box 下 margin 不计入 width：内容 200 加左右 padding 20、左右 border 10、左右 margin 40，共 270px。若只问边框盒（不含 margin）则是 230px，读题务必看清是否包含外边距。',5),
(91,'single','两个相邻的兄弟块级元素，上者 margin-bottom: 30px，下者 margin-top: 20px，它们之间的实际间距是？',
 '[{"key":"A","text":"30px，外边距折叠取较大者"},{"key":"B","text":"50px，两者相加"},{"key":"C","text":"20px，取较小者"},{"key":"D","text":"0，互相抵消"}]',
 'A','普通流中相邻块级元素的垂直外边距会发生折叠，结果取较大值（存在负值时取最大正值与最小负值之和）。Flex 与 Grid 的项目之间不折叠，创建 BFC 或加 padding、border 也能阻止折叠。',5),
(91,'single','给元素设置 padding-top: 50% 时，这个百分比是相对于什么计算的？',
 '[{"key":"A","text":"父元素（包含块）的宽度"},{"key":"B","text":"父元素的高度"},{"key":"C","text":"元素自身的高度"},{"key":"D","text":"元素自身的宽度"}]',
 'A','CSS 中四个方向的 padding 与 margin 百分比都按包含块的「宽度」计算，与高度无关。这正是用 padding-top 实现固定宽高比的原理，例如 16:9 的盒子写 padding-top: 56.25%。',5),
(91,'single','对 <span> 这类非替换的行内元素设置 width、height 与上下 padding，下列说法正确的是？',
 '[{"key":"A","text":"width 与 height 无效，上下 padding 会绘制但不占据行盒高度"},{"key":"B","text":"width、height、padding 全部生效"},{"key":"C","text":"全部无效，连左右 padding 也不生效"},{"key":"D","text":"只有 width 生效"}]',
 'A','行内非替换元素的 width 与 height 被忽略，上下 padding 与 border 会被绘制但不影响行盒高度，可能覆盖相邻行；上下 margin 完全无效。需要设置尺寸就改为 display: inline-block 或 block。',5),
(91,'single','要让父元素包住浮动的子元素（解决高度塌陷），下列做法有效的是？',
 '[{"key":"A","text":"给父元素设置 overflow: hidden 或 display: flow-root 使其创建 BFC"},{"key":"B","text":"给父元素设置 display: inline"},{"key":"C","text":"给子元素设置 clear: both"},{"key":"D","text":"给父元素设置 height: auto"}]',
 'A','让父元素成为 BFC（overflow 非 visible、display: flow-root 等）即可包住浮动子元素，推荐 flow-root 因为它没有裁剪与滚动的副作用。clear 应加在父元素末尾的伪元素或后续兄弟元素上，加在浮动子元素自身无效。',5),
(91,'single','要让一个定宽的块级元素在父容器中水平居中，正确的写法是？',
 '[{"key":"A","text":"margin: 0 auto，且元素必须有确定的宽度"},{"key":"B","text":"在元素自身上写 text-align: center"},{"key":"C","text":"margin: auto 0"},{"key":"D","text":"padding: 0 auto"}]',
 'A','块级元素左右 margin 为 auto 时会平分剩余空间从而实现居中，前提是宽度不是 auto（否则占满整行没有可分配的空间）。text-align: center 只让内部的「行内内容」居中，不改变块本身的位置。',5),
(91,'single','关于 border 与 outline 的区别，下列说法正确的是？',
 '[{"key":"A","text":"border 参与盒模型计算并占据空间，outline 不占空间、绘制在盒外"},{"key":"B","text":"两者完全相同，只是写法不同"},{"key":"C","text":"outline 只能绘制在盒子内部"},{"key":"D","text":"border 不占据空间"}]',
 'A','outline 绘制在边框之外，不计入尺寸也不影响布局（因此不会触发重排），常用于 :focus-visible 的焦点指示。用 outline: none 去掉焦点框却不提供替代样式，会严重损害键盘无障碍。',5),
(91,'single','元素同时设置 width: 300px、min-width: 400px、max-width: 500px，最终宽度是？',
 '[{"key":"A","text":"400px，被 min-width 提升"},{"key":"B","text":"300px"},{"key":"C","text":"500px"},{"key":"D","text":"450px，取三者平均"}]',
 'A','计算顺序是先取 width，再用 min/max 夹紧：低于 min-width 就提升到 400，高于 max-width 就降到上限。当 min-width 大于 max-width 时 min-width 胜出。这正是弹性宽度的常用写法。',5),
(91,'single','关于负的 margin 值，下列说法正确的是？',
 '[{"key":"A","text":"负 margin 会把元素向相反方向拉动，并可减少它在布局中占据的空间"},{"key":"B","text":"CSS 不允许外边距取负值"},{"key":"C","text":"负 margin 等价于负的 padding"},{"key":"D","text":"负 margin 只影响背景绘制"}]',
 'A','负的 margin-top 与 margin-left 会把元素及后续内容向对应方向拉近，负的 margin-right 与 margin-bottom 会减少占位，常用于列间距微调；但它破坏常规流计算，过度使用容易造成重叠。',5),
(91,'judge','判断下列说法是否正确：设置 box-sizing: border-box 后，元素的 width 包含 content、padding 与 border，但不包含 margin。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。border-box 的 width 指边框盒尺寸，等于内容加 padding 加 border；margin 永远在盒子之外，不计入任何 box-sizing 的 width。因此两个 border-box 元素并排时仍需考虑 margin 的额外占位。',5),
(91,'judge','判断下列说法是否正确：给行内元素（如 span）设置 margin: 0 auto 可以让它水平居中。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。auto 的左右外边距只对有宽度可言的块级盒生效；行内元素宽度由内容决定且不受 width 控制。让行内内容居中应在父元素上写 text-align: center。',5),
(91,'judge','判断下列说法是否正确：父元素与它的第一个子元素之间也可能发生外边距折叠，条件是父元素没有 border、padding、行内内容且未创建 BFC。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。此时父子相邻的外边距会折叠并穿透到父元素之外，表现为「给子元素加 margin-top 却把整个父块一起推下去」。解决办法是给父元素加 padding 或 border、设置 overflow 非 visible，或改用 display: flow-root 创建 BFC。',5),
(91,'judge','判断下列说法是否正确：给元素设置 height: 100% 一定能使它的高度等于父元素的高度。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。百分比高度要求父元素有确定的高度值；父元素高度是 auto（由内容决定）时，子元素的 100% 会被当作 auto 而失效。要撑满视口高度，需让 html、body 等祖先逐级具备高度，或改用 vh 单位与 Flex、Grid 布局。',5),
(91,'multi','在标准盒模型（content-box）下，下列哪些属性会影响元素在水平方向实际占据的空间？',
 '[{"key":"A","text":"width"},{"key":"B","text":"padding"},{"key":"C","text":"border"},{"key":"D","text":"margin"},{"key":"E","text":"outline"}]',
 'ABCD','content-box 的实际占宽为 width 加 padding 加 border 加 margin；outline 绘制在盒外且不参与布局计算，box-shadow 同理。若改为 border-box，padding 与 border 已包含在 width 之内，只有 margin 额外占位。',8),
(91,'multi','下列哪些方式可以让元素创建一个新的 BFC（块级格式化上下文）？',
 '[{"key":"A","text":"display: flow-root"},{"key":"B","text":"overflow: hidden"},{"key":"C","text":"float: left"},{"key":"D","text":"position: absolute"},{"key":"E","text":"display: inline"}]',
 'ABCD','flow-root、overflow 取非 visible、浮动、绝对定位、inline-block、flex 或 grid 项目、contain: layout 等都会创建 BFC；BFC 内外的外边距不再折叠，且能包含内部浮动。display: inline 不会创建 BFC，也不接受宽高设置。',8),
(91,'multi','关于盒模型的常见布局问题与排查手段，下列说法正确的有？',
 '[{"key":"A","text":"元素比预期宽，通常是 content-box 叠加了 padding 与 border"},{"key":"B","text":"子元素的 margin-top 把父元素一起推下去，通常是外边距折叠"},{"key":"C","text":"用 outline 临时描边排查布局不会改变页面尺寸"},{"key":"D","text":"所有溢出问题都可以靠加大 width 解决"},{"key":"E","text":"box-sizing 只能用通配符选择器设置"}]',
 'ABC','前三项都是典型成因与安全的排查技巧；盲目加大 width 只会掩盖问题并破坏响应式。box-sizing 可以对任意选择器单独设置，只是实践中常用通配符统一设为 border-box 以减少心智负担。',8),
(92,'single','选择器 #nav .item:hover 的特异度（按 行内,id,类,元素 四元组表示）是？',
 '[{"key":"A","text":"(0, 1, 2, 0)"},{"key":"B","text":"(0, 1, 1, 0)"},{"key":"C","text":"(0, 2, 1, 0)"},{"key":"D","text":"(1, 0, 2, 0)"}]',
 'A','id 计 1，.item 与 :hover 都属于类级共 2，元素与伪元素为 0，故为 (0,1,2,0)。比较时从左到右逐位比，id 位一旦领先就无需再看后面，这就是「再多的类选择器也盖不过一个 id」的原因。',5),
(92,'single','下列选择器中特异度最低的是？',
 '[{"key":"A","text":"ul li a"},{"key":"B","text":".nav a"},{"key":"C","text":"#header a"},{"key":"D","text":"ul.nav li a"}]',
 'A','ul li a 只在元素位累加，为 (0,0,0,3)；.nav a 为 (0,0,1,1)，只要出现一个类就超过任意多个元素选择器。因此靠堆叠标签数量是无法提升优先级的。',5),
(92,'single','关于 !important，下列说法正确的是？',
 '[{"key":"A","text":"它让声明跳过常规层叠比较，但同为 !important 时仍按来源与特异度比较"},{"key":"B","text":"它一定胜过任何其它规则"},{"key":"C","text":"它会提升所在选择器的特异度"},{"key":"D","text":"它只能用在行内样式中"}]',
 'A','!important 属于重要性层面的加权，胜过普通声明（包括行内的普通声明）；但当两条声明都是 !important 时，仍要比较来源与特异度，所以可以用同样带 !important 且特异度更高的规则覆盖它。滥用会让样式难以维护。',5),
(92,'single','选择器 li:nth-child(2n) 会选中哪些元素？',
 '[{"key":"A","text":"父元素中序号为偶数的子元素，且该位置的元素必须是 li"},{"key":"B","text":"所有 li 中文本为偶数的那些"},{"key":"C","text":"第 2 个 li"},{"key":"D","text":"class 属性含 2n 的 li"}]',
 'A','nth-child 先按父元素的子元素序号计数，再检查该位置的元素是否匹配前面的选择器；若第 2 个子元素是 p，则这条规则不命中。想只按 li 自身的序号计算，应使用 nth-of-type。',5),
(92,'single','选择器 a[href^="https"] 的含义是？',
 '[{"key":"A","text":"href 属性值以 https 开头的 a 元素"},{"key":"B","text":"href 恰好等于 https 的 a 元素"},{"key":"C","text":"href 中包含 https 的 a 元素"},{"key":"D","text":"href 以 https 结尾的 a 元素"}]',
 'A','^= 是前缀匹配，$= 是后缀匹配，*= 是子串匹配，~= 匹配以空格分隔的词，|= 匹配以连字符分隔的词。属性选择器与类同级，特异度计入类位。',5),
(92,'single','要选中「紧接在 h2 后面的那个 p」，应使用下列哪个选择器？',
 '[{"key":"A","text":"h2 + p"},{"key":"B","text":"h2 ~ p"},{"key":"C","text":"h2 > p"},{"key":"D","text":"h2 p"}]',
 'A','+ 是相邻兄弟选择器，只匹配紧随其后的第一个同级元素；~ 匹配其后所有同级兄弟；空格是后代选择器，> 是子元素选择器。四者都不要求两个元素类型相同，只看 DOM 中的层级关系。',5),
(92,'single','关于 :is() 与 :where()，下列说法正确的是？',
 '[{"key":"A","text":":is() 取参数中最高的特异度，:where() 的特异度恒为 0"},{"key":"B","text":"两者的特异度都恒为 0"},{"key":"C","text":"两者都取参数中最高的特异度"},{"key":"D","text":"两者都不能接收选择器列表"}]',
 'A',':is(a, .b, #c) 的特异度等于参数中实际命中的最高者；:where() 一律算作 0，非常适合写可被轻松覆盖的基础样式。两者都接收容错的选择器列表——其中某个参数无效不会导致整条规则失效。',5),
(92,'single','两条特异度完全相同的规则设置了同一个属性，最终生效的是？',
 '[{"key":"A","text":"源码顺序靠后的那条"},{"key":"B","text":"源码顺序靠前的那条"},{"key":"C","text":"选择器更短的那条"},{"key":"D","text":"由浏览器随机决定"}]',
 'A','层叠的比较顺序是：来源与重要性、特异度、源码顺序，因此同权重时后写者胜出。这也是把重置样式放前面、主题样式放后面的原因；使用 @layer 还可以显式声明层的顺序来覆盖这一规则。',5),
(92,'single','下列属性中会由父元素继承给子元素的是？',
 '[{"key":"A","text":"color"},{"key":"B","text":"width"},{"key":"C","text":"margin"},{"key":"D","text":"border"}]',
 'A','color、font 系列、line-height、text-align、visibility 等会继承；width、height、margin、padding、border、background 这类盒模型与背景属性不继承。可用 inherit 关键字显式强制继承，initial 与 unset 用于重置。',5),
(92,'single','选择器 .card > * 的含义是？',
 '[{"key":"A","text":"选中 .card 的所有直接子元素，类型不限"},{"key":"B","text":"选中 .card 的所有后代元素"},{"key":"C","text":"选中 .card 自身"},{"key":"D","text":"选中页面上所有 .card"}]',
 'A','* 是通用选择器且特异度为 0，与 > 组合表示直接子元素，常用于给容器内的一级子项统一设置间距。它不会选中更深层的后代，也不会选中 .card 本身。',5),
(92,'judge','判断下列说法是否正确：:hover、:focus 等伪类与类选择器权重相同，都计入特异度的类位。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。伪类（包括 :hover、:nth-child() 以及 :not() 的参数）按类级计数；只有 ::before、::first-line 这类伪元素才按元素级计数。:not() 本身不计权重，但括号内选择器的权重会计入。',5),
(92,'judge','判断下列说法是否正确：选择器 div#main.content 与 #main 作用在元素上时，前者的特异度更高。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。前者为 (0,1,1,1)，后者为 (0,1,0,0)，多出来的类位与元素位使其胜出。特异度只看选择器自身的构成，与它能匹配到多少元素毫无关系。',5),
(92,'judge','判断下列说法是否正确：CSS 中后加载的外部样式表一定比先加载的外部样式表优先级高。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。源码顺序只在来源、重要性与特异度都相同的情况下才起作用；若先加载的表中使用了 id 选择器，仍会胜过后加载表中的类选择器。此外用 @layer 声明的层顺序还能反过来决定优先级。',5),
(92,'judge','判断下列说法是否正确：伪元素 ::before 生成的内容出现在元素内容的最前面，且必须配合 content 属性才会显示。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。没有 content（哪怕是空串 content: ""）伪元素就不会被生成；它作为元素的第一个子元素参与布局，默认是行内盒，可用 display 改成块级。生成的内容不属于 DOM，多数屏幕阅读器也不会朗读。',5),
(92,'multi','下列哪些选择器按「类级」计入特异度？',
 '[{"key":"A","text":".active"},{"key":"B","text":"[type=\\"text\\"]"},{"key":"C","text":":hover"},{"key":"D","text":"::before"},{"key":"E","text":"div"}]',
 'ABC','类选择器、属性选择器与伪类都属于类级（第 3 位）；伪元素 ::before 与元素名 div 属于元素级（第 4 位）。记住这条差异就能算出绝大多数规则的胜负。',8),
(92,'multi','关于属性选择器，下列搭配正确的有？',
 '[{"key":"A","text":"[href^=\\"https\\"] 匹配以 https 开头的值"},{"key":"B","text":"[href$=\\".pdf\\"] 匹配以 .pdf 结尾的值"},{"key":"C","text":"[title*=\\"css\\"] 匹配包含 css 的值"},{"key":"D","text":"[class~=\\"btn\\"] 匹配 class 列表中含 btn 的元素"},{"key":"E","text":"[href=\\"https\\"] 匹配所有包含 https 的链接"}]',
 'ABCD','^=、$=、*= 分别是前缀、后缀与子串匹配；~= 匹配以空格分隔的独立单词，适合处理 class 列表。精确匹配要用 =，它没有通配能力。它们区分大小写，需要忽略时可加 i 标志。',8),
(92,'multi','下列哪些做法有助于减少样式冲突、提升可维护性？',
 '[{"key":"A","text":"尽量使用低特异度的类选择器"},{"key":"B","text":"用 @layer 规划样式的层顺序"},{"key":"C","text":"避免滥用 !important 与 id 选择器"},{"key":"D","text":"大量使用 !important 以确保样式生效"},{"key":"E","text":"用行内 style 覆盖所有组件样式"}]',
 'ABC','低特异度配合明确的层顺序，让覆盖变得可预期；一旦引入 id 选择器与 !important，后续覆盖只能不断加码，最终失控。行内样式同样难以覆盖且无法复用。',8),
(93,'single','flex-direction: row-reverse 的效果是？',
 '[{"key":"A","text":"主轴仍是水平方向，但起点在右侧，项目从右向左排列"},{"key":"B","text":"主轴变为垂直方向"},{"key":"C","text":"项目顺序反转而起点位置不变"},{"key":"D","text":"与 row 完全等价"}]',
 'A','row-reverse 只交换 main-start 与 main-end 的位置，视觉顺序随之反向，但 DOM 顺序与 Tab 焦点顺序不变，因此可能造成「视觉顺序与阅读顺序不一致」的无障碍问题。要用垂直方向应写 column。',5),
(93,'single','在默认的 flex-direction: row 容器中，justify-content 与 align-items 分别控制什么？',
 '[{"key":"A","text":"沿主轴（水平）与沿交叉轴（垂直）的对齐"},{"key":"B","text":"两者都控制水平方向对齐"},{"key":"C","text":"justify-content 控制垂直、align-items 控制水平"},{"key":"D","text":"两者都控制垂直方向对齐"}]',
 'A','justify-content 沿主轴分配剩余空间，align-items 沿交叉轴对齐单行内的项目；多行整体在交叉轴上的分布由 align-content 控制，且它在只有一行（nowrap）时不生效。',5),
(93,'single','flex: 1 等价于下列哪一组值？',
 '[{"key":"A","text":"flex-grow: 1; flex-shrink: 1; flex-basis: 0%"},{"key":"B","text":"flex-grow: 1; flex-shrink: 0; flex-basis: auto"},{"key":"C","text":"flex-grow: 1; flex-shrink: 1; flex-basis: auto"},{"key":"D","text":"flex-grow: 0; flex-shrink: 1; flex-basis: 0%"}]',
 'A','单值数字形式的 flex: 1 会把 flex-basis 解析为 0%（而不是 auto），所以所有项目从 0 开始按 grow 比例瓜分全部空间，得到真正的等分；basis 为 auto 的写法是 flex: auto。这是最容易记错的一处细节。',5),
(93,'single','Flex 项目的默认 flex-shrink 值是多少，它在什么情况下起作用？',
 '[{"key":"A","text":"默认 1；空间不足时项目按比例收缩"},{"key":"B","text":"默认 0；项目永不收缩"},{"key":"C","text":"默认 auto；按内容自动收缩"},{"key":"D","text":"默认 1；空间富余时自动放大"}]',
 'A','默认相当于 flex: 0 1 auto，即不放大、可收缩、基准尺寸取内容。收缩按比例进行且受最小尺寸限制，因此内容的最小尺寸可能导致溢出；放大由 flex-grow 控制，默认值为 0。',5),
(93,'single','容器设置 flex-wrap: wrap 且产生了 3 行，要让这 3 行在交叉轴上分散对齐，应使用？',
 '[{"key":"A","text":"align-content: space-between"},{"key":"B","text":"align-items: space-between"},{"key":"C","text":"justify-content: space-between"},{"key":"D","text":"align-self: space-between"}]',
 'A','align-content 控制行与行在交叉轴上的分布，只在换行产生多行时才有效；align-items 控制单行内项目的对齐，且不接受 space-between 这类分配空间的值。单行时 align-content 完全无效果。',5),
(93,'single','要让某一个 Flex 项目在交叉轴上的对齐方式与其它项目不同，应使用？',
 '[{"key":"A","text":"align-self"},{"key":"B","text":"align-items"},{"key":"C","text":"align-content"},{"key":"D","text":"justify-self"}]',
 'A','align-self 写在项目上，用于覆盖容器的 align-items；justify-self 在 Flex 布局中不起作用，主轴上单个项目的偏移应使用自动 margin 或调整 justify-content。',5),
(93,'single','在 Flex 容器中把某个项目推到最右侧（由它吃掉剩余空间），简单有效的写法是？',
 '[{"key":"A","text":"给该项目设置 margin-left: auto"},{"key":"B","text":"给容器设置 justify-content: flex-end"},{"key":"C","text":"给该项目设置 float: right"},{"key":"D","text":"给该项目设置 position: absolute"}]',
 'A','Flex 项目上的 auto 外边距会吸收主轴方向的剩余空间，把后续内容推向另一侧，且只影响这一个项目；justify-content: flex-end 会把所有项目一起推到右端。浮动对 Flex 项目无效。',5),
(93,'single','Flex 项目中放入很长的不可断行文本导致容器溢出，最常见的原因是？',
 '[{"key":"A","text":"项目的最小尺寸默认为 auto，阻止其收缩到内容宽度以下"},{"key":"B","text":"flex-grow 设置得太大"},{"key":"C","text":"flex-wrap 默认换行"},{"key":"D","text":"justify-content 设置错误"}]',
 'A','Flex 项目的 min-width 默认解析为 auto，即不小于内容的最小尺寸，因此即使 shrink 为 1 也不会被压缩到内容以下。解决办法是设置 min-width: 0，再配合溢出处理或断词规则让它可收缩。',5),
(93,'single','关于 order 属性，下列说法正确的是？',
 '[{"key":"A","text":"order 改变视觉排列顺序，但不改变 DOM 顺序与键盘焦点顺序"},{"key":"B","text":"order 会改变 DOM 结构"},{"key":"C","text":"order 只能取正整数"},{"key":"D","text":"order 的默认值为 1"}]',
 'A','order 默认为 0，可取负值，值越小越靠前；它只影响视觉顺序，屏幕阅读器与 Tab 键仍按 DOM 顺序访问。用 order 做大幅重排会造成无障碍问题，必要时应当调整 DOM 本身。',5),
(93,'single','容器设置 flex-direction: column; justify-content: center; align-items: center 对单个子项的效果是？',
 '[{"key":"A","text":"子项在垂直与水平方向上都居中"},{"key":"B","text":"只在垂直方向居中"},{"key":"C","text":"只在水平方向居中"},{"key":"D","text":"子项被拉伸填满容器"}]',
 'A','column 时主轴是垂直方向，justify-content: center 使其垂直居中，align-items: center 使其水平居中，两者配合即完全居中。关键是记住主轴与交叉轴由 flex-direction 决定，并非固定为水平或垂直。',5),
(93,'judge','判断下列说法是否正确：Flex 容器中被设置为 position: absolute 的子元素仍会作为 Flex 项目参与主轴空间分配。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。绝对定位的子元素脱离文档流，不再是 flex item，不受 flex-grow 与 flex-shrink 影响，也不占主轴空间；它的静态位置可由容器的对齐属性决定。要参与布局应使用普通静态定位。',5),
(93,'judge','判断下列说法是否正确：在 flex-direction: column 的容器中，给项目设置 width: 200px 会决定它在主轴上的初始尺寸。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。主轴为垂直方向时对应的尺寸是 height，主轴基准尺寸由 flex-basis（缺省时取 height）决定；width 此时属于交叉轴尺寸，由 align-items（默认 stretch）与 width 共同决定。判断基准尺寸前必须先弄清轴的方向。',5),
(93,'judge','判断下列说法是否正确：flex-wrap: nowrap 是默认值，即使项目总宽超过容器也不会换行，可能导致内容溢出。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。nowrap 下所有项目排在同一行，空间不足时按 flex-shrink 收缩，若无法继续收缩（shrink 为 0 或受最小尺寸限制）就会溢出容器。需要换行必须显式写 flex-wrap: wrap。',5),
(93,'judge','判断下列说法是否正确：align-items 的默认值为 stretch，因此交叉轴尺寸为 auto 的项目会被拉伸填满容器。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。stretch 会让项目在交叉轴上撑满容器，前提是该项目交叉轴方向的尺寸为 auto；一旦显式设置了 height（或交叉轴为水平时设置了 width），就以该尺寸为准不再拉伸。align-self 可在项目上单独覆盖。',5),
(93,'multi','下列哪些属性应写在 Flex 容器（父元素）上？',
 '[{"key":"A","text":"flex-direction"},{"key":"B","text":"justify-content"},{"key":"C","text":"align-items"},{"key":"D","text":"align-self"},{"key":"E","text":"flex-grow"}]',
 'ABC','容器负责方向与整体对齐，包括 flex-direction、flex-wrap、justify-content、align-items、align-content；项目负责自身的伸缩与单独对齐，包括 flex 系列、align-self 与 order。',8),
(93,'multi','关于 flex 简写，下列说法正确的有？',
 '[{"key":"A","text":"flex: 1 等价于 1 1 0%"},{"key":"B","text":"flex: auto 等价于 1 1 auto"},{"key":"C","text":"flex: none 等价于 0 0 auto"},{"key":"D","text":"flex: 0 等价于 0 1 0%"},{"key":"E","text":"flex: 2 等价于 2 0 auto"}]',
 'ABCD','单值数字形式把 flex-basis 解析为 0%、shrink 默认为 1，所以 flex: 2 实际是 2 1 0%，而不是 2 0 auto。另外 initial 为 0 1 auto（即默认行为），auto 为 1 1 auto，none 为 0 0 auto。',8),
(93,'multi','下列哪些写法有助于解决 Flex 布局中的内容溢出问题？',
 '[{"key":"A","text":"给项目设置 min-width: 0 使其可以被压缩"},{"key":"B","text":"配合 overflow 与文本截断规则处理长文本"},{"key":"C","text":"空间不足时改用 flex-wrap: wrap 让项目换行"},{"key":"D","text":"把 flex-shrink 设为 0 以保持项目原始尺寸"},{"key":"E","text":"无条件给容器加 white-space: nowrap"}]',
 'ABC','溢出常源自自动最小尺寸与不可断行的长文本：min-width: 0 打开收缩空间，再用溢出裁剪或换行兜底。shrink 设为 0 会阻止收缩、加剧溢出，nowrap 则让文本更不可能换行。',8),
(94,'single','grid-template-columns: repeat(3, 1fr) 的含义是？',
 '[{"key":"A","text":"创建 3 列，每列等分剩余可用空间"},{"key":"B","text":"创建 3 行"},{"key":"C","text":"创建 1 列并占据 3 份空间"},{"key":"D","text":"创建 3 列且每列固定 1px"}]',
 'A','repeat(次数, 轨道尺寸) 是重复简写，1fr 表示剩余可用空间的一份，三列都是 1fr 即三等分。fr 分配的是扣除固定轨道与 gap 之后剩余的空间，与百分比不同（百分比按容器宽度计算，与 gap 相加可能溢出）。',5),
(94,'single','声明 gap: 10px 20px 中两个值分别表示？',
 '[{"key":"A","text":"行间距 10px、列间距 20px"},{"key":"B","text":"列间距 10px、行间距 20px"},{"key":"C","text":"上下间距 10px、左右间距 20px"},{"key":"D","text":"内边距 10px、外边距 20px"}]',
 'A','gap 的语法与 margin 一致：单值同时作用于行列，双值为 row-gap 后 column-gap，即先行后列。gap 只在网格轨道之间产生间距，不会出现在容器边缘，因此比给每个项目加 margin 更好控制。',5),
(94,'single','给项目写 grid-column: 2 / 4 表示？',
 '[{"key":"A","text":"从第 2 条网格线开始到第 4 条网格线结束，占据两列"},{"key":"B","text":"占据第 2 到第 4 共三列"},{"key":"C","text":"放在第 2 行第 4 列"},{"key":"D","text":"只占据第 4 列"}]',
 'A','这里的值是网格线编号而不是列序号：从第 2 条线到第 4 条线共跨越第 2、3 两列。也可写成 grid-column: 2 / span 2，或用负线号 -1 表示最后一条线。务必区分「线号」与「轨道序号」。',5),
(94,'single','repeat(auto-fill, minmax(200px, 1fr)) 与 auto-fit 的关键区别体现在？',
 '[{"key":"A","text":"剩余空间富余时 auto-fit 会折叠空轨道让现有列拉伸，auto-fill 保留空轨道"},{"key":"B","text":"两者行为完全相同"},{"key":"C","text":"auto-fill 会自动换行"},{"key":"D","text":"auto-fit 只能用于行轨道"}]',
 'A','两者都会尽可能放入满足最小尺寸的轨道，但轨道数不足时 auto-fit 把空的重复轨道收拢为 0，并让 1fr 的列扩张填满容器；auto-fill 保留这些空轨道，列宽保持不变。自适应卡片网格通常用 auto-fit。',5),
(94,'single','项目被放置到显式定义的网格之外时，多出来的轨道尺寸如何确定？',
 '[{"key":"A","text":"由 grid-auto-rows 或 grid-auto-columns 决定，默认 auto 由内容撑开"},{"key":"B","text":"尺寸为 0 因而不可见"},{"key":"C","text":"自动复制最后一列的尺寸"},{"key":"D","text":"会导致整条声明失效"}]',
 'A','超出显式网格的部分属于隐式网格，默认尺寸为 auto；可用 grid-auto-rows: 100px 或 minmax() 统一控制。grid-auto-flow 决定隐式轨道按行还是按列添加，加 dense 可回填空隙。',5),
(94,'single','place-items: center 等价于下列哪一组声明？',
 '[{"key":"A","text":"align-items: center; justify-items: center"},{"key":"B","text":"justify-content: center; align-content: center"},{"key":"C","text":"align-self: center"},{"key":"D","text":"justify-self: center"}]',
 'A','place-items 是 align-items 与 justify-items 的简写（先块轴后行轴），控制项目在其网格区域内的对齐；justify-content 与 align-content 控制的是整个网格轨道在容器中的分布，二者是不同层次的概念。',5),
(94,'single','使用 grid-template-areas 时，下列要求正确的是？',
 '[{"key":"A","text":"每个字符串描述一行的区域划分，同名的相邻单元格必须构成矩形"},{"key":"B","text":"同名单元格可以拼成任意形状，如 L 形"},{"key":"C","text":"每个命名区域只能占据一个单元格"},{"key":"D","text":"必须先用 grid-template-rows 定义行才能使用"}]',
 'A','同名单元格必须连通且形成矩形，否则整条模板声明无效；用 . 表示留空的单元格。配合项目上的 grid-area 把元素放进对应区域，可读性很好，适合页面整体布局。',5),
(94,'single','grid-template-columns: minmax(200px, 1fr) 300px 中第一列的宽度规则是？',
 '[{"key":"A","text":"最小 200px，最大可伸展占满剩余空间"},{"key":"B","text":"固定为 200px"},{"key":"C","text":"固定为 1fr"},{"key":"D","text":"在 200px 与 300px 之间取值"}]',
 'A','minmax(最小值, 最大值) 定义轨道尺寸区间：下限 200px 保证不被压垮，上限 1fr 使它吃掉扣除 300px 与 gap 后的剩余空间。注意最小值不能写 fr 单位，fr 只能作为区间的上限。',5),
(94,'single','grid-template-columns: 1fr 1fr 中某一列放入很长的不可断行内容，可能出现什么情况？',
 '[{"key":"A","text":"该列被内容撑开而超出等分宽度，因为 fr 的最小尺寸默认为 auto"},{"key":"B","text":"两列严格等分，内容被自动压缩"},{"key":"C","text":"内容被自动截断"},{"key":"D","text":"网格声明无效"}]',
 'A','1fr 的完整含义是 minmax(auto, 1fr)，最小值取 auto，因此内容的最小尺寸会撑开轨道造成溢出。要严格等分应写 minmax(0, 1fr)，再配合 min-width: 0 与断词或裁剪处理内容。这是 Grid 最常见的溢出陷阱。',5),
(94,'single','给项目写 grid-row: span 2 的含义是？',
 '[{"key":"A","text":"该项目在纵向跨越 2 个行轨道"},{"key":"B","text":"该项目放在第 2 行"},{"key":"C","text":"该项目横向跨越 2 个列轨道"},{"key":"D","text":"该项目重复渲染 2 次"}]',
 'A','span n 表示跨越 n 条轨道，可与起始位置配合使用（如 grid-row: 2 / span 2）；单独写 span 2 时由自动放置算法决定起点。跨越的轨道数等于结束线减起始线，务必分清线号与轨道序号。',5),
(94,'judge','判断下列说法是否正确：Grid 中项目默认按行依次自动放置，可用 grid-auto-flow: column 改为按列放置。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。默认自动放置按行推进，grid-auto-flow 可取 row、column，也可加 dense 启用紧密填充来回填前面留下的空隙。dense 会造成视觉顺序与 DOM 顺序不一致，对无障碍不友好，应谨慎使用。',5),
(94,'judge','判断下列说法是否正确：grid-template-columns 与 grid-template-rows 定义的轨道数决定网格行列数，超出的项目一律不显示。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。超出显式网格的项目会进入隐式网格，由 grid-auto-rows 或 grid-auto-columns 决定尺寸并照常显示。隐式轨道同样是网格的一部分，也计入网格线编号，只有在无尺寸且内容为空时才看不见。',5),
(94,'judge','判断下列说法是否正确：Grid 是二维布局（同时控制行与列），而 Flexbox 是一维布局（一次只沿一条轴排列），这是二者的核心差异之一。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。Grid 先划分二维轨道再放置项目，适合页面级布局与卡片墙；Flexbox 沿单轴排列、靠换行模拟第二维，适合组件内部的一维分布。二者可以嵌套使用，并不互斥。',5),
(94,'judge','判断下列说法是否正确：给网格项目设置 position: absolute 后，它仍会占据一个网格区域并影响其它项目的自动放置。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。绝对定位的项目脱离网格流，不参与自动放置也不占位（容器需先成为其包含块）；若显式指定了 grid-area，该区域可作为定位参照，但不会影响其它项目的排布。',5),
(94,'multi','下列哪些是合法的 grid-template-columns 取值？',
 '[{"key":"A","text":"repeat(3, 100px)"},{"key":"B","text":"minmax(100px, 1fr)"},{"key":"C","text":"200px 1fr auto"},{"key":"D","text":"1fr min-content"},{"key":"E","text":"span 2"}]',
 'ABCD','轨道列表可以使用长度、百分比、fr、auto、min-content、max-content、minmax() 与 repeat()；span 2 是用于项目放置的关键字，不能作为轨道尺寸出现在模板定义中。',8),
(94,'multi','关于 fr 单位，下列说法正确的有？',
 '[{"key":"A","text":"fr 分配的是扣除固定轨道与 gap 之后的剩余空间"},{"key":"B","text":"minmax(0, 1fr) 可强制轨道收缩到 0，避免被内容撑开"},{"key":"C","text":"fr 可以与 px、auto 等混用"},{"key":"D","text":"fr 等价于百分比，按容器宽度直接换算"},{"key":"E","text":"fr 的最小值默认为 auto，因此存在内容溢出风险"}]',
 'ABCE','fr 只分配剩余空间，与百分比不同（百分比按容器尺寸算，与 gap 相加可能溢出），且可与固定轨道混用。由于最小值默认 auto，长内容可能撑开轨道，需要严格等分时应写 minmax(0, 1fr)。',8),
(94,'multi','下列哪些属性用于把网格项目放入指定区域？',
 '[{"key":"A","text":"grid-column"},{"key":"B","text":"grid-row"},{"key":"C","text":"grid-area"},{"key":"D","text":"grid-template-areas"},{"key":"E","text":"grid-auto-flow"}]',
 'ABC','写在项目上的 grid-column、grid-row 与 grid-area（可配合容器上的命名区域）决定它占据哪些轨道；grid-template-areas 与 grid-auto-flow 属于容器属性，分别用于定义区域模板与指定自动放置方向。',8),
(95,'single','媒体查询 @media (min-width: 768px) 的含义是？',
 '[{"key":"A","text":"当视口宽度大于等于 768px 时应用其中的样式"},{"key":"B","text":"视口宽度小于 768px 时应用"},{"key":"C","text":"某个元素的宽度大于 768px 时应用"},{"key":"D","text":"屏幕分辨率大于 768px 时应用"}]',
 'A','min-width 与 max-width 针对的是视口宽度且包含等号，min-width: 768px 表示宽度不小于 768px。它判断的是浏览器视口而非某个元素宽度，元素级响应应使用容器查询 @container。',5),
(95,'single','采用移动优先（mobile first）策略时，媒体查询通常写成什么形式？',
 '[{"key":"A","text":"先写面向小屏的基础样式，再用 min-width 逐级增强"},{"key":"B","text":"先写桌面样式，再用 max-width 向下覆盖"},{"key":"C","text":"全部写在 max-width 查询里"},{"key":"D","text":"完全不使用媒体查询"}]',
 'A','移动优先让默认样式面向窄屏，再用 min-width 断点向上增强，CSS 体积更小、渐进增强更自然；桌面优先则用 max-width 向下适配。同一项目应保持一种方向，混用会造成覆盖关系混乱。',5),
(95,'single','响应式设计中的断点应依据什么来确定？',
 '[{"key":"A","text":"内容在何处开始变得拥挤或难读，而不是照搬某款设备的尺寸"},{"key":"B","text":"主流手机与平板的固定屏幕宽度"},{"key":"C","text":"设计师给出的所有设计稿尺寸"},{"key":"D","text":"固定使用 768px 与 992px 两个值"}]',
 'A','设备尺寸年年变化，按内容需要设置断点才能长期可维护。通常先让布局用 fr、百分比、clamp 等弹性手段自适应，只在结构确实需要改变的地方加断点，断点数量宜少不宜多。',5),
(95,'single','下列单位中，会随根元素字号变化而缩放的是？',
 '[{"key":"A","text":"rem"},{"key":"B","text":"em"},{"key":"C","text":"px"},{"key":"D","text":"vw"}]',
 'A','rem 以根元素（html）的 font-size 为基准，便于整体缩放与尊重用户的字号偏好；em 以当前元素继承来的字号为基准，在组件内部易随层级复合变化；vw 与 vh 是视口百分比单位，px 是绝对单位。',5),
(95,'single','移动浏览器上 100vh 常导致内容被地址栏遮挡或出现多余滚动，原因是？',
 '[{"key":"A","text":"100vh 取的是地址栏收起时的最大视口高度，与当前可视区域不一致"},{"key":"B","text":"vh 单位是无效单位"},{"key":"C","text":"移动浏览器完全不支持 vh"},{"key":"D","text":"100vh 在移动端等价于 100%"}]',
 'A','移动端的 vh 对应「大视口」高度，地址栏可见时实际可视区更小。可用动态视口单位 dvh（如 100dvh）精确控制，也有 svh 与 lvh 分别对应小视口与大视口，旧浏览器可用 JS 设置自定义属性兼容。',5),
(95,'single','让图片在小屏幕上自动缩放且不超出容器，最常用的写法是？',
 '[{"key":"A","text":"img { max-width: 100%; height: auto; }"},{"key":"B","text":"img { width: 100%; }"},{"key":"C","text":"img { width: fixed; }"},{"key":"D","text":"img { overflow: hidden; }"}]',
 'A','max-width: 100% 限制图片不超过父容器宽度，height: auto 保持原始宽高比不变形；直接写 width: 100% 会把小图强行放大而失真。配合 srcset 还能按屏幕挑选合适资源。',5),
(95,'single','声明 font-size: clamp(16px, 4vw, 24px) 的效果是？',
 '[{"key":"A","text":"字号随视口宽度变化，但被限制在 16px 到 24px 之间，首选值为 4vw"},{"key":"B","text":"字号固定为 16px"},{"key":"C","text":"字号固定为 24px"},{"key":"D","text":"字号恒等于 4vw 不再变化"}]',
 'A','clamp(最小值, 首选值, 最大值) 把首选值夹在区间内，实现无需媒体查询的流体排版；它同样可用于 width、padding 与 gap。在极大或极小屏上首选值会被两端夹住，这正是我们想要的约束效果。',5),
(95,'single','要根据用户系统的深色模式偏好切换配色，应使用的媒体特性是？',
 '[{"key":"A","text":"@media (prefers-color-scheme: dark)"},{"key":"B","text":"@media (dark-mode)"},{"key":"C","text":"@media (color: dark)"},{"key":"D","text":"@media screen and (dark)"}]',
 'A','prefers-color-scheme 取值为 dark 或 light，常配合 CSS 变量整体换肤。同类偏好查询还有 prefers-reduced-motion（减少动画）与 prefers-contrast（更高对比度），它们都属于无障碍友好的增强手段。',5),
(95,'single','要为打印输出单独设置样式，应使用？',
 '[{"key":"A","text":"@media print"},{"key":"B","text":"@media screen"},{"key":"C","text":"@page print"},{"key":"D","text":"@media paper"}]',
 'A','print 媒体类型只在打印或打印预览时生效，常用于隐藏导航与广告、显示链接地址、避免深色背景浪费墨水；@page 则用于设置页边距等页面盒属性，两者用途不同。',5),
(95,'single','关于容器查询（container query），下列说法正确的是？',
 '[{"key":"A","text":"它依据组件所在容器的尺寸而非视口尺寸来决定样式"},{"key":"B","text":"它是媒体查询的别名，写法完全一样"},{"key":"C","text":"它只能查询视口宽度"},{"key":"D","text":"它必须写在媒体查询内部才能生效"}]',
 'A','容器查询先用 container-type（如 inline-size）声明容器，再用 @container (min-width: ...) 匹配，使同一组件在不同宽度的位置自适应，是组件化响应的关键能力；媒体查询仍适合整页与设备级特性。',5),
(95,'judge','判断下列说法是否正确：媒体查询只在条件满足时让规则生效，并不改变其中选择器的特异度。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。@media 只决定规则是否参与层叠，不影响特异度计算，因此媒体查询内外同样选择器的胜负仍取决于源码顺序。把媒体查询块写在文件末尾正是利用这一点来覆盖前面的普通规则。',5),
(95,'judge','判断下列说法是否正确：媒体类型 screen 与 print 互斥，写在 @media screen 中的样式在打印时不会被应用。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。未指定媒体类型时默认为 all（匹配全部）；显式写 screen 后打印场景不再匹配这些规则。日常开发通常省略类型只写特性，以免误伤打印、投影等场景。',5),
(95,'judge','判断下列说法是否正确：响应式布局只要用了百分比宽度，就再也不需要媒体查询。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。百分比与弹性单位能让元素连续缩放，但当布局结构需要改变（如侧栏从横排改为堆叠、导航变成汉堡菜单）时仍要靠断点切换。正确做法是先弹性、后断点，二者配合而非互相替代。',5),
(95,'judge','判断下列说法是否正确：em 单位总是等于 16px，因为浏览器默认字号是 16px。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。em 相对于当前元素继承来的字号计算，父级字号一变它就变，多层嵌套还会复合放大（这正是 padding 与 margin 用 em 时的常见陷阱）；只有用在根元素上时才等于默认字号，稳定的全局单位应选 rem。',5),
(95,'multi','下列哪些属于编写响应式样式时推荐的弹性手段？',
 '[{"key":"A","text":"使用 minmax() 与 fr 定义 Grid 轨道"},{"key":"B","text":"使用 flex-wrap 让项目在空间不足时自然换行"},{"key":"C","text":"使用 clamp() 实现流体字号"},{"key":"D","text":"为所有元素写死 px 宽高"},{"key":"E","text":"只依赖固定断点切换布局"}]',
 'ABC','弹性手段让组件在尺寸区间内连续自适应，从而减少对断点的依赖；写死 px 或只靠断点都会让中间尺寸出现断层。实践中的原则是先弹性、后断点。',8),
(95,'multi','关于视口单位，下列说法正确的有？',
 '[{"key":"A","text":"vw 与 vh 分别表示视口宽度与高度的百分之一"},{"key":"B","text":"vmin 取 vw 与 vh 中较小者，vmax 取较大者"},{"key":"C","text":"dvh 反映动态视口高度，更适合移动端全屏布局"},{"key":"D","text":"vw 会随着页面滚动而变化"},{"key":"E","text":"vh 在任何移动浏览器上都等于当前可见高度"}]',
 'ABC','视口单位只与视口尺寸相关，不随滚动改变；vh 在移动端对应大视口（地址栏收起时），与当前可见高度并不一致，需要精确控制时应改用 svh、lvh 或 dvh。',8),
(95,'multi','下列哪些媒体特性可用于提升无障碍体验？',
 '[{"key":"A","text":"prefers-reduced-motion"},{"key":"B","text":"prefers-color-scheme"},{"key":"C","text":"prefers-contrast"},{"key":"D","text":"prefers-device-width"},{"key":"E","text":"prefers-font-size"}]',
 'ABC','prefers-reduced-motion 用于减弱或关闭动画（照顾前庭功能障碍用户），prefers-color-scheme 尊重深浅色偏好，prefers-contrast 适配更高的对比度需求；后两项并不是真实存在的媒体特性。',8);

-- ---------- rest-db.js ----------
INSERT INTO question (knowledge_id, type, title, options, answer, analysis, score) VALUES
(108,'single','关系 R 有 10 个元组、5 个属性，关系 S 有 20 个元组、4 个属性，则 R 与 S 的笛卡尔积的元组数与属性数分别是？',
 '[{"key":"A","text":"200 个元组、9 个属性"},{"key":"B","text":"200 个元组、20 个属性"},{"key":"C","text":"30 个元组、9 个属性"},{"key":"D","text":"200 个元组、5 个属性"}]',
 'A','笛卡尔积把 R 的每个元组与 S 的每个元组两两配对，元组数为 10 × 20 = 200；属性直接拼接且不去掉重名列，属性数为 5 + 4 = 9。',5),
(108,'single','自然连接与等值连接的主要区别是？',
 '[{"key":"A","text":"自然连接要求相等的分量必须有相同属性名，且结果中公共属性只保留一列"},{"key":"B","text":"自然连接不要求任何属性相等"},{"key":"C","text":"等值连接会自动去掉重复列"},{"key":"D","text":"两者完全等价，只是写法不同"}]',
 'A','等值连接可以是任意属性间的相等比较，公共列会出现两次；自然连接是特殊的等值连接，只在同名属性上比较并合并掉重复的列。',5),
(108,'single','要查询「选修了全部课程的学生学号」，最合适的关系代数运算是？',
 '[{"key":"A","text":"选择"},{"key":"B","text":"投影"},{"key":"C","text":"除运算"},{"key":"D","text":"并运算"}]',
 'C','带「全部、所有」这类量词的查询用除法：被除关系是选课表投影出的 (学号, 课程号)，除关系是全部课程号，商即为满足全部课程的学生学号。',5),
(108,'single','关系代数中不能由其它运算导出的五种基本运算是？',
 '[{"key":"A","text":"并、差、笛卡尔积、选择、投影"},{"key":"B","text":"并、交、连接、选择、投影"},{"key":"C","text":"并、差、连接、除、选择"},{"key":"D","text":"交、连接、除、选择、投影"}]',
 'A','并、差、笛卡尔积、选择、投影是基本运算；交可由差导出（R∩S = R - (R - S)），连接由笛卡尔积加选择导出，除可由差、投影、笛卡尔积导出。',5),
(108,'single','关于关系的规范化要求，下列说法属于关系基本性质的是？',
 '[{"key":"A","text":"每一列的分量必须取自同一个域，且分量不可再分"},{"key":"B","text":"行的先后顺序有意义，代表元组的重要程度"},{"key":"C","text":"允许出现两个完全相同的元组"},{"key":"D","text":"列的顺序必须按主码在前排列"}]',
 'A','关系要求列同质、分量原子（满足 1NF）、元组不重复、行序与列序无关。元组可重复的是"多集"，不是关系。',5),
(108,'single','在关系模型中，外码的取值规则是？',
 '[{"key":"A","text":"必须与被参照关系中某个元组的主码值相等"},{"key":"B","text":"要么取空值，要么等于被参照关系中某个元组的主码值"},{"key":"C","text":"可以取任意值，不受约束"},{"key":"D","text":"必须唯一且非空"}]',
 'B','这是参照完整性：外码要么为空（表示尚无对应），要么必须能在被参照关系的主码中找到；空值是被允许的例外情形。',5),
(108,'single','对关系做投影运算后，结果关系的元组数可能减少，其原因是？',
 '[{"key":"A","text":"投影会过滤掉不满足条件的行"},{"key":"B","text":"去掉某些列后可能出现重复行，投影会自动去重"},{"key":"C","text":"投影会随机抽样"},{"key":"D","text":"投影改变了属性的域"}]',
 'B','投影先删列，关系的元组唯一性要求再删掉由此产生的重复行；所以投影后元组数 ≤ 原元组数，不能默认相等。',5),
(108,'single','左外连接（LEFT OUTER JOIN）的结果特点是？',
 '[{"key":"A","text":"只保留左右两边都能匹配的元组"},{"key":"B","text":"保留左边关系的全部元组，右表无匹配处填 NULL"},{"key":"C","text":"保留右边关系的全部元组"},{"key":"D","text":"结果元组数一定等于左关系元组数"}]',
 'B','左外连接以左关系为主体，未被匹配到的左元组在右表对应列上填 NULL，因此结果行数 ≥ 左表行数；内连接才会丢弃不匹配的行。',5),
(108,'single','关系模型的三类完整性约束中，实体完整性指的是？',
 '[{"key":"A","text":"主属性不能取空值"},{"key":"B","text":"外码必须与被参照主码对应"},{"key":"C","text":"属性值必须满足用户定义的取值范围"},{"key":"D","text":"关系中不允许有重复属性名"}]',
 'A','实体完整性要求每个关系有主码且主码属性（主属性）非空、唯一，保证实体可区分；参照完整性管外码，用户定义完整性管取值域约束。',5),
(108,'single','关于候选码与主码的说法，正确的是？',
 '[{"key":"A","text":"一个关系可以有多个候选码，但只能选定一个作为主码"},{"key":"B","text":"一个关系只能有一个候选码"},{"key":"C","text":"主码可以取空值"},{"key":"D","text":"候选码必须包含关系中的全部属性"}]',
 'A','候选码是能唯一标识元组且不含多余属性的属性集，可以有多个；从中选一个作主码。候选码中的属性叫主属性，其余为非主属性。',5),
(108,'judge','对两个关系做并运算，要求它们具有相同数目的属性且相应属性取自同一个域。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。这就是并相容（同元、同域）条件，不满足则并、交、差都无意义，这也是关系代数与集合运算的关键差别。',5),
(108,'judge','两个关系做自然连接后，结果的属性数等于两个关系属性数之和。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。自然连接会把参与比较的公共属性合并成一组，结果属性数是两关系属性数之和减去公共属性数。',5),
(108,'judge','选择运算是从行的角度挑出满足条件的元组，投影运算是从列的角度选取若干属性。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。选择 σ 水平切（选行），投影 π 垂直切（选列），这是两类最基本的单目运算。',5),
(108,'judge','除运算的结果关系的属性，是被除关系中除去与除关系公共部分之后剩下的属性。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。设 R ÷ S，结果属性为 R 的属性集减去 S 的属性集，值则是那些与 S 中所有元组都有配对的 R 中元组。',5),
(108,'multi','下列哪些属于关系代数的基本运算？',
 '[{"key":"A","text":"并"},{"key":"B","text":"差"},{"key":"C","text":"笛卡尔积"},{"key":"D","text":"连接"}]',
 'ABC','连接不是基本运算，它可由笛卡尔积加选择表示：R ⋈ S = σ_条件(R × S)。五个基本运算是并、差、笛卡尔积、选择、投影。',8),
(108,'multi','关于关系模型的外码，下列说法正确的有？',
 '[{"key":"A","text":"外码所在的关系称为参照关系"},{"key":"B","text":"外码与被参照关系的主码必须定义在同一个域上"},{"key":"C","text":"外码属性可以为空值"},{"key":"D","text":"外码在本关系中必须唯一"}]',
 'ABC','外码不要求唯一（如订单表中的客户号可重复），它只在被参照关系那侧对应唯一主码值；但域必须一致，否则无法比较。',8),
(108,'multi','关于关系代数中的并、交、差运算，下列说法正确的有？',
 '[{"key":"A","text":"交运算满足交换律，R ∩ S = S ∩ R"},{"key":"B","text":"差运算不满足交换律，R - S 一般不等于 S - R"},{"key":"C","text":"并运算会自动去掉重复元组"},{"key":"D","text":"交运算可以由差运算导出"}]',
 'ABCD','R ∩ S = R - (R - S)，因此交不是基本运算；这些运算都建立在关系作为元组集合（自动去重）的前提上。',8),
(109,'single','关于 WHERE 与 HAVING 子句的区别，正确的是？',
 '[{"key":"A","text":"WHERE 在分组前筛选元组，HAVING 在分组后筛选分组且可以使用聚集函数"},{"key":"B","text":"两者完全等价，可以随意互换"},{"key":"C","text":"HAVING 一定比 WHERE 效率高"},{"key":"D","text":"WHERE 子句中可以使用 SUM 等聚集函数"}]',
 'A','WHERE 作用于原始元组且不能出现聚集函数；HAVING 作用于分组结果，常与 GROUP BY 配合。能写进 WHERE 的条件应优先写进 WHERE，可减少参与分组的数据量。',5),
(109,'single','某列中有 3 行值为 NULL，共 10 行数据，则 COUNT(*) 与 COUNT(该列) 的结果分别是？',
 '[{"key":"A","text":"10 和 7"},{"key":"B","text":"10 和 10"},{"key":"C","text":"7 和 7"},{"key":"D","text":"10 和 0"}]',
 'A','COUNT(*) 统计行数，不看具体列值；COUNT(列名) 只统计该列非 NULL 的行，因此是 7。除 COUNT(*) 外的聚集函数（SUM、AVG 等）也都忽略 NULL。',5),
(109,'single','使用 GROUP BY 时，SELECT 列表中可以出现的项是？',
 '[{"key":"A","text":"任意列，数据库会自动选一个代表值"},{"key":"B","text":"只能是分组列或聚集函数表达式"},{"key":"C","text":"只能出现聚集函数"},{"key":"D","text":"只能出现分组列"}]',
 'B','分组后每个组对应结果中的一行，非分组列的取值在一组内可能有多个，语义不确定，标准 SQL 不允许直接出现在 SELECT 列表；MySQL 在非严格模式下会随意挑一个值，属于常见误区。',5),
(109,'single','要判断某列是否为 NULL，正确的写法是？',
 '[{"key":"A","text":"WHERE col = NULL"},{"key":"B","text":"WHERE col IS NULL"},{"key":"C","text":"WHERE col == NULL"},{"key":"D","text":"WHERE col LIKE NULL"}]',
 'B','NULL 表示未知，与任何值（包括 NULL 自身）做等值比较结果都是 UNKNOWN，行不会被选中；必须用 IS NULL / IS NOT NULL 判断。',5),
(109,'single','子查询返回的结果集中含有一个 NULL 值时，NOT IN 子查询的整体结果是？',
 '[{"key":"A","text":"忽略 NULL 继续比较"},{"key":"B","text":"整体为 UNKNOWN，导致最终一行都不返回"},{"key":"C","text":"等价于 NOT EXISTS"},{"key":"D","text":"报语法错误"}]',
 'B','NOT IN 等价于对每个值做 <> 比较再取 AND，一旦遇到 NULL，比较结果为 UNKNOWN，AND 链整体为 UNKNOWN，条件不成立，结果集为空。含 NULL 的列应改用 NOT EXISTS。',5),
(109,'single','关于内连接与左外连接，当左表中存在右表无匹配的行时？',
 '[{"key":"A","text":"内连接丢弃该行，左外连接保留它并在右表列填 NULL"},{"key":"B","text":"两者都保留该行"},{"key":"C","text":"两者都丢弃该行"},{"key":"D","text":"左外连接会报错"}]',
 'A','统计"每种商品的销量（含零销量的商品）"这类需求必须用外连接，用内连接会把没卖出的商品整个漏掉。',5),
(109,'single','SQL 查询语句各子句的逻辑执行顺序是？',
 '[{"key":"A","text":"SELECT - FROM - WHERE - GROUP BY - HAVING - ORDER BY"},{"key":"B","text":"FROM - WHERE - GROUP BY - HAVING - SELECT - ORDER BY"},{"key":"C","text":"FROM - SELECT - WHERE - GROUP BY - HAVING - ORDER BY"},{"key":"D","text":"FROM - GROUP BY - WHERE - SELECT - HAVING - ORDER BY"}]',
 'B','FROM 先确定数据源，WHERE 过滤行，再分组与组筛选，SELECT 计算投影（含别名），最后 ORDER BY 排序。因此 WHERE 中不能引用 SELECT 里定义的列别名，而 ORDER BY 可以。',5),
(109,'single','关系代数表达式优化中，最重要的一条启发式规则是？',
 '[{"key":"A","text":"选择运算尽可能先做，使中间结果变小"},{"key":"B","text":"投影运算尽可能后做"},{"key":"C","text":"先做连接再做选择"},{"key":"D","text":"先排序再选择"}]',
 'A','选择能大幅减少元组数，把它下推到连接之前可显著降低后续运算代价；同理投影也尽量提前以减小元组宽度，连接前排序可加快连接。',5),
(109,'single','在已建索引的列上使用下列哪种写法，最可能导致索引失效而退化为全表扫描？',
 '[{"key":"A","text":"WHERE col = 5"},{"key":"B","text":"WHERE SUBSTRING(col, 1, 3) = \\"abc\\""},{"key":"C","text":"WHERE col BETWEEN 10 AND 20"},{"key":"D","text":"WHERE col > 100"}]',
 'B','对索引列套用函数或表达式后，B+ 树无法用原列值定位，只能逐行计算后比较，索引失效。改写为范围前缀匹配（如 LIKE "abc%"）可利用索引。',5),
(109,'single','关于视图，下列说法正确的是？',
 '[{"key":"A","text":"普通视图只存储查询定义，不存储实际数据，查询时临时生成结果"},{"key":"B","text":"视图一定会占用与基表等量的磁盘空间"},{"key":"C","text":"所有视图都可以直接执行 INSERT 更新"},{"key":"D","text":"视图建立后基表结构变化不会影响它"}]',
 'A','视图是虚表，数据库中只保存其定义；只有物化视图才真正存数据。对视图的更新受诸多限制（含聚集、DISTINCT、连接等通常不可更新）。',5),
(109,'judge','在 SELECT 中为列定义的别名，可以在同一语句的 ORDER BY 子句中引用。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。ORDER BY 在 SELECT 之后执行，能看到别名；而 WHERE 与 HAVING（标准 SQL）执行更早，不能引用该别名。',5),
(109,'judge','建立了索引之后，该表上的任何查询都会变快。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。索引本身要占用空间并增加增删改的维护代价；当查询需要返回表中大部分行时，全表扫描加顺序 I/O 往往比逐个回表更快，优化器会自行选择。',5),
(109,'judge','ORDER BY 子句对整个查询结果排序，是查询语句中最后执行的步骤之一。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。排序在 SELECT 投影之后、LIMIT 之前完成，代价较高，能用索引顺序避免排序时应尽量利用。',5),
(109,'judge','在 WHERE 条件中对索引列使用函数会导致该列上的普通 B+ 树索引通常无法被用于快速定位。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。解决方式是改写 SQL 让列单独出现在比较左侧，或在数据库支持的情况下建立函数索引/表达式索引。',5),
(109,'multi','关于 SQL 中的 NULL，下列说法正确的有？',
 '[{"key":"A","text":"NULL 与任何值做算术运算结果仍为 NULL"},{"key":"B","text":"AVG、SUM 等聚集函数会忽略 NULL 值"},{"key":"C","text":"GROUP BY 会把所有 NULL 值分到同一组"},{"key":"D","text":"NULL = NULL 的比较结果为 TRUE"}]',
 'ABC','NULL = NULL 的结果是 UNKNOWN 而非 TRUE，这是三值逻辑的核心；分组时 NULL 被视为相同值归为一组。',8),
(109,'multi','下列哪些做法通常有利于提升查询性能？',
 '[{"key":"A","text":"把选择性强的条件下推，先用索引过滤掉大部分行"},{"key":"B","text":"只查询需要的列，避免 SELECT *"},{"key":"C","text":"为高频查询建立覆盖索引以避免回表"},{"key":"D","text":"在所有列上都建立单列索引"}]',
 'ABC','索引并非越多越好：每多一个索引都会增加写入开销与优化器负担；应针对高频、选择性高的查询建联合索引。',8),
(109,'multi','关于 EXISTS 与 IN，下列说法正确的有？',
 '[{"key":"A","text":"EXISTS 采用半连接语义，找到第一条匹配即可停止"},{"key":"B","text":"子查询含 NULL 时 NOT EXISTS 的结果比 NOT IN 更符合直觉"},{"key":"C","text":"数据库通常能把 IN 子查询改写为半连接执行"},{"key":"D","text":"IN 与 EXISTS 在所有情况下性能完全相同"}]',
 'ABC','现代优化器常把两者转成相同的半连接计划，但在子查询列可空时语义不同：NOT IN 遇 NULL 会返回空集，NOT EXISTS 不会。',8),
(110,'single','事务的 ACID 特性中，字母 I 代表的隔离性指的是？',
 '[{"key":"A","text":"事务中的操作要么全做要么全不做"},{"key":"B","text":"一个事务的执行不能被其它并发事务干扰，中间状态对外不可见"},{"key":"C","text":"事务提交后其结果永久保存"},{"key":"D","text":"事务必须使数据库从一个一致状态转到另一个一致状态"}]',
 'B','原子性是 A（全做或全不做），一致性是 C，隔离性是 I（并发事务互不干扰，效果等价于串行执行），持久性是 D。',5),
(110,'single','两个事务同时读入同一数据并各自修改后先后写回，造成后写覆盖先写，这类问题称为？',
 '[{"key":"A","text":"丢失修改"},{"key":"B","text":"不可重复读"},{"key":"C","text":"读脏数据"},{"key":"D","text":"幻读"}]',
 'A','丢失修改是两个写事务互相覆盖；不可重复读是同一事务两次读同一数据得到不同结果；读脏数据是读到别人未提交而后又被回滚的数据。',5),
(110,'single','关于排他锁（X 锁）与共享锁（S 锁）的相容性，正确的是？',
 '[{"key":"A","text":"S 锁与 S 锁相容，X 锁与任何锁都不相容"},{"key":"B","text":"X 锁与 X 锁相容"},{"key":"C","text":"S 锁与 X 锁相容"},{"key":"D","text":"任何锁之间都相容"}]',
 'A','多个事务可同时持有同一数据项的 S 锁（都只读）；一旦某事务加 X 锁，其它事务既不能加 S 也不能加 X，必须等待释放。',5),
(110,'single','两段锁协议（2PL）的内容是？',
 '[{"key":"A","text":"事务分为加锁阶段和解锁阶段，任何解锁之后不得再申请新的锁"},{"key":"B","text":"事务必须在开始时一次性加完所有锁"},{"key":"C","text":"事务只能在提交后才能加锁"},{"key":"D","text":"事务全程不加锁，靠时间戳排序"}]',
 'A','扩展阶段只加锁不解锁，收缩阶段只解锁不加锁。遵守 2PL 的并发调度一定是可串行化的（充分条件），但可能产生死锁。',5),
(110,'single','三级封锁协议中，能防止不可重复读的是哪一级？',
 '[{"key":"A","text":"一级封锁协议"},{"key":"B","text":"二级封锁协议"},{"key":"C","text":"三级封锁协议"},{"key":"D","text":"任何级别都不能"}]',
 'C','一级：修改前加 X 锁直至事务结束，防丢失修改；二级：一级加读前 S 锁读完即放，防读脏数据；三级：一级加读前 S 锁到事务结束，防不可重复读。',5),
(110,'single','下列隔离级别中，并发度最低但能彻底避免脏读、不可重复读与幻读的是？',
 '[{"key":"A","text":"读未提交"},{"key":"B","text":"读已提交"},{"key":"C","text":"可重复读"},{"key":"D","text":"可串行化"}]',
 'D','四种级别从低到高为读未提交、读已提交、可重复读、可串行化。级别越高加锁越严、一致性越好，但冲突等待与死锁增多、并发度下降。',5),
(110,'single','MySQL InnoDB 存储引擎默认的事务隔离级别是？',
 '[{"key":"A","text":"读未提交"},{"key":"B","text":"读已提交"},{"key":"C","text":"可重复读"},{"key":"D","text":"可串行化"}]',
 'C','InnoDB 默认为 REPEATABLE READ，并借助 MVCC 做一致性读、用间隙锁/临键锁抑制幻读；而 Oracle、SQL Server 默认是读已提交。',5),
(110,'single','幻读与不可重复读的主要区别是？',
 '[{"key":"A","text":"幻读针对同一数据项内容被修改，不可重复读针对行数变化"},{"key":"B","text":"幻读指同一事务两次按相同条件查询，第二次看到了新增（或消失）的行，即结果集行数变化"},{"key":"C","text":"幻读只在读未提交级别出现"},{"key":"D","text":"两者毫无区别"}]',
 'B','不可重复读是"同一行内容变了"（侧重 UPDATE/DELETE），幻读是"多出来的行"（侧重 INSERT）；解决幻读需加间隙锁或提升到可串行化。',5),
(110,'single','数据库恢复技术中，保证事务原子性主要依靠哪类日志？',
 '[{"key":"A","text":"UNDO 日志，撤销未完成事务的修改"},{"key":"B","text":"REDO 日志，重做已提交事务的修改"},{"key":"C","text":"只有 REDO 日志"},{"key":"D","text":"只靠备份，不需要日志"}]',
 'A','UNDO 记录修改前的旧值，用于回滚未完成事务（保证原子性）；REDO 记录新值，用于故障后重做已提交事务（保证持久性）。',5),
(110,'single','WAL（Write-Ahead Logging）原则的核心要求是？',
 '[{"key":"A","text":"先写数据库，再写日志"},{"key":"B","text":"先写日志，再写数据库，且日志必须先于对应的修改落盘"},{"key":"C","text":"日志与数据库可以同时写，无顺序要求"},{"key":"D","text":"只在事务提交时写一次数据库即可"}]',
 'B','必须先保证描述修改的日志记录已持久化，才能把修改本身写入数据库，否则崩溃后无法判断该重做还是撤销。',5),
(110,'judge','遵守两段锁协议的并发调度一定是可串行化调度。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。2PL 是可串行化的充分条件而非必要条件：存在可串行化调度并不遵守 2PL；遵守 2PL 的调度仍可能发生死锁。',5),
(110,'judge','可串行化调度是并发度最高的调度方式。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。可串行化对一致性保障最强，但要求事务串行等价，冲突时需等待甚至回滚，并发度反而最低；实际系统常折中选择读已提交或可重复读。',5),
(110,'judge','封锁粒度越大，系统开销越小，但并发度也越低。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。封锁整个表只需少量锁、管理开销小，但一次只能一个事务写该表；封锁到行则并发度高而锁表开销大，因此有"多粒度封锁"折中方案。',5),
(110,'judge','只要发生死锁，数据库就必须重启实例才能解除。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。DBMS 用超时法或等待图法检测死锁后，选择代价最小的事务（撤销或回滚它）释放其锁即可解除，其余事务继续运行。',5),
(110,'multi','并发操作可能带来的数据不一致性包括？',
 '[{"key":"A","text":"丢失修改"},{"key":"B","text":"不可重复读"},{"key":"C","text":"读脏数据"},{"key":"D","text":"死锁"}]',
 'ABC','死锁是封锁机制的运行故障，不属于"数据不一致"三类问题；三类不一致是丢失修改、不可重复读、读脏数据。',8),
(110,'multi','关于封锁与死锁处理，下列说法正确的有？',
 '[{"key":"A","text":"一次封锁法要求事务一次性申请全部所需锁，可预防死锁但降低并发度"},{"key":"B","text":"顺序封锁法对所有数据项规定加锁顺序，可预防死锁"},{"key":"C","text":"等待图法通过检测有向图中的环来发现死锁"},{"key":"D","text":"解除死锁的常用方法是回滚某个事务"}]',
 'ABCD','死锁处理分预防（一次封锁、顺序封锁）、诊断（超时法、等待图法）与解除（选择代价最小的事务回滚）三个层面。',8),
(110,'multi','关于事务的提交与故障恢复，下列说法正确的有？',
 '[{"key":"A","text":"事务提交前发生故障，恢复时应利用 UNDO 日志撤销其修改"},{"key":"B","text":"事务提交后发生故障，恢复时应利用 REDO 日志重做其修改"},{"key":"C","text":"检查点技术可以缩短故障恢复时需要扫描的日志长度"},{"key":"D","text":"已提交事务的结果必须能经受任何后续故障，即持久性"}]',
 'ABCD','这是持久性与原子性的实现要点：日志先写、检查点定期记录脏页与活跃事务，恢复时只需从最近检查点开始处理。',8),
(111,'single','已知关系模式 R(A, B, C, D) 的函数依赖集 F = { A → B, A → C, A → D }，则 R 的候选码是？',
 '[{"key":"A","text":"A"},{"key":"B","text":"AB"},{"key":"C","text":"ABC"},{"key":"D","text":"ABCD"}]',
 'A','A 的闭包 A⁺ = {A, B, C, D} 包含全部属性，且 A 是单属性、不可能再去掉属性，故 A 是唯一候选码，同时 A 是主属性，B、C、D 是非主属性。',5),
(111,'single','已知关系模式 R(A, B, C) 的函数依赖集 F = { A → B, B → C }，则 R 的候选码与最高范式分别是？',
 '[{"key":"A","text":"候选码 A，属于 2NF 但不属于 3NF"},{"key":"B","text":"候选码 A，属于 3NF"},{"key":"C","text":"候选码 AB，属于 BCNF"},{"key":"D","text":"候选码 A，属于 BCNF"}]',
 'A','A⁺ = ABC，候选码为 A。非主属性 C 传递依赖于 A（A→B、B→C），存在传递函数依赖，故不满足 3NF；但因为码是单属性，不存在部分依赖，满足 2NF。',5),
(111,'single','第二范式（2NF）要消除的是？',
 '[{"key":"A","text":"非主属性对码的部分函数依赖"},{"key":"B","text":"非主属性对码的传递函数依赖"},{"key":"C","text":"主属性对码的部分依赖"},{"key":"D","text":"多值依赖"}]',
 'A','2NF 在 1NF 基础上消除非主属性对码的部分依赖；3NF 再消除非主属性对码的传递依赖；BCNF 进一步要求所有决定因素都含码。',5),
(111,'single','关系模式中每一个决定因素（函数依赖的左部）都必须包含码，这是哪种范式的要求？',
 '[{"key":"A","text":"2NF"},{"key":"B","text":"3NF"},{"key":"C","text":"BCNF"},{"key":"D","text":"4NF"}]',
 'C','BCNF 是 3NF 的加强：3NF 允许决定因素不含码但该决定因素的属性是主属性的情形，BCNF 则一律要求决定因素含码，从而彻底消除因函数依赖引起的异常。',5),
(111,'single','关于 1NF 的要求，正确的是？',
 '[{"key":"A","text":"每个分量必须是不可再分的原子值，不允许表中有表"},{"key":"B","text":"必须消除传递函数依赖"},{"key":"C","text":"必须消除部分函数依赖"},{"key":"D","text":"必须只有一个候选码"}]',
 'A','1NF 只要求属性不可再分（不允许重复的组、不允许嵌套关系），它是关系模型的最低要求，与函数依赖无关。',5),
(111,'single','Armstrong 公理系统的三条基本推理规则是？',
 '[{"key":"A","text":"自反律、增广律、传递律"},{"key":"B","text":"合并律、分解律、伪传递律"},{"key":"C","text":"自反律、合并律、分解律"},{"key":"D","text":"增广律、合并律、传递律"}]',
 'A','自反律（Y⊆X 则 X→Y）、增广律（X→Y 则 XZ→YZ）、传递律（X→Y、Y→Z 则 X→Z）是基本公理；合并律、分解律、伪传递律是可由它们证明的推论。',5),
(111,'single','判定分解 ρ = {R1, R2} 是否为无损连接分解的充分条件是？',
 '[{"key":"A","text":"R1 ∩ R2 是 R1 或 R2 的码"},{"key":"B","text":"R1 ∩ R2 → R1 - R2 或 R1 ∩ R2 → R2 - R1 能由 F 推出"},{"key":"C","text":"R1 ∪ R2 = R 即可"},{"key":"D","text":"只要 R1 与 R2 都是 3NF 即可"}]',
 'B','对二元分解，若公共属性（交集）能函数决定其中一方的差集，则该分解无损。这是最常用的判定定理，注意它与保持依赖是两回事。',5),
(111,'single','关于部分函数依赖与完全函数依赖，正确的是？',
 '[{"key":"A","text":"若 X → Y 且 Y 不依赖于 X 的任何真子集，则 Y 完全函数依赖于 X"},{"key":"B","text":"只要 X → Y 成立就是完全依赖"},{"key":"C","text":"完全依赖只针对单属性"},{"key":"D","text":"部分依赖不可能出现在关系中"}]',
 'A','完全依赖要求去掉 X 中任一属性后依赖不再成立；若存在真子集 X′ ⊂ X 使 X′ → Y，则是部分依赖，这正是 2NF 要消除的对象。',5),
(111,'single','关系模式 R 的所有属性都是主属性（即都包含在某个候选码中），则 R 至少满足？',
 '[{"key":"A","text":"1NF"},{"key":"B","text":"2NF"},{"key":"C","text":"3NF"},{"key":"D","text":"BCNF"}]',
 'C','全主属性意味着不存在非主属性，因而非主属性对码的部分依赖与传递依赖无从谈起，2NF、3NF 自动成立；但决定因素未必含码，故不一定达到 BCNF。',5),
(111,'single','把关系模式 R 分解为 3NF 且同时保持函数依赖与无损连接性，常用的算法思路是？',
 '[{"key":"A","text":"先求 F 的最小覆盖，按相同左部分组生成子模式，再补上某个候选码对应的子模式"},{"key":"B","text":"直接按属性逐一拆分"},{"key":"C","text":"只按主码与非主属性一分为二"},{"key":"D","text":"先分解到 BCNF 再回退"}]',
 'A','经典 3NF 合成算法：求最小函数依赖集 → 合并左部相同的依赖成组 → 若没有任何子模式包含原模式的码，则额外加入一个由候选码构成的模式，该补充保证了无损连接性。',5),
(111,'judge','属于 BCNF 的关系模式一定属于 3NF。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。范式层级为 1NF ⊃ 2NF ⊃ 3NF ⊃ BCNF ⊃ 4NF，BCNF 是 3NF 的真子集（更强），满足 BCNF 必满足 3NF，反之不成立。',5),
(111,'judge','如果一个分解是无损连接的，那么它一定保持函数依赖。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。无损连接与保持依赖是两个独立目标，可以只满足其一；存在无损但不保持依赖的分解（会导致依赖的完整性约束难以高效检查）。',5),
(111,'judge','函数依赖 X → Y 表示：对于关系中任意两个元组，只要它们在 X 上的取值相同，在 Y 上的取值也必须相同。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。这是函数依赖在某一时刻关系实例上的语义定义，也是理解码与非主属性依赖的基础。',5),
(111,'judge','规范化程度越高越好，实际设计时应把关系模式一律分解到 4NF 或更高。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。范式越高连接越碎，查询时需要频繁做连接、性能下降；实际设计常在 3NF/BCNF 之间权衡，必要时有意识地进行反规范化。',5),
(111,'multi','关于关系模式的码，下列说法正确的有？',
 '[{"key":"A","text":"候选码能唯一标识元组且不含多余属性（极小性）"},{"key":"B","text":"包含在任一候选码中的属性称为主属性"},{"key":"C","text":"一个关系模式可以有多个候选码"},{"key":"D","text":"外码一定是本关系的候选码"}]',
 'ABC','外码是本关系中引用其它关系主码的属性（组），它在本关系里通常不是候选码，取值也可以重复。',8),
(111,'multi','关于范式与异常，下列说法正确的有？',
 '[{"key":"A","text":"数据冗余会导致插入异常、删除异常与更新异常"},{"key":"B","text":"2NF 消除了非主属性对码的部分函数依赖"},{"key":"C","text":"3NF 消除了非主属性对码的传递函数依赖"},{"key":"D","text":"4NF 消除了非平凡且非函数依赖的多值依赖"}]',
 'ABCD','规范化的目标正是逐步消除各类依赖引起的冗余与异常，但需与实际查询性能要求权衡。',8),
(111,'multi','关于最小函数依赖集（最小覆盖），下列说法正确的有？',
 '[{"key":"A","text":"每个函数依赖的右部只含单个属性"},{"key":"B","text":"不存在可被其它依赖推出的冗余依赖"},{"key":"C","text":"每个依赖的左部没有多余属性"},{"key":"D","text":"最小覆盖是唯一的"}]',
 'ABC','最小覆盖一般并不唯一，分解顺序不同可能得到不同的最小集，但它们都与原依赖集等价（闭包相同）。',8),
(112,'single','关于 B+ 树与 B 树的主要区别，正确的是？',
 '[{"key":"A","text":"B+ 树的所有关键字都出现在叶结点且叶结点用链表相连，非叶结点只起索引作用"},{"key":"B","text":"B+ 树的每个关键字都携带完整记录"},{"key":"C","text":"B 树的叶结点之间有链表相连"},{"key":"D","text":"B+ 树不支持范围查询"}]',
 'A','B 树中每个关键字都可能携带记录指针，而 B+ 树的内部结点只有索引项、全部数据在叶结点，且叶结点按序链接，因此既支持从根随机检索，又支持顺序扫描与范围查询。',5),
(112,'single','对一棵 m 阶 B+ 树，非根的内部结点中关键字个数至少为？',
 '[{"key":"A","text":"1"},{"key":"B","text":"⌈m/2⌉"},{"key":"C","text":"⌈m/2⌉ - 1"},{"key":"D","text":"m - 1"}]',
 'B','B+ 树中关键字个数等于子树个数：每个结点最多 m 个关键字、m 个子树；非根内部结点至少 ⌈m/2⌉ 个子树，故关键字也至少 ⌈m/2⌉ 个。⌈m/2⌉ - 1 是 B 树的下限，容易混淆。',5),
(112,'single','B+ 树索引检索一条记录所需的磁盘 I/O 次数主要取决于？',
 '[{"key":"A","text":"树的高度（根结点常驻内存时可再少一次）"},{"key":"B","text":"表中记录的总字节数"},{"key":"C","text":"索引文件的碎片率"},{"key":"D","text":"CPU 主频"}]',
 'A','每下降一层通常读一个结点即一次 I/O，树的高度由阶数与关键字总数决定：h ≈ log_⌈m/2⌉(n)。由于阶数很大（数百），三四层就能索引千万级数据，这是 B+ 树适合外存的原因。',5),
(112,'single','关于聚集索引（聚簇索引），下列说法正确的是？',
 '[{"key":"A","text":"一个表只能建立一个聚集索引，因为它决定了数据行的物理存储顺序"},{"key":"B","text":"一个表可以建立任意多个聚集索引"},{"key":"C","text":"聚集索引的叶结点存的是主键值而非整行数据"},{"key":"D","text":"聚集索引与数据的物理顺序无关"}]',
 'A','数据行只能按一种顺序物理存放，所以聚集索引每表唯一；InnoDB 中聚集索引的叶结点就是整行数据（按主键组织），因此主键选择对性能影响很大。',5),
(112,'single','二级索引（辅助索引）查找完整记录时通常需要「回表」，回表指的是？',
 '[{"key":"A","text":"先从二级索引叶结点拿到主键值，再用主键到聚集索引中取整行"},{"key":"B","text":"重新建立一次索引"},{"key":"C","text":"把索引从磁盘读进内存"},{"key":"D","text":"重新执行一次 SQL"}]',
 'A','InnoDB 的二级索引叶结点存索引列 + 主键值，拿到主键后需再走一遍聚集索引取完整行，这就是回表；若所需列都在索引里（覆盖索引）则可避免。',5),
(112,'single','关于联合索引 (a, b, c) 的最左前缀原则，下列查询中不能充分利用该索引的是？',
 '[{"key":"A","text":"WHERE a = 1 AND b = 2"},{"key":"B","text":"WHERE a = 1"},{"key":"C","text":"WHERE b = 2 AND c = 3"},{"key":"D","text":"WHERE a = 1 AND b = 2 AND c = 3"}]',
 'C','联合索引按 (a, b, c) 的字典序排列，必须先定位 a 才能继续使用 b、c；跳过最左列 b 无法在有序序列上二分定位，只能全索引扫描或全表扫描。',5),
(112,'single','哈希索引最适合的查询类型是？',
 '[{"key":"A","text":"等值查询"},{"key":"B","text":"范围查询"},{"key":"C","text":"排序查询"},{"key":"D","text":"模糊前缀匹配"}]',
 'A','哈希按桶定位，等值查询平均 O(1)，但桶内无序，无法支持范围扫描、ORDER BY 与最左前缀匹配，因此通用关系库多用 B+ 树。',5),
(112,'single','下列哪种列最不适合单独建立索引？',
 '[{"key":"A","text":"取值只有「男/女」两种、且分布均匀的性别列"},{"key":"B","text":"经常作为连接条件的外键列"},{"key":"C","text":"经常出现在 WHERE 等值条件中的列"},{"key":"D","text":"经常用于 ORDER BY 的列"}]',
 'A','索引有效性取决于选择性：取值种类很少的列过滤不掉多少行，索引扫描加回表反而比全表扫描慢；高频更新、大字段同样不宜随便建索引。',5),
(112,'single','覆盖索引之所以能加快查询，是因为它？',
 '[{"key":"A","text":"索引中已包含查询需要的全部列，无需回表读取数据行"},{"key":"B","text":"索引占空间更小"},{"key":"C","text":"索引自动排序"},{"key":"D","text":"它一定是唯一索引"}]',
 'A','执行计划中出现 Using index 通常表示用上了覆盖索引；把高频查询需要的少量列加入索引尾部（冗余列）是常见的以空间换时间的优化手段。',5),
(112,'single','B+ 树在插入关键字导致结点溢出时会如何处理？',
 '[{"key":"A","text":"分裂该结点，把中间关键字提升到父结点，必要时向上递归分裂直至根，树高加一"},{"key":"B","text":"直接覆盖相邻关键字"},{"key":"C","text":"拒绝插入并报错"},{"key":"D","text":"把整个树重建一遍"}]',
 'A','分裂可能一路向上波及根结点，根分裂时树高增加 1，这也是 B+ 树唯一长高的时机；删除时结点过少则与兄弟合并，可能使树变矮，故树始终平衡。',5),
(112,'judge','B+ 树是一棵平衡树，所有叶结点都位于同一层，且到根的路径长度相同。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。所有检索路径等长意味着查询代价稳定，没有退化成链表的可能，这是它相对二叉搜索树的核心优势。',5),
(112,'judge','B+ 树只能从根结点开始做随机检索，无法利用叶结点链表做顺序检索。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。叶结点之间用指针串成有序链表，定位到范围起点后沿链表顺序扫描即可完成范围查询，这正是 B+ 树优于 B 树的关键点。',5),
(112,'judge','给表增加索引会加快查询，但会降低插入、删除和更新的速度。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。写入时不仅要改数据行，还要同步维护每一棵相关 B+ 树（可能触发结点分裂或合并），索引越多写入越慢。',5),
(112,'judge','数据库优化器选择索引扫描还是全表扫描，主要依据是对返回行数的估算与代价比较。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。优化器依据统计信息估算选择率与代价，返回比例高时全表扫描的顺序 I/O 更划算；统计信息过期会导致误选，需要定期更新。',5),
(112,'multi','与 B 树相比，B+ 树的优点包括？',
 '[{"key":"A","text":"非叶结点不存记录，单结点能容纳更多关键字，树更矮"},{"key":"B","text":"叶结点链表相连，便于范围查询与全表顺序扫描"},{"key":"C","text":"查询代价稳定，任何关键字的检索路径等长"},{"key":"D","text":"内部结点也能直接返回记录，减少一次 I/O"}]',
 'ABC','D 是 B 树的特点而不是优点：B 树虽可能更早命中，但扇出小、树更高，且无法顺序扫描，综合不如 B+ 树，这正是数据库普遍选 B+ 树的原因。',8),
(112,'multi','下列哪些场景适合建立索引？',
 '[{"key":"A","text":"经常出现在 WHERE 条件中且选择性较高的列"},{"key":"B","text":"经常用于表连接的列"},{"key":"C","text":"经常用于 ORDER BY 与 GROUP BY 的列"},{"key":"D","text":"几乎不参与查询、但更新极其频繁的列"}]',
 'ABC','更新极频繁又不参与查询的列建索引只会徒增维护开销；索引是为读服务的，是否建要看读写比例与实际执行计划。',8),
(112,'multi','关于 B+ 树索引的维护，下列说法正确的有？',
 '[{"key":"A","text":"删除关键字导致结点关键字数低于下限时，可与兄弟结点合并"},{"key":"B","text":"结点分裂只在插入时发生，且可能使树高增加"},{"key":"C","text":"B+ 树的所有失衡都需要通过旋转来恢复"},{"key":"D","text":"内部结点的关键字只是分界值，可能并不对应真实存在的数据行"}]',
 'ABD','B+ 树的平衡靠分裂与合并维持，不需要类似 AVL 的旋转；内部结点保存的是子树最大（或最小）关键字的副本，仅作导航用。',8);

-- ---------- rest-dm.js ----------
INSERT INTO question (knowledge_id, type, title, options, answer, analysis, score) VALUES
(31,'single','蕴含式 p → q 为假，是在下列哪种真值组合下发生的？',
 '[{"key":"A","text":"p 为真且 q 为假"},{"key":"B","text":"p 为假且 q 为真"},{"key":"C","text":"p 为真且 q 为真"},{"key":"D","text":"p 为假且 q 为假"}]',
 'A','蕴含式 p → q 只在「前件真而后件假」时为假，其余三种组合均为真。特别地，前件为假时整个蕴含式为真，这称为「善意推定」，是初学者最容易困惑的一点。',5),
(31,'single','公式 ¬(p ∧ q) 的等值公式是？',
 '[{"key":"A","text":"¬p ∨ ¬q"},{"key":"B","text":"¬p ∧ ¬q"},{"key":"C","text":"p ∨ q"},{"key":"D","text":"p → q"}]',
 'A','这是德摩根律之一：否定一个合取，等于把否定分配到各项并把「且」换成「或」。另一条对偶的定律是 ¬(p ∨ q) 等值于 ¬p ∧ ¬q，两条合称德摩根律。',5),
(31,'single','与蕴含式 p → q 逻辑等值的「逆否命题」是？',
 '[{"key":"A","text":"¬q → ¬p"},{"key":"B","text":"q → p"},{"key":"C","text":"¬p → ¬q"},{"key":"D","text":"p → ¬q"}]',
 'A','原命题与逆否命题互为等值式，真值表完全相同；而逆命题 q → p 与否命题 ¬p → ¬q 互相等值，但与原命题不等值。证明中常用「证逆否命题」来替代直接证明。',5),
(31,'single','含有 n 个不同命题变元的公式，其真值表共有多少行？',
 '[{"key":"A","text":"2 的 n 次方行"},{"key":"B","text":"n 行"},{"key":"C","text":"n 的平方行"},{"key":"D","text":"2n 行"}]',
 'A','每个变元可取真或假两种取值，n 个变元的取值组合数为 2ⁿ，真值表需逐行枚举所有组合。因此变元较多（如超过 5 个）时真值表法会变得非常繁琐。',5),
(31,'single','已知 (p → q) 为真且 p 为真，由假言推理可推出的结论是？',
 '[{"key":"A","text":"q 为真"},{"key":"B","text":"p 为假"},{"key":"C","text":"q 为假"},{"key":"D","text":"¬p 为真"}]',
 'A','假言推理（modus ponens）的规则是：由 p → q 与 p 可推出 q。常见的逻辑谬误是「肯定后件」——由 p → q 与 q 反推 p，这在逻辑上是不成立的。',5),
(31,'single','公式 p ∨ ¬p 属于下列哪一类公式？',
 '[{"key":"A","text":"重言式（永真式）"},{"key":"B","text":"矛盾式（永假式）"},{"key":"C","text":"可满足但非重言式"},{"key":"D","text":"仅是合取式"}]',
 'A','p 为真时前件成立，p 为假时 ¬p 成立，故无论 p 取何值公式恒为真，即排中律，属于重言式。与之相对，p ∧ ¬p 恒为假，是矛盾式。',5),
(31,'single','命题「若 x 大于 2，则 x 大于 1」的否定是？',
 '[{"key":"A","text":"x 大于 2 且 x 小于等于 1"},{"key":"B","text":"若 x 小于等于 2，则 x 小于等于 1"},{"key":"C","text":"若 x 大于 2，则 x 小于等于 1"},{"key":"D","text":"x 小于等于 2 且 x 大于 1"}]',
 'A','蕴含式 p → q 的否定等值于 p ∧ ¬q，因为蕴含为假的唯一情形就是前件真后件假。注意这不是它的否命题（¬p → ¬q），命题的「否定」与否命题是两个不同的概念。',5),
(31,'judge','蕴含式 p → q 与其逆命题 q → p 逻辑等值。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。取 p 真 q 假时 p → q 为假而 q → p 为真，二者真值表不同。与原命题等值的是它的逆否命题 ¬q → ¬p，而不是逆命题。',5),
(31,'judge','合取对析取满足分配律，即 p ∧ (q ∨ r) 等值于 (p ∧ q) ∨ (p ∧ r)。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。这与集合运算中交集对并集的分配律、数的乘法对加法的分配律形式一致；同时析取对合取也满足分配律：p ∨ (q ∧ r) 等值于 (p ∨ q) ∧ (p ∨ r)。',5),
(31,'judge','若一个命题公式在全部真值指派下的取值都为真，则称它为重言式。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。重言式（永真式）与矛盾式（永假式）、可满足式（至少有一组指派使其为真）构成命题公式的三类划分，重言式的否定必为矛盾式。',5),
(31,'multi','下列公式中，与蕴含式 p → q 逻辑等值的有哪些？',
 '[{"key":"A","text":"¬p ∨ q"},{"key":"B","text":"¬q → ¬p"},{"key":"C","text":"¬(p ∧ ¬q)"},{"key":"D","text":"q → p"}]',
 'ABC','p → q 可改写为 ¬p ∨ q（因为只在 p 真 q 假时为假），¬q → ¬p 是它的逆否命题，¬(p ∧ ¬q) 正是「排除前件真后件假」这三种写法都与原公式等值。而 q → p 是逆命题，与原式不等值，故 D 不选。',8),
(32,'single','含有 n 个顶点的连通图，其最小生成树含有多少条边？',
 '[{"key":"A","text":"n - 1 条"},{"key":"B","text":"n 条"},{"key":"C","text":"n + 1 条"},{"key":"D","text":"n(n - 1)/2 条"}]',
 'A','生成树是包含全部顶点且无回路的连通子图，树的边数恒为顶点数减一。多一条边必然成环，少一条边必然不连通，因此任何生成树（含最小生成树）都恰有 n-1 条边。',5),
(32,'single','Kruskal 算法构造最小生成树的核心步骤是？',
 '[{"key":"A","text":"按边权从小到大依次考虑，若不形成回路就加入"},{"key":"B","text":"从某个起点开始不断扩展权值最小的邻边"},{"key":"C","text":"先求出任意一棵生成树再逐步替换边"},{"key":"D","text":"按边权从大到小依次删除成环的边"}]',
 'A','Kruskal 是典型的贪心算法：全局按权值升序扫描所有边，用并查集检测两端是否已连通，未连通则加入。选项 B 描述的是 Prim 算法，选项 D 是「破圈法」的思路。',5),
(32,'single','Prim 算法构造最小生成树的基本过程是？',
 '[{"key":"A","text":"从一个起始顶点出发，每次把连接已选集合与未选集合的最小边加入"},{"key":"B","text":"把所有边排序后依次加入"},{"key":"C","text":"先取权值最小的边再随机扩充"},{"key":"D","text":"每次删除当前权值最大的边"}]',
 'A','Prim 维护一个已选顶点集合，每轮选择跨越集合边界的最小权边并把新顶点并入，共进行 n-1 轮。它与 Kruskal 的区别在于：Prim 始终保持一棵连通的树，Kruskal 则可能同时维护多个连通分量（森林）。',5),
(32,'single','Kruskal 算法的时间复杂度主要由哪一步决定？',
 '[{"key":"A","text":"对所有边按权值排序，为 O(E log E)"},{"key":"B","text":"并查集的查找操作，为 O(E)"},{"key":"C","text":"顶点遍历，为 O(V)"},{"key":"D","text":"建图过程，为 O(V + E)"}]',
 'A','排序耗时 O(E log E)（也可写成 O(E log V)），是主导项；并查集的合并与查找近似 O(E·α(V))，量级更低。因此稀疏图上 Kruskal 非常高效。',5),
(32,'single','关于最小生成树的唯一性，下列结论正确的是？',
 '[{"key":"A","text":"当各边权值互不相同时最小生成树唯一，权值有相等时可能不唯一"},{"key":"B","text":"最小生成树总是唯一的"},{"key":"C","text":"最小生成树总是有两个以上"},{"key":"D","text":"最小生成树的唯一性与权值无关"}]',
 'A','所有边权互不相等时 MST 必唯一；存在相等权值时，替换等权边可得到总权值相同但结构不同的多棵 MST。无论哪种情况，最小生成树的「总权值」都是唯一确定的。',5),
(32,'single','最小生成树的定义可以概括为？',
 '[{"key":"A","text":"连通全部顶点、无回路且边权总和最小的子图"},{"key":"B","text":"任意两顶点间距离最短的子图"},{"key":"C","text":"边数最少的连通子图"},{"key":"D","text":"包含权值最小那条边的生成树"}]',
 'A','定义包含三点：覆盖所有顶点、是一棵树（无回路且连通）、在所有生成树中总权值最小。注意 MST 保证的是「总权值最小」，并不保证任意两点间的路径是最短路，那是另一个问题。',5),
(32,'single','用 Prim 算法配合邻接矩阵求解稠密图的最小生成树，其时间复杂度为？',
 '[{"key":"A","text":"O(V²)"},{"key":"B","text":"O(E log V)"},{"key":"C","text":"O(V log V)"},{"key":"D","text":"O(V·E)"}]',
 'A','邻接矩阵实现的 Prim 每轮需线性扫描找最小边，共 V 轮，总计 O(V²)，不含 log 因子，因而在稠密图（E 接近 V²）上优于 Kruskal。用二叉堆优化后则为 O(E log V)，更适合稀疏图。',5),
(32,'single','Kruskal 算法判断「加入一条边后是否会形成回路」，通常借助哪种数据结构？',
 '[{"key":"A","text":"并查集"},{"key":"B","text":"栈"},{"key":"C","text":"优先队列"},{"key":"D","text":"哈希表"}]',
 'A','并查集把已连通的顶点归入同一集合，若一条边的两个端点已属于同一集合，说明它们此前已连通，加入该边必成环，应舍弃。它支持近乎 O(1) 的合并与查询。',5),
(32,'judge','任意连通带权图的最小生成树都是唯一确定的。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。当图中存在权值相等的边时，可能出现多棵总权值相同但边集不同的最小生成树。唯一确定的只是最小生成树的权值总和，以及「所有边权互异时树唯一」这一结论。',5),
(32,'judge','连通带权图的最小生成树一定包含图中权值最小的那条边。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。这是切割性质的直接推论：对权值最小的边 e，把它的两个端点分成两个集合，任何生成树都必须有一条边跨越这个切割，而 e 是跨越边中权值最小者，故必被选入某棵最小生成树。',5),
(32,'judge','Prim 算法与 Kruskal 算法都属于贪心算法，且都能求得真正的最小生成树。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。两者虽然贪心策略不同（一个按顶点扩张、一个按边排序），但都由切割性质与回路性质保证最优性，这是「贪心可得全局最优」的少数经典范例之一。',5),
(32,'multi','关于 Kruskal 算法的执行过程，下列说法正确的有哪些？',
 '[{"key":"A","text":"初始时每个顶点各自构成一个集合"},{"key":"B","text":"按权值从小到大的顺序考察每条边"},{"key":"C","text":"用并查集检测加入该边是否会形成回路"},{"key":"D","text":"算法需要人为指定一个起始顶点"}]',
 'ABC','Kruskal 从「每个顶点是一个独立连通分量」的森林开始，按权值升序加边并用并查集判环，直到边数达到 n-1。它不需要指定起点，需要指定起点的是 Prim 算法，故 D 错。',8),
(32,'multi','关于最小生成树的性质，下列说法正确的有哪些？',
 '[{"key":"A","text":"边数等于顶点数减一"},{"key":"B","text":"是一棵连通且无回路的子图"},{"key":"C","text":"删去其中任意一条边都会使它不再连通"},{"key":"D","text":"树上任意两顶点间的路径都是原图中的最短路径"}]',
 'ABC','前三条是树的等价刻画：n-1 条边、连通无环、每条边都是桥。第四条错误，最小生成树优化的是边权总和，两点间路径未必最短路，求最短路要用 Dijkstra 或 Floyd 算法。',8),
(64,'single','两个有限集合 A、B 的容斥原理（求并集元素个数）公式是？',
 '[{"key":"A","text":"|A ∪ B| = |A| + |B| - |A ∩ B|"},{"key":"B","text":"|A ∪ B| = |A| + |B|"},{"key":"C","text":"|A ∪ B| = |A| + |B| + |A ∩ B|"},{"key":"D","text":"|A ∪ B| = |A|·|B| - |A ∩ B|"}]',
 'A','直接相加时交集元素被统计了两次，必须减去一次才得到并集的真实元素个数。三个集合时公式还要加上三两交集、再减去三重交集，思路同样是「多退少补」。',5),
(64,'single','德摩根律在集合运算中的表述是：A 与 B 并集的补集等于？',
 '[{"key":"A","text":"A 的补集与 B 的补集的交集"},{"key":"B","text":"A 的补集与 B 的补集的并集"},{"key":"C","text":"A 与 B 交集的补集"},{"key":"D","text":"A 与 B 的并集本身"}]',
 'A','补集把「并」变成「交」、把「交」变成「并」：补(A∪B) = 补A ∩ 补B，补(A∩B) = 补A ∪ 补B。它与命题逻辑中的德摩根律形式完全对应。',5),
(64,'single','集合差 A - B 可以用交集与补集表示为？',
 '[{"key":"A","text":"A ∩ 补B"},{"key":"B","text":"A ∪ 补B"},{"key":"C","text":"补A ∩ B"},{"key":"D","text":"A ∩ B"}]',
 'A','A - B 由「属于 A 且不属于 B」的元素组成，故等于 A 与 B 的补集之交。这也是文氏图中「在 A 圆内但在 B 圆外的月牙形区域」。',5),
(64,'single','含有 n 个元素的集合，其幂集（全体子集构成的集合）含有多少个元素？',
 '[{"key":"A","text":"2 的 n 次方个"},{"key":"B","text":"n 的平方个"},{"key":"C","text":"2n 个"},{"key":"D","text":"n! 个"}]',
 'A','每个元素在子集中都有「选」与「不选」两种状态，n 个元素共有 2ⁿ 种组合，故幂集元素个数为 2ⁿ。例如含 3 个元素的集合，其幂集含 8 个元素。',5),
(64,'single','已知 |A| = 10，|B| = 8，|A ∩ B| = 3，则 |A ∪ B| 等于？',
 '[{"key":"A","text":"15"},{"key":"B","text":"18"},{"key":"C","text":"21"},{"key":"D","text":"5"}]',
 'A','由容斥原理 |A ∪ B| = 10 + 8 - 3 = 15。交集部分的 3 个元素在直接相加时被重复计了一次，减掉后才是并集的真实规模。',5),
(64,'single','集合的对称差 A △ B 的定义是？',
 '[{"key":"A","text":"(A - B) ∪ (B - A)"},{"key":"B","text":"A ∪ B"},{"key":"C","text":"A ∩ B"},{"key":"D","text":"(A ∪ B) - (A ∩ B) 的补集"}]',
 'A','对称差由「只属于 A 或只属于 B」的元素组成，即两个差集的并。它也等于 (A ∪ B) - (A ∩ B)，两种写法等价，在文氏图中对应两个圆不重叠的部分。',5),
(64,'single','关于空集与子集的关系，下列结论正确的是？',
 '[{"key":"A","text":"空集是任意集合的子集"},{"key":"B","text":"空集只属于它自己"},{"key":"C","text":"空集没有子集"},{"key":"D","text":"空集等于任意集合"}]',
 'A','子集的定义是「若 x 属于空集则 x 属于 A」，因前提恒假，该蕴含式恒真，故空集是任何集合的子集（包括它自己）。但要注意它是「子集」而非「元素」，空集一般不属于任意集合。',5),
(64,'single','集合 A 与 B 的笛卡尔积 A × B 的元素个数为？',
 '[{"key":"A","text":"|A| 乘以 |B|"},{"key":"B","text":"|A| 加 |B|"},{"key":"C","text":"|A| 的 |B| 次方"},{"key":"D","text":"|A ∩ B|"}]',
 'A','笛卡尔积的元素是有序对 (a, b)，a 有 |A| 种取法、b 有 |B| 种取法，由乘法原理共 |A|·|B| 个。注意有序对与无序对不同，一般 A × B 不等于 B × A。',5),
(64,'single','交集对并集的分配律表达式是？',
 '[{"key":"A","text":"A ∩ (B ∪ C) = (A ∩ B) ∪ (A ∩ C)"},{"key":"B","text":"A ∩ (B ∪ C) = (A ∪ B) ∩ (A ∪ C)"},{"key":"C","text":"A ∩ (B ∪ C) = (A ∩ B) ∩ (A ∩ C)"},{"key":"D","text":"A ∩ (B ∪ C) = A ∪ B ∪ C"}]',
 'A','交集对并集可分配，反过来并集对交集也可分配：A ∪ (B ∩ C) = (A ∪ B) ∩ (A ∪ C)。这两条与逻辑中 ∧、∨ 的分配律一一对应。',5),
(64,'single','在全集 U 中，集合 A 的补集的补集等于？',
 '[{"key":"A","text":"A 本身"},{"key":"B","text":"空集"},{"key":"C","text":"全集 U"},{"key":"D","text":"A 的幂集"}]',
 'A','两次取补互相抵消：补(补A) = A，这称为对合律。同时还有 A ∪ 补A = U 与 A ∩ 补A = 空集，这两条与对合律一起构成补集的基本性质。',5),
(64,'judge','对任意两个集合 A、B，都有 A - B = B - A。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。集合差不满足交换律：A - B 是「属于 A 不属于 B」的部分，B - A 是「属于 B 不属于 A」的部分，二者一般不同。例如 A = {1,2}、B = {2,3} 时 A - B = {1} 而 B - A = {3}。',5),
(64,'judge','若 A ∪ B = A ∩ B，则必有 A = B。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。由 A ∩ B 包含于 A 包含于 A ∪ B，而两端相等，故中间的 A 也等于它们，同理 B 也相等，于是 A = B。这也说明只有两个相同的集合才会出现「并集等于交集」的情形。',5),
(64,'judge','若 A 是 B 的子集，则 B 的补集是 A 的补集的子集。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。取补会使包含关系反向：A 包含于 B 意味着「不属于 B」的元素必定「不属于 A」，故补B 包含于 补A。这是集合论中的反向律，在文氏图上也很直观。',5),
(64,'judge','含有 3 个元素的集合，其幂集共含有 6 个元素。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。幂集元素个数为 2³ = 8，而不是 3×2 = 6。常见的错误是把「每个元素取或不取」误算成线性关系，实际应为指数关系。',5),
(64,'multi','设全集 U = {1, 2, 3, 4, 5}，A = {1, 2, 3}，B = {3, 4}，下列结论正确的有哪些？',
 '[{"key":"A","text":"A ∪ B = {1, 2, 3, 4}"},{"key":"B","text":"A ∩ B = {3}"},{"key":"C","text":"A - B = {1, 2}"},{"key":"D","text":"A 在 U 中的补集为 {1, 2}"}]',
 'ABC','并集为 {1,2,3,4}，交集为 {3}，差集 A - B 去掉了公共元素 3 得 {1,2}。而 A 在全集 U 中的补集应为 {4, 5}，不是 {1, 2}，故 D 错——补集必须相对于全集来取。',8),
(64,'multi','关于集合运算律，下列等式成立的有哪几项？',
 '[{"key":"A","text":"补(A ∪ B) = 补A ∩ 补B"},{"key":"B","text":"补(A ∩ B) = 补A ∪ 补B"},{"key":"C","text":"A - B = A ∩ 补B"},{"key":"D","text":"A ∪ B = 补A ∩ 补B"}]',
 'ABC','前两条是德摩根律，第三条是差集的定义式，三者都成立。第四条错误：A ∪ B 的补集才等于 补A ∩ 补B，漏掉左边的补集记号就完全不对了，对照德摩根律即可看出差别。',8),
(64,'multi','已知 |A| = 20，|B| = 15，|A ∩ B| = 5，下列计算正确的有哪些？',
 '[{"key":"A","text":"|A ∪ B| = 30"},{"key":"B","text":"|A - B| = 15"},{"key":"C","text":"|B - A| = 10"},{"key":"D","text":"|A ∩ B| = 35"}]',
 'ABC','由容斥原理 |A ∪ B| = 20 + 15 - 5 = 30；A - B 等于 |A| 减去交集部分，即 20 - 5 = 15；同理 |B - A| = 15 - 5 = 10。交集大小题设已给为 5，不可能是 35，故 D 错。',8),
(65,'single','无向连通图存在欧拉回路（从某点出发经过每条边恰好一次后回到起点）的充要条件是？',
 '[{"key":"A","text":"图中所有顶点的度数都是偶数"},{"key":"B","text":"图中恰有两个奇度顶点"},{"key":"C","text":"图中顶点数为偶数"},{"key":"D","text":"图中边数为偶数"}]',
 'A','每个顶点每「进入」一次就要「离开」一次，故度数必须为偶数；连通且全偶度也是充分的（可用逐步构造回路证明）。这正是「一笔画并能回到起点」的判定条件。',5),
(65,'single','无向连通图存在欧拉通路但不存在欧拉回路的充要条件是？',
 '[{"key":"A","text":"图中恰有两个奇度顶点"},{"key":"B","text":"图中所有顶点度数为偶数"},{"key":"C","text":"图中恰有一个奇度顶点"},{"key":"D","text":"图中奇度顶点个数大于 2"}]',
 'A','通路的起点与终点不同，这两个端点的度数必为奇数，其余顶点度数为偶数，故奇度顶点恰有 2 个。注意由握手定理，奇度顶点总数必为偶数，所以「恰有 1 个」是不可能的。',5),
(65,'single','含有 n 个顶点的连通无向图，其边数至少为多少？',
 '[{"key":"A","text":"n - 1"},{"key":"B","text":"n"},{"key":"C","text":"n + 1"},{"key":"D","text":"n(n - 1)/2"}]',
 'A','连通图边数最少时是一棵树，恰有 n-1 条边；少于 n-1 条边必然不连通。边数最多的简单图是完全图，有 n(n-1)/2 条边。',5),
(65,'single','下列关于树的描述，正确的是？',
 '[{"key":"A","text":"连通且无回路，任意两点间有唯一路径"},{"key":"B","text":"连通但可能有回路"},{"key":"C","text":"无回路但可以不连通"},{"key":"D","text":"边数等于顶点数"}]',
 'A','树的等价定义有多种：连通无环、任意两点有唯一路径、边数为顶点数减一且连通等。不连通的无环图称为森林，不是树。',5),
(65,'single','在连通图中，删去某条边后图不再连通，则这条边称为？',
 '[{"key":"A","text":"桥（割边）"},{"key":"B","text":"环边"},{"key":"C","text":"重边"},{"key":"D","text":"弦"}]',
 'A','桥是连通性的「关键边」，删除它会使连通分量数增加。等价刻画是：一条边是桥当且仅当它不属于任何回路。树中的每条边都是桥。',5),
(65,'single','欧拉回路与哈密顿回路的主要区别在于？',
 '[{"key":"A","text":"欧拉回路经过每条边恰好一次，哈密顿回路经过每个顶点恰好一次"},{"key":"B","text":"二者是同一概念"},{"key":"C","text":"欧拉回路要求图是树，哈密顿回路要求图是完全图"},{"key":"D","text":"欧拉回路只能在有向图中定义"}]',
 'A','欧拉回路关注的是边的一笔画遍历，哈密顿回路关注的是顶点的遍历。二者的难度也截然不同：欧拉回路有多项式判定准则，而判定哈密顿回路是 NP 完全问题。',5),
(65,'single','无向图中所有顶点的度数之和等于？',
 '[{"key":"A","text":"边数的 2 倍"},{"key":"B","text":"边数"},{"key":"C","text":"顶点数"},{"key":"D","text":"顶点数加边数"}]',
 'A','这是握手定理：每条边连接两个顶点，在统计各顶点度数时被计入两次，故度数总和为 2|E|。它的直接推论是奇度顶点的个数必为偶数。',5),
(65,'single','有向图存在欧拉回路的充要条件是？',
 '[{"key":"A","text":"底图连通且每个顶点的入度等于出度"},{"key":"B","text":"每个顶点入度与出度都为偶数"},{"key":"C","text":"图中无环"},{"key":"D","text":"图中顶点数为偶数"}]',
 'A','有向情形下要求每个顶点「进去多少次就出来多少次」，即入度等于出度，同时所有含边的顶点要在同一个连通分量中。这与无向图的「全偶度」条件相对应。',5),
(65,'single','由 3 个顶点首尾相连构成的三角形图，是否存在欧拉回路？',
 '[{"key":"A","text":"存在，因为每个顶点的度数都是 2"},{"key":"B","text":"不存在，因为顶点数为奇数"},{"key":"C","text":"不存在，因为边数为奇数"},{"key":"D","text":"无法判断"}]',
 'A','三角形每个顶点度数为 2（偶数）且图连通，满足欧拉回路的充要条件，可以从任一点出发绕行一圈回到原点。奇数的顶点数或边数都不影响判定，关键在于度数奇偶。',5),
(65,'single','一个连通无向图有 4 个奇度顶点，则它至少需要几笔才能画完（不重复边）？',
 '[{"key":"A","text":"2 笔"},{"key":"B","text":"1 笔"},{"key":"C","text":"3 笔"},{"key":"D","text":"4 笔"}]',
 'A','奇度顶点数为 2k 时，该图最少需要 k 笔才能一笔画完。这里 4 个奇度顶点，故需要 2 笔。这是欧拉通路条件在多笔画情形下的直接推广。',5),
(65,'judge','任意无向图中，奇度顶点的个数一定是偶数。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。由握手定理，度数总和为偶数；若奇度顶点个数为奇数，则度数总和为「若干个偶数之和加奇数个奇数」，结果为奇数，矛盾。',5),
(65,'judge','一个连通图一定存在欧拉回路。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。连通只是必要条件之一，还必须所有顶点度数为偶数。例如「星形图」连通但中心点度数大于 2 且叶结点度数为 1，存在奇度顶点，没有欧拉回路。',5),
(65,'judge','在树中，任意一条边都是桥。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。树无回路，任何一条边都不属于回路，删去它后两个端点之间不再有通路，图变得不连通，故每条边都是桥。这也是树的边数恰为 n-1 的直观原因。',5),
(65,'judge','存在欧拉回路的图一定存在哈密顿回路。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。两个概念互不蕴含。反例：两个三角形共用一个顶点（8 字形），所有顶点度数为偶数（公共点度 4、其余度 2），有欧拉回路；但任何回路都无法经过公共顶点两次以上，因而不存在哈密顿回路。',5),
(65,'multi','下列连通图中，存在欧拉回路的有哪些？',
 '[{"key":"A","text":"三角形（3 个顶点依次相连）"},{"key":"B","text":"含 5 个顶点的环"},{"key":"C","text":"两个三角形共用一个顶点"},{"key":"D","text":"正方形加一条对角线"}]',
 'ABC','三角形与五元环各顶点度数均为 2；两个三角形共用一个顶点时，公共顶点度数为 4、其余顶点度数为 2，全为偶数且连通，故三者都有欧拉回路。正方形加一条对角线后，对角线两端的顶点度数变为 3（奇数），没有欧拉回路，故 D 不选。',8),
(65,'multi','关于图的连通性，下列说法正确的有哪些？',
 '[{"key":"A","text":"无向连通图中任意两个顶点之间都存在路径"},{"key":"B","text":"树的边数等于顶点数减一"},{"key":"C","text":"删去桥会使连通图变得不连通"},{"key":"D","text":"连通图中每个顶点的度数都至少为 2"}]',
 'ABC','前三条分别是连通的定义、树的性质与桥的定义。第四条错误：树是连通图，但叶结点的度数为 1，小于 2，可见连通并不要求每个顶点度数都大于等于 2。',8),
(65,'multi','关于欧拉通路与欧拉回路的区别，下列说法正确的有哪些？',
 '[{"key":"A","text":"欧拉回路要求起点与终点相同"},{"key":"B","text":"欧拉通路允许起点与终点不同"},{"key":"C","text":"恰有 2 个奇度顶点的连通图存在欧拉通路但不存在欧拉回路"},{"key":"D","text":"存在欧拉回路的图也可能恰有 2 个奇度顶点"}]',
 'ABC','欧拉回路必须闭合成环，通路可以开放；奇度顶点个数为 0 时有回路，恰为 2 时只有通路。因此一个图不可能同时存在欧拉回路又恰有 2 个奇度顶点，故 D 错。',8);

-- ---------- rest-html.js ----------
INSERT INTO question (knowledge_id, type, title, options, answer, analysis, score) VALUES
(86,'single','HTML5 中正确的文档类型声明写法是？',
 '[{"key":"A","text":"<!DOCTYPE html>"},{"key":"B","text":"<!DOCTYPE HTML5>"},{"key":"C","text":"<doctype html>"},{"key":"D","text":"<!DOCTYPE html PUBLIC \\"-//W3C//DTD HTML 5//EN\\">"}]',
 'A','HTML5 把声明简化为不区分大小写的 <!DOCTYPE html>，不再需要引用 DTD；写成 HTML5 或带 PUBLIC 的旧式写法都不符合规范。它必须是文档的第一行，前面不能有注释或空行，否则部分浏览器会进入怪异模式。',5),
(86,'single','关于 <title> 元素，下列说法正确的是？',
 '[{"key":"A","text":"每个文档都需要一个非空的 title，且只能出现一次"},{"key":"B","text":"title 可省略，浏览器会用文件名代替"},{"key":"C","text":"title 应该写在 body 中"},{"key":"D","text":"一个文档可以写多个 title 分别对应不同页面"}]',
 'A','title 是 head 中唯一必需的元素，决定标签页文字、收藏夹名称与搜索结果标题，一个文档只能有一个。它必须是纯文本，不能包含子元素。',5),
(86,'single','下列最适合用来包裹一篇可独立分发的内容（如博客文章、新闻报道）的标签是？',
 '[{"key":"A","text":"<article>"},{"key":"B","text":"<section>"},{"key":"C","text":"<div>"},{"key":"D","text":"<aside>"}]',
 'A','article 表示独立、可自成一体的内容单元，脱离上下文后仍能完整理解（可复用、可订阅）；section 是文档内的主题分节，通常带标题；div 无语义，仅用于样式分组；aside 是与主体相关但可分离的旁支内容。',5),
(86,'single','<nav> 元素最适合包裹的内容是？',
 '[{"key":"A","text":"页面的主导航链接组"},{"key":"B","text":"文章的正文段落"},{"key":"C","text":"页脚的版权声明"},{"key":"D","text":"页面中出现的每一个链接"}]',
 'A','nav 用于主要导航区块（站点主菜单、目录、分页等），并非所有链接都要塞进去；页脚里的一堆次要链接通常不必用 nav。同一页面可以有多个 nav，建议用 aria-label 加以区分。',5),
(86,'single','关于 <header> 与 <footer>，下列说法正确的是？',
 '[{"key":"A","text":"二者既可以是页面级的，也可以是 section、article 内部的，允许出现多次"},{"key":"B","text":"一个文档中二者各只能出现一次"},{"key":"C","text":"header 必须位于 body 的最开头"},{"key":"D","text":"footer 必须是页面的最后一个元素"}]',
 'A','它们的作用域取决于最近的祖先分节内容：放在 article 里就是这篇文章的头部或尾部，因此一个页面可以有多个。它们不参与大纲层级，也没有位置上的强制要求。',5),
(86,'single','关于 <main> 元素，下列说法正确的是？',
 '[{"key":"A","text":"表示文档主体内容，页面中通常只应有一个可见的 main"},{"key":"B","text":"可以用多个 main 标记多块主要内容"},{"key":"C","text":"main 必须包含 nav"},{"key":"D","text":"main 只能放在 header 内部"}]',
 'A','main 承载页面核心内容，规范要求至多一个可见的 main（其余若存在必须隐藏），且不应包含页头、导航、侧栏、页脚这类在各页重复出现的内容。它对屏幕阅读器「跳到主内容」很有帮助。',5),
(86,'single','关于 h1~h6 的使用原则，正确的是？',
 '[{"key":"A","text":"按层级逐级递进，不要为了字号大小而跳级"},{"key":"B","text":"一个页面只能有一个 h1，且必须写在最前面"},{"key":"C","text":"标题级别可以随意嵌套使用"},{"key":"D","text":"只要样式一致，h1 可以出现任意多次"}]',
 'A','标题表达的是文档大纲层级，跳级（如 h2 直接到 h4）会破坏大纲、影响辅助技术。HTML5 允许每个分节内容各有自己的标题层级，所以 h1 并非绝对只能一个，但同一分节内仍应连续。字号应由 CSS 控制，不要靠选标题级别来调大小。',5),
(86,'single','为插图附加说明文字，最合适的结构是？',
 '[{"key":"A","text":"<figure> 内放 <img> 与 <figcaption>"},{"key":"B","text":"<img> 后面跟一个 <p>"},{"key":"C","text":"<div> 内放 <img> 与 <span>"},{"key":"D","text":"用 <caption> 包住 <img>"}]',
 'A','figure 表示可带标题的独立流内容（图、代码块、表格等），figcaption 作为其第一个或最后一个子元素给出说明。caption 是 table 的专用子元素，不能用于图片。',5),
(86,'single','把页面划分为「简介 / 功能 / 定价」三块，每块都有自己的标题，最合适的标签是？',
 '[{"key":"A","text":"三个 <section>，各自配一个标题"},{"key":"B","text":"三个 <div>"},{"key":"C","text":"三个 <article>"},{"key":"D","text":"三个 <aside>"}]',
 'A','有主题且带标题的分节应使用 section；这些块不是可独立分发的完整内容，不适合 article；div 没有语义，只在纯样式分组时使用。经验法则是：section 里应该能找到一个标题。',5),
(86,'single','要在文章中标记一段需要高亮引起注意的文本，最合适的标签是？',
 '[{"key":"A","text":"<mark>"},{"key":"B","text":"<strong>"},{"key":"C","text":"<em>"},{"key":"D","text":"<b>"}]',
 'A','mark 表示因与上下文相关而被标记或高亮的文本（如搜索结果中的关键词）；strong 表示重要性，em 表示语气上的强调，b 只表示视觉醒目而不带额外语义。',5),
(86,'judge','判断下列说法是否正确：<section> 与 <div> 的区别在于前者带有语义且通常配有标题，后者纯粹用于样式与脚本分组。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。两者都是块级容器、默认样式相近，但 section 会进入文档大纲并表达主题分节；div 不携带任何语义，是找不到合适标签时的最后选择。',5),
(86,'judge','判断下列说法是否正确：HTML5 允许省略 <html>、<head>、<body> 等标签，但浏览器解析时会自动补齐，DOM 中依然存在这些元素。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。规范允许在特定条件下省略这些标签的书写，解析器会自动创建对应的 DOM 节点，所以省略不等于没有。实际工程中仍建议写全，可读性与兼容性更好。',5),
(86,'judge','判断下列说法是否正确：<article> 内部不能再嵌套 <article>，否则会造成文档大纲混乱。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。article 可以合法嵌套，典型场景是一篇文章内嵌多条用户评论——每条评论本身也是可独立的内容。嵌套表达的是内层的独立性从属于外层，不会破坏大纲。',5),
(86,'judge','判断下列说法是否正确：为了 SEO，应当把页面所有内容都用 div 包裹并大量堆砌 h1。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。div 没有语义、无法传达结构；堆砌 h1 会破坏大纲层级，容易被判定为作弊并严重损害无障碍。正确做法是用语义标签表达结构、按层级使用标题。',5),
(86,'multi','下列哪些属于 HTML5 新增的语义化分节元素？',
 '[{"key":"A","text":"<header>"},{"key":"B","text":"<footer>"},{"key":"C","text":"<nav>"},{"key":"D","text":"<center>"},{"key":"E","text":"<font>"}]',
 'ABC','header、footer、nav、section、article、aside、main、figure 都是 HTML5 引入的语义元素；center 与 font 属于纯表现型的 HTML4 标签，已被废弃，样式应当交给 CSS。',8),
(86,'multi','下列哪些场景适合使用 <aside> 元素？',
 '[{"key":"A","text":"文章内的延伸阅读或术语解释框"},{"key":"B","text":"页面侧边栏中与主内容相关但可独立的部分"},{"key":"C","text":"站点的主导航菜单"},{"key":"D","text":"页面的主体文章内容"}]',
 'AB','aside 表示与周围内容相关、但去掉后也不影响主体理解的内容，如侧边栏、旁注、引申阅读。主导航应放 nav，主体内容应放 main 或 article。注意 aside 放在 article 内与放在页面级时，其关联范围不同。',8),
(86,'multi','下列哪些做法有利于形成良好的 HTML 文档大纲？',
 '[{"key":"A","text":"每个分节元素内提供一个标题"},{"key":"B","text":"按层级连续使用 h1~h6，不跳级"},{"key":"C","text":"用 CSS 控制字号，而不是挑选标题级别"},{"key":"D","text":"用 <div class=\\"title\\"> 代替标题标签"},{"key":"E","text":"把整页正文都写进一个 h1"}]',
 'ABC','大纲由标题与分节内容共同决定：分节元素最好各有标题，级别连续不跳级；视觉大小交给 CSS，避免为了大号字使用 h1，更不要用带样式的 div 冒充标题——后者对屏幕阅读器完全不可识别。',8),
(87,'single','表单提交时，决定某个 input 是否会被提交、以及提交时键名的是哪个属性？',
 '[{"key":"A","text":"name"},{"key":"B","text":"id"},{"key":"C","text":"class"},{"key":"D","text":"value"}]',
 'A','浏览器只为具有 name 属性的成功控件收集数据，键名就是 name 的值；id 只用于 label 关联与脚本定位，不参与提交。未勾选的复选框、被禁用的控件以及没有 name 的控件都不会出现在提交数据中。',5),
(87,'single','用 method="get" 提交表单时，数据会怎样发送？',
 '[{"key":"A","text":"拼在 URL 的查询串中，可被收藏与缓存"},{"key":"B","text":"放在请求体中，不会出现在地址栏"},{"key":"C","text":"自动加密后传输"},{"key":"D","text":"以 JSON 格式整体发送"}]',
 'A','get 把键值对编码进 URL，适合无副作用的查询请求，但受长度限制且会留在历史记录与服务器日志中；post 把数据放进请求体。注意 post 也不是加密，敏感数据仍必须走 HTTPS。',5),
(87,'single','给 input 加上 required 属性后，下列说法正确的是？',
 '[{"key":"A","text":"提交时浏览器会拦截空值并提示，但服务端仍必须做同样校验"},{"key":"B","text":"可以保证提交的数据一定合法"},{"key":"C","text":"等价于设置了 maxlength"},{"key":"D","text":"只对 type=\\"text\\" 生效"}]',
 'A','required 触发浏览器的约束校验（constraint validation），空值提交会被阻止；但这只是客户端的用户体验优化，用户可以绕过前端直接发请求，所以服务端必须重复校验。',5),
(87,'single','把 input 的 type 设为 number 后，下列说法正确的是？',
 '[{"key":"A","text":"浏览器限制只能输入数字并可用 min、max、step 约束，但取出的 value 仍是字符串"},{"key":"B","text":"取出的 value 直接就是整数类型"},{"key":"C","text":"会自动拒绝所有小数"},{"key":"D","text":"移动端不会再弹出数字键盘"}]',
 'A','type 只影响输入法、校验与键盘类型，表单值始终是字符串，需要自行转换；min、max、step 参与约束校验。移动端反而会弹出更适合的数字键盘。',5),
(87,'single','要实现「点击文字用户名时焦点落到输入框」，正确的做法是？',
 '[{"key":"A","text":"label 的 for 属性值等于 input 的 id"},{"key":"B","text":"label 的 name 等于 input 的 name"},{"key":"C","text":"把 label 与 input 放在同级即可自动关联"},{"key":"D","text":"给 label 设置 type 属性"}]',
 'A','label 的 for 必须与表单控件的 id 完全一致，或者把控件直接包在 label 内部形成隐式关联。关联后点击文字可聚焦控件，屏幕阅读器也会朗读该标签。name 只用于提交，与标签关联无关。',5),
(87,'single','关于 placeholder 属性，下列做法正确的是？',
 '[{"key":"A","text":"仅作为输入示例提示，不能替代 label"},{"key":"B","text":"用它代替 label 以节省页面空间"},{"key":"C","text":"输入为空时它会作为默认值提交"},{"key":"D","text":"它会自动触发浏览器的必填校验"}]',
 'A','placeholder 在用户开始输入后就消失，无法承担标签职责，且部分屏幕阅读器支持不佳、默认对比度偏低。每个控件都应有可见的 label（必要时可使用视觉隐藏的 label）。',5),
(87,'single','<select> 中的 <option> 没有写 value 属性时，提交的值是？',
 '[{"key":"A","text":"该 option 的开始与结束标签之间的文本内容"},{"key":"B","text":"空字符串"},{"key":"C","text":"该 option 在列表中的序号"},{"key":"D","text":"字符串 undefined"}]',
 'A','未指定 value 时浏览器把 option 的文本内容作为提交值；显式写 value 可以把显示文本与提交值解耦，例如显示「北京」而提交城市代码。',5),
(87,'single','一组复选框都写了 name="hobby"，勾选两项后提交的数据形式是？',
 '[{"key":"A","text":"同一个键携带两个值，后端需按数组或多值方式接收"},{"key":"B","text":"只提交最后勾选的那一项"},{"key":"C","text":"只提交第一项"},{"key":"D","text":"互相覆盖变成空值"}]',
 'A','同名控件会以重复键的形式出现，后端需用 getlist、getAll 之类的方法取到数组。只有 radio 才是同一 name 内互斥单选，这是两者最关键的差别。',5),
(87,'single','表单中包含 <input type="file"> 时，form 必须具备的设置是？',
 '[{"key":"A","text":"method=\\"post\\" 且 enctype=\\"multipart/form-data\\""},{"key":"B","text":"method=\\"get\\" 即可"},{"key":"C","text":"enctype=\\"application/json\\""},{"key":"D","text":"target=\\"_blank\\""}]',
 'A','默认 enctype 是 application/x-www-form-urlencoded，无法承载文件内容；上传文件必须改为 multipart/form-data，且文件不能通过 get 发送。application/json 并不是 form 的合法 enctype 取值。',5),
(87,'single','给 input 加上 pattern="[0-9]{6}" 后，下列说法正确的是？',
 '[{"key":"A","text":"提交时浏览器校验值必须匹配该正则，但空值不参与此校验"},{"key":"B","text":"会自动把输入限制为纯数字"},{"key":"C","text":"会阻止用户敲入字母"},{"key":"D","text":"会自动替用户格式化输入内容"}]',
 'A','pattern 只在提交时参与约束校验，并不限制键盘输入；为了匹配完整值，属性值应按「从头到尾」的语义书写。注意空值不会触发 pattern 校验，需要同时加 required 才能真正强制必填。',5),
(87,'judge','判断下列说法是否正确：给表单控件设置 disabled 后，该控件的值仍会正常提交到服务器。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。disabled 控件既不参与交互也不被提交，还无法获得焦点；readonly 控件不可编辑但会被提交，且可获得焦点。想「显示但不允许修改且需要提交」时应选 readonly。',5),
(87,'judge','判断下列说法是否正确：type="submit" 的按钮点击后会提交表单，而 type="button" 的按钮默认不会触发提交。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。button 的 type 默认值就是 submit，放在表单内点击即提交并可能刷新页面；只想执行脚本时应显式写 type="button"，或在提交事件中 preventDefault。',5),
(87,'judge','判断下列说法是否正确：在表单的文本框中按下回车键通常会触发隐式提交，效果等同于点击提交按钮。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。多数浏览器在文本框中按回车会触发隐式提交（等价于点击第一个提交按钮）。若不希望如此，应在表单上监听 submit 事件并阻止默认行为。',5),
(87,'judge','判断下列说法是否正确：HTML5 的 type="email" 等内置校验可以完全防止用户提交恶意或格式错误的数据。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。内置校验只做基本格式提示，且完全运行在客户端，可被禁用脚本或构造请求绕过。它属于体验优化，服务端必须重新校验所有输入。',5),
(87,'multi','下列哪些属性会参与浏览器的约束校验（constraint validation）？',
 '[{"key":"A","text":"required"},{"key":"B","text":"minlength"},{"key":"C","text":"max"},{"key":"D","text":"pattern"},{"key":"E","text":"placeholder"}]',
 'ABCD','required、minlength/maxlength、min/max/step、pattern 以及 type 都会参与校验，失败时提交被阻止，并可用 :invalid 伪类或 validity 对象获取细节；placeholder 只是提示文本，不参与任何校验。',8),
(87,'multi','关于 <label> 与控件的关联，下列写法有效的有？',
 '[{"key":"A","text":"label 的 for 与 input 的 id 相同"},{"key":"B","text":"把 input 直接写在 label 内部（隐式关联）"},{"key":"C","text":"label 的 for 指向一个 div 的 id"},{"key":"D","text":"label 与 input 使用相同的 name 值"},{"key":"E","text":"label 写了 for 但页面上不存在该 id"}]',
 'AB','显式关联靠 for 匹配 id，隐式关联则把控件作为 label 的后代（取其中第一个可关联控件），二者都能让点击文字聚焦控件并被辅助技术宣读。for 指向非表单元素或指向不存在的 id 都无效，label 也没有 name 属性。',8),
(87,'multi','下列哪些做法有助于提升表单的可用性与安全性？',
 '[{"key":"A","text":"为每个控件提供可见的 label 与清晰的错误提示"},{"key":"B","text":"服务端对所有输入重新校验并在输出时转义"},{"key":"C","text":"用合适的 type 与 inputmode 触发合适的键盘"},{"key":"D","text":"仅在前端用 JS 做校验就够了"},{"key":"E","text":"把敏感或决定性数据放在 hidden 隐藏域中传给客户端"}]',
 'ABC','合适的类型与 inputmode 能改善移动端输入体验，可见标签与明确错误提示提升可用性；安全性只能靠服务端校验，hidden 域的内容用户可以直接查看和篡改，绝不能放敏感数据。',8),
(88,'single','要让表头单元格横跨第 1 行的两列，应使用的写法是？',
 '[{"key":"A","text":"<th colspan=\\"2\\">"},{"key":"B","text":"<th rowspan=\\"2\\">"},{"key":"C","text":"<td span=\\"2\\">"},{"key":"D","text":"<col span=\\"2\\">"}]',
 'A','colspan 让单元格横向合并列，rowspan 纵向合并行，二者都写在 td 或 th 上且取值为合并的格数；span 是 col 与 colgroup 的属性，不是 td 的属性。合并后该行后续的单元格数量要相应减少。',5),
(88,'single','关于 <tfoot>，下列说法正确的是？',
 '[{"key":"A","text":"用于对表格的表脚行分组，浏览器中渲染在表格底部"},{"key":"B","text":"必须写在 tbody 之后"},{"key":"C","text":"每个表格只能包含一行"},{"key":"D","text":"它等价于最后一行 tbody"}]',
 'A','tfoot 与 thead、tbody 一起对表格行分组，便于长表打印时重复表头表脚；书写顺序上 tfoot 甚至可以放在 tbody 之前，浏览器仍会渲染在底部。一个表格可以有多个 tbody。',5),
(88,'single','为表头单元格添加 scope="col" 的作用是？',
 '[{"key":"A","text":"表明该 th 是所在列的表头，帮助辅助技术建立单元格与表头的对应关系"},{"key":"B","text":"让单元格横跨多列"},{"key":"C","text":"设置该列的固定宽度"},{"key":"D","text":"让该列可以点击排序"}]',
 'A','scope 可取 col、row、colgroup、rowgroup，用于声明 th 的作用范围，屏幕阅读器据此在朗读单元格时播报对应表头；它不影响视觉渲染，跨列请用 colspan。',5),
(88,'single','为表格提供标题说明，正确的元素是？',
 '[{"key":"A","text":"<caption>，且必须作为 table 的第一个子元素"},{"key":"B","text":"<title>"},{"key":"C","text":"<legend>"},{"key":"D","text":"<summary>"}]',
 'A','caption 为整个表格提供标题，必须是 table 的第一个子元素，默认显示在表格上方（可用 caption-side 调整）；title 属于整个文档，legend 属于 fieldset，summary 属于 details。',5),
(88,'single','在 <ul> 中创建多级列表时，子级列表应放在什么位置？',
 '[{"key":"A","text":"放在某个 <li> 的内部"},{"key":"B","text":"直接放在父级 <ul> 内部且位于 li 之外"},{"key":"C","text":"用 <ol> 的 start 属性表示层级"},{"key":"D","text":"用 <li level=\\"2\\"> 表示层级"}]',
 'A','列表的直接子元素只能是 li，下一级列表必须作为 li 的内容嵌套；直接把 ul 放进 ul 属于无效 HTML。缩进层级应由 CSS 控制，不要靠嵌套 div 实现。',5),
(88,'single','要让有序列表从 5 开始编号，正确的写法是？',
 '[{"key":"A","text":"<ol start=\\"5\\">"},{"key":"B","text":"<ol value=\\"5\\">"},{"key":"C","text":"<li start=\\"5\\">"},{"key":"D","text":"<ol type=\\"5\\">"}]',
 'A','start 指定 ol 的起始编号，type 指定编号样式（1、a、A、i、I），reversed 可倒序；给单个 li 写 value 可以改变该项及之后各项的编号。这些表现性效果也可用 CSS 计数器实现。',5),
(88,'single','用描述列表展示「术语—解释」对应关系，正确的结构是？',
 '[{"key":"A","text":"<dl> 内放若干组 <dt> 与 <dd>"},{"key":"B","text":"<ul> 内放 <dt> 与 <dd>"},{"key":"C","text":"<dl> 内放 <li>"},{"key":"D","text":"<table> 内放 <dt>"}]',
 'A','dl 表示描述列表，dt 是术语、dd 是其描述；一个 dt 可以对应多个 dd，多个 dt 也可共用一个 dd。HTML5 允许在 dl 内用 div 把若干组包起来，但直接子元素不能是 li 或 p。',5),
(88,'single','现代 Web 中不推荐使用 <table> 做页面整体布局，主要原因是？',
 '[{"key":"A","text":"table 表达的是二维数据关系，用于布局会损害语义与无障碍且难以响应式"},{"key":"B","text":"table 的渲染速度必然更慢"},{"key":"C","text":"table 标签在 HTML5 中已被废弃"},{"key":"D","text":"table 不允许嵌套使用"}]',
 'A','表格布局会让屏幕阅读器把它读成数据表，语义混乱；单元格尺寸由内容决定，移动端很难重排。页面布局应使用 Flexbox、Grid 等 CSS 手段。table 本身并未被废弃，展示真实表格数据仍是首选。',5),
(88,'single','某表格第一行是 <td colspan="2">A</td><td>B</td>，第二行是 <td>C</td><td>D</td><td>E</td>，该表格的列数是？',
 '[{"key":"A","text":"3"},{"key":"B","text":"2"},{"key":"C","text":"5"},{"key":"D","text":"4"}]',
 'A','第一行占 2+1=3 列，第二行占 3 列，两行列数一致，故表格共 3 列、2 行、5 个单元格。表格的列数由所有行中的最大列数决定，合并单元格只是让某些行少写了几个格子。',5),
(88,'single','关于 ul 与 ol 的内容模型，下列说法正确的是？',
 '[{"key":"A","text":"其直接子元素只能是 li（以及 script、template 等支持脚本的元素）"},{"key":"B","text":"可以直接放 div 做分组"},{"key":"C","text":"可以直接放 p 做说明"},{"key":"D","text":"可以放任意流内容"}]',
 'A','列表标签的子元素被严格限定为 li，需要分组或说明时应把内容放进 li 内部；直接在 ul 中放 div 或 p 属于无效 HTML，浏览器的容错解析可能产生出乎意料的 DOM 结构。',5),
(88,'judge','判断下列说法是否正确：表格中同一列的所有单元格宽度必然一致，无法让不同行的同一列宽度不同。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。表格本质是网格，列宽由该列所有单元格共同决定，无法像普通块那样逐行独立设置。需要错落布局时应改用 CSS Grid；可用 colgroup 与 col 为整列统一设置宽度。',5),
(88,'judge','判断下列说法是否正确：表格设置 border-collapse: collapse 后，border-spacing 属性不再起作用。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。collapse 模式下相邻边框合并成单线，单元格间距由边框自身决定，border-spacing 只在默认的 separate 模式中生效。此时可用 border-style: hidden 处理冲突边框的优先级。',5),
(88,'judge','判断下列说法是否正确：有序列表的编号样式只能用 type 属性设置，CSS 无法改变。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。CSS 的 list-style-type（如 decimal、lower-alpha、disc、none）可以完全控制项目符号与编号样式，也可用 ::marker 或计数器自定义。type 属性虽仍有效，但表现应优先交给 CSS。',5),
(88,'judge','判断下列说法是否正确：tbody 标签可以省略，浏览器解析时会自动插入 tbody 元素。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。tbody 的开始与结束标签都可省略，解析器会自动为表格补上 tbody，所以 DOM 中 tr 的父节点通常是 tbody 而不是 table。因此写选择器 table > tr 会选不中，应写 table tr 或 tbody tr。',5),
(88,'multi','下列哪些元素可用于对表格的行进行分组？',
 '[{"key":"A","text":"<thead>"},{"key":"B","text":"<tbody>"},{"key":"C","text":"<tfoot>"},{"key":"D","text":"<colgroup>"},{"key":"E","text":"<caption>"}]',
 'ABC','thead、tbody、tfoot 都是行分组元素，一个 table 可含多个 tbody；colgroup 是按列分组（配合 col 设置列属性），caption 是表格标题，二者都不包含任何行。',8),
(88,'multi','关于 HTML 列表元素，下列说法正确的有？',
 '[{"key":"A","text":"ul 表示无序列表，ol 表示有序列表，dl 表示描述列表"},{"key":"B","text":"可用 CSS 的 list-style: none 去掉项目符号"},{"key":"C","text":"去掉项目符号后部分浏览器会丢失列表语义，可补 role=\\"list\\""},{"key":"D","text":"li 元素必须显式书写结束标签"},{"key":"E","text":"ol 的每一项编号只能从 1 开始"}]',
 'ABC','三种列表各自有明确语义，符号样式由 CSS 控制；Safari 在 list-style: none 时会移除列表语义，补 role="list" 可恢复。li 的结束标签可以省略（遇到下一个 li 或列表结束时自动闭合），ol 可用 start 或 li 的 value 改变起始编号。',8),
(88,'multi','下列哪些做法能提升数据表格的可访问性？',
 '[{"key":"A","text":"用 th 标注表头并配合 scope"},{"key":"B","text":"用 caption 说明表格用途"},{"key":"C","text":"复杂表头用 id 与 headers 显式关联单元格"},{"key":"D","text":"把所有单元格都写成 td 以保持样式统一"},{"key":"E","text":"用多层嵌套表格实现复杂表头"}]',
 'ABC','这三项都能让屏幕阅读器正确播报「某行某列代表什么」；把表头写成 td 会丢失语义，嵌套表格排版则让辅助技术难以理解，复杂表头应使用 id/headers 或 scope="colgroup/rowgroup"。',8),
(89,'single','使用 target="_blank" 打开新标签页时，推荐同时添加的 rel 取值是？',
 '[{"key":"A","text":"noopener noreferrer"},{"key":"B","text":"nofollow"},{"key":"C","text":"alternate"},{"key":"D","text":"canonical"}]',
 'A','新页面可通过 window.opener 反向操作原页面，noopener 切断该引用并带来性能收益，noreferrer 同时不发送 Referer。现代浏览器对 target="_blank" 已默认隐含 noopener，但显式写出更稳妥。nofollow 是给爬虫看的。',5),
(89,'single','页面位于 /news/index.html，其中写 <a href="../img/logo.png">，最终请求的地址是？',
 '[{"key":"A","text":"/img/logo.png"},{"key":"B","text":"/news/img/logo.png"},{"key":"C","text":"/news/../img/logo.png"},{"key":"D","text":"/logo.png"}]',
 'A','相对 URL 以当前文档所在目录为基准解析：../ 回到 /news 的上一级即站点根，再拼接 img/logo.png。以 / 开头才是相对于站点根的路径，带协议与域名的才是绝对 URL。',5),
(89,'single','要让点击链接时下载文件而不是打开它，应使用的属性是？',
 '[{"key":"A","text":"<a download>"},{"key":"B","text":"<a type=\\"download\\">"},{"key":"C","text":"<a target=\\"download\\">"},{"key":"D","text":"<a disposition=\\"attachment\\">"}]',
 'A','download 提示浏览器保存资源（可带值指定文件名），但受同源限制，跨域资源会被忽略而照常导航。真正可靠的下载控制应配合服务端的 Content-Disposition 响应头。',5),
(89,'single','关于 <img> 的 alt 属性，下列做法正确的是？',
 '[{"key":"A","text":"用简洁文字描述图片内容与用途；纯装饰图片应写 alt=\\"\\""},{"key":"B","text":"省略 alt 让浏览器自动识别内容"},{"key":"C","text":"统一写成 alt=\\"图片\\""},{"key":"D","text":"把大段说明文字写进 alt"}]',
 'A','alt 在图片无法加载时显示、并被屏幕阅读器朗读；装饰性图片应写空 alt 让辅助技术跳过（完全不写 alt 反而可能被读成文件名）。alt 也不是标题（那是 title），不应堆砌关键词。',5),
(89,'single','响应式图片中 srcset 与 sizes 配合使用的目的是？',
 '[{"key":"A","text":"让浏览器根据设备像素比与实际显示宽度挑选最合适的资源"},{"key":"B","text":"把图片压缩后再传输"},{"key":"C","text":"让图片自动裁剪成圆形"},{"key":"D","text":"实现图片懒加载"}]',
 'A','srcset 提供多个候选（可用 w 描述符或 x 描述符），sizes 告诉浏览器图片在不同视口下的显示宽度，浏览器据此选择最小合适的文件。懒加载应使用 loading="lazy"，与 srcset 不是一回事。',5),
(89,'single','想在现代浏览器优先提供 WebP、不支持时回退到 JPEG，最合适的结构是？',
 '[{"key":"A","text":"<picture> 内含 <source type=\\"image/webp\\"> 与一个 <img>"},{"key":"B","text":"在 <img> 上写两个 src"},{"key":"C","text":"用 CSS 的 background 切换"},{"key":"D","text":"用 <object> 嵌套"}]',
 'A','picture 是容器，内部按先后顺序列出 source（可用 type、media、srcset 描述条件），最后必须有一个 img 作为回退与最终渲染元素。真正显示的始终是 img，样式也应作用在 img 上。',5),
(89,'single','要让视频在页面加载后自动播放，除 autoplay 外通常还必须满足什么条件？',
 '[{"key":"A","text":"同时设置 muted，否则多数浏览器会阻止自动播放"},{"key":"B","text":"同时设置 controls"},{"key":"C","text":"同时设置 loop"},{"key":"D","text":"必须显式指定 width 与 height"}]',
 'A','主流浏览器的自动播放策略只允许静音自动播放（或用户已与站点交互过），带声音的 autoplay 会被拦截。controls 与 loop 与能否自动播放无关。',5),
(89,'single','<video> 内提供多个 <source> 时，浏览器如何选择？',
 '[{"key":"A","text":"自上而下选择第一个自身能够解码的格式"},{"key":"B","text":"全部下载后选画质最好的"},{"key":"C","text":"随机选择一个"},{"key":"D","text":"必须由 JS 指定"}]',
 'A','浏览器按顺序逐个尝试，遇到能播放的类型即停止，因此应把更优或更兼容的格式排在前面，并给出 type 属性以避免无谓的下载。最后一个 source 之后可放替代文本。',5),
(89,'single','给 <video> 加 preload="none" 的含义是？',
 '[{"key":"A","text":"提示浏览器不要预先加载视频数据"},{"key":"B","text":"视频将无法播放"},{"key":"C","text":"禁止缓冲"},{"key":"D","text":"等同于 autoplay"}]',
 'A','preload 可取 none、metadata、auto，只是给浏览器的提示而非强制命令：none 表示不预取，metadata 只取时长尺寸等元数据，auto 可尽量预取。选 none 能明显节省流量。',5),
(89,'single','要链接到当前页面中 id="top" 的元素，正确的 href 写法是？',
 '[{"key":"A","text":"href=\\"#top\\""},{"key":"B","text":"href=\\"top\\""},{"key":"C","text":"href=\\".top\\""},{"key":"D","text":"href=\\"/#top\\""}]',
 'A','以 # 开头的片段标识符会定位到文档中 id 等于该值的元素（旧式写法也支持 a 的 name）。单独写 top 会被当作相对路径去请求文件，/#top 则是先跳到站点根再定位。',5),
(89,'judge','判断下列说法是否正确：HTML5 中的 <a> 元素可以包裹块级内容（如 h2、div），只要其中不再嵌套其它交互元素。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。a 具有透明内容模型，只要其祖先允许，内部可以放标题、图片、段落等，方便整块卡片可点击；但不能再嵌套另一个 a 或 button 等交互元素，否则行为未定义。',5),
(89,'judge','判断下列说法是否正确：给 <img> 写上 width 与 height 属性会导致图片无法响应式缩放。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。这两个属性给出的是图片的固有尺寸，现代浏览器据此计算宽高比并预留空间，避免加载完成时的布局跳动；配合 CSS 的 max-width: 100% 与 height: auto 仍可自适应缩放。真正破坏响应式的是写死 CSS 宽高且不给 auto。',5),
(89,'judge','判断下列说法是否正确：给图片加上 loading="lazy" 后，图片一定会在进入视口之前就加载完毕，绝不会出现空白。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。lazy 只是把加载推迟到接近视口时才开始，仍需要网络时间；首屏图片用 lazy 反而可能延迟显示。首屏关键图片应直接加载甚至预加载，lazy 适合长页面下方的图片。',5),
(89,'judge','判断下列说法是否正确：<img> 加载跨域图片默认不需要 CORS，但把该图片画到 canvas 后再读取像素会因画布被污染而报错。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。img 标签加载跨域图片不受同源策略限制；但绘制到 canvas 后调用 getImageData 或 toDataURL 会抛出安全错误，除非图片以 crossorigin 属性加载且服务器返回了允许的 CORS 响应头。',5),
(89,'multi','下列哪些做法有利于图片的性能与浏览体验？',
 '[{"key":"A","text":"为不同视口提供 srcset 与 sizes"},{"key":"B","text":"给非首屏图片加 loading=\\"lazy\\""},{"key":"C","text":"设置 width 与 height 以预留空间、减少布局抖动"},{"key":"D","text":"把所有图片转成 Base64 内联以节省请求"},{"key":"E","text":"用一张大图配合 CSS 缩放适配所有屏幕"}]',
 'ABC','srcset 减少不必要的下载、lazy 推迟加载时机、固有尺寸避免布局跳动；Base64 内联会让 HTML 变大且无法单独缓存，通常只适合极小的图标；一张大图缩放既浪费流量又在小屏上发虚。',8),
(89,'multi','关于 <a> 的 target 与 rel，下列说法正确的有？',
 '[{"key":"A","text":"target=\\"_blank\\" 会在新的标签页中打开"},{"key":"B","text":"rel=\\"noopener\\" 可防止新页面通过 window.opener 操作原页面"},{"key":"C","text":"rel=\\"nofollow\\" 用于告知搜索引擎不要传递该链接的权重"},{"key":"D","text":"rel=\\"noopener\\" 会导致链接无法打开"},{"key":"E","text":"target 属性只对指向外部站点的链接有效"}]',
 'ABC','noopener 只切断脚本引用，完全不影响链接能否打开；target 对任意链接都有效，取值还包括 _self、_parent、_top 以及框架名。',8),
(89,'multi','下列哪些是 HTML5 媒体元素（video、audio）支持的属性？',
 '[{"key":"A","text":"controls"},{"key":"B","text":"autoplay"},{"key":"C","text":"loop"},{"key":"D","text":"muted"},{"key":"E","text":"download"}]',
 'ABCD','controls、autoplay、loop、muted、preload 以及 video 专用的 poster、playsinline 都是媒体元素属性；download 属于 a 元素，媒体文件的下载应通过链接或服务端的 Content-Disposition 实现。',8),
(90,'single','HTML5 中声明文档字符编码的正确写法是？',
 '[{"key":"A","text":"<meta charset=\\"utf-8\\">"},{"key":"B","text":"<meta http-equiv=\\"Content-Type\\" content=\\"text/html\\">"},{"key":"C","text":"<meta encoding=\\"utf-8\\">"},{"key":"D","text":"<charset>utf-8</charset>"}]',
 'A','HTML5 把写法简化为 <meta charset="utf-8">，并应放在 head 中尽可能靠前的位置（建议前 1024 字节内），否则浏览器可能先用别的编码解析而出现乱码。UTF-8 是唯一推荐的编码。',5),
(90,'single','移动端页面的 head 中通常需要加入的 viewport 元信息是？',
 '[{"key":"A","text":"<meta name=\\"viewport\\" content=\\"width=device-width, initial-scale=1\\">"},{"key":"B","text":"<meta name=\\"viewport\\" content=\\"fixed\\">"},{"key":"C","text":"<meta name=\\"screen\\" content=\\"mobile\\">"},{"key":"D","text":"<meta http-equiv=\\"viewport\\">"}]',
 'A','该声明让布局视口宽度等于设备宽度并按 1:1 初始缩放；否则移动浏览器会先用约 980px 的虚拟视口渲染再整体缩小，导致文字极小。此外不应禁用用户缩放，那会损害无障碍。',5),
(90,'single','设置 <html lang="zh-CN"> 的主要作用是？',
 '[{"key":"A","text":"帮助屏幕阅读器选择正确的发音引擎，并辅助翻译与字体选择"},{"key":"B","text":"设置页面字体"},{"key":"C","text":"声明文档的字符编码"},{"key":"D","text":"指定文字方向为从左到右"}]',
 'A','lang 声明内容语言，屏幕阅读器据此切换语音、浏览器据此决定是否提示翻译、CSS 也可用 :lang() 做差异化样式。字符编码由 meta charset 决定，文字方向则由 dir 属性控制。',5),
(90,'single','为仅含图标的按钮提供无障碍名称，下列做法最合适的是？',
 '[{"key":"A","text":"给 button 加 aria-label=\\"搜索\\"，图标元素加 aria-hidden=\\"true\\""},{"key":"B","text":"给图标 img 写 alt=\\"按钮\\""},{"key":"C","text":"在按钮旁放一个隐藏的 div 写文字"},{"key":"D","text":"把说明写进 title 属性即可"}]',
 'A','aria-label 直接为按钮提供可访问名称，装饰性图标应 aria-hidden 以免被重复朗读。title 只在鼠标悬停时显示，触摸设备与多数屏幕阅读器支持不佳，不能作为唯一的名称来源。',5),
(90,'single','用 div 加 role="button" 模拟按钮时，还必须手动补齐的能力是？',
 '[{"key":"A","text":"加 tabindex=\\"0\\" 使其可聚焦，并处理 Enter 与空格键的响应"},{"key":"B","text":"设置 cursor: pointer 即可"},{"key":"C","text":"设置 type=\\"button\\""},{"key":"D","text":"添加 href 属性"}]',
 'A','ARIA 只改变语义映射，不提供焦点与键盘行为；原生 button 天生可聚焦、回车与空格触发点击并支持禁用状态。能用原生语义元素时应优先使用，这正是 ARIA 的第一条规则。',5),
(90,'single','要让输入框的错误提示被屏幕阅读器自动播报，推荐做法是？',
 '[{"key":"A","text":"用 aria-describedby 指向提示元素，并给 input 加 aria-invalid=\\"true\\""},{"key":"B","text":"把错误文字写进 placeholder"},{"key":"C","text":"用 alert 弹窗即可"},{"key":"D","text":"把提示放在 title 属性中"}]',
 'A','aria-describedby 把描述性元素关联到控件，朗读时一并播报；配合 aria-invalid 标出当前值不合法。动态出现的提示也可放进 role="alert" 区域以即时播报，同时应把焦点移到出错的控件。',5),
(90,'single','为键盘与屏幕阅读器用户提供「跳到主内容」链接，通常的实现方式是？',
 '[{"key":"A","text":"页面顶部放一个指向 #main 的链接，平时移出屏幕、聚焦时再显示"},{"key":"B","text":"用 JS 在加载后自动滚动到主内容"},{"key":"C","text":"给 main 加 tabindex=\\"0\\" 即可"},{"key":"D","text":"给主内容区加 autofocus"}]',
 'A','跳转链接让用户跳过重复的导航区块；它必须在 DOM 中靠前且保持可聚焦，因此视觉隐藏要用「移出屏幕、聚焦时回到视口」的 CSS 技巧，不能用 display: none 或 visibility: hidden，那样连聚焦也做不到。',5),
(90,'single','按 WCAG AA 级要求，普通正文文本与其背景的最低对比度是？',
 '[{"key":"A","text":"4.5:1"},{"key":"B","text":"3:1"},{"key":"C","text":"7:1"},{"key":"D","text":"2:1"}]',
 'A','AA 级要求普通文本 4.5:1、大号文本（18pt 以上或 14pt 加粗）3:1；AAA 级则分别提升到 7:1 与 4.5:1。对比度只看文字与背景色，占位符文本同样受此约束，不能靠阴影或描边蒙混过关。',5),
(90,'single','关于屏幕阅读器与页面结构，下列说法正确的是？',
 '[{"key":"A","text":"正确使用地标元素与标题层级，能让用户按标题或地标快速跳转"},{"key":"B","text":"只要视觉上清晰就足够了"},{"key":"C","text":"屏幕阅读器只能按 DOM 顺序逐字朗读"},{"key":"D","text":"无障碍只需要给图片加 alt"}]',
 'A','屏幕阅读器支持按标题、地标（main、nav、footer 等）、表单控件等多种方式导航，因此结构语义直接决定浏览效率。无障碍是整体工程，alt 只是其中一环。',5),
(90,'single','关于 <meta name="description">，下列说法正确的是？',
 '[{"key":"A","text":"它描述页面内容，可能被搜索引擎用作结果摘要，但不决定排名"},{"key":"B","text":"它是搜索排名中最具决定性的因素"},{"key":"C","text":"它能阻止页面被搜索引擎索引"},{"key":"D","text":"它必须包含至少 20 个关键词"}]',
 'A','description 只是摘要提示，搜索引擎可能改写或不采用；阻止索引应使用 robots 元信息或 robots.txt。堆砌关键词属于作弊行为，反而可能被降权。',5),
(90,'judge','判断下列说法是否正确：aria-hidden="true" 会把元素及其后代从无障碍树中移除，但元素仍可被键盘聚焦，因此不能用在可聚焦元素上。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。aria-hidden 只作用于辅助技术，元素照样能被 Tab 聚焦，用在可聚焦元素上会造成「焦点停在听不见的元素」这种陷阱。需要隐藏时应同时设置 tabindex="-1" 或使用 inert。',5),
(90,'judge','判断下列说法是否正确：给 div 添加 role="checkbox" 后，浏览器会自动为它加上空格键切换选中状态的行为。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。role 只改变语义映射，键盘交互、焦点管理与 aria-checked 状态维护都要自己写代码。因此 ARIA 的第一条规则是：能用原生语义元素就不要用 div 模拟。',5),
(90,'judge','判断下列说法是否正确：在 viewport 元信息中设置 user-scalable=no 会阻止用户缩放，属于损害无障碍的做法。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。弱视用户依赖双指缩放阅读，禁止缩放会直接让部分用户无法使用页面；iOS 10 之后的 Safari 也默认忽略该限制。不要用禁止缩放来掩盖移动端布局问题。',5),
(90,'judge','判断下列说法是否正确：只要使用了语义化 HTML 就无需再做其它无障碍工作，例如表单控件可以不写 label。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。语义化只是基础，控件仍必须有可访问名称、键盘可达、焦点可见、颜色对比达标，动态内容还要用 ARIA 实时区域播报。无障碍需要逐项验证，不能一劳永逸。',5),
(90,'multi','下列哪些属于让键盘用户能够正常使用的基本要求？',
 '[{"key":"A","text":"所有交互元素都可聚焦"},{"key":"B","text":"焦点有清晰可见的指示"},{"key":"C","text":"焦点顺序与视觉顺序一致"},{"key":"D","text":"避免使用正的 tabindex 值"},{"key":"E","text":"关键信息只在鼠标悬停时展示"}]',
 'ABCD','可聚焦、焦点可见、顺序合理是键盘可用性的三大支柱；正的 tabindex 会打乱自然的焦点顺序、造成跳跃混乱，应当避免（需要时用 0 或 -1）。信息只靠 hover 呈现会让键盘与触摸用户完全拿不到。',8),
(90,'multi','下列哪些 HTML 元素本身具有地标（landmark）语义，便于屏幕阅读器跳转？',
 '[{"key":"A","text":"<main>"},{"key":"B","text":"<nav>"},{"key":"C","text":"<footer>"},{"key":"D","text":"<div>"},{"key":"E","text":"<span>"}]',
 'ABC','main、nav、页面级的 header 与 footer、aside 以及带有可访问名称的 form 会映射为地标角色；div 与 span 没有语义，需要时可用 role 指定，但优先使用原生元素。',8),
(90,'multi','关于 <meta> 元素，下列说法正确的有？',
 '[{"key":"A","text":"meta 是空元素，只有属性没有内容和结束标签"},{"key":"B","text":"charset 应尽早出现在 head 中"},{"key":"C","text":"http-equiv 可模拟部分 HTTP 响应头"},{"key":"D","text":"meta 可以写在 body 中作为普通内容"},{"key":"E","text":"name 与 http-equiv 必须同时出现"}]',
 'ABC','meta 属于 void 元素，没有结束标签也没有内容；charset 越靠前越能避免重新解析；http-equiv 可模拟 refresh、内容安全策略等响应头。meta 只允许出现在 head 中，name 与 http-equiv 二者选其一。',8);

-- ---------- rest-java.js ----------
INSERT INTO question (knowledge_id, type, title, options, answer, analysis, score) VALUES
(76,'single','Java 中用 new 创建出来的对象实例通常存放在哪个运行时内存区域？',
 '[{"key":"A","text":"堆（Heap）"},{"key":"B","text":"虚拟机栈"},{"key":"C","text":"方法区（元空间）"},{"key":"D","text":"程序计数器"}]',
 'A','对象实例几乎都在堆上分配并由 GC 统一回收；虚拟机栈存放栈帧（局部变量表、操作数栈），局部变量里只保留指向堆对象的引用。方法区存类元信息与常量，程序计数器只记录字节码行号。',5),
(76,'single','String s1 = "abc"; String s2 = "abc"; String s3 = new String("abc"); 则 s1 == s2 与 s1 == s3 的结果分别是？',
 '[{"key":"A","text":"true 和 true"},{"key":"B","text":"true 和 false"},{"key":"C","text":"false 和 true"},{"key":"D","text":"false 和 false"}]',
 'B','字符串字面量在编译期进入常量池，s1 与 s2 指向池中同一个对象，故 == 为 true；new String("abc") 一定在堆上新建对象，s1 == s3 比较的是地址，因此为 false。比较内容必须用 equals。',5),
(76,'single','执行 String s = new String("abc"); 会创建几个对象？',
 '[{"key":"A","text":"1 个"},{"key":"B","text":"2 个"},{"key":"C","text":"1 个或 2 个，取决于常量池中此前是否已存在该字面量"},{"key":"D","text":"0 个，只是引用"}]',
 'C','若常量池里还没有 "abc"，会先在池中创建一个字符串对象，再在堆上 new 出一个，共 2 个；若池中已有（例如之前用过该字面量），则只在堆上创建 1 个。new 出来的对象永远在堆上，与池中的不是同一个。',5),
(76,'single','在 HotSpot 的 JDK 8 中，已被加载的类元信息（类版本、字段、方法、字节码）存放在？',
 '[{"key":"A","text":"永久代"},{"key":"B","text":"元空间（Metaspace，位于本地内存）"},{"key":"C","text":"堆的新生代"},{"key":"D","text":"虚拟机栈"}]',
 'B','JDK 8 用本地内存的元空间取代了永久代，减少了永久代 OOM 与调优复杂度；同时字符串常量池和静态变量被移到了堆中。元空间不足会抛出 OutOfMemoryError: Metaspace。',5),
(76,'single','现代 JVM 判断一个对象是否可以回收，主要采用的算法是？',
 '[{"key":"A","text":"引用计数法"},{"key":"B","text":"可达性分析：从 GC Roots 出发看对象是否仍在引用链上"},{"key":"C","text":"按对象年龄自动淘汰"},{"key":"D","text":"由程序员手动标记"}]',
 'B','Java 主流实现用可达性分析，从栈帧局部变量、静态字段、JNI 引用、常量等 GC Roots 出发搜索引用链，不可达者才被判定为可回收；引用计数法因无法解决循环引用（且开销大）而未被采用。',5),
(76,'single','适合用来实现"内存敏感的缓存"（内存不足时才释放）的引用类型是？',
 '[{"key":"A","text":"强引用"},{"key":"B","text":"软引用（SoftReference）"},{"key":"C","text":"弱引用（WeakReference）"},{"key":"D","text":"虚引用（PhantomReference）"}]',
 'B','软引用对象在内存即将溢出时才被回收，适合做缓存；弱引用只要发生 GC 就会被回收，常用于 WeakHashMap 和规范化的映射；虚引用完全不影响生存期，只在对象被回收时收到通知（用于管理堆外内存）。',5),
(76,'single','java.lang.StackOverflowError 通常表示哪块内存区域出了问题？',
 '[{"key":"A","text":"堆空间不足"},{"key":"B","text":"方法区（元空间）不足"},{"key":"C","text":"虚拟机栈的栈深度超过了允许的最大值"},{"key":"D","text":"直接内存（堆外）不足"}]',
 'C','线程请求的栈深度大于虚拟机允许的深度时抛出该错误，最常见于无限递归或过深的方法调用链；可通过增大 -Xss 缓解，但根治要靠修正递归终止条件。堆不足是 OutOfMemoryError: Java heap space。',5),
(76,'single','Java 只有值传递。对于对象类型的参数，被调方法可以做到的是？',
 '[{"key":"A","text":"让调用者的变量指向另一个新对象"},{"key":"B","text":"修改该对象内部的状态（字段），但不能改变调用者变量指向哪个对象"},{"key":"C","text":"修改实参引用本身"},{"key":"D","text":"任何修改都不会影响调用者"}]',
 'B','传参时复制的是引用值，因此被调方法拿到的是同一个对象的引用，可以改对象内容；但在被调方法里给形参重新赋值（指向新对象）只影响副本，调用者的变量仍指向原对象。',5),
(76,'single','首次创建子类对象时，静态代码块与构造方法的执行顺序是？',
 '[{"key":"A","text":"父类构造、子类构造、父类静态、子类静态"},{"key":"B","text":"父类静态、子类静态、父类构造、子类构造"},{"key":"C","text":"子类静态、父类静态、子类构造、父类构造"},{"key":"D","text":"只执行子类构造"}]',
 'B','类初始化阶段先执行静态内容，且父类先于子类（静态块只在类首次加载时执行一次）；随后创建对象，从父类构造逐级向下，父类实例字段与构造块先于子类执行。',5),
(76,'judge','在循环中用 String 的 + 反复拼接字符串会不断产生新的 String 对象，应改用 StringBuilder。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。String 不可变，每次 + 都要新建对象并拷贝字符数组，n 次拼接是 O(n²) 且产生大量垃圾。StringBuilder 的 append 均摊 O(1)。（JDK 9 起单次表达式的 + 会由 StringConcatFactory 优化，但循环中的反复拼接仍应显式使用 StringBuilder。）',5),
(76,'judge','把对象引用置为 null 后，该对象在下一次垃圾回收时一定会被回收。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。置 null 只是断开这一条引用，若对象仍被其它 GC Roots 可达（其它局部变量、容器、静态字段等）就不会被回收；而且现代 JVM 能分析出局部变量是否已不再使用，这类置 null 通常并无必要。',5),
(76,'judge','有了垃圾回收机制，Java 程序就不会发生内存泄漏。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。GC 只回收不可达对象，逻辑上已废弃但仍被可达强引用链挂着的对象不会被回收——静态集合缓存、未注销的监听器、未关闭的连接、线程池中的 ThreadLocal 都会造成这种泄漏。',5),
(76,'judge','方法区用于存放已被加载的类信息、常量、静态变量以及即时编译器编译后的代码。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。这是方法区的规范定义（JDK 8 的 HotSpot 实现为元空间），它是线程共享区域；其中运行时常量池存放编译期生成的字面量与符号引用，String.intern() 也与之密切相关。',5),
(76,'multi','下列哪些写法会造成 Java 中的内存泄漏？（多选）',
 '[{"key":"A","text":"把对象放入 static 的集合后长期不移除"},{"key":"B","text":"注册监听器或回调后未注销"},{"key":"C","text":"线程池中 ThreadLocal 使用完不 remove"},{"key":"D","text":"对象仅作为方法内的局部变量使用"}]',
 'ABC','A、B、C 都会让对象在逻辑上废弃后仍被 GC Roots 链引用而常驻内存，其中线程池里的线程长期存活，ThreadLocal 不清理既泄漏又会串数据；D 是正常用法，方法结束后即不可达，会被正常回收。',8),
(76,'multi','关于 JVM 运行时数据区，下列说法正确的有？（多选）',
 '[{"key":"A","text":"程序计数器是线程私有的，且是规范中唯一不会抛出 OOM 的区域"},{"key":"B","text":"虚拟机栈与本地方法栈是线程私有的"},{"key":"C","text":"堆是所有线程共享的最大一块内存，几乎所有对象都在其中分配"},{"key":"D","text":"每个线程都独享一份堆空间"}]',
 'ABC','A、B、C 符合 JVM 规范；D 错，堆是全局共享的，因此对象分配与 GC 都必须考虑并发（TLAB 只是线程私有的分配缓冲区，提高分配效率，并不意味着独占整块堆）。',8),
(76,'multi','关于 Java 的四种引用，下列说法正确的有？（多选）',
 '[{"key":"A","text":"软引用适合做内存敏感缓存，内存不足时才回收"},{"key":"B","text":"弱引用在下次 GC 时即被回收，WeakHashMap 用它实现条目自动清理"},{"key":"C","text":"虚引用不影响对象生存期，可在对象被回收时收到通知"},{"key":"D","text":"强引用在内存不足时会被 JVM 自动降级为软引用"}]',
 'ABC','A、B、C 是三种非强引用的标准语义与用途；D 错，只要强引用可达，对象就绝不会被回收，内存不足时 JVM 会抛 OutOfMemoryError，而不会自动改变引用强度。',8),
(76,'single','Integer a = 127; Integer b = 127; Integer c = 128; Integer d = 128; 则 a == b 与 c == d 的结果分别是？',
 '[{"key":"A","text":"true 和 false"},{"key":"B","text":"false 和 false"},{"key":"C","text":"true 和 true"},{"key":"D","text":"false 和 true"}]',
 'A','自动装箱调用 Integer.valueOf，它默认缓存 -128 到 127 的对象，127 命中缓存故 a == b 为 true；128 超出范围会新建对象，故 c == d 为 false。比较包装类的值必须用 equals，这一缓存区间可通过 JVM 参数调整上限。',5),
(77,'single','JDK 8 中无参构造的 ArrayList，第一次 add 时容量变为多少，之后每次扩容约为多少倍？',
 '[{"key":"A","text":"10，2 倍"},{"key":"B","text":"10，1.5 倍"},{"key":"C","text":"0，1.5 倍"},{"key":"D","text":"16，2 倍"}]',
 'B','ArrayList 采用懒初始化：无参构造时底层数组为空，第一次添加才扩容到默认 10；此后按 oldCapacity + (oldCapacity >> 1) 即约 1.5 倍增长，并用 Arrays.copyOf 搬移元素。HashMap 才是按 2 倍扩容。',5),
(77,'single','关于 HashMap 的默认负载因子与扩容方式，正确的是？',
 '[{"key":"A","text":"负载因子 0.5，容量翻倍"},{"key":"B","text":"负载因子 0.75，扩容为原来的 2 倍"},{"key":"C","text":"负载因子 0.75，扩容增加固定 16"},{"key":"D","text":"负载因子 1.0，容量翻倍"}]',
 'B','默认负载因子 0.75 是时间与空间的折中：元素数超过 容量 × 0.75 时触发 resize，容量翻倍并重新散列。JDK 8 的扩容还会把原链表拆成两条，元素的新位置是原位置或原位置加旧容量，无需重新计算哈希。',5),
(77,'single','JDK 8 的 HashMap 中，单个桶里的链表长度达到多少且哈希表容量达标时会转化为红黑树？',
 '[{"key":"A","text":"8"},{"key":"B","text":"6"},{"key":"C","text":"16"},{"key":"D","text":"64"}]',
 'A','链表长度达到 8（TREEIFY_THRESHOLD）且表容量不小于 64 时树化，使查找从 O(n) 降到 O(log n)；扩容拆分后若树中元素少于 6 则退化为链表。这只是兜底，根本还是要让 hashCode 分布均匀。',5),
(77,'single','自定义对象作为 HashMap 的键，必须正确重写哪两个方法？',
 '[{"key":"A","text":"toString 与 equals"},{"key":"B","text":"hashCode 与 equals"},{"key":"C","text":"clone 与 equals"},{"key":"D","text":"compareTo 与 hashCode"}]',
 'B','HashMap 先按 hashCode 定位桶，再用 equals 判定键是否相同，两者必须同时遵守约定（equals 相等则 hashCode 必须相等）。只重写其中一个会导致 put 进去却 get 不出来的诡异现象。',5),
(77,'single','在用增强 for 循环遍历 ArrayList 的过程中调用 list.remove(obj)，通常会发生什么？',
 '[{"key":"A","text":"正常删除，循环继续"},{"key":"B","text":"抛出 ConcurrentModificationException（fail-fast）"},{"key":"C","text":"删除后自动重建迭代器"},{"key":"D","text":"编译错误"}]',
 'B','ArrayList 的迭代器用 modCount 检测结构变更，外部直接 remove 会使 expectedModCount 与 modCount 不一致，下一次迭代即抛 ConcurrentModificationException。正确做法是用 iterator.remove() 或 removeIf。',5),
(77,'single','HashSet 判断两个元素重复的依据是？',
 '[{"key":"A","text":"仅比较 equals"},{"key":"B","text":"先比较 hashCode 定位桶，再用 equals 比较"},{"key":"C","text":"仅比较 hashCode"},{"key":"D","text":"比较内存地址"}]',
 'B','HashSet 内部就是一个只有键的 HashMap：hashCode 决定落在哪个桶，equals 决定该桶内是否与已有元素重复。因此 hashCode 相同而 equals 不同的两个对象可以共存（哈希冲突），equals 相同而 hashCode 不同则会被误判为不同元素。',5),
(77,'single','需要频繁按下标随机访问元素时，应选择？',
 '[{"key":"A","text":"LinkedList"},{"key":"B","text":"ArrayList"},{"key":"C","text":"TreeSet"},{"key":"D","text":"ArrayDeque"}]',
 'B','ArrayList 底层是连续数组，get(i) 为 O(1)；LinkedList 是双向链表，按下标访问需要逐个移动，是 O(n)。LinkedList 的优势只在头尾插入删除和实现队列/双端队列。',5),
(77,'single','遍历集合时需要删除满足条件的元素，安全的做法是？',
 '[{"key":"A","text":"在增强 for 里调用集合的 remove"},{"key":"B","text":"使用 Iterator 的 remove() 方法（或 Collection.removeIf）"},{"key":"C","text":"用普通 for 倒序遍历并调用 remove 就一定能避免问题"},{"key":"D","text":"先 clear 再重新添加"}]',
 'B','Iterator.remove() 会在删除后同步 expectedModCount，因此不会触发 fail-fast；removeIf 内部也是基于迭代器实现的。对 List 倒序按下标删除虽不抛异常，但会让代码依赖具体实现，可读性差且不适用于 Set。',5),
(77,'judge','HashMap 允许键为 null，而 Hashtable 不允许键或值为 null。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。HashMap 允许一个 null 键（哈希按 0 处理）和多个 null 值；Hashtable 遇到 null 键或值会抛 NullPointerException，ConcurrentHashMap 同样禁止 null，以避免"get 返回 null 时无法区分键不存在与值本身为 null"的歧义。',5),
(77,'judge','ArrayList 是线程安全的，多线程下可以直接共享使用。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。ArrayList 没有任何同步措施，并发 add 可能导致元素覆盖丢失、数组越界甚至内部结构损坏。可选方案：Collections.synchronizedList 包装、读多写少用 CopyOnWriteArrayList，或改用并发容器与设计。',5),
(77,'judge','TreeSet 中的元素必须实现 Comparable，或在构造 TreeSet 时提供一个 Comparator。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。TreeSet 基于红黑树，靠比较结果排序并去重（比较返回 0 即视为同一元素），没有比较规则会在插入时抛 ClassCastException。还要注意排序规则应与 equals 保持一致，否则会出现违反 Set 语义的行为。',5),
(77,'single','对同一个 HashMap 先执行 put("a", 1) 再执行 put("a", 2)，之后该 map 的大小与 get("a") 分别是？',
 '[{"key":"A","text":"1 和 2"},{"key":"B","text":"2 和 2"},{"key":"C","text":"2 和 1"},{"key":"D","text":"1 和 1"}]',
 'A','键相同（hashCode 相同且 equals 相等）的 put 是覆盖：不新增条目，只把值替换为后来的 2，故 size 仍为 1。这与 List 的 add 语义截然不同，也正是 putIfAbsent 存在的意义——它遇到已存在的键时不覆盖。',5),
(77,'judge','LinkedList 按下标访问元素 get(i) 的时间复杂度是 O(1)。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。LinkedList 需要从头（或尾，JDK 会比较 i 与 size/2 选择方向）逐个移动节点，复杂度 O(n)。因此按下标遍历 LinkedList 是 O(n²)，必须用迭代器或 for-each；频繁随机访问应改用 ArrayList。',5),
(77,'multi','下列哪些集合实现是线程安全的？（多选）',
 '[{"key":"A","text":"ConcurrentHashMap"},{"key":"B","text":"CopyOnWriteArrayList"},{"key":"C","text":"Vector"},{"key":"D","text":"HashMap"}]',
 'ABC','A 用分段/CAS + synchronized 实现高并发安全；B 通过在修改时复制数组实现读不加锁，适合读多写少的场景；C 的方法都加了 synchronized（性能较差，已不推荐）；D 错，HashMap 并发写入会丢数据，JDK 7 甚至可能形成环形链表。',8),
(77,'multi','关于 equals 与 hashCode 的约定，下列说法正确的有？（多选）',
 '[{"key":"A","text":"equals 相等的两个对象，hashCode 必须相等"},{"key":"B","text":"hashCode 相等的两个对象，equals 不一定相等（哈希冲突）"},{"key":"C","text":"把对象放入 HashMap 后又修改了参与 hashCode 计算的字段，会导致该键再也查不到"},{"key":"D","text":"只重写 equals 而不重写 hashCode，只要逻辑自洽就没问题"}]',
 'ABC','A、B 是规范的核心约定；C 正确，哈希值变化后定位到错误的桶，条目成为"丢失的键"，这正是推荐用不可变对象（或 final 字段）做键的原因；D 错，违反约定会让 HashMap、HashSet 的行为彻底错乱。',8),
(78,'single','下列属于受检异常（checked exception）的是？',
 '[{"key":"A","text":"NullPointerException"},{"key":"B","text":"IOException"},{"key":"C","text":"ArrayIndexOutOfBoundsException"},{"key":"D","text":"ArithmeticException"}]',
 'B','受检异常指 Exception 及其子类中除 RuntimeException 之外的部分，编译器强制要求捕获或声明抛出，通常表示外部环境问题（IO、SQL、网络）。空指针、下标越界、除零都是 RuntimeException，编译期不检查，应靠修正代码消除。',5),
(78,'single','下列情形中，finally 块不会被执行的是？',
 '[{"key":"A","text":"try 块中遇到 return"},{"key":"B","text":"try 块中调用了 System.exit(0)"},{"key":"C","text":"try 块中抛出异常"},{"key":"D","text":"catch 块中有 return"}]',
 'B','除 System.exit、JVM 崩溃、宿主线程被强制终止等极端情况外，finally 一定执行，包括 try/catch 中有 return 时（返回值先计算暂存，执行完 finally 再返回）。因此资源释放写在 finally 里是可靠的。',5),
(78,'single','方法中写 try { return 1; } finally { return 2; }，最终的返回值是？',
 '[{"key":"A","text":"1"},{"key":"B","text":"2"},{"key":"C","text":"0"},{"key":"D","text":"编译错误"}]',
 'B','finally 中的 return 会覆盖 try 的返回值，并吞掉尚未抛出的异常，故返回 2。规范强烈反对在 finally 里写 return 或抛异常，因为它会掩盖真实的控制流与异常信息，成为极难排查的 bug。',5),
(78,'single','方法 int f(){ int x = 1; try { return x; } finally { x = 2; } } 的返回值是？',
 '[{"key":"A","text":"1"},{"key":"B","text":"2"},{"key":"C","text":"0"},{"key":"D","text":"结果不确定"}]',
 'A','返回值的计算发生在 finally 之前，JVM 先把要返回的 1 暂存，finally 中对局部变量 x 的修改已不影响它，故返回 1。但若返回的是对象引用，finally 里修改该对象的内部字段仍然会体现出来。',5),
(78,'single','使用 try-with-resources 语句时，对资源类型的要求是？',
 '[{"key":"A","text":"必须实现 AutoCloseable 接口"},{"key":"B","text":"必须实现 Serializable"},{"key":"C","text":"必须是 final 类"},{"key":"D","text":"必须重写 finalize 方法"}]',
 'A','try-with-resources 要求资源实现 AutoCloseable（其子接口 Closeable 也满足），编译器会自动生成 finally 调用 close()，且按声明的逆序关闭，并把关闭过程中产生的异常记录为被压制异常（suppressed）。',5),
(78,'single','在 catch 块中写 throw new MyException(e)（把原异常传入构造方法）的目的是？',
 '[{"key":"A","text":"让异常不再被调用者捕获"},{"key":"B","text":"把原始异常保存为 cause 形成异常链，便于定位根因"},{"key":"C","text":"提高异常处理的执行效率"},{"key":"D","text":"把受检异常转换为非受检异常"}]',
 'B','传入原异常后它成为 cause，打印堆栈时会出现 Caused by 段落，完整保留最初的出错位置与上下文。直接 new 一个新异常而不带 cause 会丢失根因，是线上排障时最令人头疼的写法。',5),
(78,'single','多个 catch 块同时捕获不同异常时，书写顺序的要求是？',
 '[{"key":"A","text":"父类在前，子类在后"},{"key":"B","text":"子类（更具体的异常）在前，父类在后"},{"key":"C","text":"顺序任意，JVM 会自动选择最匹配的"},{"key":"D","text":"一个 try 只能写一个 catch"}]',
 'B','catch 按书写顺序自上而下匹配，若把 catch (Exception e) 写在前面，后面的 catch (IOException e) 永远不可达，编译器直接报错。Java 7 起可用 catch (IOException | SQLException e) 合并处理方式相同的异常。',5),
(78,'single','OutOfMemoryError 在异常体系中的地位是？',
 '[{"key":"A","text":"Exception 的子类，属于受检异常"},{"key":"B","text":"Error 的子类，表示 JVM 自身处于不正常状态，一般不应捕获"},{"key":"C","text":"RuntimeException 的子类"},{"key":"D","text":"由编译器生成的合成异常"}]',
 'B','Error 与 Exception 同属 Throwable：Error 表示 JVM 层面的严重问题（OOM、StackOverflowError、NoClassDefFoundError），程序通常无法恢复，捕获它们只会掩盖故障，且在 OOM 后连处理逻辑本身都可能失败。',5),
(78,'judge','RuntimeException 及其子类属于非受检异常，编译器不强制要求捕获或声明抛出。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。非受检异常包括 RuntimeException 和 Error，编译期不做检查，通常意味着编程错误（空指针、越界、非法参数）。正确做法是通过改进代码（判空、校验参数）消除它们，而不是用 catch (Exception) 一律吞掉。',5),
(78,'judge','子类重写父类方法时，可以抛出比父类方法更多、更宽的受检异常。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。重写方法的受检异常不能比父类更宽：可以不抛、可以抛相同类型或其子类，但不能新增或扩大，否则调用方按父类契约编写的代码会被破坏。非受检异常不受此限制。',5),
(78,'judge','try 块中有 return 语句时，finally 块依然会执行。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。return 会先计算并暂存返回值，然后执行 finally，最后才真正返回方法。正是这个特性使 finally（以及基于它的 try-with-resources）成为释放锁、关闭连接等清理动作的标准位置。',5),
(78,'judge','throws 写在方法签名上用于声明该方法可能抛出的受检异常，而 throw 用于在方法体内抛出具体的异常对象。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。throws 把处理责任交给调用方（调用者必须捕获或继续声明），throw 才真正产生异常实例并中断当前流程。二者拼写相近而职责完全不同，混淆它们是初学者的典型错误。',5),
(78,'single','关于异常的性能，下列说法正确的是？',
 '[{"key":"A","text":"异常比返回错误码更快"},{"key":"B","text":"构造异常时要填充堆栈轨迹，开销较大，不应把异常当作正常流程控制"},{"key":"C","text":"catch 块本身极慢，应尽量减少 catch"},{"key":"D","text":"异常对象不能被重复抛出"}]',
 'B','new 异常时调用 fillInStackTrace 快照整个调用栈，成本远高于一次分支判断，且创建的对象会加重 GC。因此不要用异常实现循环退出或业务分支，也不要在热点路径上靠捕获异常来判断状态（如用 NumberFormatException 做批量校验）。',5),
(78,'multi','关于 finally 与资源关闭，下列说法正确的有？（多选）',
 '[{"key":"A","text":"try-with-resources 会自动调用资源的 close 方法"},{"key":"B","text":"多个资源时按声明的逆序关闭"},{"key":"C","text":"finally 中再抛出的异常会覆盖 try 中原有的异常"},{"key":"D","text":"只要写了 finally 就绝不会出现资源泄漏"}]',
 'ABC','A、B 正确（关闭顺序与声明顺序相反，符合栈式语义）；C 正确，finally 里的异常会替换原异常，try-with-resources 会把被替换者记入 getSuppressed()；D 错，finally 中忘记 close 或 close 自身失败，资源依然会泄漏。',8),
(78,'multi','下列哪些属于 Error，通常不应在业务代码中捕获？（多选）',
 '[{"key":"A","text":"OutOfMemoryError"},{"key":"B","text":"StackOverflowError"},{"key":"C","text":"NoClassDefFoundError"},{"key":"D","text":"FileNotFoundException"}]',
 'ABC','A、B、C 都是 Error，表示 JVM 已处于不正常状态，程序几乎无法恢复，捕获只能掩盖问题；D 是 IOException 的子类，属于受检异常，必须而且应当在合适层次被捕获或向上声明。',8),
(79,'single','启动一个新线程的正确方式是？',
 '[{"key":"A","text":"直接调用线程对象的 run() 方法"},{"key":"B","text":"调用线程对象的 start() 方法，由 JVM 在新线程中回调 run()"},{"key":"C","text":"调用 resume() 方法"},{"key":"D","text":"先调用 run() 再调用 start()"}]',
 'B','start() 才向 JVM 申请创建线程并使其进入就绪状态，随后由 JVM 回调 run()；直接调用 run() 只是普通方法调用，仍在当前线程串行执行，完全没有并发效果，这是新手最常犯的错误。',5),
(79,'single','synchronized 修饰一个实例方法时，它获取的锁是？',
 '[{"key":"A","text":"当前实例对象 this"},{"key":"B","text":"该类的 Class 对象"},{"key":"C","text":"代码块中指定的对象"},{"key":"D","text":"方法对应的字节码"}]',
 'A','修饰实例方法锁 this，修饰静态方法锁类的 Class 对象，修饰代码块则锁括号里显式给出的对象。由于两者是不同的锁，静态同步方法与实例同步方法之间并不会互斥，这一点常被误判造成并发 bug。',5),
(79,'single','volatile 关键字能保证的是？',
 '[{"key":"A","text":"操作的原子性"},{"key":"B","text":"可见性（写操作立即对其它线程可见）与禁止特定的指令重排序"},{"key":"C","text":"互斥访问"},{"key":"D","text":"线程的执行顺序"}]',
 'B','volatile 通过内存屏障使读写直达主内存，并保证前后指令不被越过它重排（可用于修复双重检查锁定中的重排序问题）；但它不保证 i++ 这类"读-改-写"复合操作的原子性，也不提供互斥。',5),
(79,'single','多个线程各自对同一个 int 变量执行 10000 次 count++，最终结果通常是？',
 '[{"key":"A","text":"恰好等于 线程数 × 10000"},{"key":"B","text":"小于 线程数 × 10000，因丢失更新而偏小"},{"key":"C","text":"大于 线程数 × 10000"},{"key":"D","text":"一定等于某个线程的贡献值"}]',
 'B','count++ 分为读、加、写三步，两个线程可能读到同一个旧值并各自写回，造成更新丢失，结果偏小且每次运行都可能不同。解决方式：synchronized、AtomicInteger（CAS 自旋）或高并发计数更优的 LongAdder。',5),
(79,'single','关于 Object.wait() 的正确说法是？',
 '[{"key":"A","text":"可以在任意位置调用"},{"key":"B","text":"必须在持有该对象锁的同步块内调用，调用后释放锁并进入等待集"},{"key":"C","text":"wait 不会释放已持有的锁"},{"key":"D","text":"wait 是 Thread 类的方法"}]',
 'B','wait/notify/notifyAll 定义在 Object 上，必须在 synchronized(obj) 内部调用，否则抛 IllegalMonitorStateException；wait 会释放锁，被唤醒后需重新竞争锁才能继续，且条件判断应写在 while 循环中以防虚假唤醒。',5),
(79,'single','Thread.sleep(1000) 与 obj.wait(1000) 的关键区别是？',
 '[{"key":"A","text":"两者都会释放已持有的锁"},{"key":"B","text":"sleep 不释放任何锁，wait 会释放当前对象上的锁"},{"key":"C","text":"wait 不会让出 CPU"},{"key":"D","text":"sleep 只能在同步块中调用"}]',
 'B','sleep 让当前线程休眠指定时间，期间仍持有已获得的锁（容易造成其它线程长时间阻塞）；wait 必须在同步块中调用并会释放该对象的锁，是线程间协作的手段。两者都会让出 CPU 并可被中断。',5),
(79,'single','直接使用 Executors.newFixedThreadPool(n) 的潜在风险是？',
 '[{"key":"A","text":"线程池无法复用线程"},{"key":"B","text":"它内部使用无界队列，任务持续堆积可能导致 OOM"},{"key":"C","text":"线程数会自动增长到无限"},{"key":"D","text":"它不支持提交 Callable"}]',
 'B','该工厂方法用无界的 LinkedBlockingQueue 存放任务，生产速度长期高于消费速度时队列无限增长，最终抛出 OutOfMemoryError（newCachedThreadPool 则因最大线程数无界而危险）。生产环境建议直接构造 ThreadPoolExecutor 并明确队列容量与拒绝策略。',5),
(79,'judge','调用 Thread.start() 之后，线程在 Java 层面进入 RUNNABLE 状态，它涵盖了操作系统层面的就绪与运行两种情况。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。Thread.State 只有 NEW、RUNNABLE、BLOCKED、WAITING、TIMED_WAITING、TERMINATED 六种；等待 synchronized 锁是 BLOCKED，调用无超时的 wait/join 是 WAITING，带超时则是 TIMED_WAITING。',5),
(79,'single','相对 synchronized，ReentrantLock 的主要优势是？',
 '[{"key":"A","text":"任何情况下性能都更高"},{"key":"B","text":"支持可中断地获取锁、超时获取、公平性选择以及多个条件队列"},{"key":"C","text":"不需要手动释放锁"},{"key":"D","text":"语法更加简洁"}]',
 'B','ReentrantLock 提供 lockInterruptibly、tryLock(超时)、newCondition 创建多个条件队列以及公平/非公平策略，灵活性远超 synchronized；代价是必须在 finally 中显式 unlock。JDK 6 之后两者性能已基本持平。',5),
(79,'single','约定所有线程都按同一个全局顺序申请多把锁，可以破坏死锁的哪个必要条件？',
 '[{"key":"A","text":"互斥条件"},{"key":"B","text":"占有且等待条件"},{"key":"C","text":"不可剥夺条件"},{"key":"D","text":"循环等待条件"}]',
 'D','统一加锁顺序后就不可能出现"持有 A 等 B、持有 B 等 A"的环形等待链，从而破坏循环等待——这是最实用、代价最小的死锁预防手段。一次性申请全部资源破坏的是"占有且等待"，超时回退破坏的是"不可剥夺"。',5),
(79,'judge','被 volatile 修饰的变量执行 i++ 这样的复合操作仍然是线程不安全的。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。volatile 只保证单次读写的原子性与可见性，i++ 包含读、加、写三个步骤，多线程下仍会丢失更新。要保证原子性应使用 synchronized、AtomicInteger 或 LongAdder，不能指望 volatile。',5),
(79,'judge','一个线程运行结束后，可以再次调用它的 start() 方法重新启动。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。线程生命周期不可回退，对已启动过（或已终止）的线程再次调用 start() 会抛 IllegalThreadStateException。需要重复执行任务应创建新的线程实例，或直接把任务提交给线程池复用线程。',5),
(79,'judge','synchronized 是可重入锁：同一个线程可以再次获取自己已经持有的锁。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。可重入避免了同步方法互相调用时把自己锁死，实现上记录持有线程与进入计数，计数归零才真正释放锁。ReentrantLock 同样可重入，这也是它名字的由来。',5),
(79,'multi','关于线程安全，下列说法正确的有？（多选）',
 '[{"key":"A","text":"无状态对象（没有成员变量）天然线程安全"},{"key":"B","text":"真正不可变的对象（字段全为 final 且状态不可变）天然线程安全"},{"key":"C","text":"StringBuilder 线程不安全，StringBuffer 线程安全"},{"key":"D","text":"方法中的局部变量一定不存在线程安全问题"}]',
 'ABC','A 正确，没有共享状态就没有竞争；B 正确，不可变对象可安全发布给任意线程；C 正确，StringBuffer 的方法加了 synchronized；D 错，局部变量本身在栈帧中私有，但它引用的对象一旦逃逸（如放进共享集合）仍会产生线程安全问题。',8),
(79,'multi','下列哪些是推荐的线程间等待与协作方式？（多选）',
 '[{"key":"A","text":"Object.wait() 与 notifyAll()"},{"key":"B","text":"Condition.await() 与 signal()"},{"key":"C","text":"CountDownLatch"},{"key":"D","text":"用 Thread.sleep() 不断轮询一个共享标志位"}]',
 'ABC','A、B 基于条件队列，C 是一次性同步器，都能及时被唤醒且不空耗 CPU；D 是反模式，响应延迟不可控还浪费 CPU，仅靠 volatile 标志加轮询也只适用于极简场景，协作逻辑应交给同步工具。',8),
(80,'single','关于 List<String> 与 List<Integer> 在运行期的表现，正确的是？',
 '[{"key":"A","text":"二者对应不同的 Class 对象"},{"key":"B","text":"类型被擦除，运行期 getClass() 返回的是同一个 List 的 Class"},{"key":"C","text":"可以互相强制转换且保留元素类型检查"},{"key":"D","text":"List<String> 是 List<Integer> 的子类型"}]',
 'B','泛型在编译后擦除为原始类型（或上界），运行期只有一个 List.class，所以无法用 instanceof 区分、也无法据其重载；存取时所需的强制类型转换和维持多态的桥方法都由编译器自动插入。',5),
(80,'single','List<?> 与 List<Object> 的关键区别是？',
 '[{"key":"A","text":"二者完全等价"},{"key":"B","text":"List<?> 表示某种未知的具体类型，不能向其添加除 null 之外的元素；List<Object> 可以添加任意 Object"},{"key":"C","text":"List<?> 可以添加任意元素"},{"key":"D","text":"List<Object> 不能读取元素"}]',
 'B','通配符表达"某一种确定但未知的类型"，编译器无法验证写入的类型安全，故禁止添加（null 除外）；List<Object> 的元素类型明确就是 Object，可以写入任何对象。上界用 ? extends，下界用 ? super。',5),
(80,'single','按照 PECS 原则，一个只负责向外提供元素（生产者）的集合参数应声明为？',
 '[{"key":"A","text":"List<? super T>"},{"key":"B","text":"List<? extends T>"},{"key":"C","text":"List<T>"},{"key":"D","text":"List<?>"}]',
 'B','Producer extends：生产者用 ? extends T，读出的元素可安全地当作 T 使用；Consumer super：只写入的集合用 ? super T，写入 T 及其子类都合法。Collections.copy(dest, src) 的签名就是这一原则的范例。',5),
(80,'single','泛型方法 <T> T get(List<T> list) 的类型参数 T 由什么决定？',
 '[{"key":"A","text":"由方法的返回值类型决定"},{"key":"B","text":"由调用处的实参类型推断，必要时可显式指定"},{"key":"C","text":"固定为 Object"},{"key":"D","text":"由所在类的类型参数决定"}]',
 'B','泛型方法的类型参数独立于类的类型参数，编译期根据实参与目标类型推断，推断不出时可写 obj.<String>get(list) 显式指定。静态方法无法使用类的类型参数，必须自己声明 <T>。',5),
(80,'single','为什么 Java 不允许创建具体泛型类型的数组，如 new List<String>[10]？',
 '[{"key":"A","text":"语法上不支持，因为数组协变且在运行期检查元素类型，与泛型擦除机制冲突"},{"key":"B","text":"因为运行期性能太差"},{"key":"C","text":"因为 List 是接口"},{"key":"D","text":"Java 禁止一切数组创建"}]',
 'A','数组是协变且在运行期做元素类型检查（ArrayStoreException），而泛型被擦除，二者结合会产生类型漏洞：可以把 List<Integer> 存进 List<String>[] 而不被察觉。替代方案是创建通配数组后强转，或用 List<List<String>>。',5),
(80,'single','要通过反射获取某个字段声明的泛型类型（例如 List<String> 中的 String），应使用？',
 '[{"key":"A","text":"field.getType()"},{"key":"B","text":"field.getGenericType() 得到 ParameterizedType 后再取实际类型参数"},{"key":"C","text":"field.getClass()"},{"key":"D","text":"完全无法获取，泛型已被彻底擦除"}]',
 'B','泛型并非全部丢失：类、字段、方法、父类的泛型签名保存在字节码的 Signature 属性中，getGenericType() 会返回 ParameterizedType，可取出 String 等实际类型参数。真正被擦除的是"对象实例所属的具体类型参数"。',5),
(80,'single','通过反射调用一个私有方法，正确步骤是？',
 '[{"key":"A","text":"用 getMethod 获取后直接 invoke"},{"key":"B","text":"用 getDeclaredMethod 获取后调用 setAccessible(true) 再 invoke"},{"key":"C","text":"私有方法永远无法调用"},{"key":"D","text":"必须先把方法改为 public"}]',
 'B','getMethod 只能取到 public 方法（含继承的），私有方法要用 getDeclaredMethod；再调用 setAccessible(true) 关闭 Java 语言访问检查，否则 invoke 时抛 IllegalAccessException。JDK 9 之后跨模块的反射还受模块是否 open 的限制。',5),
(80,'single','关于 Class.forName("com.foo.Bar")，下列说法错误的是？',
 '[{"key":"A","text":"它会触发该类的加载"},{"key":"B","text":"它会执行该类的静态初始化（静态代码块）"},{"key":"C","text":"它返回该类的 Class 对象"},{"key":"D","text":"它会创建一个该类的实例"}]',
 'D','forName 完成加载、链接与初始化（执行静态块）并返回 Class 对象，并不创建实例；创建实例要用 getDeclaredConstructor().newInstance()。JDBC 驱动的注册正是利用 forName 触发静态代码块完成的。',5),
(80,'single','不能同时定义 void f(List<String>) 与 void f(List<Integer>) 两个重载方法，原因是？',
 '[{"key":"A","text":"Java 不支持任何重载"},{"key":"B","text":"类型擦除后两者签名都是 f(List)，产生名称冲突"},{"key":"C","text":"泛型类型不能作为方法参数"},{"key":"D","text":"List<String> 与 List<Integer> 是完全相同的类型"}]',
 'B','重载看的是擦除后的签名，两个方法擦除后都是 f(List)，编译器报 name clash: 两者具有相同的擦除。解决办法是改名，或通过让它们实现不同的泛型接口来区分（此时编译器会生成桥方法）。',5),
(80,'judge','Java 的泛型可以直接用于基本类型，例如 List<int>。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。泛型参数必须是引用类型，List<int> 无法编译，只能写 List<Integer> 并承担装箱开销与额外的内存占用。对性能敏感的大量数值计算可考虑基本类型流或专门的原始类型集合。',5),
(80,'judge','由于类型擦除，不能在运行时用 instanceof 判断一个对象是否是 List<String>。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。运行期已无 String 这一类型参数信息，list instanceof List<String> 是编译错误，只能写 list instanceof List<?> 或逐个检查元素类型。这直观体现了"泛型只提供编译期类型安全"的特点。',5),
(80,'judge','反射可以在运行期读取并修改类的私有字段。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。getDeclaredField 配合 setAccessible(true) 即可读写私有字段，这是 Spring 依赖注入、ORM 映射、序列化框架的实现基础；代价是破坏封装、受模块系统与安全管理器限制，且字段改名不会被编译器发现。',5),
(80,'judge','反射调用比直接方法调用慢，因为它需要动态解析方法、做访问检查并对参数装箱。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。反射路径难以被 JIT 内联和优化，频繁调用应缓存 Class/Method 对象并调用 setAccessible(true)，或改用 MethodHandle；在框架启动、配置解析等非热点路径上，这点开销通常可以接受。',5),
(80,'multi','关于 Java 泛型，下列说法正确的有？（多选）',
 '[{"key":"A","text":"泛型在编译期提供类型检查，避免运行期强制转换出错"},{"key":"B","text":"擦除后必要时由编译器自动插入强制类型转换与桥方法"},{"key":"C","text":"静态方法不能使用所属类的类型参数"},{"key":"D","text":"可以在泛型代码中用 new T() 创建类型参数的实例"}]',
 'ABC','A、B 正确，编译器插入 checkcast 保证类型安全，桥方法用于维持重写关系；C 正确，类的类型参数属于实例，静态方法必须自行声明 <T>；D 错，T 在运行期不存在，只能借助 Class<T> 反射或显式传入工厂来创建。',8),
(80,'multi','关于反射机制，下列说法正确的有？（多选）',
 '[{"key":"A","text":"可以获取类的构造方法、方法、字段与注解信息"},{"key":"B","text":"可以在运行期根据字符串形式的类名动态加载并实例化"},{"key":"C","text":"反射调用绕过编译期类型检查，参数错误要到运行期才暴露"},{"key":"D","text":"反射获取到的泛型信息在任何位置都与源码声明完全一致"}]',
 'ABC','A、B、C 是反射的基本能力与其代价；D 错，泛型信息只保留在类、字段、方法、父类等签名处，局部变量、数组元素等位置的泛型被完全擦除，类型变量本身也可能只剩下上界，不能一概而论。',8),
(80,'single','下列泛型声明中，表示"元素类型是 Number 或它的某个子类"的是？',
 '[{"key":"A","text":"List<? extends Number>"},{"key":"B","text":"List<? super Number>"},{"key":"C","text":"List<Number>"},{"key":"D","text":"List<?>"}]',
 'A','上界通配符 ? extends Number 表示某一种 Number 或其子类型（Integer、Double 等），可以安全地按 Number 读出，但不能写入（除 null 外，因为无法确定具体是哪种子类型）；? super Number 表示 Number 或其父类型，写入 Number 及子类都合法。这正是 PECS 中 extends 与 super 的方向差异。',5);

-- ---------- rest-js.js ----------
INSERT INTO question (knowledge_id, type, title, options, answer, analysis, score) VALUES
(96,'single','表达式 typeof null 的运行结果是？',
 '[{"key":"A","text":"\\"null\\""},{"key":"B","text":"\\"object\\""},{"key":"C","text":"\\"undefined\\""},{"key":"D","text":"\\"number\\""}]',
 'B','这是语言早期的历史遗留：值以类型标签存储，null 的标签恰好与对象相同，于是 typeof null 得到 "object"。判断 null 必须用 x === null，不能用 typeof。',5),
(96,'single','表达式 [] == ![] 的结果是？',
 '[{"key":"A","text":"true"},{"key":"B","text":"false"},{"key":"C","text":"抛出 TypeError"},{"key":"D","text":"undefined"}]',
 'A','先算 ![]：空数组是对象、为真值，取反得 false；再比较 [] == false，布尔先转数字为 0，空数组转原始值为空串，空串转数字也是 0，故相等返回 true。误区是以为对象和布尔比较一定不等，忽略了宽松相等会先做类型转换。',5),
(96,'single','判断变量 x 的值确实是 NaN，最可靠的写法是？',
 '[{"key":"A","text":"x === NaN"},{"key":"B","text":"Number.isNaN(x)"},{"key":"C","text":"isNaN(x)"},{"key":"D","text":"x == NaN"}]',
 'B','NaN 与任何值都不相等，包括它自己，所以 x === NaN 恒为 false。全局 isNaN 会先做隐式转换，isNaN("abc") 也返回 true，会把普通字符串误判为 NaN。Number.isNaN 不做转换，仅当值确实是 NaN 时才为 true。',5),
(96,'single','表达式 0.1 + 0.2 === 0.3 的结果是？',
 '[{"key":"A","text":"true"},{"key":"B","text":"false"},{"key":"C","text":"在部分浏览器为 true"},{"key":"D","text":"抛出精度异常"}]',
 'B','0.1、0.2 都无法用二进制浮点精确表示，相加得到 0.30000000000000004，与 0.3 不相等。比较浮点应看差值是否小于某个容差，如 Math.abs(a - b) < Number.EPSILON，或改用整数分单位计算。',5),
(96,'single','代码 console.log(a); let a = 1; 的运行结果是？',
 '[{"key":"A","text":"输出 undefined"},{"key":"B","text":"输出 1"},{"key":"C","text":"抛出 ReferenceError"},{"key":"D","text":"输出 null"}]',
 'C','let/const 声明的作用域内，从进入作用域到声明语句执行之前，变量处于暂时性死区（TDZ），此时读取它会抛 ReferenceError，而不是像 var 那样得到 undefined。这也是 let 相对 var 更安全的地方。',5),
(96,'single','Number("") 与 parseInt("") 的结果分别是？',
 '[{"key":"A","text":"0 和 NaN"},{"key":"B","text":"NaN 和 NaN"},{"key":"C","text":"0 和 0"},{"key":"D","text":"NaN 和 0"}]',
 'A','Number 对空串按整体转换规则得到 0，而 parseInt 要求至少解析出一位数字，解析不出就返回 NaN。同类易混点：Number("12px") 是 NaN，parseInt("12px") 是 12。',5),
(96,'single','表达式 "5" + 3 与 "5" - 3 的结果分别是？',
 '[{"key":"A","text":"8 和 2"},{"key":"B","text":"\\"53\\" 和 2"},{"key":"C","text":"\\"53\\" 和 NaN"},{"key":"D","text":"8 和 NaN"}]',
 'B','加号遇到字符串优先做拼接，得到字符串 "53"；减号只做数值运算，会把两边转数字，得到 2。规律：+ 是重载运算符（可能拼接），- * / 一律转数字。',5),
(96,'single','Symbol("a") === Symbol("a") 与 Symbol.for("a") === Symbol.for("a") 的结果分别是？',
 '[{"key":"A","text":"false 和 true"},{"key":"B","text":"true 和 true"},{"key":"C","text":"false 和 false"},{"key":"D","text":"true 和 false"}]',
 'A','Symbol() 每次都创建一个全新的唯一值，即使描述文字相同也不相等；Symbol.for 会先查全局注册表，同名 key 命中就复用同一个 Symbol，所以相等。',5),
(96,'single','Object.is(NaN, NaN) 与 Object.is(0, -0) 的结果分别是？',
 '[{"key":"A","text":"true 和 false"},{"key":"B","text":"false 和 true"},{"key":"C","text":"true 和 true"},{"key":"D","text":"false 和 false"}]',
 'A','Object.is 是同值比较：它把 NaN 视为与自身相等，同时能区分 +0 与 -0，这两点正是 === 做不到的（=== 下 NaN !== NaN、0 === -0）。',5),
(96,'single','Boolean(new Boolean(false)) 与 Boolean([]) 的结果分别是？',
 '[{"key":"A","text":"true 和 true"},{"key":"B","text":"false 和 false"},{"key":"C","text":"false 和 true"},{"key":"D","text":"true 和 false"}]',
 'A','new Boolean(false) 得到的是包装对象，任何对象转布尔都是 true，与它内部包裹的 false 无关；空数组也是对象，同样为 true。只有 undefined、null、0、NaN、""、false 这几种才是假值。',5),
(96,'judge','用 var 声明的变量，其声明会被提升到作用域顶部，但赋值不会提升，因此提升后访问得到 undefined。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。var 的声明提升使变量在作用域一开始就存在并初始化为 undefined，赋值语句仍在原位置执行，这就是所谓的变量提升。',5),
(96,'judge','表达式 [] == false 的结果为 true。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。空数组转原始值为空串，空串转数字为 0；false 转数字也是 0，故相等。注意 [] == 0 也为 true，但 [] === false 为 false。',5),
(96,'judge','用 const 声明的对象，其属性既不能新增也不能修改。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。const 约束的是绑定不可重新赋值，对象内部内容仍可增删改；要禁止修改需 Object.freeze（且它只冻结一层）。',5),
(96,'judge','表达式 "2" > "10" 的结果为 true。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。两个操作数都是字符串时按字典序逐字符比较，"2" 的首字符码点大于 "1"，所以结果为 true，而数值比较 2 > 10 才是 false。想按数值比要先转 Number。',5),
(96,'multi','下列哪些值在 if 条件中被当作假值（falsy）？',
 '[{"key":"A","text":"数字 0"},{"key":"B","text":"空字符串 \\"\\""},{"key":"C","text":"NaN"},{"key":"D","text":"空数组 []"}]',
 'ABC','假值只有 false、0、-0、0n、""、null、undefined、NaN 八种。空数组、空对象、字符串 "0"、字符串 "false" 都是对象或非空串，属于真值。',8),
(96,'multi','关于 == 与 ===，下列说法正确的有？',
 '[{"key":"A","text":"=== 在类型不同时直接返回 false，不做类型转换"},{"key":"B","text":"== 认为 null 与 undefined 相等，且二者不与其它任何值相等"},{"key":"C","text":"=== 比较两个对象时比较的是引用地址而非内容"},{"key":"D","text":"== 比较任意两个对象时会先把它们转换为原始值"}]',
 'ABC','== 只在需要时转换，两个操作数都是对象时直接比较引用；null 与 undefined 在 == 下互相相等且不粘其它值，所以 x == null 常被用来同时判空。',8),
(96,'multi','关于 let、const、var 的作用域与声明规则，下列说法正确的有？',
 '[{"key":"A","text":"let 与 const 声明的变量具有块级作用域"},{"key":"B","text":"const 声明时必须初始化，且不能对同一绑定重新赋值"},{"key":"C","text":"同一作用域内用 let 重复声明同名变量会抛 SyntaxError"},{"key":"D","text":"const 声明的对象，其内部属性值一旦确定就无法再修改"}]',
 'ABC','var 只有函数/全局作用域且有提升，let/const 有块级作用域与暂时性死区、不可重复声明。const 只锁绑定不锁内容，对象属性照样能改。',8),
(97,'single','表达式 ["1", "2", "3"].map(parseInt) 的运行结果是？',
 '[{"key":"A","text":"[1, 2, 3]"},{"key":"B","text":"[1, NaN, NaN]"},{"key":"C","text":"[NaN, NaN, NaN]"},{"key":"D","text":"[1, NaN, 3]"}]',
 'B','map 把 (元素, 下标, 数组) 三个参数全部传给回调，而 parseInt 的第二个参数是进制：下标 1 是非法进制得 NaN，下标 2 表示二进制，"3" 不是合法二进制数字也得 NaN。正确写法是 map(x => parseInt(x, 10))。',5),
(97,'single','表达式 [10, 1, 2].sort() 的默认排序结果是？',
 '[{"key":"A","text":"[1, 2, 10]"},{"key":"B","text":"[10, 1, 2]"},{"key":"C","text":"[1, 10, 2]"},{"key":"D","text":"[2, 1, 10]"}]',
 'C','默认排序把元素转成字符串按码点比较，"10" 的首字符 "1" 小于 "2"，于是 10 排在 2 前。数值排序必须传比较函数 arr.sort((a, b) => a - b)。',5),
(97,'single','表达式 [].reduce((a, b) => a + b) 的运行结果是？',
 '[{"key":"A","text":"返回 0"},{"key":"B","text":"返回 undefined"},{"key":"C","text":"抛出 TypeError：Reduce of empty array with no initial value"},{"key":"D","text":"返回 NaN"}]',
 'C','不提供初始值时，reduce 会用第 0 个元素作为初始累加器并从下标 1 开始；数组为空就没有任何元素可用作初始值，规范规定此时抛 TypeError。给出初始值 0 则空数组安全地返回 0。',5),
(97,'single','关于 map 与 forEach 的返回值，正确的是？',
 '[{"key":"A","text":"map 返回新数组，forEach 返回 undefined"},{"key":"B","text":"两者都返回新数组"},{"key":"C","text":"forEach 返回原数组，map 返回 undefined"},{"key":"D","text":"两者都返回 undefined"}]',
 'A','map 把每次回调的返回值收集成等长新数组，原数组不变；forEach 只做遍历、丢弃回调返回值，结果是 undefined，需要累积结果时应改 map/reduce 或自己 push。',5),
(97,'single','关于 filter 的行为，正确的是？',
 '[{"key":"A","text":"返回一个新数组，包含所有使回调返回真值的原元素"},{"key":"B","text":"返回第一个满足条件的元素"},{"key":"C","text":"返回所有满足条件元素的下标数组"},{"key":"D","text":"原地删除不满足条件的元素"}]',
 'A','filter 不修改原数组，只把回调返回真值的元素按原顺序放进新数组；返回第一个元素的是 find，返回下标的是 findIndex。',5),
(97,'single','关于 slice(1, 3) 与 splice(1, 3) 的区别，正确的是？',
 '[{"key":"A","text":"slice 返回新数组且不改原数组；splice 删除元素并返回被删元素，会改原数组"},{"key":"B","text":"两者都不改原数组"},{"key":"C","text":"两者都会修改原数组"},{"key":"D","text":"splice 返回新数组，slice 返回被删元素"}]',
 'A','slice 是纯读操作，截取区间 [1,3) 的浅拷贝；splice(1,3) 表示从下标 1 起删除 3 个元素，返回被删元素组成的数组，原数组长度会变，因此会打断正在进行的遍历。',5),
(97,'single','表达式 Array(3).map(() => 1) 的结果是？',
 '[{"key":"A","text":"[1, 1, 1]"},{"key":"B","text":"[undefined, undefined, undefined]"},{"key":"C","text":"长度为 3 但元素仍是空的空洞数组，回调一次都没执行"},{"key":"D","text":"[]"}]',
 'C','Array(3) 只设置了 length，创建的是稀疏数组，没有任何真实元素；map、forEach、filter 等都会跳过空洞。要初始化应写 Array.from({ length: 3 }, () => 1) 或先 fill。',5),
(97,'single','要删除数组最后一个元素并返回该元素，应使用的方法是？',
 '[{"key":"A","text":"pop()"},{"key":"B","text":"shift()"},{"key":"C","text":"push()"},{"key":"D","text":"slice(-1)"}]',
 'A','pop 删除并返回末元素，shift 删除并返回首元素，两者都改原数组；push 在尾部追加并返回新长度；slice(-1) 不改原数组但返回的是长度为 1 的数组而不是元素本身。',5),
(97,'single','要把多层嵌套数组 [[1, [2]], 3] 完全拉平成一维数组，应使用？',
 '[{"key":"A","text":"arr.flat()"},{"key":"B","text":"arr.flat(Infinity)"},{"key":"C","text":"arr.flatMap(x => x)"},{"key":"D","text":"arr.concat()"}]',
 'B','flat 的参数是拉平深度，默认 1 只拆一层，传 Infinity 才递归拉平到底；flatMap 等价于先 map 再 flat(1)，也只拉一层。',5),
(97,'single','关于 find 与 findIndex 的返回值，正确的是？',
 '[{"key":"A","text":"find 返回元素本身，findIndex 返回下标；找不到时分别是 undefined 和 -1"},{"key":"B","text":"两者都返回下标"},{"key":"C","text":"find 返回数组，findIndex 返回元素"},{"key":"D","text":"找不到时两者都返回 null"}]',
 'A','找不到时 find 给 undefined、findIndex 给 -1，不能用它们的结果做真假判断来区分"找到了下标 0"与"没找到"。indexOf 用严格相等比较，无法按条件查找对象。',5),
(97,'judge','Array.isArray([]) 与 [] instanceof Array 在单一全局环境下都能判断数组，但跨 iframe 时 instanceof 可能失效。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。不同全局环境（iframe、vm）各有自己的 Array 构造函数，原型链不同，instanceof 会误判；Array.isArray 按内部标记判断，跨环境可靠。',5),
(97,'judge','sort 方法会在原数组上就地排序，并返回排序后的同一个数组引用。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。sort、reverse、splice 都是原地修改，返回的是原数组本身；若要保留原数组，应先 [...arr] 再排序。',5),
(97,'judge','表达式 [].every(x => x > 0) 的结果为 false。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。every 是全称量词，在空集合上为真，空数组调用 every 恒为 true；同理 some 在空数组上恒为 false。想表达"非空且全部满足"必须先判断 length。',5),
(97,'judge','concat 方法会修改调用它的原数组，把参数连接到它后面。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。concat 返回拼接后的新数组，原数组不变；只有 push、unshift、splice 等才会原地增删。',5),
(97,'multi','下列哪些数组方法会直接修改调用它的原数组？',
 '[{"key":"A","text":"push"},{"key":"B","text":"splice"},{"key":"C","text":"sort"},{"key":"D","text":"map"}]',
 'ABC','push/pop/shift/unshift/splice/sort/reverse/fill 都会原地改动；map、filter、slice、concat、flat 返回新数组，原数组保持不变。',8),
(97,'multi','关于 reduce 的执行细节，下列说法正确的有？',
 '[{"key":"A","text":"回调参数依次为累加器、当前元素、当前下标、原数组"},{"key":"B","text":"提供初始值时，第一次回调的累加器就是该初始值，并从下标 0 开始遍历"},{"key":"C","text":"不提供初始值时，第一次回调的累加器为第 0 个元素，并从下标 1 开始"},{"key":"D","text":"reduce 只能对数字数组求和，不能返回对象或数组"}]',
 'ABC','累加器可以是任意类型，用 reduce 统计词频、分组、拍平成对象都很常见；关键是记得给初始值，否则空数组会抛 TypeError。',8),
(97,'multi','关于数组的高阶函数，下列说法正确的有？',
 '[{"key":"A","text":"map 返回的新数组与原数组长度相同"},{"key":"B","text":"filter 返回的新数组长度可能小于原数组"},{"key":"C","text":"forEach 中的 return 无法终止整个遍历，要提前中断应改用 for 循环或 some/every"},{"key":"D","text":"map 的回调返回 undefined 时，该项会被从结果数组中剔除"}]',
 'ABC','map 是一对一变换，回调返回 undefined 也照样占位（结果里就是 undefined），剔除元素要交给 filter。forEach 无法 break，靠 return 只能跳过当次。',8),
(98,'single','关于对象展开 {...obj} 的拷贝行为，正确的是？',
 '[{"key":"A","text":"深拷贝，嵌套对象也完全独立"},{"key":"B","text":"浅拷贝，嵌套对象仍与原对象共享引用"},{"key":"C","text":"只复制自有可枚举属性，且不包含 Symbol 键"},{"key":"D","text":"等价于 Object.create(obj)，新对象以 obj 为原型"}]',
 'B','展开只复制一层：顶层属性写进新对象，嵌套对象复制的是引用，改嵌套属性两边都变。展开同样会复制可枚举的 Symbol 键，这点与 Object.assign 一致；要真正独立可用 structuredClone 或递归深拷贝。',5),
(98,'single','代码 const { a: b } = obj; 的含义是？',
 '[{"key":"A","text":"取 obj 的 a 属性，把它的值赋给变量 b"},{"key":"B","text":"取 obj 的 b 属性，把它的值赋给变量 a"},{"key":"C","text":"同时声明 a 和 b 两个变量"},{"key":"D","text":"语法错误，对象解构不能写冒号"}]',
 'A','对象解构里冒号左侧是"要取的属性名"，右侧是"要声明的变量名"，所以这里声明的是变量 b，值为 obj.a；只写 const { a } = obj 才是属性名与变量名同名。',5),
(98,'single','对象解构的默认值 const { a = 1 } = obj 在什么情况下生效？',
 '[{"key":"A","text":"仅当 obj.a 为 undefined 时"},{"key":"B","text":"当 obj.a 为 null 或 undefined 时"},{"key":"C","text":"当 obj.a 为任意假值（0、\\"\\"、false）时"},{"key":"D","text":"任何时候都用 1 覆盖取到的值"}]',
 'A','解构默认值只由 undefined 触发，null、0、空串都会原样赋给变量。这与 || 的假值兜底不同，也是默认值最常踩的坑。',5),
(98,'single','对象字面量中出现同名属性 { a: 1, a: 2 }，最终结果是？',
 '[{"key":"A","text":"报 SyntaxError"},{"key":"B","text":"{ a: 1 }"},{"key":"C","text":"{ a: 2 }"},{"key":"D","text":"{ a: [1, 2] }"}]',
 'C','非严格模式下重复键不报错，后写的覆盖先写的，最终 a 为 2；严格模式（ES5 起）对重复键不再报错但仍取最后一个值。',5),
(98,'single','对象字面量中用数字 1 作键时，它会被如何处理？',
 '[{"key":"A","text":"保持数字类型"},{"key":"B","text":"转换为字符串 \\"1\\" 存储"},{"key":"C","text":"转换为 Symbol"},{"key":"D","text":"不允许数字作键，会报错"}]',
 'B','对象键只能是字符串或 Symbol，数字键会被转成字符串；这类"整数键"在遍历时还会按数值升序优先排列，排在普通字符串键之前。',5),
(98,'single','想在对象字面量中用变量 key 的值作为属性名，应写成？',
 '[{"key":"A","text":"{ key: value }"},{"key":"B","text":"{ [key]: value }"},{"key":"C","text":"{ \\"key\\": value }"},{"key":"D","text":"{ key => value }"}]',
 'B','方括号是计算属性名语法，方括号内表达式的值会被转成字符串当键；直接写 key 得到的是字面量属性 "key"，与变量无关。',5),
(98,'single','用一行语句交换变量 a 与 b 的值，正确的写法是？',
 '[{"key":"A","text":"[a, b] = [b, a]"},{"key":"B","text":"{ a, b } = { b, a }"},{"key":"C","text":"a = b; b = a"},{"key":"D","text":"swap(a, b)"}]',
 'A','数组解构按位置匹配：先整体求值右侧 [b, a] 得到新数组，再按顺序赋给左侧的 a、b。写法 C 会让两者都变成原 b 的值，是错误的经典写法。',5),
(98,'single','关于 Object.assign(target, s1, s2) 的行为，正确的是？',
 '[{"key":"A","text":"深拷贝，返回一个新对象"},{"key":"B","text":"把源对象的可枚举自有属性浅拷贝到 target 并返回 target，同名属性后者覆盖前者"},{"key":"C","text":"把 target 的属性拷贝到源对象上"},{"key":"D","text":"只能接收一个源对象，多余参数被忽略"}]',
 'B','Object.assign 是浅拷贝且会修改第一个实参（传 {} 当目标即可避免污染），getter 会被求值成普通值，Symbol 键也会被复制。',5),
(98,'single','表达式 obj?.a?.b 在 obj 为 null 时的结果是？',
 '[{"key":"A","text":"抛出 TypeError"},{"key":"B","text":"undefined"},{"key":"C","text":"null"},{"key":"D","text":"false"}]',
 'B','可选链在遇到 null 或 undefined 时立即短路，整个表达式返回 undefined，不再继续取属性；注意它只对 null/undefined 短路，对 0、"" 等假值不短路。',5),
(98,'single','要把数组 arr 的每个元素作为独立实参传给 Math.max，应写成？',
 '[{"key":"A","text":"Math.max(arr)"},{"key":"B","text":"Math.max(...arr)"},{"key":"C","text":"Math.max.apply(arr)"},{"key":"D","text":"Math.max([...arr])"}]',
 'B','展开运算符在函数调用位置会把可迭代对象摊开成参数序列；直接传数组会被转成数字 NaN。ES5 时代常用 Math.max.apply(null, arr) 达到同样效果。',5),
(98,'judge','对象展开与 Object.assign 一样都是浅拷贝，嵌套对象仍会与原对象共享引用。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。两者语义几乎一致，都只复制一层自有可枚举属性；深拷贝要另想办法。',5),
(98,'judge','Object.freeze(obj) 会递归冻结 obj 的所有嵌套属性，使整棵对象树都不可变。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。freeze 是浅冻结，只锁住第一层的属性不可写、不可配置；嵌套对象本身仍是普通可变对象，需要手写递归深冻结。',5),
(98,'judge','解构赋值 const { a } = null 会在运行时抛出 TypeError。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。null 与 undefined 不能被转为对象，对它们取属性即报 TypeError；数组解构同理，只有给默认值也无法救（默认值只对 undefined 的元素生效，对 null/undefined 的源本身无效）。',5),
(98,'judge','Object.keys 遍历普通对象时，整数形式的键会按数值升序优先排列，其余字符串键保持插入顺序。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。属性遍历顺序规则是：先升序枚举整数索引键，再按插入顺序枚举字符串键，最后按插入顺序枚举 Symbol 键。',5),
(98,'multi','关于对象浅拷贝，下列说法正确的有？',
 '[{"key":"A","text":"{ ...obj } 只复制自有可枚举属性，不复制原型链上的属性"},{"key":"B","text":"对拷贝结果的顶层属性重新赋值不会影响原对象"},{"key":"C","text":"修改拷贝结果中嵌套对象的属性会同时影响原对象"},{"key":"D","text":"JSON.parse(JSON.stringify(obj)) 能完整保留函数、Symbol 与循环引用"}]',
 'ABC','JSON 序列化法会丢掉函数、undefined、Symbol，遇到循环引用直接报错，Date 也会变成字符串；可靠深拷贝应优先 structuredClone。',8),
(98,'multi','关于解构赋值，下列说法正确的有？',
 '[{"key":"A","text":"数组解构按下标位置匹配，可以用逗号跳过元素"},{"key":"B","text":"对象解构按属性名匹配，与书写顺序无关"},{"key":"C","text":"解构时可用 rest 语法收集剩余属性，如 const { a, ...rest } = obj"},{"key":"D","text":"数组解构的剩余元素可以写成 const [a, ...rest, z] = arr"}]',
 'ABC','剩余元素（rest）必须是解构模式中的最后一项，[a, ...rest, z] 是语法错误；对象 rest 同理只能放在最后。',8),
(98,'multi','关于对象属性的检查与枚举，下列说法正确的有？',
 '[{"key":"A","text":"in 运算符会检查原型链上的属性"},{"key":"B","text":"obj.hasOwnProperty(\\"x\\") 只检查对象自身的属性"},{"key":"C","text":"for...in 会枚举原型链上的可枚举属性"},{"key":"D","text":"Object.keys(obj) 会包含原型链上的可枚举属性"}]',
 'ABC','Object.keys/values/entries 只看自有可枚举属性，不含原型链；想过滤原型污染的影响，for...in 循环里通常要配 hasOwnProperty 判断。',8),
(99,'single','addEventListener("click", fn, true) 中第三个参数传 true 的含义是？',
 '[{"key":"A","text":"让监听器在冒泡阶段执行"},{"key":"B","text":"让监听器在捕获阶段执行"},{"key":"C","text":"等价于 once，只执行一次"},{"key":"D","text":"等价于 passive，阻止默认行为"}]',
 'B','第三个参数为 true（或 { capture: true }）时监听器注册在捕获阶段，会从外向内先触发；默认 false 表示冒泡阶段，由内向外触发。',5),
(99,'single','事件处理函数中 e.target 与 e.currentTarget 的区别是？',
 '[{"key":"A","text":"两者永远指向同一个元素"},{"key":"B","text":"target 是事件的源头元素，currentTarget 是当前正在执行监听器的元素"},{"key":"C","text":"target 只在捕获阶段有效"},{"key":"D","text":"currentTarget 指事件冒泡的终点元素"}]',
 'B','事件委托时点击子元素，target 是被点的子元素，而 currentTarget 是绑监听器的父容器，因此取数据时要用 target（或 closest 向上找）。',5),
(99,'single','innerHTML 与 textContent 的主要区别是？',
 '[{"key":"A","text":"innerHTML 会解析 HTML 标签并可能执行其中的脚本，textContent 一律当纯文本处理"},{"key":"B","text":"两者完全等价"},{"key":"C","text":"textContent 会解析 HTML 标签"},{"key":"D","text":"innerHTML 只能读不能写"}]',
 'A','写入 innerHTML 会重建子树、丢失已绑定的事件与状态，且拼接用户输入会带来 XSS 风险；展示纯文本优先用 textContent，既安全又更快。',5),
(99,'single','document.querySelector("p") 的返回值是？',
 '[{"key":"A","text":"页面中所有 p 元素组成的数组"},{"key":"B","text":"第一个匹配的 p 元素；找不到时返回 null"},{"key":"C","text":"第一个匹配的 p 元素；找不到时返回 undefined"},{"key":"D","text":"一个 NodeList 集合"}]',
 'B','querySelector 返回单个 Element 或 null，要拿到全部匹配应用 querySelectorAll（返回 NodeList，找不到时是空 NodeList）。',5),
(99,'single','关于 querySelectorAll 与 getElementsByClassName 返回值的区别，正确的是？',
 '[{"key":"A","text":"两者返回的都是随 DOM 变化而更新的动态集合"},{"key":"B","text":"querySelectorAll 返回静态 NodeList，getElementsByClassName 返回动态 HTMLCollection"},{"key":"C","text":"两者返回的都是静态 NodeList"},{"key":"D","text":"querySelectorAll 返回的是动态 HTMLCollection"}]',
 'B','动态集合会在每次访问时重新查询 DOM，边遍历边增删元素容易跳过或重复；静态 NodeList 是查询那一刻的快照，遍历更安全。',5),
(99,'single','事件委托（在父元素上统一监听子元素事件）主要依赖哪种机制？',
 '[{"key":"A","text":"事件捕获"},{"key":"B","text":"事件冒泡"},{"key":"C","text":"事件对象复用"},{"key":"D","text":"浏览器默认行为"}]',
 'B','子元素上的事件会沿 DOM 树向上冒泡到祖先，因此在祖先上挂一个监听器就能处理整片子树的事件，从而大幅减少监听器数量。',5),
(99,'single','只想阻止链接的默认跳转、但让事件继续向上传播，应调用？',
 '[{"key":"A","text":"e.stopPropagation()"},{"key":"B","text":"e.preventDefault()"},{"key":"C","text":"在处理函数中 return true"},{"key":"D","text":"e.cancelBubble = true"}]',
 'B','preventDefault 取消默认行为（跳转、提交、勾选等），不影响传播；stopPropagation 才阻止继续传播。老式 return false 在属性写法里等价于两者都做。',5),
(99,'single','DOMContentLoaded 与 window 的 load 事件在触发时机上的区别是？',
 '[{"key":"A","text":"两者总是同时触发"},{"key":"B","text":"DOMContentLoaded 在 DOM 解析完成后即触发，不等图片等子资源；load 要等所有资源加载完毕"},{"key":"C","text":"load 先于 DOMContentLoaded 触发"},{"key":"D","text":"DOMContentLoaded 要等所有脚本与样式下载完才触发"}]',
 'B','需要在 DOM 就绪后绑定事件、初始化组件时监听 DOMContentLoaded 即可；要读取图片真实尺寸、依赖全部资源就绪时才用 load。',5),
(99,'single','需要向列表容器批量插入上千个节点时，性能较好的做法是？',
 '[{"key":"A","text":"每循环一次就改一次容器的 innerHTML"},{"key":"B","text":"先在 DocumentFragment（或字符串）中拼好，再一次性插入，减少重排与重绘"},{"key":"C","text":"循环调用 document.write 逐条写入"},{"key":"D","text":"为每个节点单独设置 style 属性触发渲染"}]',
 'B','每次插入都会触发布局与重排，批量操作先在离线容器里组装、一次性挂载，能把 N 次重排压成 1 次；document.write 还会清空已有文档。',5),
(99,'single','关于 classList 与 className 的说法，正确的是？',
 '[{"key":"A","text":"classList.add(\\"x\\") 会清掉元素原有的其它类名"},{"key":"B","text":"className 赋值会整体覆盖类名字符串，classList 提供 add/remove/toggle 等原子操作"},{"key":"C","text":"classList 只能读取，不能修改类名"},{"key":"D","text":"两者都是只读属性，无法修改类名"}]',
 'B','className 或 setAttribute("class") 赋值是整体替换，容易误删；classList 的 add/remove/toggle/contains 只动单个类名，且 toggle 还能接受第二个布尔参数。',5),
(99,'judge','用 el.onclick = fn 重复赋值会覆盖前一个处理函数，而 addEventListener 可以叠加多个监听器。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。onXXX 属性是单一槽位，后赋的值覆盖先前的；addEventListener 维护监听器列表，按注册顺序依次调用（同一函数+同一阶段只登记一次）。',5),
(99,'judge','事件委托对将来动态插入的子元素同样生效，无需重新绑定。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。判断逻辑写在祖先的监听器里，靠 target 或 closest 识别具体子项，因此新增节点天然被覆盖，这也是列表类场景的首选方案。',5),
(99,'judge','所有 DOM 事件都会冒泡，focus 与 blur 也不例外。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。focus、blur、load、mouseenter、mouseleave 等不冒泡；若需冒泡版可用 focusin/focusout，或用捕获阶段监听。',5),
(99,'judge','在捕获阶段调用 stopPropagation 后，目标元素上的监听器也不会执行。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。stopPropagation 会中断整条传播路径，后续阶段（包括目标阶段和冒泡阶段）的监听器都不再触发；只想拦住冒泡而不影响目标自身，可在冒泡阶段的祖先里调用它。',5),
(99,'multi','关于 DOM 事件传播，下列说法正确的有？',
 '[{"key":"A","text":"一次事件传播依次经历捕获、目标、冒泡三个阶段"},{"key":"B","text":"addEventListener 第三个参数为 true 表示在捕获阶段调用监听器"},{"key":"C","text":"stopPropagation 会阻止同一元素上已注册的其它监听器继续执行"},{"key":"D","text":"stopImmediatePropagation 会阻止后续监听器并停止传播"}]',
 'ABD','stopPropagation 只阻止跨元素的继续传播，同元素上的其它监听器照常执行；要连本元素剩余监听器一起掐掉，必须用 stopImmediatePropagation。',8),
(99,'multi','关于常用 DOM 查询 API 的返回值，下列说法正确的有？',
 '[{"key":"A","text":"getElementById 返回单个元素或 null"},{"key":"B","text":"querySelectorAll 返回静态的 NodeList"},{"key":"C","text":"getElementsByTagName 返回动态的 HTMLCollection"},{"key":"D","text":"任何 NodeList 都天然拥有 map、filter 等数组方法"}]',
 'ABC','NodeList 只有 forEach，要用 map/filter 需先 Array.from 或 [...list] 转成真数组；HTMLCollection 连 forEach 都不保证有。',8),
(99,'multi','关于阻止浏览器默认行为，下列说法正确的有？',
 '[{"key":"A","text":"可在事件处理函数中调用 e.preventDefault()"},{"key":"B","text":"在 onclick 内联属性里 return false 可以阻止默认行为"},{"key":"C","text":"阻止表单的 submit 默认行为后页面不会刷新"},{"key":"D","text":"e.preventDefault() 同时也会阻止事件继续冒泡"}]',
 'ABC','preventDefault 只管默认动作，与冒泡无关；另外只有在监听器被调用且事件 cancelable 时它才有效，passive 监听器里调用会被忽略并告警。',8),
(100,'single','代码 console.log("A"); setTimeout(() => console.log("B"), 0); Promise.resolve().then(() => console.log("C")); console.log("D"); 的输出顺序是？',
 '[{"key":"A","text":"A B C D"},{"key":"B","text":"A D C B"},{"key":"C","text":"A C D B"},{"key":"D","text":"A D B C"}]',
 'B','同步代码先打印 A 与 D；调用栈清空后先清空微任务队列，于是 then 回调的 C 先执行，随后才取宏任务队列里的定时器回调打印 B。误区是以为延时 0 就等于立即执行。',5),
(100,'single','关于事件循环中宏任务与微任务的执行顺序，正确的是？',
 '[{"key":"A","text":"每轮先取一个宏任务执行，执行完立即清空整个微任务队列"},{"key":"B","text":"先把所有宏任务执行完，再统一执行微任务"},{"key":"C","text":"微任务要等到下一轮事件循环才执行"},{"key":"D","text":"两者由引擎随机交替执行"}]',
 'A','一次循环：取一个宏任务 → 执行 → 清空微任务队列（包括微任务中新产生的微任务） → 必要时渲染。所以微任务的优先级高于下一个宏任务。',5),
(100,'single','async 函数中执行 return 1，调用该函数得到的返回值是？',
 '[{"key":"A","text":"数字 1"},{"key":"B","text":"一个已兑现（fulfilled）的 Promise，其值为 1"},{"key":"C","text":"一个始终 pending 的 Promise"},{"key":"D","text":"undefined"}]',
 'B','async 函数的返回值总会被自动包装成 Promise：return 1 等价于 return Promise.resolve(1)，因此必须用 await 或 .then 才能拿到 1。',5),
(100,'single','在 async 函数中，await 表达式之后的代码相当于？',
 '[{"key":"A","text":"紧跟在 await 之后同步立即执行"},{"key":"B","text":"被放入该 Promise 的 then 回调，即作为一个微任务稍后执行"},{"key":"C","text":"被推迟到下一个宏任务执行"},{"key":"D","text":"被丢弃，不会执行"}]',
 'B','await 把函数"暂停"，剩余逻辑被安排为 then 回调，因此它在微任务队列中恢复执行；这也意味着 await 后面的代码一定晚于同批次同步代码。',5),
(100,'single','Promise.all([p1, p2]) 中若 p2 先被 reject，整体结果是？',
 '[{"key":"A","text":"仍会等 p1 完成，最后返回含两项结果的数组"},{"key":"B","text":"立即以 p2 的拒绝原因 reject，p1 的结果不再对外可见"},{"key":"C","text":"返回 [p1 的结果, Error 对象]"},{"key":"D","text":"永远保持 pending"}]',
 'B','all 是快速失败语义：任一被拒就整体被拒，其余 Promise 仍会继续执行但结果被丢弃；想拿到全部结局改用 allSettled。',5),
(100,'single','希望等所有 Promise 都结束（不论成功失败）并获知每一项的结果，应使用？',
 '[{"key":"A","text":"Promise.all"},{"key":"B","text":"Promise.allSettled"},{"key":"C","text":"Promise.race"},{"key":"D","text":"Promise.any"}]',
 'B','allSettled 永不拒绝，返回形如 { status: "fulfilled", value } 或 { status: "rejected", reason } 的数组，适合批量上报、并发请求汇总等场景。',5),
(100,'single','Promise.race([p1, p2]) 的语义是？',
 '[{"key":"A","text":"等两个都完成后返回结果数组"},{"key":"B","text":"采纳第一个敲定（fulfilled 或 rejected 均可）的 Promise 的结果"},{"key":"C","text":"只采纳第一个成功的 Promise"},{"key":"D","text":"先限时再取结果"}]',
 'B','race 看谁先落定，失败也算数，因此一个先被拒的 Promise 会让 race 直接拒绝；常用它与定时器组合实现超时控制。',5),
(100,'single','在 async 函数中捕获 await 语句抛出的错误，正确的写法是？',
 '[{"key":"A","text":"用 try...catch 把 await 语句包起来"},{"key":"B","text":"给 await 传第二个错误回调参数"},{"key":"C","text":"只能靠 window.onerror 全局捕获"},{"key":"D","text":"无法捕获，只能让进程崩溃"}]',
 'A','await 会把 Promise 的拒绝转成同步风格的 throw，于是 try...catch 就能捕获；不加捕获会让该 async 函数返回的 Promise 变成 rejected，继续向外传播。',5),
(100,'single','new Promise((resolve, reject) => { console.log("x"); }) 中的执行器函数何时被调用？',
 '[{"key":"A","text":"异步执行，属于微任务"},{"key":"B","text":"同步执行，在构造 Promise 的那一刻立即运行"},{"key":"C","text":"等到调用 then 时才执行"},{"key":"D","text":"作为宏任务在下一轮循环执行"}]',
 'B','执行器是同步调用的，里面的 console.log 会立刻输出；只有 resolve/reject 触发的 then 回调才排进微任务队列。',5),
(100,'single','关于 setTimeout(fn, 0) 的实际执行时机，正确的是？',
 '[{"key":"A","text":"延时写 0 就会立刻插入执行，无需等待"},{"key":"B","text":"必须等当前同步代码与全部微任务执行完；且定时器嵌套超过 5 层后最小延时会钳制到约 4ms"},{"key":"C","text":"一定比同批次产生的 Promise.then 回调先执行"},{"key":"D","text":"延时为 0 时被引擎优化为同步执行"}]',
 'B','定时器回调是宏任务，只能等栈空且微任务清空后才轮到它；HTML 规范还规定嵌套定时器层级超过 5 后最小延时约 4ms，所以 setTimeout 0 从不是"立刻"。',5),
(100,'judge','Promise 的状态一旦从 pending 变为 fulfilled 或 rejected 就不可再改变。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。状态不可逆，之后重复调用 resolve/reject 均被忽略，这也是 Promise 能安全缓存结果、避免回调被多次触发的原因。',5),
(100,'judge','async 函数中抛出的异常会使它返回的 Promise 变为 rejected，可用 .catch 或调用处的 try...catch 捕获。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。函数体里未捕获的异常等价于 return Promise.reject(err)，因此 .catch 能兜住；漏掉捕获会产生 unhandledrejection。',5),
(100,'judge','Promise.all([]) 的结果是一个永远保持 pending 的 Promise。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。空数组上没有可拒绝的项，all([]) 会立即兑现为 []，同理 Promise.race([]) 才是永远 pending。',5),
(100,'judge','await 会阻塞整个 JavaScript 主线程，使它后面的所有代码都无法执行。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。await 只暂停当前 async 函数的执行并把控制权交回事件循环，主线程照样处理其它任务；被暂停的只是这条执行流。',5),
(100,'multi','下列哪些属于微任务（microtask）？',
 '[{"key":"A","text":"Promise.then 注册的回调"},{"key":"B","text":"queueMicrotask 注册的函数"},{"key":"C","text":"MutationObserver 的回调"},{"key":"D","text":"setTimeout 的回调"}]',
 'ABC','常见微任务还有 await 之后的代码、Promise 的 catch/finally 回调；Node 里另有优先级更高的 process.nextTick。setTimeout 属宏任务。',8),
(100,'multi','下列哪些属于宏任务（task）？',
 '[{"key":"A","text":"setTimeout / setInterval 的回调"},{"key":"B","text":"用户点击等 UI 事件的回调"},{"key":"C","text":"script 整体代码块"},{"key":"D","text":"Promise.then 的回调"}]',
 'ABC','宏任务包括定时器、I/O、UI 交互事件和整段脚本；Promise.then、queueMicrotask、MutationObserver 是微任务，优先级更高。',8),
(100,'multi','关于 Promise 的组合器，下列说法正确的有？',
 '[{"key":"A","text":"all 在任一被拒时立即拒绝"},{"key":"B","text":"allSettled 永不拒绝，每项都带 status 字段"},{"key":"C","text":"race 采纳第一个敲定的结果，成功或失败都算"},{"key":"D","text":"race 会忽略第一个被拒的 Promise，继续等待后续成功"}]',
 'ABC','ignore 失败的是 any：any 只在全部被拒时才拒绝并抛出 AggregateError，否则采纳第一个成功值；race 则对失败一视同仁。',8);

-- ---------- rest-linalg.js ----------
INSERT INTO question (knowledge_id, type, title, options, answer, analysis, score) VALUES
(25,'single','矩阵乘积 AB 有意义（可相乘）的必要条件是？',
 '[{"key":"A","text":"A 的列数等于 B 的行数"},{"key":"B","text":"A 的行数等于 B 的列数"},{"key":"C","text":"A 与 B 是同型矩阵"},{"key":"D","text":"A 与 B 都是方阵"}]',
 'A','矩阵乘法要求左矩阵 A 的列数等于右矩阵 B 的行数，因为结果中每个元素是 A 的一行与 B 的一列对应相乘再求和。同型矩阵是加减法的要求，方阵更不是乘法的前提。',5),
(25,'single','设 A 是 3 行 2 列矩阵，B 是 2 行 4 列矩阵，则 AB 的形状是？',
 '[{"key":"A","text":"3 行 4 列"},{"key":"B","text":"2 行 2 列"},{"key":"C","text":"4 行 3 列"},{"key":"D","text":"无法相乘"}]',
 'A','乘积的行数取自左矩阵 A 的行数 3，列数取自右矩阵 B 的列数 4，故 AB 为 3×4。记忆口诀「中间相等、两端定形」：内侧维数 2 与 2 必须一致，外侧维数 3 与 4 决定结果形状。',5),
(25,'single','关于矩阵乘积的转置，(AB) 的转置等于？',
 '[{"key":"A","text":"B 的转置乘以 A 的转置"},{"key":"B","text":"A 的转置乘以 B 的转置"},{"key":"C","text":"AB 本身"},{"key":"D","text":"A 的转置加 B 的转置"}]',
 'A','转置会把乘积的次序颠倒，即 (AB)ᵀ = BᵀAᵀ。这一「反序」规律可推广到多个矩阵相乘；把次序写成 AᵀBᵀ 是初学者最常见的错误，而且在矩阵不可交换时两者确实不等。',5),
(25,'single','平面上把向量 (1, 0) 变到 (0, 1)、把 (0, 1) 变到 (-1, 0) 的线性变换矩阵是？',
 '[{"key":"A","text":"[[0, -1], [1, 0]]"},{"key":"B","text":"[[0, 1], [1, 0]]"},{"key":"C","text":"[[-1, 0], [0, 1]]"},{"key":"D","text":"[[1, 1], [0, 1]]"}]',
 'A','线性变换矩阵的列就是基向量 e₁、e₂ 的像：第一列为 (0,1)、第二列为 (-1,0)，故矩阵为 [[0,-1],[1,0]]，它表示绕原点逆时针旋转 90 度。选项 B 是关于直线 y = x 的对称变换。',5),
(25,'single','下列平面映射中，不属于线性变换的是哪一个？',
 '[{"key":"A","text":"T(x, y) = (x + 1, y)"},{"key":"B","text":"T(x, y) = (2x, y)"},{"key":"C","text":"T(x, y) = (x + y, x - y)"},{"key":"D","text":"T(x, y) = (0, 0)"}]',
 'A','线性变换必须把原点送到原点（T(0) = 0），而 T(x,y) = (x+1, y) 把 (0,0) 送到 (1,0)，属于平移，不是线性变换而是仿射变换。其余三项都满足可加性与齐次性。',5),
(25,'single','用矩阵 [[2, 0], [0, 3]] 作用于列向量 (1, 1)，得到的向量是？',
 '[{"key":"A","text":"(2, 3)"},{"key":"B","text":"(3, 2)"},{"key":"C","text":"(2, 2)"},{"key":"D","text":"(1, 1)"}]',
 'A','对角矩阵作用的效果是各坐标分别按对角元缩放：第一个分量乘 2、第二个分量乘 3，故 (1,1) 变为 (2,3)。这也是沿两个坐标轴方向做非均匀拉伸的几何解释。',5),
(25,'single','n 阶方阵 A 可逆的充要条件是？',
 '[{"key":"A","text":"A 的行列式不等于 0"},{"key":"B","text":"A 的主对角线元素全不为 0"},{"key":"C","text":"A 是对称矩阵"},{"key":"D","text":"A 的元素全不为 0"}]',
 'A','行列式非零与可逆、满秩、行（列）向量线性无关、齐次方程只有零解等互为充要条件。对角线元素全不为零只是三角矩阵的判别法，对一般矩阵并不成立。',5),
(25,'single','设 A 是 m 行 n 列矩阵且 m 小于 n，则齐次线性方程组 Ax = 0 的解的情况是？',
 '[{"key":"A","text":"必有非零解"},{"key":"B","text":"只有零解"},{"key":"C","text":"无解"},{"key":"D","text":"必有唯一解"}]',
 'A','未知数个数 n 大于方程个数 m 时，系数矩阵的秩至多为 m 小于 n，存在自由变量，故必有非零解（且有无穷多解）。齐次方程组一定有零解，因此「无解」这种情况不会出现。',5),
(25,'single','用一个初等矩阵左乘矩阵 A，相当于对 A 做什么操作？',
 '[{"key":"A","text":"作一次相应的初等行变换"},{"key":"B","text":"作一次相应的初等列变换"},{"key":"C","text":"把 A 转置"},{"key":"D","text":"把 A 取逆"}]',
 'A','左乘对应行变换，右乘对应列变换，这是初等矩阵最基本的用法，也是高斯消元可以写成矩阵连乘形式的依据。方向记反是常见错误：记住「左行右列」。',5),
(25,'judge','矩阵乘法一般不满足交换律，即 AB 与 BA 未必相等。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。即使 AB 与 BA 都有意义且同为方阵，二者通常也不相等；例如 A = [[0,1],[0,0]]、B = [[0,0],[1,0]] 时 AB 与 BA 结果不同。只有在 A、B 可交换的特殊情形（如同为对角矩阵、或互为逆矩阵）下才相等。',5),
(25,'judge','若两个矩阵的乘积 AB 等于零矩阵，则必定有 A 为零矩阵或 B 为零矩阵。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。矩阵环中存在零因子：非零矩阵的乘积可以是零矩阵。例如 A = [[1,0],[0,0]]、B = [[0,0],[0,1]] 都不为零，但 AB 是零矩阵。这与数的乘法性质不同，是矩阵运算的典型陷阱。',5),
(25,'judge','对任意矩阵 A，A 的转置乘以 A 所得矩阵一定是对称矩阵。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。因为 (AᵀA)ᵀ = Aᵀ(Aᵀ)ᵀ = AᵀA，转置后等于自身，故必为对称矩阵。这一结论与 A 是否为方阵无关，只要乘积有意义即可，也是最小二乘法中正规方程系数矩阵对称的原因。',5),
(25,'judge','两个对称矩阵相乘，其乘积一定仍是对称矩阵。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。(AB)ᵀ = BᵀAᵀ = BA，只有当 A 与 B 可交换（BA = AB）时乘积才对称。一般情况下两个对称矩阵之积并不对称，例如 A = [[1,0],[0,0]]、B = [[0,1],[1,0]] 的乘积就不是对称矩阵。',5),
(25,'multi','关于矩阵转置的性质，下列等式恒成立的有哪几项？',
 '[{"key":"A","text":"(A 的转置) 的转置等于 A"},{"key":"B","text":"(A + B) 的转置等于 A 的转置加 B 的转置"},{"key":"C","text":"(AB) 的转置等于 B 的转置乘以 A 的转置"},{"key":"D","text":"(AB) 的转置等于 A 的转置乘以 B 的转置"}]',
 'ABC','转置满足自反性、对加法的分配性，以及对乘法成立但次序颠倒的反序律，前三条都正确。第四条把次序写反了，在矩阵不可交换时并不成立，是最典型的错误写法。',8),
(25,'multi','设 A 为 3 阶方阵，下列哪些条件可以断定 A 不可逆？',
 '[{"key":"A","text":"A 的行列式等于 0"},{"key":"B","text":"A 的秩小于 3"},{"key":"C","text":"A 的三个行向量线性相关"},{"key":"D","text":"A 有三个互不相同的特征值"}]',
 'ABC','行列式为 0、秩小于阶数、行向量线性相关都与不可逆等价。第四条不能断定不可逆：三个互不相同的特征值只说明 A 可对角化，其中某个特征值完全可能是 0，此时 A 仍是奇异矩阵。',8),
(26,'single','矩阵 A = [[2, 0], [0, 3]] 的特征值是？',
 '[{"key":"A","text":"2 与 3"},{"key":"B","text":"0 与 1"},{"key":"C","text":"1 与 2"},{"key":"D","text":"仅有 2"}]',
 'A','对角矩阵的特征值就是其主对角线元素，因为 A e₁ = 2e₁、A e₂ = 3e₂，两个基向量本身就是特征向量。一般矩阵则要先解特征方程才能求得。',5),
(26,'single','求矩阵 A 的特征值所依据的方程是？',
 '[{"key":"A","text":"det(A - λI) = 0"},{"key":"B","text":"det(A + λI) = 0"},{"key":"C","text":"A - λI = 0"},{"key":"D","text":"A 的迹等于 0"}]',
 'A','由 Av = λv（v 非零）得 (A - λI)v = 0 有非零解，故系数矩阵必须奇异，即 det(A - λI) = 0，这就是特征方程。写成加号会改变根的符号，不能混用。',5),
(26,'single','设 2 阶矩阵 A 的特征值为 λ₁ 与 λ₂，则特征值之和与特征值之积分别等于？',
 '[{"key":"A","text":"A 的迹与 A 的行列式"},{"key":"B","text":"A 的行列式与 A 的迹"},{"key":"C","text":"A 的秩与 A 的迹"},{"key":"D","text":"A 的主对角线乘积与 A 的迹"}]',
 'A','由特征多项式的韦达关系：λ₁ + λ₂ = tr(A)（主对角线元素之和），λ₁·λ₂ = det(A)。这一关系可用于快速检验计算结果，例如算得两个特征值之积与行列式不符就一定出错了。',5),
(26,'single','上三角矩阵 A = [[1, 1], [0, 2]] 的特征值是？',
 '[{"key":"A","text":"1 与 2"},{"key":"B","text":"1 与 1"},{"key":"C","text":"0 与 2"},{"key":"D","text":"2 与 2"}]',
 'A','三角矩阵（包括上三角与下三角）的特征值就是主对角线上的元素，因为 det(A - λI) = (1 - λ)(2 - λ)。右上角那个 1 只影响特征向量，不影响特征值。',5),
(26,'single','关于属于不同特征值的特征向量，下列结论正确的是？',
 '[{"key":"A","text":"它们线性无关"},{"key":"B","text":"它们必定正交"},{"key":"C","text":"它们一定相等"},{"key":"D","text":"它们可能线性相关"}]',
 'A','属于互不相同特征值的特征向量必定线性无关，这是可对角化判定的基础。但正交性并不必然成立，只有实对称矩阵才能保证不同特征值的特征向量相互正交。',5),
(26,'single','矩阵 A = [[4, 1], [2, 3]] 的迹为 7、行列式为 10，则它的两个特征值是？',
 '[{"key":"A","text":"5 与 2"},{"key":"B","text":"7 与 10"},{"key":"C","text":"4 与 3"},{"key":"D","text":"1 与 6"}]',
 'A','特征多项式为 λ² - 7λ + 10 = (λ - 5)(λ - 2) = 0，故特征值为 5 与 2。检验：和为 7 等于迹、积为 10 等于行列式，完全吻合。',5),
(26,'single','若 λ 是矩阵 A 的特征值，则关于 A² 的特征值正确的说法是？',
 '[{"key":"A","text":"λ² 是 A² 的特征值"},{"key":"B","text":"λ 仍是 A² 的唯一特征值"},{"key":"C","text":"2λ 是 A² 的特征值"},{"key":"D","text":"无法确定"}]',
 'A','由 Av = λv 得 A²v = A(λv) = λAv = λ²v，故同一个 v 是 A² 的特征向量、对应特征值 λ²。一般地 p(A) 的特征值为 p(λ)，这一性质常用于求矩阵多项式的特征值。',5),
(26,'single','若矩阵 B 与 A 相似（即存在可逆 P 使 B = P 的逆乘以 A 乘以 P），则下列一定成立的是？',
 '[{"key":"A","text":"A 与 B 有相同的特征值"},{"key":"B","text":"A 与 B 有相同的特征向量"},{"key":"C","text":"A 与 B 相等"},{"key":"D","text":"A 与 B 有相同的元素"}]',
 'A','相似变换保持特征多项式不变，故特征值相同（包括重数）、迹与行列式也相同。但特征向量会随基的改变而改变：若 v 是 A 的特征向量，则 P 的逆 v 才是 B 的特征向量。',5),
(26,'single','矩阵 A = [[0, 1], [1, 0]] 的两个特征值是？',
 '[{"key":"A","text":"1 与 -1"},{"key":"B","text":"0 与 1"},{"key":"C","text":"1 与 1"},{"key":"D","text":"0 与 0"}]',
 'A','特征方程 det(A - λI) = λ² - 1 = 0，得 λ = ±1。该矩阵表示关于直线 y = x 的对称变换：沿 y = x 方向的向量不变（特征值 1），沿 y = -x 方向的向量反向（特征值 -1）。',5),
(26,'judge','零向量可以作为矩阵的特征向量。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。特征向量按定义必须是非零向量，否则 A·0 = λ·0 对任何 λ 都成立，特征值将失去意义。求解时先由特征方程定出 λ，再解齐次方程组取非零解作为特征向量。',5),
(26,'judge','实对称矩阵一定可以正交对角化，即为它存在由特征向量组成的正交基。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确，这就是谱定理：实对称矩阵的特征值全为实数，且不同特征值的特征向量自动正交，重特征值内部也可正交化，故存在正交矩阵 Q 使 QᵀAQ 为对角矩阵。',5),
(26,'judge','n 阶矩阵可对角化的充要条件是它拥有 n 个线性无关的特征向量。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。把这 n 个特征向量作为列组成可逆矩阵 P，即得 P 的逆 A P 为对角矩阵。若某特征值的几何重数小于代数重数，线性无关特征向量不够 n 个，矩阵就不能对角化。',5),
(26,'judge','若 n 阶矩阵 A 的所有特征值都不为 0，则 A 必定可逆。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。因为 det(A) 等于全部特征值之积，特征值全不为 0 时行列式非零，故 A 可逆。反过来，A 奇异（不可逆）当且仅当 0 是它的一个特征值。',5),
(26,'multi','设 v 是矩阵 A 属于特征值 λ 的特征向量（即 Av = λv），下列说法正确的有哪些？',
 '[{"key":"A","text":"对任意非零常数 k，kv 也是属于 λ 的特征向量"},{"key":"B","text":"属于同一个 λ 的两个特征向量的非零线性组合仍是属于 λ 的特征向量"},{"key":"C","text":"特征值 λ 可以等于 0"},{"key":"D","text":"特征向量必须是单位向量"}]',
 'ABC','特征向量构成（含零向量的）特征子空间，故对非零数乘与同特征值内的线性组合封闭；λ = 0 是允许的，此时特征向量正是 A 的零空间中的非零向量。特征向量只要求非零，不要求是单位向量，故 D 错。',8),
(26,'multi','设 2 阶矩阵 A 的迹为 5、行列式为 6，下列说法正确的有哪些？',
 '[{"key":"A","text":"A 的特征值为 2 与 3"},{"key":"B","text":"A 的特征多项式为 λ² - 5λ + 6"},{"key":"C","text":"A 是可逆矩阵"},{"key":"D","text":"A 一定是对称矩阵"}]',
 'ABC','由 λ² - tr(A)λ + det(A) = λ² - 5λ + 6 = (λ-2)(λ-3) 得特征值为 2 与 3，均不为 0，故 A 可逆。迹与行列式只能确定特征值，不能确定矩阵的具体形态，A 未必对称，故 D 错。',8),
(58,'single','对增广矩阵作初等行变换后，所得方程组与原方程组的关系是？',
 '[{"key":"A","text":"同解（解集合完全相同）"},{"key":"B","text":"解一定改变"},{"key":"C","text":"解的个数一定减少"},{"key":"D","text":"只是形式变化，解无法比较"}]',
 'A','三种初等行变换（换行、某行乘非零常数、某行加另一行的倍数）都是可逆操作，因此变换前后方程组同解，这正是高斯消元法的理论依据。',5),
(58,'single','把矩阵化成行阶梯形后，其主元（每行首个非零元）的个数等于该矩阵的什么量？',
 '[{"key":"A","text":"秩"},{"key":"B","text":"行数"},{"key":"C","text":"列数"},{"key":"D","text":"行列式"}]',
 'A','行阶梯形中非零行的数目即主元个数，它等于矩阵的秩，也等于行（列）向量组的极大无关组所含向量个数。行列式只对同阶方阵定义，与主元个数不是一回事。',5),
(58,'single','非齐次线性方程组 Ax = b 有解的充要条件是？',
 '[{"key":"A","text":"系数矩阵的秩等于增广矩阵的秩"},{"key":"B","text":"系数矩阵的秩等于未知数个数"},{"key":"C","text":"系数矩阵是方阵"},{"key":"D","text":"增广矩阵的秩大于系数矩阵的秩"}]',
 'A','有解要求常数项 b 能被 A 的列向量线性表出，等价于 rank(A) = rank(A|b)。若增广后秩增大，说明消元中出现了「0 = 非零」的矛盾行，此时方程组无解。',5),
(58,'single','n 元齐次线性方程组 Ax = 0 有非零解的充要条件是？',
 '[{"key":"A","text":"系数矩阵的秩小于 n"},{"key":"B","text":"系数矩阵的秩等于 n"},{"key":"C","text":"方程个数大于 n"},{"key":"D","text":"A 的行列式不为 0"}]',
 'A','秩小于未知数个数时存在自由变量，可任意取值从而得到非零解。秩等于 n 时只有零解，此时若 A 是方阵则行列式非零、A 可逆。',5),
(58,'single','一个含 3 个方程、3 个未知数的线性方程组，若系数矩阵的秩为 3，则其解的情况是？',
 '[{"key":"A","text":"有唯一解"},{"key":"B","text":"有无穷多解"},{"key":"C","text":"无解"},{"key":"D","text":"必有零解"}]',
 'A','秩为 3 等于未知数个数，故若有解则唯一；同时满秩方阵的增广矩阵秩也为 3，不会出现矛盾行，所以一定有解且唯一。注意这里不要求它是齐次方程组。',5),
(58,'single','高斯消元过程中，若当前列的主元位置元素为 0，通常采取的处理方式是？',
 '[{"key":"A","text":"与下方该列元素非零的行交换"},{"key":"B","text":"直接停止，判定无解"},{"key":"C","text":"把该行整行删除"},{"key":"D","text":"把该列乘以 0"}]',
 'A','通过换行（选主元）把非零元素换到主元位置后即可继续消元；若该列以下全为 0，才说明这一列没有主元，属于自由变量列，应转向下一列而不是终止算法。',5),
(58,'single','对 n 阶稠密线性方程组做高斯消元，其算法时间复杂度为？',
 '[{"key":"A","text":"O(n³)"},{"key":"B","text":"O(n²)"},{"key":"C","text":"O(n log n)"},{"key":"D","text":"O(2ⁿ)"}]',
 'A','消元阶段对每一列都要更新下方所有元素，总运算量约为 (2/3)n³ 次浮点运算，回代只占 O(n²)，故整体为 O(n³)。这也是大规模线性方程组必须考虑稀疏结构或迭代法的原因。',5),
(58,'single','在行阶梯形矩阵中，非主元列所对应的未知数称为？',
 '[{"key":"A","text":"自由变量（自由未知量）"},{"key":"B","text":"基本变量"},{"key":"C","text":"主元变量"},{"key":"D","text":"矛盾变量"}]',
 'A','主元列对应基本变量，可由自由变量表示；非主元列对应自由变量，可任取常数，每给一组自由变量的取值就得到方程组的一个解，因此有无穷多解时解可以参数化表示。',5),
(58,'single','非齐次线性方程组有无穷多解时，其通解的结构可表述为？',
 '[{"key":"A","text":"一个特解加上对应齐次方程组的通解"},{"key":"B","text":"仅由特解组成"},{"key":"C","text":"齐次通解减去特解"},{"key":"D","text":"若干个特解的乘积"}]',
 'A','若 x₀ 是 Ax = b 的某个特解、v 满足 Av = 0，则 A(x₀ + v) = b，故 x₀ 加齐次通解给出全部解。这一「特解 + 齐次通解」的结构与微分方程中通解的结构完全类似。',5),
(58,'single','用高斯消元法解方程组 x + y = 3 与 2x - y = 0，得到的解是？',
 '[{"key":"A","text":"x = 1，y = 2"},{"key":"B","text":"x = 2，y = 1"},{"key":"C","text":"x = 3，y = 0"},{"key":"D","text":"x = 0，y = 3"}]',
 'A','两式相加得 3x = 3，故 x = 1；代回第一式得 y = 2。检验：2×1 - 2 = 0 成立。消元法是「代入法」的机械化版本，适合编程实现。',5),
(58,'judge','对增广矩阵做倍加变换（把某一行的倍数加到另一行）不会改变方程组的解集合。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。倍加变换相当于把两个方程线性组合，是可逆操作（反向再做一次减去同样的倍数即可还原），因此解集合不变。消元正是靠这种变换逐列消去下方元素。',5),
(58,'judge','若齐次线性方程组的方程个数少于未知数个数，则它一定有非零解。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。此时秩不超过方程个数 m，而 m 小于未知数个数 n，故秩小于 n，必有自由变量，从而存在非零解。这是判断齐次方程组有非零解最常用的快速结论。',5),
(58,'judge','对一个线性方程组而言，它可能出现的解的情况包括无解、唯一解和无穷多解三种。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。由秩的关系可完全分类：rank(A) 小于 rank(A|b) 时无解；相等且等于未知数个数时唯一解；相等但小于未知数个数时无穷多解。线性方程组不可能出现「恰有两个解」的情况。',5),
(58,'judge','高斯消元中采用列主元法（选主元）会改变方程组的最终解。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。选主元只是交换方程的次序（即交换增广矩阵的两行），属于初等行变换，解集合不变。它的目的是避免主元为 0 以及抑制舍入误差的放大，提高数值稳定性。',5),
(58,'multi','关于线性方程组 Ax = b 的解与秩的关系，下列说法正确的有哪些？',
 '[{"key":"A","text":"rank(A) = rank(A|b) = n 时有唯一解"},{"key":"B","text":"rank(A) = rank(A|b) 且小于 n 时有无穷多解"},{"key":"C","text":"rank(A) 小于 rank(A|b) 时无解"},{"key":"D","text":"rank(A) 大于 rank(A|b) 时无解"}]',
 'ABC','前三条是解的完整分类，n 为未知数个数。第四条在逻辑上不可能出现：增广矩阵是在 A 的基础上增加一列，其秩只会大于或等于 rank(A)，不可能更小。',8),
(58,'multi','用高斯消元法解方程组时，下列哪些对增广矩阵的操作是允许的？',
 '[{"key":"A","text":"交换两行"},{"key":"B","text":"把某一行乘以非零常数"},{"key":"C","text":"把某一行的倍数加到另一行"},{"key":"D","text":"交换两列"}]',
 'ABC','前三种即三类初等行变换，都不改变解集合。交换两列相当于改变未知量的排列次序（把 x₁ 与 x₂ 的角色互换），虽然方程组本质不变，但已不是对增广矩阵的合法行变换，记录解时必须还原，故 D 不选。',8),
(58,'multi','关于高斯消元中选主元的必要性，下列说法正确的有哪些？',
 '[{"key":"A","text":"主元为 0 时该步消元无法继续进行"},{"key":"B","text":"主元绝对值过小时会放大舍入误差"},{"key":"C","text":"列主元法是在当前列选取绝对值最大的元素并通过换行置为主元"},{"key":"D","text":"选主元的目的是改变方程组的解"}]',
 'ABC','选主元既解决主元为 0 的算法中断问题，也避免用很小的数做除数导致误差被放大（例如主元为 10 的 -8 次方时结果几乎失去有效数字）。它不改变解，故 D 错。',8),
(59,'single','以两个二维向量为列构成的 2 阶行列式，其绝对值表示什么几何量？',
 '[{"key":"A","text":"这两个向量张成的平行四边形的面积"},{"key":"B","text":"这两个向量夹角的大小"},{"key":"C","text":"这两个向量长度之和"},{"key":"D","text":"这两个向量终点的距离"}]',
 'A','2 阶行列式的绝对值等于两列向量张成的平行四边形面积，这正是行列式「有向面积」的含义。若两向量共线，面积为 0，行列式也恰为 0，与线性相关的判定一致。',5),
(59,'single','以三个三维向量为列构成的 3 阶行列式，其绝对值表示？',
 '[{"key":"A","text":"这三个向量张成的平行六面体的体积"},{"key":"B","text":"这三个向量构成三角形的面积"},{"key":"C","text":"这三个向量长度之积"},{"key":"D","text":"这三个向量张成的平面的面积"}]',
 'A','3 阶行列式的绝对值是三个列向量张成的平行六面体体积（混合积的绝对值）。三向量共面时体积为 0，行列式也为 0，这是三维情形下线性相关的几何判据。',5),
(59,'single','若方阵 A 的行列式为 0，则从线性变换的角度看意味着什么？',
 '[{"key":"A","text":"该变换把空间压缩到更低维度，不可逆"},{"key":"B","text":"该变换是旋转"},{"key":"C","text":"该变换保持面积不变"},{"key":"D","text":"该变换把空间放大"}]',
 'A','行列式等于面积（或体积）的缩放倍数，为 0 说明变换后区域退化为低维图形（如平面被压成一条直线），信息丢失因而不可逆。这也等价于矩阵的列向量线性相关。',5),
(59,'single','线性变换的行列式为负数，其几何含义是？',
 '[{"key":"A","text":"变换改变了空间的定向（发生了镜像翻转）"},{"key":"B","text":"变换把空间压缩了"},{"key":"C","text":"变换是恒等变换"},{"key":"D","text":"变换没有几何意义"}]',
 'A','行列式的符号表示定向：为正保持定向（如旋转），为负改变定向（如关于某条直线的对称，相当于「翻面」）。绝对值仍表示面积缩放倍数，符号与大小各表达一层含义。',5),
(59,'single','关于两个同阶方阵乘积的行列式，下列等式正确的是？',
 '[{"key":"A","text":"det(AB) = det(A)·det(B)"},{"key":"B","text":"det(AB) = det(A) + det(B)"},{"key":"C","text":"det(AB) = det(A) / det(B)"},{"key":"D","text":"det(AB) = det(A) 的 det(B) 次方"}]',
 'A','行列式对乘法是完全可乘的：AB 表示连续施加两次变换，面积缩放倍数自然相乘。注意行列式对加法没有类似的公式，det(A+B) 一般不等于 det(A) + det(B)。',5),
(59,'single','已知平面上两点 P、Q 与原点 O，用 2 阶行列式计算三角形 OPQ 面积的公式是？',
 '[{"key":"A","text":"取向量 OP 与 OQ 构成的行列式，再取其绝对值的一半"},{"key":"B","text":"取该行列式本身"},{"key":"C","text":"取该行列式的绝对值"},{"key":"D","text":"取该行列式的平方"}]',
 'A','行列式给出的是以 OP、OQ 为邻边的平行四边形面积，三角形恰好是它的一半，故面积为 |det|/2。这是解析几何中「行列式求面积」的常用公式。',5),
(59,'single','单位矩阵的行列式等于多少，其几何解释是什么？',
 '[{"key":"A","text":"1，恒等变换不改变面积与体积"},{"key":"B","text":"0，恒等变换把空间压缩"},{"key":"C","text":"n，取决于阶数"},{"key":"D","text":"-1，改变了定向"}]',
 'A','恒等变换保持所有几何量不变，面积缩放倍数为 1，故 det(I) = 1。行列式的这一「基准值」也解释了为什么 det(A⁻¹) = 1/det(A)：两次变换合起来是恒等变换。',5),
(59,'single','对方阵作一次「交换两行」的初等变换，其行列式如何变化？',
 '[{"key":"A","text":"变为原来的相反数（变号）"},{"key":"B","text":"保持不变"},{"key":"C","text":"变为原来的 2 倍"},{"key":"D","text":"变为 0"}]',
 'A','交换两行（或两列）使行列式变号，这是行列式的基本性质之一；由此可推出两行相同时行列式为 0（交换后既应变号又应不变，只能为 0）。',5),
(59,'single','上三角矩阵的行列式等于什么？',
 '[{"key":"A","text":"主对角线元素的乘积"},{"key":"B","text":"所有元素之和"},{"key":"C","text":"非零元素的个数"},{"key":"D","text":"主对角线元素之和"}]',
 'A','按第一列展开可递推得上三角行列式等于对角元之积。高斯消元把矩阵化为三角形的做法正是利用这一点来快速求行列式，同时要注意消元过程中换行会引入符号变化。',5),
(59,'single','线性变换对应的矩阵为 [[2, 0], [0, 3]]，则单位正方形在该变换下的像的面积是？',
 '[{"key":"A","text":"6"},{"key":"B","text":"5"},{"key":"C","text":"2"},{"key":"D","text":"3"}]',
 'A','该变换把单位正方形拉成长为 2、宽为 3 的矩形，面积为 2×3 = 6，也等于行列式 det = 2×3 = 6。一般地，任意图形的面积都会被乘以 |det| 倍，与图形形状无关。',5),
(59,'judge','行列式为 0 的线性变换必定把平面压缩到一条直线或一个点上。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。二维情形行列式为 0 说明列向量线性相关，所有像向量都落在同一直线上（或都退化为原点），二维区域被压成一维或零维，面积缩放倍数为 0。',5),
(59,'judge','行列式的绝对值等于该线性变换对面积（三维时为体积）的缩放倍数。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确，这是行列式最核心的几何解释。任意区域经变换后，其面积等于原面积乘以 |det|；符号则单独表示是否改变定向，两者结合起来完整描述了变换的几何效果。',5),
(59,'judge','任意方阵交换其中两行后，其行列式的绝对值与符号都保持不变。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。交换两行后行列式变号，绝对值不变但符号相反。只有作了偶数次换行时符号才恢复；若交换的是两列，结论完全相同。',5),
(59,'judge','若方阵 A 可逆，则 A 的逆矩阵的行列式等于 A 的行列式的倒数。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。由 det(A·A⁻¹) = det(I) = 1 及乘法可乘性得 det(A)·det(A⁻¹) = 1，故 det(A⁻¹) = 1/det(A)。这也说明可逆矩阵的行列式必不为 0。',5),
(59,'multi','关于行列式的基本性质，下列说法正确的有哪些？',
 '[{"key":"A","text":"矩阵转置后行列式不变"},{"key":"B","text":"某一行乘以常数 k，行列式变为原来的 k 倍"},{"key":"C","text":"若两行完全相同，则行列式为 0"},{"key":"D","text":"det(A + B) 恒等于 det(A) + det(B)"}]',
 'ABC','转置不变、按行的齐次性、两行相同则为零都是行列式的标准性质。行列式对矩阵加法没有可加性，一般情况下 det(A+B) 与 det(A)+det(B) 毫无关系，故 D 错。',8),
(59,'multi','设 2 阶矩阵 A 的两个列向量分别为 (1, 0) 与 (0, 2)，下列说法正确的有哪些？',
 '[{"key":"A","text":"det(A) = 2"},{"key":"B","text":"该变换把单位正方形的面积放大为原来的 2 倍"},{"key":"C","text":"A 是可逆矩阵"},{"key":"D","text":"该变换是一个旋转变换"}]',
 'ABC','A = [[1,0],[0,2]]，行列式为 2，故面积放大 2 倍且可逆。旋转变换要求行列式为 1 且保持长度不变，而该变换沿 y 方向拉伸了 2 倍，不是旋转，故 D 错。',8),
(59,'multi','设 A 为 n 阶方阵，下列哪些说法与 det(A) = 0 等价？',
 '[{"key":"A","text":"A 的列向量组线性相关"},{"key":"B","text":"A 不可逆"},{"key":"C","text":"齐次方程组 Ax = 0 有非零解"},{"key":"D","text":"A 中必定存在一行元素全为 0"}]',
 'ABC','行列式为 0、列向量线性相关、矩阵奇异、齐次方程组有非零解、秩小于 n 这些都互相等价。但行列式为 0 并不要求某一行全为零，例如 [[1,2],[2,4]] 两行成比例却没有全零行，故 D 错。',8);

-- ---------- rest-math.js ----------
INSERT INTO question (knowledge_id, type, title, options, answer, analysis, score) VALUES
(22,'single','数列 a(n) = (3n + 1) / (2n - 5) 当 n 趋于无穷时的极限是？',
 '[{"key":"A","text":"3/2"},{"key":"B","text":"1/2"},{"key":"C","text":"3"},{"key":"D","text":"不存在"}]',
 'A','分子分母同除以最高次幂 n，得 (3 + 1/n) / (2 - 5/n)，当 n 趋于无穷时 1/n 与 5/n 都趋于 0，故极限为 3/2。常见误区是只看最高次项系数却漏掉低次项在求极限时确实消失这一前提，或误以为分子分母都发散就没有极限。',5),
(22,'single','极限 lim（x 趋于 0）sin(3x) / tan(2x) 的值为？',
 '[{"key":"A","text":"3/2"},{"key":"B","text":"2/3"},{"key":"C","text":"1"},{"key":"D","text":"0"}]',
 'A','x 趋于 0 时 sin(3x) 等价于 3x，tan(2x) 等价于 2x，等价无穷小替换后得 3x / 2x = 3/2。等价无穷小只能在乘除运算中替换，若在加减式中随意替换（如把 sin(3x) - 3x 直接换成 0）就会丢失高阶项而算错。',5),
(22,'single','极限 lim（n 趋于无穷）(1 + 2/n) 的 n 次方等于？',
 '[{"key":"A","text":"e 的 2 次方"},{"key":"B","text":"e"},{"key":"C","text":"e 的 1/2 次方"},{"key":"D","text":"1"}]',
 'A','由第二个重要极限 lim（t 趋于无穷）(1 + 1/t)^t = e，令 t = n/2，则 (1 + 2/n)^n = [(1 + 1/t)^t]^2，极限为 e^2。一般地 (1 + k/n)^n 趋于 e^k；误选 C 的人常把指数与系数的关系弄反。',5),
(22,'single','当 x 趋于 0 时，1 - cos x 是关于 x 的几阶无穷小？',
 '[{"key":"A","text":"二阶，等价于 x²/2"},{"key":"B","text":"一阶，等价于 x"},{"key":"C","text":"三阶，等价于 x³/6"},{"key":"D","text":"不是无穷小"}]',
 'A','由半角公式 1 - cos x = 2 sin²(x/2)，而 sin(x/2) 等价于 x/2，故 1 - cos x 等价于 2·(x/2)² = x²/2，是二阶无穷小。误区：把它与 sin x 一样当成与 x 等价的一阶无穷小，那样在求极限时会少掉一个 x 因子。',5),
(22,'single','用夹逼准则求 lim（n 趋于无穷）(1 + 2 + ... + n) / n² 的值？',
 '[{"key":"A","text":"1/2"},{"key":"B","text":"1"},{"key":"C","text":"0"},{"key":"D","text":"不存在"}]',
 'A','分子是等差数列求和 n(n+1)/2，除以 n² 得 (n+1)/(2n) = 1/2 + 1/(2n)，当 n 趋于无穷时趋于 1/2。也可用夹逼：每项 k/n² 之和介于 n·1/n² 与 n·n/n² 之间做粗略估计，但精确值需先求和再取极限。',5),
(22,'single','极限 lim（x 趋于 1）(x² - 1) / (x - 1) 的值为？',
 '[{"key":"A","text":"2"},{"key":"B","text":"0"},{"key":"C","text":"1"},{"key":"D","text":"不存在"}]',
 'A','直接代入得 0/0 型未定式，需先约去公因子：x² - 1 = (x-1)(x+1)，原式化为 x + 1（x 不等于 1），趋于 2。极限考察的是 x 趋近于 1 时的趋势而非在 x=1 处的函数值，因此函数在 x=1 处是否有定义并不影响极限。',5),
(22,'single','设 a(1) = 根号 2，a(n+1) = 根号(2 + a(n))，则该数列的极限为？',
 '[{"key":"A","text":"2"},{"key":"B","text":"根号 2"},{"key":"C","text":"1"},{"key":"D","text":"发散不存在"}]',
 'A','数列单调递增且有上界 2（可用归纳法验证），由单调有界准则知极限存在，设为 L。对递推式两边取极限得 L = 根号(2+L)，即 L² - L - 2 = 0，解得 L = 2 或 L = -1，因各项为正故取 L = 2。常见错误是不验证极限存在就直接对递推式取极限。',5),
(22,'single','极限 lim（x 趋于 0）x · sin(1/x) 的值为多少？',
 '[{"key":"A","text":"0"},{"key":"B","text":"1"},{"key":"C","text":"不存在"},{"key":"D","text":"无穷大"}]',
 'A','x 是无穷小，sin(1/x) 在 x 趋于 0 时剧烈振荡但恒有界（绝对值不超过 1），无穷小与有界量之积仍为无穷小，故极限为 0。注意 sin(1/x) 本身极限不存在，不能拆成两个极限相乘，只能靠「无穷小乘有界」这一结论。',5),
(22,'single','函数 f(x) 在 x 趋于 x₀ 时极限存在的充要条件是？',
 '[{"key":"A","text":"左极限与右极限都存在且相等"},{"key":"B","text":"左极限存在即可"},{"key":"C","text":"右极限存在即可"},{"key":"D","text":"f(x₀) 有定义"}]',
 'A','双侧极限存在当且仅当左右极限各自存在且数值相等，与 f 在 x₀ 处是否有定义、取值如何完全无关。典型反例是分段函数在分点处左右极限不等（跳跃间断点），此时双侧极限不存在。',5),
(22,'judge','收敛的数列一定有界，但有界的数列不一定收敛。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。收敛必有界是数列极限的基本性质（收敛点列只能落在有限区间内）；反之不成立，如 (-1)^n 有界但在 1 与 -1 之间振荡，没有极限。有界只是收敛的必要非充分条件。',5),
(22,'judge','任意多个无穷小量的和仍然是无穷小量。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。只有有限个无穷小之和才是无穷小。例如取 n 个 1/n（每个都趋于 0），其和为 1，极限并不是 0。这类「有限与无限」的区别是极限运算中最容易忽略的陷阱。',5),
(22,'judge','若 lim f(x) = A 且 lim g(x) = B，且 A 大于 B，则在 x 充分接近极限点时恒有 f(x) 大于 g(x)。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确，这是极限的保序性：由极限值的严格大小关系可推出在足够小的去心邻域内函数值的同样大小关系。注意若只知 f(x) 大于 g(x)，只能推出 A 大于等于 B，严格不等号未必保持。',5),
(22,'judge','两个无穷大量之和一定是无穷大量，两个无穷大量之商也一定是无穷大量。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。两个无穷大之和确实是无穷大（同号时），但之商是未定式：例如 n²/n 趋于无穷，而 n/n² 趋于 0，n/n 趋于 1。无穷大之比必须具体分析，不能一概而论。',5),
(22,'multi','当 x 趋于 0 时，下列哪些量与 x 是等价无穷小（比值为 1）？',
 '[{"key":"A","text":"sin x"},{"key":"B","text":"1 - cos x"},{"key":"C","text":"ln(1 + x)"},{"key":"D","text":"arctan x"}]',
 'ACD','sin x、ln(1+x)、arctan x 与 x 之比的极限都是 1，故都是 x 的等价无穷小；而 1 - cos x 等价于 x²/2，与 x 之比趋于 0，是比 x 更高阶的无穷小，不属于等价关系。判断等价无穷小的关键是看比值极限是否为 1，而不是看是否都趋于 0。',8),
(22,'multi','下列数列中收敛的有哪些？',
 '[{"key":"A","text":"a(n) = 1/n"},{"key":"B","text":"a(n) = n/(n+1)"},{"key":"C","text":"a(n) = (-1)^n"},{"key":"D","text":"a(n) = sin n"}]',
 'AB','1/n 趋于 0，n/(n+1) = 1 - 1/(n+1) 趋于 1，二者都收敛；(-1)^n 在 1 与 -1 之间来回振荡，sin n 随 n 增大不趋于任何固定值（在 -1 与 1 之间稠密振荡），二者都发散。判断收敛要看 n 趋于无穷时的整体趋势，不能只看前几项。',8),
(23,'single','函数 f(x) = |x| 在 x = 0 处的左导数与右导数分别为？',
 '[{"key":"A","text":"-1 与 1"},{"key":"B","text":"1 与 -1"},{"key":"C","text":"0 与 0"},{"key":"D","text":"都不存在"}]',
 'A','x 小于 0 时 f(x) = -x，左导数为 -1；x 大于 0 时 f(x) = x，右导数为 1。左右导数不相等，故 f 在 x=0 处不可导，但函数在该点是连续的，这也说明连续并不蕴含可导。',5),
(23,'single','设 f(x) = x³ - 3x，则 f 在 x = 2 处的导数值为？',
 '[{"key":"A","text":"9"},{"key":"B","text":"3"},{"key":"C","text":"6"},{"key":"D","text":"2"}]',
 'A','f\'(x) = 3x² - 3，代入 x = 2 得 3×4 - 3 = 9。注意导数是一个数值（函数在该点切线的斜率），要先求导函数再代入，不能先把 x=2 代进原函数再求导（那样得到的是常数的导数 0）。',5),
(23,'single','函数 y = e 的 (2x) 次方的二阶导数在 x = 0 处的值为？',
 '[{"key":"A","text":"4"},{"key":"B","text":"2"},{"key":"C","text":"1"},{"key":"D","text":"0"}]',
 'A','一阶导 y\' = 2e^(2x)，二阶导 y\'\' = 4e^(2x)，代入 x = 0 得 4。每求一次导都会因链式法则多乘一个系数 2，初学者的典型错误是只乘一次而得到 2。',5),
(23,'single','由参数方程 x = t²，y = t³ 确定的曲线，在 t = 1 处的 dy/dx 为？',
 '[{"key":"A","text":"3/2"},{"key":"B","text":"2/3"},{"key":"C","text":"3"},{"key":"D","text":"1"}]',
 'A','参数方程求导公式 dy/dx = (dy/dt) / (dx/dt) = 3t² / 2t = 3t/2，代入 t = 1 得 3/2。注意要先各自对参数 t 求导再相除，不能直接用 y/x；且在 t = 0 处 dx/dt = 0，公式失效。',5),
(23,'single','由隐方程 x² + y² = 25 确定的函数，在点 (3, 4) 处的导数 dy/dx 为？',
 '[{"key":"A","text":"-3/4"},{"key":"B","text":"3/4"},{"key":"C","text":"-4/3"},{"key":"D","text":"4/3"}]',
 'A','两边对 x 求导得 2x + 2y·y\' = 0，即 y\' = -x/y，代入 (3,4) 得 -3/4。负号表示圆在该点的切线向右下方倾斜；误选 C 的人常把 x 与 y 的位置颠倒。',5),
(23,'single','设 y = x²，在 x = 1 处取自变量增量 Δx = 0.1，则微分 dy 的值为？',
 '[{"key":"A","text":"0.2"},{"key":"B","text":"0.21"},{"key":"C","text":"0.1"},{"key":"D","text":"0.02"}]',
 'A','dy = f\'(x)·Δx = 2x·Δx = 2×1×0.1 = 0.2。而真实增量 Δy = 1.1² - 1 = 0.21，两者相差 0.01，正是高阶无穷小 (Δx)² = 0.01，这体现了 Δy = dy + o(Δx) 的关系。',5),
(23,'single','函数 f(x) = x² 在区间 [0, 2] 上满足拉格朗日中值定理的 ξ 值为？',
 '[{"key":"A","text":"1"},{"key":"B","text":"0"},{"key":"C","text":"2"},{"key":"D","text":"1/2"}]',
 'A','由 f(2) - f(0) = f\'(ξ)(2 - 0)，即 4 - 0 = 2ξ·2，解得 ξ = 1。几何意义：区间内存在一点，其切线与连接两端点的弦平行；ξ 必须落在开区间 (0,2) 内部。',5),
(23,'single','用洛必达法则求极限 lim（x 趋于 0）(e^x - 1 - x) / x² 的值为？',
 '[{"key":"A","text":"1/2"},{"key":"B","text":"0"},{"key":"C","text":"1"},{"key":"D","text":"不存在"}]',
 'A','属 0/0 型，求导一次得 (e^x - 1)/(2x) 仍为 0/0 型，再求导得 e^x/2，代入 x=0 得 1/2。关键是要连续使用洛必达直到不再是未定式，用一次就止步会错答。',5),
(23,'single','设 f(x) = x³ - 3x，则该函数的单调递增区间是？',
 '[{"key":"A","text":"(-∞, -1) 与 (1, +∞)"},{"key":"B","text":"(-1, 1)"},{"key":"C","text":"(-∞, 0)"},{"key":"D","text":"(0, +∞)"}]',
 'A','f\'(x) = 3x² - 3 = 3(x-1)(x+1)，当 |x| 大于 1 时 f\' 大于 0，函数递增；当 -1 小于 x 小于 1 时 f\' 小于 0，函数递减。判单调要看导数符号，而不是看函数值正负。',5),
(23,'judge','函数在某点可导，则它在该点必定连续。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。可导意味着 Δy/Δx 有有限极限，于是 Δy = (Δy/Δx)·Δx 趋于 0，即函数在该点连续。反之不成立，如 |x| 在 x=0 处连续但不可导。',5),
(23,'judge','若 f 在 x₀ 处可导且 f\'(x₀) = 0，则 x₀ 一定是 f 的极值点。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。导数为 0 只是可导函数取极值的必要条件而非充分条件。反例 f(x) = x³ 在 x=0 处导数为 0，但函数在该点单调穿过，既非极大也非极小。还需检查导数在两侧的符号变化或二阶导符号。',5),
(23,'judge','函数 y = f(x) 的微分 dy = f\'(x)·Δx 是自变量增量 Δx 的线性函数。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。固定 x 后 f\'(x) 是常数，dy 关于 Δx 是一次齐次的，这正是微分作为「增量线性主部」的含义；真实增量 Δy 与 dy 之差是比 Δx 高阶的无穷小。',5),
(23,'judge','若函数 f 在闭区间 [a, b] 上连续、在开区间 (a, b) 内可导，且 f(a) = f(b)，则存在 ξ 使 f\'(ξ) = 0。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确，这是罗尔定理。它是拉格朗日中值定理在两端点函数值相等时的特例，几何意义是区间内至少有一点切线水平。定理的三个条件（闭区间连续、开区间可导、端点值相等）缺一不可。',5),
(23,'multi','下列函数中在 x = 0 处可导的有哪些？',
 '[{"key":"A","text":"y = x·|x|"},{"key":"B","text":"y = x²"},{"key":"C","text":"y = |x|"},{"key":"D","text":"y = sin|x|"}]',
 'AB','x·|x| 的差商为 |h|·h/h = ±h 趋于 0，可导且导数为 0；x² 显然可导。|x| 左右导数为 1 与 -1 不相等；sin|x| 在 0 处右导数为 1、左导数为 -1，也不可导。判可导必须检验左右导数是否一致，仅函数连续不够。',8),
(23,'multi','设 f(x) = x³ - 3x，下列说法正确的有哪些？',
 '[{"key":"A","text":"f 在 x = 1 处取得极小值 -2"},{"key":"B","text":"f 在 x = -1 处取得极大值 2"},{"key":"C","text":"f 的驻点为 x = -1 与 x = 1"},{"key":"D","text":"f 在区间 (-1, 1) 上单调递增"}]',
 'ABC','f(1) = 1 - 3 = -2，且 f 在 x=1 左侧递减右侧递增，是极小值；f(-1) = -1 + 3 = 2，是极大值；令导数为 0 得驻点 ±1。而在 (-1, 1) 内导数 3x²-3 小于 0，函数单调递减，故 D 错。',8),
(24,'single','定积分 ∫（从 0 到 1）3x² dx 的值为？',
 '[{"key":"A","text":"1"},{"key":"B","text":"3"},{"key":"C","text":"1/3"},{"key":"D","text":"0"}]',
 'A','原函数为 x³，代入上下限得 1³ - 0³ = 1。由牛顿-莱布尼茨公式，定积分等于原函数在区间端点的增量；注意系数 3 已被吸收进原函数，不要算成 3。',5),
(24,'single','定积分 ∫（从 -1 到 1）x³·cos x dx 的值为？',
 '[{"key":"A","text":"0"},{"key":"B","text":"2/3"},{"key":"C","text":"1"},{"key":"D","text":"2"}]',
 'A','x³ 是奇函数，cos x 是偶函数，奇函数乘偶函数仍是奇函数，在对称区间 [-1, 1] 上积分为 0。利用奇偶性可免去繁琐的分部积分，但前提是积分区间必须关于原点对称。',5),
(24,'single','定积分 ∫（从 0 到 π）sin x dx 的值为？',
 '[{"key":"A","text":"2"},{"key":"B","text":"0"},{"key":"C","text":"1"},{"key":"D","text":"π"}]',
 'A','原函数为 -cos x，代入得 -cos π - (-cos 0) = 1 + 1 = 2。sin x 在 [0, π] 上非负，积分即为曲线下的面积，结果为正；误答 0 是把一个完整周期 [0, 2π] 的结论套用到了半周期上。',5),
(24,'single','设 F(x) = ∫（从 0 到 x）e 的 (t²) 次方 dt，则 F\'(x) 等于？',
 '[{"key":"A","text":"e 的 (x²) 次方"},{"key":"B","text":"e 的 (t²) 次方"},{"key":"C","text":"2x·e 的 (x²) 次方"},{"key":"D","text":"0"}]',
 'A','由变上限积分求导定理，F\'(x) 就是把上限 x 代入被积函数：e^(x²)。注意被积函数 e^(t²) 的原函数不是初等函数，无法先积出来再求导，这正是该定理的价值所在。',5),
(24,'single','定积分 ∫（从 0 到 1）1/(1 + x²) dx 的值为？',
 '[{"key":"A","text":"π/4"},{"key":"B","text":"π/2"},{"key":"C","text":"1"},{"key":"D","text":"ln 2"}]',
 'A','原函数为 arctan x，代入得 arctan 1 - arctan 0 = π/4。这是反三角函数求导公式的逆向应用；注意 1/(1+x²) 的原函数是 arctan x 而非 ln(1+x²)。',5),
(24,'single','由曲线 y = x² 与直线 y = x 所围成平面图形的面积为？',
 '[{"key":"A","text":"1/6"},{"key":"B","text":"1/3"},{"key":"C","text":"1/2"},{"key":"D","text":"1/12"}]',
 'A','两曲线交于 x = 0 与 x = 1，在 [0,1] 上直线 y = x 在抛物线上方，面积 = ∫₀¹(x - x²)dx = 1/2 - 1/3 = 1/6。求面积必须先确定交点区间并判断哪条曲线在上，否则会得到负值的「积分」而非面积。',5),
(24,'single','函数 f(x) = x 在区间 [0, 2] 上的平均值（积分中值）为？',
 '[{"key":"A","text":"1"},{"key":"B","text":"2"},{"key":"C","text":"1/2"},{"key":"D","text":"4"}]',
 'A','平均值 = (1/(b-a))∫ₐᵇ f = (1/2)∫₀² x dx = (1/2)·2 = 1。积分中值定理保证连续函数在区间内某点的函数值等于该平均值，这里恰好就是中点 x = 1。',5),
(24,'single','定积分 ∫（从 0 到 2）|x - 1| dx 的值为？',
 '[{"key":"A","text":"1"},{"key":"B","text":"0"},{"key":"C","text":"2"},{"key":"D","text":"1/2"}]',
 'A','在 x = 1 处分段：∫₀¹(1-x)dx + ∫₁²(x-1)dx = 1/2 + 1/2 = 1。含绝对值的积分必须先用零点分段去掉绝对值符号，直接把它当成 (x-1) 积分会得到 0 的错误结果。',5),
(24,'single','定积分 ∫（从 -2 到 2）根号(4 - x²) dx 的值为？',
 '[{"key":"A","text":"2π"},{"key":"B","text":"4π"},{"key":"C","text":"π"},{"key":"D","text":"8"}]',
 'A','被积函数 y = 根号(4 - x²) 是半径为 2 的上半圆，积分值等于半圆面积 (1/2)·π·2² = 2π。利用几何意义求积分往往比换元更快，但要注意只是上半圆，若误按整圆算会得到 4π。',5),
(24,'judge','定积分的值与积分变量所采用的字母无关，即 ∫f(x)dx 与 ∫f(t)dt 相同。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。积分变量是「哑变量」，只起占位作用，换成任何字母都不影响积分值；定积分只由被积函数的对应法则和积分区间决定。',5),
(24,'judge','若函数 f 在闭区间 [a, b] 上可积，则 f 必定在 [a, b] 上连续。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。可积的条件比连续宽松：闭区间上有界且只有有限个间断点的函数也可积，例如只有一处跳跃间断点的阶梯函数。连续一定可积，但可积未必连续。',5),
(24,'judge','交换定积分的上下限，积分值变号，即 ∫（从 a 到 b）f = -∫（从 b 到 a）f。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。这是定积分的定向性规定，由牛顿-莱布尼茨公式 F(b) - F(a) = -(F(a) - F(b)) 直接得出；它也保证了区间可加性 ∫ₐᵇ = ∫ₐᶜ + ∫ᵧᵇ 在 c 超出 [a,b] 时依然成立。',5),
(24,'judge','若 f 在 [a, b] 上可积且恒有 f(x) 大于等于 0，但 f 不恒为 0，则 ∫f 一定大于 0。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。仅由非负只能推出积分大于等于 0；若 f 只在有限个点上取正值、其余为 0，则积分为 0。要得到严格大于 0，需要 f 连续且在某点为正（从而在一个小区间上为正）。',5),
(24,'multi','下列定积分中，其值为 0 的有哪些？',
 '[{"key":"A","text":"∫（从 -1 到 1）x dx"},{"key":"B","text":"∫（从 -π 到 π）sin x dx"},{"key":"C","text":"∫（从 -1 到 1）x·cos x dx"},{"key":"D","text":"∫（从 -1 到 1）x² dx"}]',
 'ABC','前三个被积函数都是奇函数（x、sin x、x·cos x），积分区间关于原点对称，故积分为 0；x² 是偶函数，在 [-1,1] 上的积分为 2∫₀¹x²dx = 2/3，不为 0。判奇偶时要对整个被积函数判断，不能只看其中一个因子。',8),
(24,'multi','设 f 在区间上连续，下列哪些等式恒成立？',
 '[{"key":"A","text":"∫（从 a 到 b）f = ∫（从 a 到 c）f + ∫（从 c 到 b）f"},{"key":"B","text":"d/dx ∫（从 a 到 x）f(t)dt = f(x)"},{"key":"C","text":"|∫（从 a 到 b）f| 小于等于 ∫（从 a 到 b）|f|（a 小于 b）"},{"key":"D","text":"∫（从 a 到 b）f(x)dx = f(b) - f(a)"}]',
 'ABC','区间可加性与变上限积分求导都恒成立，绝对值不等式由积分的保序性得出（把 ±f 分别积分即可）。选项 D 错误：f(b) - f(a) 等于 ∫ₐᵇ f 的导数 f\'(x) 的积分，而不是 f 本身的积分。',8),
(55,'single','函数 e 的 x 次方在 x = 0 处的麦克劳林展开中，x³ 项的系数是？',
 '[{"key":"A","text":"1/6"},{"key":"B","text":"1/3"},{"key":"C","text":"1/2"},{"key":"D","text":"1"}]',
 'A','e^x = 1 + x + x²/2! + x³/3! + ...，3! = 6，故 x³ 项系数为 1/6。通项是 x^n/n!，系数由阶乘决定而不是 n，误答 1/3 就是漏了阶乘。',5),
(55,'single','sin x 的麦克劳林展开式中，x⁵ 项的系数是？',
 '[{"key":"A","text":"1/120"},{"key":"B","text":"-1/120"},{"key":"C","text":"1/60"},{"key":"D","text":"-1/60"}]',
 'A','sin x = x - x³/3! + x⁵/5! - ...，5! = 120，且这一项符号为正（各项符号按 + - + - 交替），故系数为 1/120。容易错在两点：把 5! 算成 60，或把符号取反。',5),
(55,'single','用一阶泰勒多项式（线性近似）估算 e 的 0.1 次方，其近似值为？',
 '[{"key":"A","text":"1.1"},{"key":"B","text":"1.105"},{"key":"C","text":"1"},{"key":"D","text":"1.01"}]',
 'A','在 x₀ = 0 处展开：e^x ≈ 1 + x，代入 x = 0.1 得 1.1。若取到二阶则为 1 + 0.1 + 0.005 = 1.105，精度更高。一阶近似的误差约为 (0.1)²/2 = 0.005。',5),
(55,'single','cos x 的麦克劳林展开式的前三个非零项是？',
 '[{"key":"A","text":"1 - x²/2 + x⁴/24"},{"key":"B","text":"x - x³/6 + x⁵/120"},{"key":"C","text":"1 + x²/2 + x⁴/24"},{"key":"D","text":"1 - x²/2 - x⁴/24"}]',
 'A','cos x 是偶函数，展开只含偶次幂：1 - x²/2! + x⁴/4! = 1 - x²/2 + x⁴/24，符号交替。选项 B 是 sin x 的展开，选项 C 符号全正，选项 D 的第三项符号错误。',5),
(55,'single','函数 ln(1 + x) 的麦克劳林级数的收敛域是？',
 '[{"key":"A","text":"(-1, 1]"},{"key":"B","text":"(-1, 1)"},{"key":"C","text":"[-1, 1]"},{"key":"D","text":"(-∞, +∞)"}]',
 'A','ln(1+x) = x - x²/2 + x³/3 - ...，收敛半径 R = 1；在 x = 1 处变为交错级数 1 - 1/2 + 1/3 - ... 收敛（和为 ln2），在 x = -1 处变为 -∑1/n 发散，故收敛域为 (-1, 1]。端点必须单独判断。',5),
(55,'single','用泰勒公式求极限 lim（x 趋于 0）(sin x - x) / x³ 的值为？',
 '[{"key":"A","text":"-1/6"},{"key":"B","text":"1/6"},{"key":"C","text":"0"},{"key":"D","text":"-1/3"}]',
 'A','sin x = x - x³/6 + o(x³)，故 sin x - x = -x³/6 + o(x³)，除以 x³ 得 -1/6。用等价无穷小替换在这里会失效（替换后分子为 0），必须展开到足够的阶数，这是泰勒法求极限的核心技巧。',5),
(55,'single','函数 1/(1 - x) 在 x = 0 处的麦克劳林展开及其收敛区间分别是？',
 '[{"key":"A","text":"1 + x + x² + ...，收敛区间 (-1, 1)"},{"key":"B","text":"1 - x + x² - ...，收敛区间 (-1, 1)"},{"key":"C","text":"1 + x + x² + ...，收敛区间 (-∞, +∞)"},{"key":"D","text":"1 + x + x² + ...，收敛区间 [-1, 1]"}]',
 'A','这是等比级数求和公式的逆向应用：1/(1-x) = ∑x^n，公比为 x，收敛当且仅当 |x| 小于 1，在 x = ±1 处通项不趋于 0 均发散，故收敛区间为开区间 (-1, 1)。',5),
(55,'single','函数 f(x) = ln x 在 x = 1 处的一阶泰勒多项式（线性近似）是？',
 '[{"key":"A","text":"x - 1"},{"key":"B","text":"x"},{"key":"C","text":"1 - x"},{"key":"D","text":"ln 1 + x"}]',
 'A','f(1) = 0，f\'(x) = 1/x 得 f\'(1) = 1，故一阶泰勒多项式为 f(1) + f\'(1)(x-1) = x - 1。这表明在 x = 1 附近 ln x 约等于 x - 1，也解释了极限 ln x/(x-1) 趋于 1。',5),
(55,'single','用二阶泰勒多项式近似根号(1 + x)（在 x = 0 处展开），其表达式为？',
 '[{"key":"A","text":"1 + x/2 - x²/8"},{"key":"B","text":"1 + x/2 + x²/8"},{"key":"C","text":"1 + x/2"},{"key":"D","text":"1 - x/2 + x²/8"}]',
 'A','f(x) = (1+x)^(1/2)，f(0) = 1，f\'(0) = 1/2，f\'\'(0) = -1/4，故二阶展开为 1 + x/2 + (-1/4)/2·x² = 1 + x/2 - x²/8。二次项系数为负，说明该函数图像是上凸的。',5),
(55,'single','带佩亚诺余项的 n 阶泰勒公式中，余项 o((x - x₀)^n) 的含义是？',
 '[{"key":"A","text":"余项是比 (x - x₀)^n 更高阶的无穷小"},{"key":"B","text":"余项恰好等于 (x - x₀)^n"},{"key":"C","text":"余项是比 (x - x₀)^n 更低阶的无穷小"},{"key":"D","text":"余项为常数"}]',
 'A','佩亚诺余项只刻画 x 趋于 x₀ 时的阶：余项与 (x-x₀)^n 之比的极限为 0。它适合求极限与判断阶数，但不能用于误差的定量估计；要估算具体误差需改用带拉格朗日余项的泰勒公式。',5),
(55,'judge','麦克劳林公式就是泰勒公式在展开点 x₀ = 0 处的特例。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。泰勒公式在任意点 x₀ 处展开，取 x₀ = 0 即得麦克劳林公式，二者只是展开点不同，余项与收敛性的处理完全一样。',5),
(55,'judge','任何在 x₀ 处无穷可导的函数，其泰勒级数都收敛到该函数本身。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。存在反例：f(x) = e 的 (-1/x²) 次方（并规定 f(0) = 0）在 x = 0 处各阶导数全为 0，其泰勒级数恒等于 0，但除 x = 0 外函数值并不为 0。函数能否展开成其泰勒级数，取决于余项是否趋于 0。',5),
(55,'judge','用泰勒多项式做函数逼近时，在展开点处多项式与被逼近函数的函数值及各阶导数（直到 n 阶）都相同。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。这正是泰勒多项式的构造条件：P_n 与 f 在 x₀ 处 0 到 n 阶导数逐项相等，因此它在 x₀ 附近与被逼近函数高度贴合，阶数越高贴合范围通常越广。',5),
(55,'judge','函数 f(x) = e 的 (-1/x²) 次方（补充定义 f(0) = 0）在 x = 0 处的各阶导数均为 0，因此其麦克劳林级数恒为 0，不等于 f(x)。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。这是「泰勒级数未必收敛到原函数」的经典反例：该函数在 0 处无限平坦（各阶导数为 0），级数只能给出零函数，说明仅凭无穷可导不足以保证可展开性。',5),
(55,'multi','下列麦克劳林展开式中正确的有哪几项？',
 '[{"key":"A","text":"e^x = 1 + x + x²/2! + x³/3! + ..."},{"key":"B","text":"sin x = x - x³/3! + x⁵/5! - ..."},{"key":"C","text":"cos x = 1 - x²/2! + x⁴/4! - ..."},{"key":"D","text":"ln(1 + x) = x + x²/2 + x³/3 + ..."}]',
 'ABC','前三个都是标准展开：e^x 全正号，sin x 奇次幂符号交替，cos x 偶次幂符号交替。ln(1+x) 的正确展开为 x - x²/2 + x³/3 - ...，是交错级数，选项 D 全取正号因而错误。',8),
(55,'multi','当 x 趋于 0 时，下列哪些量与 x² 是同阶无穷小？',
 '[{"key":"A","text":"1 - cos x"},{"key":"B","text":"ln(1 + x²)"},{"key":"C","text":"e 的 (x²) 次方 - 1"},{"key":"D","text":"x - sin x"}]',
 'ABC','1 - cos x 等价于 x²/2，ln(1+x²) 等价于 x²，e^(x²) - 1 等价于 x²，三者都是二阶无穷小。而 x - sin x 等价于 x³/6，是三阶无穷小，与 x² 之比趋于 0，不属于同阶。',8),
(55,'multi','关于用 n 阶泰勒多项式 P_n 逼近函数 f，下列说法正确的有哪些？',
 '[{"key":"A","text":"P_n 与 f 在展开点 x₀ 处的函数值相同"},{"key":"B","text":"P_n 与 f 在 x₀ 处的 1 到 n 阶导数都相同"},{"key":"C","text":"给定展开点与阶数后，满足上述条件的泰勒多项式是唯一的"},{"key":"D","text":"P_n 在 f 的整个定义域上都一致逼近 f"}]',
 'ABC','前三条正是泰勒多项式的定义与唯一性：由 x₀ 处 0 到 n 阶导数唯一确定。第四条错误，泰勒多项式只保证在 x₀ 附近（局部）逼近良好，远离展开点时误差可能很大甚至发散，如 ln(1+x) 的展开在 x 大于 1 处不收敛。',8),
(56,'single','微分方程 dy/dx = 2y 的通解是？',
 '[{"key":"A","text":"y = C·e 的 (2x) 次方"},{"key":"B","text":"y = e 的 (2x) 次方"},{"key":"C","text":"y = C·e 的 x 次方"},{"key":"D","text":"y = 2y + C"}]',
 'A','分离变量得 dy/y = 2dx，积分得 ln|y| = 2x + C₁，即 y = C·e^(2x)，其中 C 为任意常数。一阶微分方程的通解必含一个任意常数；漏掉 C 只得到其中一个特解。',5),
(56,'single','初值问题 y\' + y = 0，y(0) = 3 的解是？',
 '[{"key":"A","text":"y = 3·e 的 (-x) 次方"},{"key":"B","text":"y = 3·e 的 x 次方"},{"key":"C","text":"y = e 的 (-x) 次方"},{"key":"D","text":"y = 3x"}]',
 'A','通解 y = C·e^(-x)，代入 y(0) = 3 得 C = 3，故 y = 3e^(-x)。初值条件的作用恰恰是从通解族中挑出唯一一条积分曲线。',5),
(56,'single','二阶常系数齐次方程 y\'\' - 4y = 0 的通解是？',
 '[{"key":"A","text":"C₁·e 的 (2x) 次方 + C₂·e 的 (-2x) 次方"},{"key":"B","text":"C₁·e 的 (2x) 次方 + C₂·x·e 的 (2x) 次方"},{"key":"C","text":"C₁·cos 2x + C₂·sin 2x"},{"key":"D","text":"(C₁ + C₂x)·e 的 (4x) 次方"}]',
 'A','特征方程 r² - 4 = 0，得两个不等实根 r = ±2，故通解为两个指数解的线性组合。选项 B 对应重根情形，选项 C 对应共轭复根 ±2i（那是 y\'\' + 4y = 0）。',5),
(56,'single','方程 y\'\' + y = 0 的通解是？',
 '[{"key":"A","text":"C₁·cos x + C₂·sin x"},{"key":"B","text":"C₁·e 的 x 次方 + C₂·e 的 (-x) 次方"},{"key":"C","text":"C₁ + C₂x"},{"key":"D","text":"C·cos x"}]',
 'A','特征方程 r² + 1 = 0 得共轭复根 ±i，对应实解 cos x 与 sin x，通解为二者的线性组合。选项 B 是 y\'\' - y = 0 的通解，注意特征方程符号决定根的类型（实根还是复根）。',5),
(56,'single','在微分方程 y\' = x 的斜率场中，点 (2, 3) 处小线段的斜率是？',
 '[{"key":"A","text":"2"},{"key":"B","text":"3"},{"key":"C","text":"5"},{"key":"D","text":"0"}]',
 'A','斜率场的规则是：在点 (x, y) 处画一条斜率为 f(x, y) 的小线段。这里 f(x, y) = x 与 y 无关，故在 x = 2 处所有小线段斜率都是 2，形成一列方向相同的平行短线。',5),
(56,'single','一阶线性方程 y\' + 2y = 4 的常数（平衡）解是？',
 '[{"key":"A","text":"y = 2"},{"key":"B","text":"y = 4"},{"key":"C","text":"y = 0"},{"key":"D","text":"y = -2"}]',
 'A','常数解的导数为 0，代入得 2y = 4，即 y = 2。通解为 y = 2 + C·e^(-2x)，当 x 趋于无穷时所有解都趋于平衡解 y = 2，这正是平衡解的稳定性含义。',5),
(56,'single','Logistic 方程 y\' = y(1 - y) 的平衡解为？',
 '[{"key":"A","text":"y = 0 与 y = 1"},{"key":"B","text":"只有 y = 0"},{"key":"C","text":"只有 y = 1"},{"key":"D","text":"y = -1 与 y = 1"}]',
 'A','令 y\' = 0 得 y(1-y) = 0，解出 y = 0 与 y = 1。在斜率场中它们对应两条水平（斜率为 0）的积分曲线；初值在 (0,1) 内的解会单调趋向 y = 1，大于 1 的解则递减趋向 1。',5),
(56,'single','用分离变量法求解 dy/dx = x / y，得到的隐式通解是？',
 '[{"key":"A","text":"y² = x² + C"},{"key":"B","text":"y = x² + C"},{"key":"C","text":"y² = x + C"},{"key":"D","text":"ln|y| = x + C"}]',
 'A','分离得 y dy = x dx，两边积分得 y²/2 = x²/2 + C₁，整理为 y² = x² + C（常数已重新记名）。这是一族双曲线，注意它写的是隐式解，显式写出还要开方并讨论符号。',5),
(56,'single','方程 y\'\' - 2y\' + y = 0 的特征根与通解分别是？',
 '[{"key":"A","text":"二重根 r = 1，通解为 (C₁ + C₂x)·e 的 x 次方"},{"key":"B","text":"两个不等实根 1 与 -1，通解为 C₁e^x + C₂e^(-x)"},{"key":"C","text":"复根 ±i，通解为 C₁cos x + C₂sin x"},{"key":"D","text":"二重根 r = -1，通解为 (C₁ + C₂x)·e 的 (-x) 次方"}]',
 'A','特征方程 r² - 2r + 1 = (r-1)² = 0，得二重根 r = 1。重根时两个线性无关解为 e^x 与 x·e^x，必须补乘 x 才能得到第二个独立解，否则解族不完整。',5),
(56,'single','初值问题 y\' = 2x，y(1) = 2 的解是？',
 '[{"key":"A","text":"y = x² + 1"},{"key":"B","text":"y = x²"},{"key":"C","text":"y = x² + 2"},{"key":"D","text":"y = 2x"}]',
 'A','直接积分得 y = x² + C，代入 y(1) = 2 得 1 + C = 2，故 C = 1，解为 y = x² + 1。检验：y\' = 2x 且 y(1) = 2，两条都满足。',5),
(56,'judge','一阶常微分方程的通解中恰含一个任意常数，二阶方程的通解中恰含两个。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。通解中独立任意常数的个数等于方程的阶数，每积分一次引入一个常数；要确定唯一解就需同样个数的初值条件。',5),
(56,'judge','在斜率场中，积分曲线在与小线段相交处必须与该线段相切。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。这正是斜率场（方向场）的定义：小线段标示出解曲线在该点的切线方向，因此任何一条积分曲线经过该点时其切线方向必然与线段一致，这也是用斜率场可视化求解的原理。',5),
(56,'judge','方程 y\' = y² 的解 y = -1/(x + C) 会在 x = -C 处出现垂直渐近线，说明解不能延拓到全体实数。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。这是非线性方程的典型现象——解在有限时刻「爆破」（blow up）。线性方程的解通常可以延拓到整个区间，而非线性方程即使右端很光滑，解也可能只能在有限区间上存在。',5),
(56,'judge','二阶线性齐次方程任意两个解的线性组合仍是该方程的解。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确，这就是叠加原理：算子 L = d²/dx² + p(x)d/dx + q(x) 是线性的，故 L(c₁y₁ + c₂y₂) = c₁L(y₁) + c₂L(y₂) = 0。注意该结论只对齐次方程成立，非齐次方程的叠加要另加修正。',5),
(56,'multi','关于方程 y\'\' + 4y\' + 4y = 0，下列说法正确的有哪些？',
 '[{"key":"A","text":"特征方程为 r² + 4r + 4 = 0"},{"key":"B","text":"特征根为二重根 r = -2"},{"key":"C","text":"通解为 (C₁ + C₂x)·e 的 (-2x) 次方"},{"key":"D","text":"通解为 C₁·e 的 (2x) 次方 + C₂·e 的 (-2x) 次方"}]',
 'ABC','特征方程 r² + 4r + 4 = (r+2)² = 0，得二重根 r = -2，通解为 (C₁ + C₂x)e^(-2x)。选项 D 对应的是特征根 ±2，即方程 y\'\' - 4y = 0，符号不同结果完全不同。',8),
(56,'multi','关于微分方程的斜率场，下列说法正确的有哪些？',
 '[{"key":"A","text":"每个点的小线段斜率由把该点坐标代入 f(x, y) 得到"},{"key":"B","text":"自治方程 y\' = f(y) 的斜率场沿水平方向平移不变"},{"key":"C","text":"平衡解在斜率场中表现为斜率为 0 的水平直线"},{"key":"D","text":"在满足唯一性条件的区域内，两条积分曲线可以在某点相交"}]',
 'ABC','前三条是斜率场的基本性质：逐点按 f(x,y) 定方向；自治方程与 x 无关故沿 x 方向平移不变；平衡解即 f = 0 的水平线。第四条错误，若两条解曲线在某点相交，则过该点有两个解，与解的唯一性矛盾。',8),
(56,'multi','下列方程中属于一阶线性微分方程的有哪些？',
 '[{"key":"A","text":"y\' + x·y = sin x"},{"key":"B","text":"x·y\' + y = e 的 x 次方"},{"key":"C","text":"y\' = y² + x"},{"key":"D","text":"y·y\' = 1"}]',
 'AB','一阶线性方程可写成 a₁(x)y\' + a₀(x)y = g(x)，关于 y 与 y\' 都是一次的。前两项符合（第二项除以 x 后即为标准形）；第三项含 y²、第四项含 y·y\'，都出现了未知函数的非线性项，故不是线性方程。',8),
(57,'single','设 f(x, y) = x²y + 3y，则 f 对 x 的偏导数为？',
 '[{"key":"A","text":"2xy"},{"key":"B","text":"x² + 3"},{"key":"C","text":"2xy + 3"},{"key":"D","text":"x²y"}]',
 'A','对 x 求偏导时把 y 视为常数：x²y 对 x 求导得 2xy，3y 是常数求导为 0。f_y = x² + 3 是另一个偏导，不要混淆两个变量。',5),
(57,'single','设 f(x, y) = x²y + 3y，则 f 对 y 的偏导数为？',
 '[{"key":"A","text":"x² + 3"},{"key":"B","text":"2xy"},{"key":"C","text":"2xy + 3"},{"key":"D","text":"x²y"}]',
 'A','对 y 求偏导时把 x 视为常数：x²y 的导数为 x²，3y 的导数为 3，合计 x² + 3。偏导数的本质是固定其余变量后的一元导数。',5),
(57,'single','设 f(x, y) = sin(xy)，则 ∂f/∂x 等于？',
 '[{"key":"A","text":"y·cos(xy)"},{"key":"B","text":"x·cos(xy)"},{"key":"C","text":"cos(xy)"},{"key":"D","text":"y·sin(xy)"}]',
 'A','由链式法则，对外层 sin 求导得 cos(xy)，再乘以内层 xy 对 x 的偏导 y，结果为 y·cos(xy)。求偏导时另一个变量要像常数一样参与链式法则的系数。',5),
(57,'single','函数 f(x, y) = x² + 2y² 在点 (1, 1) 处的梯度向量 ∇f 是？',
 '[{"key":"A","text":"(2, 4)"},{"key":"B","text":"(1, 2)"},{"key":"C","text":"(2, 2)"},{"key":"D","text":"(4, 2)"}]',
 'A','f_x = 2x 在 (1,1) 处为 2，f_y = 4y 在 (1,1) 处为 4，故 ∇f = (2, 4)。梯度由各偏导数按坐标顺序排列组成，不要把它当成标量。',5),
(57,'single','函数 f(x, y) = x² + y² 在点 (1, 2) 处沿单位方向 (3/5, 4/5) 的方向导数为？',
 '[{"key":"A","text":"22/5"},{"key":"B","text":"2"},{"key":"C","text":"11/5"},{"key":"D","text":"5"}]',
 'A','∇f = (2x, 2y) 在 (1,2) 处为 (2, 4)，方向导数 = ∇f·u = 2·(3/5) + 4·(4/5) = 6/5 + 16/5 = 22/5。方向必须先用单位向量，若直接用 (3,4) 会把结果放大 5 倍。',5),
(57,'single','函数 f(x, y) = xy 在点 (1, 1) 处的梯度模长 |∇f| 等于？',
 '[{"key":"A","text":"根号 2"},{"key":"B","text":"1"},{"key":"C","text":"2"},{"key":"D","text":"根号 3"}]',
 'A','f_x = y = 1，f_y = x = 1，故 ∇f = (1, 1)，模长为 根号(1² + 1²) = 根号 2。梯度模长正是该点方向导数的最大值。',5),
(57,'single','设 f(x, y) = x²y³，则其二阶混合偏导 ∂²f/∂x∂y 等于？',
 '[{"key":"A","text":"6xy²"},{"key":"B","text":"2xy³"},{"key":"C","text":"6x²y"},{"key":"D","text":"3x²y²"}]',
 'A','先对 x 求偏导得 2xy³，再对 y 求偏导得 6xy²。反过来先对 y 再对 x：3x²y² → 6xy²，结果相同，这体现了混合偏导在连续条件下的对称性。',5),
(57,'single','函数 f(x, y, z) = xyz 在点 (1, 2, 3) 处的梯度向量是？',
 '[{"key":"A","text":"(6, 3, 2)"},{"key":"B","text":"(1, 2, 3)"},{"key":"C","text":"(2, 3, 6)"},{"key":"D","text":"(3, 2, 1)"}]',
 'A','f_x = yz = 6，f_y = xz = 3，f_z = xy = 2，故 ∇f = (6, 3, 2)。分量顺序与变量顺序一一对应：某个分量等于其余变量的乘积。',5),
(57,'single','梯度向量 ∇f 与函数 f 的等值线（等高线）之间是什么关系？',
 '[{"key":"A","text":"梯度垂直于等值线，并指向函数值增大的方向"},{"key":"B","text":"梯度平行于等值线"},{"key":"C","text":"梯度与等值线成 45 度角"},{"key":"D","text":"两者没有关系"}]',
 'A','沿等值线移动函数值不变，故方向导数为 0，即 ∇f 与切向点积为 0，所以梯度垂直于等值线；同时它指向函数值上升最快的方向。这一性质是梯度下降法等优化算法的几何基础。',5),
(57,'single','函数在某点沿哪个方向的方向导数取得最大值，最大值等于什么？',
 '[{"key":"A","text":"沿梯度方向，最大值等于梯度模长"},{"key":"B","text":"沿 x 轴方向，最大值等于 f_x"},{"key":"C","text":"沿任意方向都一样"},{"key":"D","text":"沿与梯度垂直的方向，最大值等于 0"}]',
 'A','方向导数 D_u f = ∇f·u = |∇f|·cos θ，当 θ = 0（即 u 与梯度同向）时取最大值 |∇f|；与梯度反向时取最小值 -|∇f|，垂直时为 0。',5),
(57,'judge','二元函数在一点处的两个偏导数都存在，则该函数在该点必定连续。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。偏导数只沿坐标轴两个方向刻画变化率，不能控制沿其他方向趋近时的行为。经典反例 f(x,y) = xy/(x²+y²)（原点处补 0）在原点两个偏导都为 0，但函数在该点不连续。',5),
(57,'judge','若二阶混合偏导数 f(xy) 与 f(yx) 连续，则二者相等。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确，这是混合偏导与求导次序无关定理。连续性条件不可省略——缺少该条件时存在两个混合偏导不相等的反例。',5),
(57,'judge','梯度为零向量的点一定是函数的极值点。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。梯度为 0 只是可微函数取极值的必要条件。反例 f(x,y) = x² - y² 在原点梯度为 (0,0)，但沿 x 方向函数上升、沿 y 方向下降，是鞍点而非极值点。',5),
(57,'judge','在点 P 处，函数沿某方向的方向导数等于梯度与该方向单位向量的内积。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确，这是可微函数方向导数的计算公式 D_u f = ∇f·u。它对任意方向都成立，也直接推出「梯度方向使方向导数最大」这一结论。',5),
(57,'multi','设 f(x, y) = x²y²，下列说法正确的有哪些？',
 '[{"key":"A","text":"f 对 x 的偏导为 2xy²"},{"key":"B","text":"f 对 y 的偏导为 2x²y"},{"key":"C","text":"二阶混合偏导为 4xy"},{"key":"D","text":"∇f 在点 (1, 1) 处为 (1, 1)"}]',
 'ABC','f_x = 2xy²，f_y = 2x²y，再求导得 f_xy = 4xy，三条都正确。在 (1,1) 处 ∇f = (2, 2) 而非 (1, 1)，故 D 错——求梯度时容易漏掉平方求导产生的系数 2。',8),
(57,'multi','关于梯度 ∇f 的几何意义，下列说法正确的有哪些？',
 '[{"key":"A","text":"∇f 指向函数值增长最快的方向"},{"key":"B","text":"∇f 的模长等于该点方向导数的最大值"},{"key":"C","text":"∇f 垂直于该点的等值线"},{"key":"D","text":"沿 ∇f 方向函数的变化率为 0"}]',
 'ABC','前三条是梯度的三大几何性质，均正确。第四条错误：沿梯度方向的方向导数恰为 |∇f|（最大值），变化率为 0 的方向是与梯度垂直的等值线切向。',8),
(57,'multi','设 f(x, y) = x³ - 3xy + y³，关于原点 (0, 0) 下列说法正确的有哪些？',
 '[{"key":"A","text":"f 对 x 的偏导在原点为 0"},{"key":"B","text":"f 对 y 的偏导在原点为 0"},{"key":"C","text":"(0, 0) 是 f 的一个驻点"},{"key":"D","text":"(0, 0) 是 f 的极小值点"}]',
 'ABC','f_x = 3x² - 3y 与 f_y = -3x + 3y² 在原点都为 0，故原点是驻点。但它不是极值点：沿 y = x 有 f = 2x³ - 3x²，当 x 很小时为负；沿 y = -x 有 f = 3x² 为正，故是鞍点，D 错。',8),
(101,'single','设 z = x²y，则在点 (1, 2) 处的全微分 dz 为？',
 '[{"key":"A","text":"4dx + dy"},{"key":"B","text":"2dx + dy"},{"key":"C","text":"4dx + 4dy"},{"key":"D","text":"dx + 4dy"}]',
 'A','z_x = 2xy 在 (1,2) 处为 4，z_y = x² 在 (1,2) 处为 1，故 dz = 4dx + dy。全微分是各自变量增量的一次齐次线性组合，系数就是对应的偏导数。',5),
(101,'single','设 z = f(x, y) 可微，且 x = t²，y = 2t，则 dz/dt 的链式法则表达式为？',
 '[{"key":"A","text":"f_x·2t + f_y·2"},{"key":"B","text":"f_x + f_y"},{"key":"C","text":"f_x·2t + f_y·t"},{"key":"D","text":"f_x·t² + f_y·2t"}]',
 'A','链式法则：dz/dt = f_x·(dx/dt) + f_y·(dy/dt) = f_x·2t + f_y·2。每条中间路径贡献一项，注意是对中间变量求偏导、对参数求普通导数，二者不能混用。',5),
(101,'single','由隐方程 x² + y² - 1 = 0 确定的隐函数 y = y(x)，其导数 dy/dx 等于？',
 '[{"key":"A","text":"-x/y"},{"key":"B","text":"x/y"},{"key":"C","text":"-y/x"},{"key":"D","text":"2x + 2y"}]',
 'A','隐函数求导公式 dy/dx = -F_x/F_y = -2x/(2y) = -x/y。负号容易漏掉；另外该式在 y = 0（圆的左右端点）处失效，此时隐函数不能表示成 y(x)。',5),
(101,'single','二元可微函数 f(x, y) 在点 P 取得极值的必要条件是？',
 '[{"key":"A","text":"f_x = 0 且 f_y = 0"},{"key":"B","text":"f_x = f_y（不必为 0）"},{"key":"C","text":"二阶偏导同号"},{"key":"D","text":"梯度模长最大"}]',
 'A','与一元情形类似，可微函数在极值点处各一阶偏导必为 0，即梯度为零向量（驻点）。它只是必要条件，驻点还可能是鞍点，需用二阶判别法进一步判断。',5),
(101,'single','记 A = f(xx)，B = f(xy)，C = f(yy)，则在驻点处判定极小值的充分条件是？',
 '[{"key":"A","text":"AC - B² 大于 0 且 A 大于 0"},{"key":"B","text":"AC - B² 大于 0 且 A 小于 0"},{"key":"C","text":"AC - B² 小于 0"},{"key":"D","text":"AC - B² 等于 0"}]',
 'A','判别式 AC - B² 大于 0 时取极值：A 大于 0（即关于 x 方向上凸）为极小值，A 小于 0 为极大值。判别式小于 0 是鞍点，等于 0 时该判别法失效需另作分析。',5),
(101,'single','用拉格朗日乘数法求 f(x, y) = xy 在约束 x + y = 2 下的最大值，其值为？',
 '[{"key":"A","text":"1"},{"key":"B","text":"2"},{"key":"C","text":"4"},{"key":"D","text":"0"}]',
 'A','令 L = xy + λ(x + y - 2)，驻点条件 y + λ = 0、x + λ = 0、x + y = 2，解得 x = y = 1，f = 1。也可直接消元：y = 2 - x，f = 2x - x² 在 x = 1 处取最大 1，结果一致。',5),
(101,'single','二元函数在一点处全微分存在的充分条件是？',
 '[{"key":"A","text":"两个偏导数在该点的某邻域内存在且在该点连续"},{"key":"B","text":"两个偏导数在该点存在"},{"key":"C","text":"函数在该点连续"},{"key":"D","text":"函数在该点的方向导数都存在"}]',
 'A','偏导连续蕴含可微，这是充分条件；反之可微只能推出偏导存在与连续，推不出偏导连续。仅有偏导存在或仅有连续都不足以保证可微。',5),
(101,'single','函数 f(x, y) = x² - y² 在原点 (0, 0) 处属于哪种情形？',
 '[{"key":"A","text":"驻点且为鞍点"},{"key":"B","text":"极小值点"},{"key":"C","text":"极大值点"},{"key":"D","text":"不是驻点"}]',
 'A','f_x = 2x、f_y = -2y 在原点均为 0，是驻点；但 f(x,0) = x² 大于等于 0、f(0,y) = -y² 小于等于 0，原点附近既有比它大也有比它小的函数值，故是鞍点。判别式 AC - B² = 2×(-2) = -4 小于 0 也印证了这一点。',5),
(101,'single','在有界闭区域 D 上求连续函数 f(x, y) 的最大值与最小值，正确的做法是？',
 '[{"key":"A","text":"比较 D 内部驻点的函数值与 D 边界上的最值"},{"key":"B","text":"只比较 D 内部驻点的函数值"},{"key":"C","text":"只比较 D 边界上的函数值"},{"key":"D","text":"只看梯度模长最大的点"}]',
 'A','连续函数在有界闭区域上必取到最大最小值，最值可能出现在内部驻点，也可能出现在边界上（边界需用一元方法或拉格朗日法再求一次），因此必须把所有候选值一起比较。只查内部会漏掉边界取到最值的常见情形。',5),
(101,'single','设 z = f(u, v)，其中 u = x + y，v = x - y，则 z 对 x 的偏导为？',
 '[{"key":"A","text":"f_u + f_v"},{"key":"B","text":"f_u - f_v"},{"key":"C","text":"f_u"},{"key":"D","text":"f_v"}]',
 'A','链式法则：z_x = f_u·u_x + f_v·v_x = f_u·1 + f_v·1 = f_u + f_v。变量替换后要对每条通向 x 的路径各贡献一项，符号由中间变量对 x 的偏导决定。',5),
(101,'judge','二元函数在一点可微，则该点处的两个偏导数必定存在。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。可微蕴含偏导存在，且全微分的系数恰为两个偏导数，即 dz = f_x dx + f_y dy。反之不然，仅有偏导存在推不出可微。',5),
(101,'judge','二元函数在一点沿所有方向的方向导数都存在，则该函数在该点可微。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。方向导数只刻画沿射线方向的变化率，即使各方向都存在也未必能拼出一个统一的线性主部。可微要求更强的条件（如偏导连续）才能保证全增量有线性近似。',5),
(101,'judge','用拉格朗日乘数法求条件极值时，拉格朗日函数 L = f + λ·g 的驻点一定给出原问题的最值点。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。拉格朗日乘数法给出的是条件极值的必要条件（候选点），是否为最值还需结合问题的实际背景或比较边界情况来判断；此外还要检查约束梯度不为零这一正则条件。',5),
(101,'judge','若二元函数在有界闭区域上连续，则它在该区域上必定能取到最大值与最小值。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确，这是有界闭集上连续函数的最值定理（多元形式的魏尔斯特拉斯定理）。条件中的「有界」与「闭」缺一不可，开区域或无界区域上连续函数未必取到最值。',5),
(101,'multi','设 f(x, y) = x² + xy + y²，下列说法正确的有哪些？',
 '[{"key":"A","text":"f 对 x 的偏导为 2x + y"},{"key":"B","text":"f 对 y 的偏导为 x + 2y"},{"key":"C","text":"在点 (1, 1) 处 dz = 3dx + 3dy"},{"key":"D","text":"(0, 0) 是 f 的极大值点"}]',
 'ABC','f_x = 2x + y、f_y = x + 2y，在 (1,1) 处二者都是 3，故 dz = 3dx + 3dy。原点处 A = 2、B = 1、C = 2，AC - B² = 3 大于 0 且 A 大于 0，是极小值点而非极大值点，D 错。',8),
(101,'multi','关于二元函数极值的二阶判别法（记 A = f(xx)，B = f(xy)，C = f(yy)），正确的有哪些？',
 '[{"key":"A","text":"AC - B² 大于 0 且 A 大于 0 时为极小值"},{"key":"B","text":"AC - B² 大于 0 且 A 小于 0 时为极大值"},{"key":"C","text":"AC - B² 小于 0 时为鞍点"},{"key":"D","text":"AC - B² 等于 0 时一定是极值点"}]',
 'ABC','前三条是判别法的标准结论。当 AC - B² = 0 时判别法失效，既可能是极值也可能不是（如 f = x⁴ + y⁴ 与 f = x⁴ - y⁴ 在该指标下都为 0 但性质不同），必须改用其他方法判断，故 D 错。',8),
(101,'multi','用拉格朗日乘数法求 f(x, y) = x² + y² 在约束 x + y = 1 下的最小值，下列说法正确的有哪些？',
 '[{"key":"A","text":"拉格朗日函数可写为 L = x² + y² + λ(x + y - 1)"},{"key":"B","text":"驻点条件为 2x + λ = 0、2y + λ = 0、x + y = 1"},{"key":"C","text":"解得 x = y = 1/2，最小值为 1/2"},{"key":"D","text":"最小值为 1"}]',
 'ABC','由 2x + λ = 0 与 2y + λ = 0 得 x = y，再结合 x + y = 1 得 x = y = 1/2，此时 f = 1/4 + 1/4 = 1/2，故 D 错。几何上这就是原点到直线 x + y = 1 的最短距离的平方。',8),
(102,'single','二重积分在单位正方形区域 [0,1]×[0,1] 上对被积函数 1 积分，其值为？',
 '[{"key":"A","text":"1"},{"key":"B","text":"2"},{"key":"C","text":"0"},{"key":"D","text":"1/2"}]',
 'A','被积函数恒为 1 时，二重积分的值就等于积分区域的面积，单位正方形面积为 1。这是二重积分最基本的几何解释，也是检验积分限设置是否正确的常用手段。',5),
(102,'single','二重积分在单位圆域 x² + y² 小于等于 1 上对被积函数 1 积分，其值为？',
 '[{"key":"A","text":"π"},{"key":"B","text":"2π"},{"key":"C","text":"π/2"},{"key":"D","text":"π²"}]',
 'A','被积函数为 1 时积分值即区域面积，单位圆面积为 π·1² = π。若误用半径为 2 或被积函数换成 r 就会得到不同结果，注意区分「面积」与「对 r 的积分」。',5),
(102,'single','在极坐标变换 x = r·cos θ，y = r·sin θ 下，面积元素 dxdy 变为？',
 '[{"key":"A","text":"r dr dθ"},{"key":"B","text":"dr dθ"},{"key":"C","text":"r² dr dθ"},{"key":"D","text":"sin r dr dθ"}]',
 'A','雅可比行列式 ∂(x,y)/∂(r,θ) 的绝对值为 r，故 dxdy = r dr dθ。漏掉这个因子 r 是极坐标换元最常见的错误，会导致结果整体偏小。',5),
(102,'single','把累次积分 ∫（从 0 到 1）∫（从 x 到 1）f(x,y) dy dx 交换积分次序，结果是？',
 '[{"key":"A","text":"∫（从 0 到 1）∫（从 0 到 y）f(x,y) dx dy"},{"key":"B","text":"∫（从 0 到 1）∫（从 0 到 x）f(x,y) dx dy"},{"key":"C","text":"∫（从 0 到 1）∫（从 y 到 1）f(x,y) dx dy"},{"key":"D","text":"∫（从 0 到 1）∫（从 0 到 1）f(x,y) dx dy"}]',
 'A','原区域由 0 小于等于 x 小于等于 1、x 小于等于 y 小于等于 1 描述，即三角形区域。改写为先定 y（0 到 1）再定 x（0 到 y），得 ∫₀¹∫₀^y f dx dy。画区域图是交换次序时避免出错的关键。',5),
(102,'single','用极坐标计算二重积分在圆域 x² + y² 小于等于 1 上对 (x² + y²) 积分，其值为？',
 '[{"key":"A","text":"π/2"},{"key":"B","text":"π"},{"key":"C","text":"π/4"},{"key":"D","text":"2π/3"}]',
 'A','化为 ∫₀^{2π}∫₀¹ r²·r dr dθ = 2π·[r⁴/4]₀¹ = 2π/4 = π/2。注意被积函数 x²+y² 化为 r²，再加上面积元素带来的 r，实际积分的是 r³。',5),
(102,'single','设 D 为正方形 [0,1]×[0,1]，则二重积分对 (x + y) 在 D 上积分的值为？',
 '[{"key":"A","text":"1"},{"key":"B","text":"2"},{"key":"C","text":"1/2"},{"key":"D","text":"3/2"}]',
 'A','由线性性与对称性，∬x dA = ∬y dA = 1/2，故 ∬(x+y) dA = 1。也可直接算：∫₀¹∫₀¹(x+y)dxdy = 1/2 + 1/2 = 1。',5),
(102,'single','三重积分在单位立方体 [0,1]³ 上对被积函数 1 积分，其值为？',
 '[{"key":"A","text":"1"},{"key":"B","text":"3"},{"key":"C","text":"6"},{"key":"D","text":"1/6"}]',
 'A','被积函数为 1 时三重积分等于区域的体积，单位立方体体积为 1×1×1 = 1。这与二维情形完全类似，可推广：n 重积分对 1 积分给出 n 维体积。',5),
(102,'single','二重积分 ∬(D) f(x,y) dA（f 大于等于 0）的几何意义是？',
 '[{"key":"A","text":"以 D 为底、以曲面 z = f(x,y) 为顶的曲顶柱体的体积"},{"key":"B","text":"曲面 z = f(x,y) 的表面积"},{"key":"C","text":"区域 D 的边界长度"},{"key":"D","text":"函数 f 在 D 上的平均值"}]',
 'A','这就是二重积分的几何解释：把 D 上每点处高度 f(x,y) 累积起来得到体积。平均值则是积分值再除以区域面积，表面积需要第一类曲面积分，二者不可混淆。',5),
(102,'single','第一类曲线积分 ∫(C) ds 在几何上表示什么？',
 '[{"key":"A","text":"曲线 C 的弧长"},{"key":"B","text":"曲线 C 围成的面积"},{"key":"C","text":"沿 C 的做功"},{"key":"D","text":"曲线 C 的长度乘以 2"}]',
 'A','第一类曲线积分对弧长积分，被积函数为 1 时即为曲线弧长；若被积函数为线密度，则给出曲线形构件的质量。对坐标的第二类曲线积分才对应变力做功。',5),
(102,'single','极坐标变换的雅可比行列式 ∂(x,y)/∂(r,θ) 的值为？',
 '[{"key":"A","text":"r"},{"key":"B","text":"1/r"},{"key":"C","text":"r²"},{"key":"D","text":"1"}]',
 'A','计算得 |cos θ, -r sin θ; sin θ, r cos θ| = r cos²θ + r sin²θ = r。换元时取的是雅可比行列式的绝对值，在 r 大于等于 0 时就是 r 本身。',5),
(102,'judge','二重积分的值由被积函数与积分区域决定，与所采用的积分次序无关。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。在可积（如连续）的前提下，两种次序的累次积分相等，这正是交换积分次序技巧的理论依据；实际计算中选用哪种次序往往取决于哪种更容易算出。',5),
(102,'judge','若积分区域 D 关于 x 轴对称，且被积函数 f 关于变量 y 是奇函数，则 f 在 D 上的二重积分为 0。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。对称位置 (x, y) 与 (x, -y) 处的函数值互为相反数，两块面积元素相同，贡献恰好抵消。使用这一性质时必须同时验证区域对称与函数奇偶性两个条件。',5),
(102,'judge','三重积分 ∬∬∬(Ω) dV 的值恒等于区域 Ω 的表面积。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。被积函数为 1 的三重积分给出的是 Ω 的体积而非表面积；表面积要用第一类曲面积分 ∬(∂Ω) dS 来计算。体积与表面积是两个不同的几何量，量纲也不同。',5),
(102,'judge','二重积分具有区域可加性：把区域 D 分成两块 D₁ 与 D₂，则 D 上的积分等于两块上积分之和。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确，这是积分的基本性质，与一元定积分区间可加性完全对应。它也是分段积分、处理绝对值与分段被积函数的理论依据。',5),
(102,'multi','关于二重积分的性质，下列说法正确的有哪些？',
 '[{"key":"A","text":"具有区域可加性"},{"key":"B","text":"对被积函数具有线性性"},{"key":"C","text":"若 f 在 D 上恒大于等于 0，则积分值非负"},{"key":"D","text":"积分值总等于区域面积乘以区域中心处的函数值"}]',
 'ABC','前三条是二重积分的基本性质。第四条错误：积分中值定理只保证存在某一点使积分等于面积乘该点函数值，这一点未必是几何中心，换成中心一般不成立。',8),
(102,'multi','设 D 为圆域 x² + y² 小于等于 4，用极坐标计算 D 的面积，下列说法正确的有哪些？',
 '[{"key":"A","text":"可写成 ∫（从 0 到 2π）∫（从 0 到 2）r dr dθ"},{"key":"B","text":"面积元素为 r dr dθ"},{"key":"C","text":"计算结果为 4π"},{"key":"D","text":"计算结果为 2π"}]',
 'ABC','半径 R = 2，极坐标下 ∫₀^{2π}∫₀² r dr dθ = 2π·(4/2) = 4π，与圆面积公式 πR² = 4π 一致。选项 D 相当于只算了半圆或漏了因子，错误。',8),
(102,'multi','关于三重积分的柱坐标变换，下列说法正确的有哪些？',
 '[{"key":"A","text":"变换式为 x = r cos θ，y = r sin θ，z = z"},{"key":"B","text":"体积元素为 r dr dθ dz"},{"key":"C","text":"雅可比行列式的绝对值为 r"},{"key":"D","text":"体积元素为 dr dθ dz"}]',
 'ABC','柱坐标是极坐标加上 z 不变，雅可比绝对值仍为 r，故体积元素为 r dr dθ dz。选项 D 漏掉了雅可比因子 r，是最典型的换元错误。',8),
(103,'single','等比级数（几何级数）∑a·r^n 收敛的条件及其和分别是？',
 '[{"key":"A","text":"|r| 小于 1，和为 a/(1 - r)"},{"key":"B","text":"|r| 小于 1，和为 a/(1 + r)"},{"key":"C","text":"r 小于 1，和为 a/(1 - r)"},{"key":"D","text":"任意 r 都收敛，和为 a/(1 - r)"}]',
 'A','部分和 S(n) = a(1 - r^n)/(1 - r)，只有当 |r| 小于 1 时 r^n 趋于 0，极限为 a/(1-r)。必须取绝对值：r = -2 时 r^n 振荡无极限，级数发散。',5),
(103,'single','级数 ∑（n 从 1 到 ∞）1/n² 的敛散性是？',
 '[{"key":"A","text":"收敛"},{"key":"B","text":"发散"},{"key":"C","text":"无法确定"},{"key":"D","text":"收敛到 1"}]',
 'A','这是 p 级数在 p = 2 大于 1 的情形，由 p 级数判别法知收敛（其和实际上为 π²/6）。它与调和级数 ∑1/n（p = 1 发散）只有指数之差，结论却完全相反。',5),
(103,'single','调和级数 ∑（n 从 1 到 ∞）1/n 的敛散性是？',
 '[{"key":"A","text":"发散"},{"key":"B","text":"收敛到 1"},{"key":"C","text":"收敛到 e"},{"key":"D","text":"条件收敛"}]',
 'A','可以用积分判别法或柯西凝聚判别法证明它发散：虽然通项 1/n 趋于 0，但部分和增长如 ln n 无上界。这提醒我们通项趋于 0 只是收敛的必要而非充分条件。',5),
(103,'single','级数 ∑（n 从 1 到 ∞）(1/2)^n 的和为？',
 '[{"key":"A","text":"1"},{"key":"B","text":"2"},{"key":"C","text":"1/2"},{"key":"D","text":"发散"}]',
 'A','首项 a = 1/2、公比 r = 1/2 的等比级数，和为 (1/2)/(1 - 1/2) = 1。注意若从 n = 0 开始求和则结果为 2，求和的起始下标会改变答案。',5),
(103,'single','交错级数 ∑（n 从 1 到 ∞）(-1) 的 (n-1) 次方 / n 的敛散性及和为？',
 '[{"key":"A","text":"收敛，和为 ln 2"},{"key":"B","text":"发散"},{"key":"C","text":"绝对收敛，和为 1"},{"key":"D","text":"收敛，和为 π/4"}]',
 'A','通项 1/n 单调递减趋于 0，由莱布尼茨判别法知收敛；其绝对值级数即调和级数发散，故为条件收敛。和由 ln(1+x) 的展开在 x = 1 处取值得 ln 2。',5),
(103,'single','用比值判别法判断级数 ∑1/n! 的敛散性，其结论是？',
 '[{"key":"A","text":"收敛，因为相邻项之比趋于 0"},{"key":"B","text":"发散，因为通项趋于 0"},{"key":"C","text":"收敛，因为比值为 1/2"},{"key":"D","text":"无法判断"}]',
 'A','a(n+1)/a(n) = n!/(n+1)! = 1/(n+1) 趋于 0，小于 1，故级数收敛（其和为 e - 1）。比值判别法中极限 ρ 小于 1 收敛、大于 1 发散、等于 1 失效。',5),
(103,'single','p 级数 ∑1/n^p 收敛的充要条件是？',
 '[{"key":"A","text":"p 大于 1"},{"key":"B","text":"p 大于等于 1"},{"key":"C","text":"p 大于 0"},{"key":"D","text":"p 小于 1"}]',
 'A','由积分判别法，∫₁^∞ x^(-p) dx 在 p 大于 1 时收敛、p 小于等于 1 时发散，故 p 级数收敛当且仅当 p 大于 1。p = 1 的调和级数是临界情形且发散。',5),
(103,'single','级数 ∑a(n) 收敛的必要条件是？',
 '[{"key":"A","text":"通项 a(n) 趋于 0"},{"key":"B","text":"通项 a(n) 单调递减"},{"key":"C","text":"∑|a(n)| 收敛"},{"key":"D","text":"部分和有界且单调"}]',
 'A','若级数收敛到 S，则 a(n) = S(n) - S(n-1) 趋于 S - S = 0，故通项趋于 0 是必要条件。但它不充分，调和级数就是反例；常用它的逆否命题判别发散：通项不趋于 0 则级数必发散。',5),
(103,'single','由展开式 e^x = ∑（n 从 0 到 ∞）x^n/n! 取 x = 1，可得级数 ∑1/n! 的和为？',
 '[{"key":"A","text":"e"},{"key":"B","text":"e - 1"},{"key":"C","text":"e + 1"},{"key":"D","text":"1"}]',
 'A','取 x = 1 得 ∑（n 从 0 到 ∞）1/n! = e，其中第 0 项为 1，故若从 n = 1 开始求和则为 e - 1。注意题目问的是从 n = 0 起的完整级数，和为 e。',5),
(103,'single','幂级数 ∑（n 从 0 到 ∞）x^n 的收敛半径与收敛区间分别是？',
 '[{"key":"A","text":"R = 1，收敛区间 (-1, 1)"},{"key":"B","text":"R = 1，收敛区间 [-1, 1]"},{"key":"C","text":"R = ∞，收敛区间为全体实数"},{"key":"D","text":"R = 0，只在 x = 0 收敛"}]',
 'A','这是公比为 x 的等比级数，|x| 小于 1 时收敛；在 x = 1 处为 ∑1 发散，在 x = -1 处为 ∑(-1)^n 通项不趋于 0 也发散，故收敛区间为开区间 (-1, 1)。',5),
(103,'judge','若级数 ∑a(n) 收敛，则其通项必趋于 0。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。这是收敛的必要条件，其逆否命题「通项不趋于 0 则级数发散」是判别发散最常用的工具。但反过来不成立，通项趋于 0 并不能保证收敛。',5),
(103,'judge','若通项 a(n) 趋于 0，则级数 ∑a(n) 一定收敛。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。调和级数 ∑1/n 的通项趋于 0 但级数发散，这是最经典的反例。通项趋于 0 只是必要条件，还需要额外的判别法才能判定收敛。',5),
(103,'judge','绝对收敛的级数必定收敛，且其和不超过各项绝对值之和。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。绝对收敛蕴含收敛是级数理论的基本定理；由三角不等式还可得 |∑a(n)| 小于等于 ∑|a(n)|。绝对收敛的级数还能任意重排而不改变和。',5),
(103,'judge','条件收敛的级数可以任意重排其项，重排后级数的和保持不变。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。由黎曼重排定理，条件收敛级数经过适当重排可以收敛到任意指定的实数，甚至发散。只有绝对收敛的级数才享有「重排不改变和」的性质。',5),
(103,'multi','下列级数中收敛的有哪些？',
 '[{"key":"A","text":"∑ 1/n²"},{"key":"B","text":"∑ (1/2)^n"},{"key":"C","text":"∑ (-1)^n / n"},{"key":"D","text":"∑ 1/n"}]',
 'ABC','∑1/n² 是 p = 2 大于 1 的 p 级数，收敛；∑(1/2)^n 是公比 1/2 的等比级数，收敛；∑(-1)^n/n 满足莱布尼茨条件，收敛（条件收敛）；∑1/n 是调和级数，发散。',8),
(103,'multi','关于幂级数 ∑a(n)·x^n 的收敛半径 R，下列说法正确的有哪些？',
 '[{"key":"A","text":"在 |x| 小于 R 内级数绝对收敛"},{"key":"B","text":"在 |x| 大于 R 处级数发散"},{"key":"C","text":"当极限存在时可用 R = lim|a(n)/a(n+1)| 求得"},{"key":"D","text":"在 x = R 与 x = -R 处必定收敛"}]',
 'ABC','收敛半径的定义保证 |x| 小于 R 绝对收敛、|x| 大于 R 发散，比值法可求 R。但在两个端点 x = ±R 处收敛性不确定，必须单独代入判断，例如 ∑x^n 在 x = ±1 处都发散，故 D 错。',8),
(103,'multi','关于绝对收敛与条件收敛，下列说法正确的有哪些？',
 '[{"key":"A","text":"绝对收敛的级数可以任意重排且和不变"},{"key":"B","text":"∑(-1)^n/n² 是绝对收敛的"},{"key":"C","text":"∑(-1)^n/n 是条件收敛的"},{"key":"D","text":"若 ∑|a(n)| 发散，则 ∑a(n) 必定发散"}]',
 'ABC','∑|(-1)^n/n²| = ∑1/n² 收敛，故绝对收敛；∑|(-1)^n/n| = ∑1/n 发散而原级数收敛，故条件收敛。选项 D 错误：绝对值级数发散时原级数仍可能条件收敛，例如这里的交错调和级数。',8);

-- ---------- rest-phys.js ----------
INSERT INTO question (knowledge_id, type, title, options, answer, analysis, score) VALUES
(29,'single','以初速度 v0、与水平方向成 θ 角斜抛物体（不计空气阻力，落回同一水平面），其飞行总时间为？',
 '[{"key":"A","text":"2 v0 sinθ 除以 g"},{"key":"B","text":"v0 sinθ 除以 g"},{"key":"C","text":"2 v0 cosθ 除以 g"},{"key":"D","text":"2 v0 除以 g"}]',
 'A','竖直方向做竖直上抛运动，上升时间为 v0 sinθ / g，下落对称地再花同样时间，故总时间 T = 2 v0 sinθ / g。选项 B 只是上升到最高点的时间；把 sinθ 写成 cosθ 是混淆了竖直与水平分量。',5),
(29,'single','在初速度大小一定的情况下，斜抛物体获得最大水平射程的抛射角为？',
 '[{"key":"A","text":"45 度"},{"key":"B","text":"30 度"},{"key":"C","text":"60 度"},{"key":"D","text":"90 度"}]',
 'A','射程 R = v0² sin2θ / g，当 sin2θ = 1 即 2θ = 90°、θ = 45° 时取最大值。另外互余的两个角（如 30° 与 60°）射程相同，只是飞行时间与最大高度不同。',5),
(29,'single','从高 h 处水平抛出的物体（不计空气阻力），其水平位移大小取决于？',
 '[{"key":"A","text":"抛出高度 h 与水平初速度 v0"},{"key":"B","text":"只取决于水平初速度"},{"key":"C","text":"只取决于抛出高度"},{"key":"D","text":"物体的质量"}]',
 'A','落地时间 t = 根号下 (2h/g) 由高度决定，水平位移 x = v0 t = v0 根号下 (2h/g)，故两者共同决定。质量在全程被约掉，这正是伽利略"轻重物体同时落地"的结论。',5),
(29,'single','从高 20 m 处以 10 m/s 水平抛出一物体，取 g = 10 m/s²，则它落地时竖直方向的分速度大小为？',
 '[{"key":"A","text":"20 m/s"},{"key":"B","text":"10 m/s"},{"key":"C","text":"28 m/s"},{"key":"D","text":"14 m/s"}]',
 'A','竖直方向做自由落体：vy = 根号下 (2gh) = 根号下 (2×10×20) = 20 m/s。注意竖直分速度与水平初速度无关，10 m/s 是水平分量，别把两者相加当合速度。',5),
(29,'single','接上题（高 20 m、水平初速 10 m/s、g = 10 m/s²），物体落地时的合速度大小约为？',
 '[{"key":"A","text":"22.4 m/s"},{"key":"B","text":"20 m/s"},{"key":"C","text":"30 m/s"},{"key":"D","text":"10 m/s"}]',
 'A','两分量垂直，合速度 v = 根号下 (vx² + vy²) = 根号下 (100 + 400) = 根号 500 ≈ 22.4 m/s。抛体速度必须用矢量合成，直接把 10 与 20 相加得到 30 是错误的。',5),
(29,'single','斜抛物体运动到轨迹最高点的瞬间，其速度与加速度的情况是？',
 '[{"key":"A","text":"速度水平、大小为 v0 cosθ，加速度仍为 g 竖直向下"},{"key":"B","text":"速度为零，加速度也为零"},{"key":"C","text":"速度为零，加速度为 g"},{"key":"D","text":"速度水平，加速度为零"}]',
 'A','最高点只是竖直分速度减为 0，水平分速度 v0 cosθ 依然存在，故速度不为零；全程只受重力，加速度恒为 g 向下。若最高点加速度为零，物体就会沿水平方向匀速飞出去而不再落下。',5),
(29,'single','不计空气阻力时，抛体在整个飞行过程中始终保持不变的物理量是？',
 '[{"key":"A","text":"水平方向的速度分量"},{"key":"B","text":"速度的大小"},{"key":"C","text":"竖直方向的速度分量"},{"key":"D","text":"动量"}]',
 'A','水平方向不受力，故 vx 恒定；速度大小因竖直分量变化而改变，竖直分量本身也在变。动量同样不守恒——重力持续施加冲量，只有水平方向的动量分量守恒。',5),
(29,'single','从同一高度、以相同速率分别竖直上抛、竖直下抛和水平抛出三个小球（不计空气阻力），它们落地时的速率大小关系为？',
 '[{"key":"A","text":"三者相等"},{"key":"B","text":"竖直上抛的最大"},{"key":"C","text":"竖直下抛的最大"},{"key":"D","text":"水平抛出最小"}]',
 'A','由机械能守恒：初态动能相同、高度相同，落至同一水平面时重力势能减少量相同，故末动能相等、速率相同。三者的差别只在飞行时间与速度方向，不在速率大小。',5),
(29,'single','以相同速率分别按 30 度与 60 度角斜抛（落回同一水平面），两者的水平射程关系是？',
 '[{"key":"A","text":"相等"},{"key":"B","text":"30 度的射程更大"},{"key":"C","text":"60 度的射程更大"},{"key":"D","text":"取决于物体质量"}]',
 'A','射程 R = v0² sin2θ / g，而 sin60° = sin120°，故互余的两角射程相等。但 60° 抛出的飞行时间更长、最大高度更大，射程相同并不意味着轨迹相同。',5),
(29,'judge','平抛运动的水平位移与物体的质量有关，质量越大飞得越近。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。忽略空气阻力时水平位移 x = v0 根号下 (2h/g)，只由初速度、高度与 g 决定，质量在方程中被约掉。日常中重物"落得快"是有空气阻力的结果，不是重力作用的规律。',5),
(29,'judge','忽略空气阻力时，抛体在整个飞行过程中的加速度恒为重力加速度 g，方向竖直向下。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。抛出后物体只受重力，故加速度恒为 g 且与速度大小、方向无关，这正是抛体轨迹为抛物线的根本原因。若存在空气阻力，加速度还会包含与速度方向相反的阻力项，不再是常量。',5),
(29,'judge','研究抛体运动时，可把它分解为水平方向的匀速直线运动与竖直方向的匀变速直线运动来处理。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。运动的独立性原理允许把二维运动按正交方向分解：水平方向受力为零故匀速，竖直方向受恒定重力故匀变速，两者通过时间联系。这是处理一切抛体问题的基本方法。',5),
(29,'judge','斜抛时抛射角越大，物体的水平射程就一定越大。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。射程按 sin2θ 变化，从 0° 增大到 45° 时递增，超过 45° 后反而减小，90°（竖直上抛）时射程为 0。把"抛得高"与"抛得远"混为一谈是常见的直觉错误。',5),
(29,'multi','关于平抛运动（不计空气阻力），下列说法正确的有？',
 '[{"key":"A","text":"落地时间只由抛出高度决定，与水平初速度无关"},{"key":"B","text":"水平位移等于水平初速度乘以落地时间"},{"key":"C","text":"落地速度方向由水平与竖直分速度共同决定"},{"key":"D","text":"水平方向做匀加速直线运动"}]',
 'ABC','竖直方向自由落体给出 t = 根号下 (2h/g)，与 v0 无关；水平位移即 v0 t；落地速度方向由 tanα = vy/vx 决定。D 错：水平方向不受力，做的是匀速直线运动。',8),
(29,'multi','关于斜抛运动（不计空气阻力，落回同一水平面），下列说法正确的有？',
 '[{"key":"A","text":"运动轨迹是一条抛物线"},{"key":"B","text":"飞行时间由竖直分速度 v0 sinθ 决定"},{"key":"C","text":"水平射程为 v0² sin2θ 除以 g"},{"key":"D","text":"在最大高度处物体的速度为零"}]',
 'ABC','轨迹方程由 x = v0 cosθ·t、y = v0 sinθ·t − (1/2)gt² 消去 t 得到二次函数，故为抛物线；时间与射程分别由竖直分量与 sin2θ 决定。D 错：最高点仍有水平分速度 v0 cosθ，只有竖直分量为零。',8),
(30,'single','弹簧振子的周期为 T = 2π 根号下 (m/k)。若劲度系数 k 不变、振子质量变为原来的 4 倍，则周期变为？',
 '[{"key":"A","text":"2T"},{"key":"B","text":"4T"},{"key":"C","text":"T 的一半"},{"key":"D","text":"不变"}]',
 'A','周期与质量的平方根成正比，质量乘 4 则周期乘 根号 4 = 2。注意不是线性关系：质量增大使惯性变大，振动变慢，但只按平方根缩放。',5),
(30,'single','单摆在小角度摆动时的周期为 T = 2π 根号下 (L/g)。若摆长变为原来的 4 倍，则周期变为？',
 '[{"key":"A","text":"2T"},{"key":"B","text":"4T"},{"key":"C","text":"T 的一半"},{"key":"D","text":"16T"}]',
 'A','周期正比于摆长的平方根，摆长乘 4 则周期乘 2。摆长加倍只让周期变为约 1.414 倍，不少同学误以为成正比关系而错选 4T。',5),
(30,'single','某简谐振动的位移为 x = A cos(ωt + φ)，则其速度的最大值为？',
 '[{"key":"A","text":"ωA"},{"key":"B","text":"A"},{"key":"C","text":"ω²A"},{"key":"D","text":"ω 除以 A"}]',
 'A','速度 v = −Aω sin(ωt+φ)，最大值为 ωA，出现在振子过平衡位置时。ω²A 是加速度的最大值，两者相差一个 ω，量纲也不同，容易记混。',5),
(30,'single','某简谐振动的位移为 x = A cos(ωt + φ)，则其加速度的最大值为？',
 '[{"key":"A","text":"ω²A"},{"key":"B","text":"ωA"},{"key":"C","text":"A"},{"key":"D","text":"ωA 的一半"}]',
 'A','加速度 a = −ω²A cos(ωt+φ)，最大值 ω²A，出现在位移最大（振幅位置）处。它与位移大小成正比、方向相反，这是判断一个运动是否为简谐振动的判据。',5),
(30,'single','弹簧振子作简谐振动时，其总机械能 E 与振幅 A 的关系是？',
 '[{"key":"A","text":"与 A 的平方成正比"},{"key":"B","text":"与 A 成正比"},{"key":"C","text":"与 A 无关"},{"key":"D","text":"与 A 的三次方成正比"}]',
 'A','总能量 E = (1/2)kA²，正比于振幅平方。因此振幅加倍需要输入 4 倍能量；而周期与振幅无关，这两个"与振幅的关系"要区分清楚。',5),
(30,'single','某简谐振动的位移（SI 单位）为 x = 0.1 cos(10t)，则其振动周期约为？',
 '[{"key":"A","text":"0.628 s"},{"key":"B","text":"10 s"},{"key":"C","text":"0.1 s"},{"key":"D","text":"6.28 s"}]',
 'A','由表达式读出角频率 ω = 10 rad/s，周期 T = 2π/ω = 6.283/10 ≈ 0.628 s。10 是角频率而非周期，0.1 是振幅，把 ω 直接当成周期是读数时的典型错误。',5),
(30,'single','简谐振动中加速度 a 与位移 x 的关系可概括为？',
 '[{"key":"A","text":"a = −ω²x，大小成正比、方向始终相反"},{"key":"B","text":"a = ω²x，方向相同"},{"key":"C","text":"a 与 x 无关，是常量"},{"key":"D","text":"a 与速度成正比"}]',
 'A','回复力 F = −kx 给出 a = −(k/m)x = −ω²x，负号表示加速度始终指向平衡位置。这一"正比反向"关系是简谐振动的定义性特征，也是判断某系统能否作简谐振动的依据。',5),
(30,'single','弹簧振子通过平衡位置的瞬间，其速度与加速度的情况是？',
 '[{"key":"A","text":"速度最大，加速度为零"},{"key":"B","text":"速度为零，加速度最大"},{"key":"C","text":"速度与加速度都最大"},{"key":"D","text":"速度与加速度都为零"}]',
 'A','平衡位置处 x = 0，回复力为零故加速度为零，而势能全部转化为动能，速度达到最大 ωA。两端（振幅位置）恰好相反：速度为零、加速度最大。',5),
(30,'single','在小角度摆动时，单摆的周期与下列哪个因素无关？',
 '[{"key":"A","text":"摆球的质量"},{"key":"B","text":"摆长 L"},{"key":"C","text":"当地重力加速度 g"},{"key":"D","text":"摆长与重力加速度的比值"}]',
 'A','T = 2π 根号下 (L/g) 只含摆长与重力加速度，与摆球质量、振幅（小角度下）无关，这就是单摆可用于测重力加速度的原因。质量只影响能量大小，不影响快慢。',5),
(30,'judge','简谐振动的周期与振幅无关，振幅增大时周期保持不变。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。对弹簧振子 T = 2π 根号下 (m/k)、单摆小角度下 T = 2π 根号下 (L/g)，都不含振幅。这称为等时性；但要注意单摆在大摆角时周期会随摆角增大而变大，等时性只是小角近似。',5),
(30,'judge','简谐振动中加速度的方向总是与位移的方向相同。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。加速度 a = −ω²x，负号说明它始终与位移反向、指向平衡位置，这正是"回复"二字的含义。若二者同向，偏离会越来越大，振动根本无法维持。',5),
(30,'judge','单摆的周期严格不随摆角变化，无论摆角多大都成立。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。T = 2π 根号下 (L/g) 来自 sinθ ≈ θ 的小角近似，通常要求摆角小于 5°；摆角增大时实际周期会变大（如 30° 时约增大 2%）。把近似结论当成严格规律是常见误区。',5),
(30,'judge','无阻尼的简谐振动中，动能与势能之和保持不变。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。回复力是保守力，机械能 E = (1/2)kA² 恒定，振动过程中动能与势能此消彼长地相互转化：平衡位置动能最大，振幅位置势能最大。有阻尼时能量才逐步耗散、振幅衰减。',5),
(30,'multi','对于简谐振动表达式 x = A cos(ωt + φ)，下列说法正确的有？',
 '[{"key":"A","text":"A 是振幅，表示最大位移"},{"key":"B","text":"ω 是角频率，满足 ω = 2π 除以 T"},{"key":"C","text":"φ 是初相位，由初始时刻的位置与速度决定"},{"key":"D","text":"振动频率与振幅成正比"}]',
 'ABC','三个参数分别决定"幅度""快慢""起点"，其中初相位由 t=0 时的 x 与 v 共同确定（仅知位置还差一个符号）。D 错：频率由系统本身（k、m 或 L、g）决定，与振幅无关，这正是等时性。',8),
(30,'multi','弹簧振子在无阻尼振动过程中，下列说法正确的有？',
 '[{"key":"A","text":"在最大位移处速度为零、加速度最大"},{"key":"B","text":"在平衡位置动能最大"},{"key":"C","text":"机械能守恒"},{"key":"D","text":"周期随振幅增大而增大"}]',
 'ABC','最大位移处弹性势能最大、速度为零而加速度 ω²A 最大；平衡位置势能（以平衡位置为零点）为零、动能最大。D 错：周期与振幅无关，振幅大小只影响能量与速度最大值。',8),
(62,'single','质量为 m 的物体沿倾角为 θ 的光滑斜面由静止下滑，其加速度大小为？',
 '[{"key":"A","text":"g sinθ"},{"key":"B","text":"g cosθ"},{"key":"C","text":"g tanθ"},{"key":"D","text":"g"}]',
 'A','沿斜面方向只有重力的分量 mg sinθ 起作用，由牛顿第二定律 ma = mg sinθ 得 a = g sinθ，与质量无关。g cosθ 是垂直斜面方向被支持力平衡掉的分量，它决定的是支持力大小。',5),
(62,'single','质量为 m 的物体静止在倾角为 θ 的光滑斜面上被释放后下滑，斜面对它的支持力大小为？',
 '[{"key":"A","text":"mg cosθ"},{"key":"B","text":"mg"},{"key":"C","text":"mg sinθ"},{"key":"D","text":"mg tanθ"}]',
 'A','垂直斜面方向没有加速度，故支持力与重力垂直斜面的分量平衡：N = mg cosθ。只有在水平面上（θ=0）才有 N = mg；θ 越大支持力越小，到 90° 时为零。',5),
(62,'single','物体恰能沿倾角为 θ 的斜面匀速下滑，则动摩擦因数 μ 与 θ 的关系为？',
 '[{"key":"A","text":"μ = tanθ"},{"key":"B","text":"μ = sinθ"},{"key":"C","text":"μ = cosθ"},{"key":"D","text":"μ = 1 除以 tanθ"}]',
 'A','匀速说明沿斜面方向合力为零：mg sinθ = μmg cosθ，解得 μ = tanθ。这也是用"逐渐抬高斜面直到物体刚开始滑动"来测静摩擦因数的实验原理。',5),
(62,'single','物体静止在倾角为 θ 的粗糙斜面上恰好不下滑时，静摩擦因数 μs 应满足？',
 '[{"key":"A","text":"tanθ 小于等于 μs"},{"key":"B","text":"tanθ 大于等于 μs"},{"key":"C","text":"sinθ 大于等于 μs"},{"key":"D","text":"cosθ 小于等于 μs"}]',
 'A','需要的静摩擦力为 mg sinθ，它能提供的最大值为 μs mg cosθ，故不滑条件为 mg sinθ 小于等于 μs mg cosθ，即 tanθ 小于等于 μs。注意静摩擦因数与 tanθ 比较，而不是与 sinθ 比较。',5),
(62,'single','质量为 2 kg 的物体沿倾角 30 度的光滑斜面下滑，取 g = 10 m/s²，其加速度大小为？',
 '[{"key":"A","text":"5 m/s²"},{"key":"B","text":"10 m/s²"},{"key":"C","text":"8.66 m/s²"},{"key":"D","text":"2 m/s²"}]',
 'A','a = g sin30° = 10 × 0.5 = 5 m/s²。8.66 是 g cos30°，那是垂直斜面方向的分量对应的量；质量 2 kg 在计算中被约掉，与结果无关。',5),
(62,'single','用平行于斜面的力 F 把质量为 m 的物体沿倾角 θ 的光滑斜面匀速向上推动，则 F 的大小为？',
 '[{"key":"A","text":"mg sinθ"},{"key":"B","text":"mg cosθ"},{"key":"C","text":"μmg cosθ"},{"key":"D","text":"mg sinθ 加 mg cosθ"}]',
 'A','匀速说明沿斜面合力为零，只需克服重力沿斜面向下的分量 mg sinθ，故 F = mg sinθ。垂直斜面的分量由支持力平衡，不需要 F 去抵消，加了它就是多算。',5),
(62,'single','在粗糙水平面上用水平力 F 推动质量为 m 的物体，动摩擦因数为 μ，则物体的加速度为？',
 '[{"key":"A","text":"(F − μmg) 除以 m"},{"key":"B","text":"F 除以 m"},{"key":"C","text":"μmg 除以 m"},{"key":"D","text":"(F + μmg) 除以 m"}]',
 'A','水平方向合力为 F − μmg，由牛顿第二定律得 a = (F − μmg)/m。注意摩擦力方向与运动方向相反（取负号）；若 F 小于 μmg 则物体不会动，此时静摩擦力等于 F。',5),
(62,'single','关于牛顿第二定律 F = ma 中的方向关系，下列说法正确的是？',
 '[{"key":"A","text":"加速度方向始终与合外力方向相同"},{"key":"B","text":"加速度方向始终与速度方向相同"},{"key":"C","text":"加速度方向与合外力方向相反"},{"key":"D","text":"加速度方向总是指向地面"}]',
 'A','a = F合/m，质量是正标量，故加速度与合外力同向。速度方向才决定运动的走向（如减速上升时加速度向下而速度向上），把加速度与速度方向混同是最常见的错误。',5),
(62,'single','质量为 60 kg 的人站在电梯中，电梯以 2 m/s² 加速上升，取 g = 10 m/s²，则人对地板的压力（视重）为？',
 '[{"key":"A","text":"720 N"},{"key":"B","text":"600 N"},{"key":"C","text":"480 N"},{"key":"D","text":"120 N"}]',
 'A','由 N − mg = ma 得 N = m(g+a) = 60×12 = 720 N，大于重力，这就是超重。480 N 对应电梯加速下降（失重）的情形，600 N 是静止或匀速时的读数。',5),
(62,'single','牛顿第三定律中的作用力与反作用力，与一对平衡力的关键区别在于？',
 '[{"key":"A","text":"作用力与反作用力分别作用在两个不同物体上，不能相互抵消"},{"key":"B","text":"作用力与反作用力大小不相等"},{"key":"C","text":"作用力与反作用力方向相同"},{"key":"D","text":"作用力与反作用力必须是同种性质的接触力"}]',
 'A','作用力与反作用力等大、反向、共线，但分别作用于两个物体，因此永远不能合成、不能抵消；平衡力则作用在同一物体上。它们大小必相等、方向必相反，故 B、C 都错。',5),
(62,'judge','物体沿光滑斜面下滑时，斜面对物体的支持力大小等于物体所受重力 mg。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。垂直斜面方向平衡给出 N = mg cosθ，只有当 θ = 0（水平面）时才等于 mg。倾角越大支持力越小，这也是斜面上摩擦力随倾角变化的原因。',5),
(62,'judge','静摩擦力的大小总等于 μs 乘以正压力 N。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。μs N 只是静摩擦力的最大值；实际静摩擦力由平衡条件决定，可在 0 到 μs N 之间取任意值。例如水平面上未推动的箱子，静摩擦力等于推力而非 μs N。',5),
(62,'judge','物体滑动的速度越大，它受到的滑动摩擦力就越大。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。滑动摩擦力 f = μN 只与动摩擦因数和正压力有关，在常见速度范围内与相对速度大小基本无关。日常感觉"越快越费力"主要来自空气阻力，它才与速度有关。',5),
(62,'judge','牛顿第一定律说明物体只有持续受力才能保持运动状态。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。第一定律（惯性定律）恰恰相反：不受外力时物体保持静止或匀速直线运动，力是改变运动状态的原因而非维持运动的原因。这一观点纠正了亚里士多德的直觉。',5),
(62,'multi','关于斜面上物体的受力分析，下列说法正确的有？',
 '[{"key":"A","text":"重力可分解为沿斜面方向与垂直斜面方向的两个分量"},{"key":"B","text":"沿斜面方向的分量大小为 mg sinθ"},{"key":"C","text":"垂直斜面方向的分量大小为 mg cosθ"},{"key":"D","text":"物体除重力、支持力、摩擦力外还受到一个独立的\\"下滑力\\""}]',
 'ABC','分解只是处理重力的等效手段，两个分量大小分别为 mg sinθ 与 mg cosθ。D 错：所谓"下滑力"就是重力沿斜面的分力，把它当成额外的一个力会导致重复计入。',8),
(62,'multi','关于摩擦力，下列说法正确的有？',
 '[{"key":"A","text":"静摩擦力的大小由平衡条件决定，可在零与最大值之间取值"},{"key":"B","text":"滑动摩擦力的方向总是与相对运动方向相反"},{"key":"C","text":"摩擦力一定是阻力，不可能成为动力"},{"key":"D","text":"最大静摩擦力一般略大于滑动摩擦力"}]',
 'ABD','静摩擦力是"按需提供"的被动力，滑动摩擦力阻碍相对滑动，且最大静摩擦力通常略大于滑动摩擦力（所以推动后较省力）。C 错：人走路、车辆加速时地面提供的摩擦力正是动力。',8),
(62,'multi','关于牛顿运动定律，下列说法正确的有？',
 '[{"key":"A","text":"第二定律 F = ma 中的 F 指物体所受的合外力"},{"key":"B","text":"第三定律中的作用力与反作用力大小相等、方向相反"},{"key":"C","text":"作用力与反作用力可以作用在同一物体上相互平衡"},{"key":"D","text":"牛顿定律只在惯性参考系中直接成立"}]',
 'ABD','第二定律的 F 必须是合力，第三定律强调等大反向且作用在不同物体上。C 错：既然作用在不同物体上就不可能平衡；D 对，在非惯性系中必须引入惯性力才能形式地使用这些定律。',8),
(63,'single','一个系统动量守恒的必要条件是？',
 '[{"key":"A","text":"系统所受的合外力为零"},{"key":"B","text":"系统不受任何外力作用"},{"key":"C","text":"系统内各物体质量相等"},{"key":"D","text":"碰撞必须是完全弹性的"}]',
 'A','由动量定理，系统总动量的变化率等于合外力，故合外力为零时动量守恒。外力可以存在，只要矢量和为零（B 过于苛刻）；弹性与否只影响动能，不影响动量守恒。',5),
(63,'single','完全弹性碰撞中，碰撞前后保持不变的物理量是？',
 '[{"key":"A","text":"动量与总动能都守恒"},{"key":"B","text":"只有动量守恒"},{"key":"C","text":"只有总动能守恒"},{"key":"D","text":"动量与动能都不守恒"}]',
 'A','完全弹性的定义就是无机械能损失：动量守恒（合外力冲量为零）且总动能守恒，由此可解出两球碰后速度。只有动量守恒是"非弹性碰撞"的特征。',5),
(63,'single','完全非弹性碰撞区别于其它碰撞的关键特征是？',
 '[{"key":"A","text":"碰后两物体具有相同速度，动能损失最大"},{"key":"B","text":"碰后两物体速度大小相等、方向相反"},{"key":"C","text":"动量不再守恒"},{"key":"D","text":"总动能增加"}]',
 'A','完全非弹性即"粘在一起"：碰后共速，动量仍守恒，但在动量守恒允许的所有结果中动能损失最大。动能只能减少或不变（除非有炸药等内能源），绝不会增加。',5),
(63,'single','质量相同的小球 A 以速度 v 正碰静止的小球 B，若为一维完全弹性对心碰撞，碰后结果是？',
 '[{"key":"A","text":"A 静止，B 以速度 v 沿原方向运动"},{"key":"B","text":"两球都以 v/2 运动"},{"key":"C","text":"A 以 v 反弹，B 静止"},{"key":"D","text":"两球都静止"}]',
 'A','等质量弹性对心碰撞会"交换速度"：A 停下、B 获得速度 v，动量与动能同时守恒。若两球等质量但非弹性，则不会出现这种完全交接；B 是等质量完全非弹性的结果（共速 v/2）。',5),
(63,'single','质量为 2 kg 的物体以 3 m/s 追上前方质量为 3 kg、速度为 1 m/s 的同向物体，若发生完全非弹性碰撞，碰后共同速度为？',
 '[{"key":"A","text":"1.8 m/s"},{"key":"B","text":"2 m/s"},{"key":"C","text":"2.4 m/s"},{"key":"D","text":"1.2 m/s"}]',
 'A','动量守恒：(2×3 + 3×1) / (2+3) = 9/5 = 1.8 m/s，方向沿原运动方向。2 m/s 是两者速度的算术平均，只有在质量相等时才等于动量守恒的结果。',5),
(63,'single','接上题（2 kg 以 3 m/s 追撞 3 kg 以 1 m/s 运动，完全非弹性碰撞），碰撞过程中损失的动能为？',
 '[{"key":"A","text":"2.4 J"},{"key":"B","text":"10.5 J"},{"key":"C","text":"8.1 J"},{"key":"D","text":"1.5 J"}]',
 'A','碰前动能 (1/2)×2×9 + (1/2)×3×1 = 10.5 J，碰后 (1/2)×5×1.8² = 8.1 J，损失 2.4 J（转化为内能）。也可以直接用公式 (1/2)·(m1m2/(m1+m2))·(v1−v2)² 计算。',5),
(63,'single','恢复系数 e = 1 对应的碰撞类型是？',
 '[{"key":"A","text":"完全弹性碰撞"},{"key":"B","text":"完全非弹性碰撞"},{"key":"C","text":"非完全弹性碰撞"},{"key":"D","text":"任何碰撞都满足 e = 1"}]',
 'A','恢复系数 e = 分离速度 / 接近速度：e = 1 为完全弹性（动能守恒），e = 0 为完全非弹性（碰后共速），0 < e < 1 为实际的非完全弹性碰撞。',5),
(63,'single','动量定理指出，物体所受合外力的冲量等于？',
 '[{"key":"A","text":"物体动量的增量"},{"key":"B","text":"物体动能的增量"},{"key":"C","text":"物体的动量大小"},{"key":"D","text":"合外力的大小"}]',
 'A','I = ∫F dt = Δp，是矢量关系：冲量方向与动量变化方向一致。动能的增量对应的是"功"而非冲量，把 Ft 与 Fs 混用是常见错误。',5),
(63,'single','质量为 m 的小球以速率 v 垂直撞墙后以相同速率反弹，其动量变化量的大小为？',
 '[{"key":"A","text":"2mv"},{"key":"B","text":"0"},{"key":"C","text":"mv"},{"key":"D","text":"mv²"}]',
 'A','取初速度方向为正，初动量 mv、末动量 −mv，变化量 Δp = −2mv，大小为 2mv。速率不变不代表动量不变——动量是矢量，反向就变了，漏掉负号会得到 0。',5),
(63,'single','质量为 60 kg 的人静止站在光滑冰面上，水平向前抛出质量为 2 kg 的物体，物体对地速度为 10 m/s，则人的反冲速度大小为？',
 '[{"key":"A","text":"约 0.33 m/s，方向与物体相反"},{"key":"B","text":"10 m/s，方向与物体相同"},{"key":"C","text":"约 0.33 m/s，方向与物体相同"},{"key":"D","text":"0，人保持静止"}]',
 'A','水平方向动量守恒：2×10 = 60×v，得 v ≈ 0.33 m/s，方向与抛出方向相反。冰面光滑意味着水平方向外力可忽略；人的质量大，所以反冲速度远小于物体速度。',5),
(63,'judge','碰撞过程中动量守恒要求系统完全不受任何外力作用。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。只需合外力为零，或在碰撞的极短时间内外力的冲量远小于内力冲量而可忽略。例如水平面上两球相撞，重力与支持力都存在但互相抵消，动量依然守恒。',5),
(63,'judge','完全非弹性碰撞中动量守恒，但机械能有损失。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。碰后两物体共速，动量守恒给出共同速度，而损失的动能转化为内能、形变或声能，这是各类碰撞中损失最大的一种。动量守恒只依赖合外力为零，与能量是否损失无关。',5),
(63,'judge','一维完全弹性对心碰撞中，若两球质量相等则必定交换速度。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。联立动量守恒 m v1 + m v2 = m u1 + m u2 与动能守恒，可得 u1 = v2、u2 = v1，即速度互换（其中一个静止时就是"甲停乙走"）。斜碰或非对心碰撞不适用此结论。',5),
(63,'judge','系统内物体之间的相互作用力（内力）可以改变各物体各自的动量，但不能改变系统的总动量。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。内力总是成对出现、等大反向，它们产生的冲量之和为零，只能让动量在系统内部转移，因此总动量不变——这正是动量守恒定律的本质，也是它与能量守恒在"内力可耗散机械能"上的区别。',5),
(63,'multi','关于动量守恒定律，下列说法正确的有？',
 '[{"key":"A","text":"成立条件是系统所受合外力为零"},{"key":"B","text":"碰撞、爆炸等极短时间内外力冲量可忽略时可近似使用"},{"key":"C","text":"动量是矢量，需按各坐标分量分别列方程"},{"key":"D","text":"动量守恒要求每个物体的速度大小都不变"}]',
 'ABC','动量守恒是矢量守恒，二维问题必须分 x、y 两个方向列式；爆炸、碰撞时间短，重力等外力的冲量可忽略。D 错：守恒的是总动量，各物体速度完全可以改变，只要矢量和不变。',8),
(63,'multi','关于冲量与动量定理，下列说法正确的有？',
 '[{"key":"A","text":"合外力的冲量等于物体动量的增量"},{"key":"B","text":"冲量是矢量，方向与合外力方向相同"},{"key":"C","text":"延长作用时间可以减小平均冲击力"},{"key":"D","text":"动量定理只适用于恒定不变的力"}]',
 'ABC','I = ∫F dt = Δp，恒力时简化为 Ft，变力则用积分或平均力处理，故 D 错。缓冲垫、安全气囊正是通过延长作用时间来降低平均冲击力，这是动量定理最典型的工程应用。',8),
(63,'multi','关于碰撞的分类与能量变化，下列说法正确的有？',
 '[{"key":"A","text":"完全弹性碰撞中总动能守恒"},{"key":"B","text":"完全非弹性碰撞后两物体速度相同"},{"key":"C","text":"非完全弹性碰撞动量守恒但动能有损失"},{"key":"D","text":"任何碰撞过程中动能都守恒"}]',
 'ABC','三类碰撞都满足动量守恒（合外力冲量为零），区别只在动能：弹性不变、完全非弹性损失最大、实际的非弹性居中。D 错：宏观碰撞几乎总有动能损失，动能守恒只是理想模型。',8),
(106,'single','刚体的转动惯量大小取决于下列哪些因素？',
 '[{"key":"A","text":"刚体的总质量、质量相对转轴的分布以及转轴的位置"},{"key":"B","text":"只取决于刚体的总质量"},{"key":"C","text":"只取决于转动的角速度"},{"key":"D","text":"只取决于刚体的几何形状"}]',
 'A','转动惯量 I = Σ mi ri²，质量越远离转轴贡献越大，因此同一刚体绕不同轴（如细杆绕中心与绕端点）的 I 不同，质量相同而分布不同（圆盘与圆环）I 也不同。它与角速度无关。',5),
(106,'single','刚体定轴转动的转动定律（类比牛顿第二定律）可写为？',
 '[{"key":"A","text":"合外力矩 M 等于转动惯量 I 乘以角加速度 α"},{"key":"B","text":"合外力等于 I 乘以 α"},{"key":"C","text":"M 等于 I 乘以角速度 ω"},{"key":"D","text":"M 等于 m 乘以 α"}]',
 'A','M = Iα 是转动的基本定律：力矩对应力、转动惯量对应质量、角加速度对应线加速度。注意与平动公式 F = ma 类比时各量必须"成套"替换，混用 I 与 m 会量纲出错。',5),
(106,'single','刚体绕固定轴以角速度 ω 转动，其对该轴的角动量大小为？',
 '[{"key":"A","text":"L = I ω"},{"key":"B","text":"L = I α"},{"key":"C","text":"L = m ω"},{"key":"D","text":"L = I 除以 ω"}]',
 'A','角动量 L = Iω，与平动动量 p = mv 对应；Iα 是力矩。角动量、力矩、角速度都是矢量（沿转轴方向，由右手定则确定方向），做加减时必须考虑方向。',5),
(106,'single','刚体（或质点系）的角动量守恒的条件是？',
 '[{"key":"A","text":"所受合外力矩为零"},{"key":"B","text":"所受合外力为零"},{"key":"C","text":"转动惯量保持不变"},{"key":"D","text":"角速度保持不变"}]',
 'A','由角动量定理 dL/dt = M外，合外力矩为零则 L 守恒。合外力为零只能保证动量守恒，两者互不等价：例如外力偶（合力为零但合力矩不为零）就能改变角动量。',5),
(106,'single','花样滑冰运动员在旋转中收拢双臂后转速明显加快，主要原因是？',
 '[{"key":"A","text":"转动惯量减小，角动量守恒使角速度增大"},{"key":"B","text":"受到冰面施加的加速力矩"},{"key":"C","text":"转动惯量增大导致角速度增大"},{"key":"D","text":"重力势能转化为转动动能"}]',
 'A','冰面摩擦力矩可忽略，L = Iω 守恒；收臂使质量分布靠近转轴、I 减小，故 ω 增大。注意此时转动动能 (1/2)Iω² 反而增大，增加的能量来自运动员肌肉做功。',5),
(106,'single','均匀细杆长为 L、质量为 m，若转轴通过其一端并与杆垂直，则该杆对此轴的转动惯量为？',
 '[{"key":"A","text":"mL² 除以 3"},{"key":"B","text":"mL² 除以 12"},{"key":"C","text":"mL² 除以 2"},{"key":"D","text":"mL²"}]',
 'A','绕质心（过中心垂直杆）为 mL²/12，由平行轴定理加 md²（d = L/2）得 mL²/12 + mL²/4 = mL²/3。可见转轴离质心越远转动惯量越大，绕端点比绕中心难转动 4 倍。',5),
(106,'single','转动惯量为 I 的刚体以角速度 ω 绕定轴转动，其转动动能为？',
 '[{"key":"A","text":"(1/2) I ω²"},{"key":"B","text":"I ω"},{"key":"C","text":"(1/2) I ω"},{"key":"D","text":"I ω²"}]',
 'A','与平动动能 (1/2)mv² 完全对应，(1/2)Iω² 是转动动能的标准形式。也可以由各质元 (1/2)mi vi² 与 vi = ri ω 求和得到，注意系数二分之一不能丢。',5),
(106,'single','用同样大小的力推门，作用在离转轴较远处比靠近转轴更省力，原因是？',
 '[{"key":"A","text":"力臂越大，力矩 M = F 乘力臂 越大"},{"key":"B","text":"力臂大时力的大小自动变大"},{"key":"C","text":"力臂大时摩擦力变小"},{"key":"D","text":"力臂大时门的重力变小"}]',
 'A','力矩 M = F r sinθ，力与半径垂直时 M = Fr，力臂 r 越大同样力产生的转动效应越强，因此门把手总装在远离合页的一侧。当力的作用线沿半径方向（θ=0）时力矩为零，推也白推。',5),
(106,'single','转动惯量为 2 kg·m² 的刚体受到 4 N·m 的恒定合外力矩作用，其角加速度为？',
 '[{"key":"A","text":"2 rad/s²"},{"key":"B","text":"8 rad/s²"},{"key":"C","text":"0.5 rad/s²"},{"key":"D","text":"4 rad/s²"}]',
 'A','由转动定律 α = M/I = 4/2 = 2 rad/s²。角加速度与力矩成正比、与转动惯量成反比，这与平动中 a = F/m 的形式完全一致，把 I 当成 m 直接相除就会得 0.5。',5),
(106,'single','平行轴定理的内容是：刚体对任一轴的转动惯量 I 等于？',
 '[{"key":"A","text":"过质心的平行轴的转动惯量 Ic 加上 m d²（d 为两轴间距）"},{"key":"B","text":"Ic 减去 m d²"},{"key":"C","text":"Ic 加上 m d"},{"key":"D","text":"仅与 Ic 相等"}]',
 'A','平行轴定理 I = Ic + md² 说明偏离质心越远转动惯量越大，且在所有平行轴中绕质心轴的最小。掌握它就能由细杆绕中心的结果推出绕端点的结果，不必重新积分。',5),
(106,'judge','刚体的转动惯量会随它转动角速度的增大而增大。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。转动惯量 I = Σ mi ri² 只由质量分布与转轴位置决定，与是否转动、转多快无关，它是刚体本身的几何—质量属性。转动快慢影响的是角动量 L = Iω 与转动动能，而不是 I。',5),
(106,'judge','若刚体所受的合外力矩为零，则它的角动量保持不变。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。这正是角动量守恒定律：dL/dt 等于合外力矩，力矩为零则 L 恒定。此时 I 与 ω 可以各自变化（如滑冰选手收臂），但乘积 Iω 不变，这是转动问题中最常用的守恒关系。',5),
(106,'judge','力矩的方向总是与产生它的力的方向相同。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。力矩是矢量 M = r 叉乘 F，其方向垂直于 r 与 F 所确定的平面，由右手定则判定，一般与力的方向垂直。只有大小 M = Fr sinθ 才与力的大小有关。',5),
(106,'judge','两个总质量相同的刚体，它们的转动惯量一定相同。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。转动惯量还取决于质量离转轴的远近：质量与半径都相同的均匀圆盘 I = (1/2)mR²，而薄圆环 I = mR²，后者是前者的两倍。把转动惯量等同于质量是常见错误。',5),
(106,'multi','关于转动惯量，下列说法正确的有？',
 '[{"key":"A","text":"它是刚体转动惯性大小的量度"},{"key":"B","text":"其值与转轴的位置有关"},{"key":"C","text":"其值与质量相对转轴的分布有关"},{"key":"D","text":"其值与刚体是否正在转动有关"}]',
 'ABC','转动惯量在转动中的地位正如质量在平动中的地位，由质量、分布与转轴三者共同决定，同一刚体换一根轴结果就不同。D 错：它是静态的几何—质量属性，与运动状态无关。',8),
(106,'multi','关于角动量守恒，下列说法正确的有？',
 '[{"key":"A","text":"守恒条件是系统所受合外力矩为零"},{"key":"B","text":"内力矩不改变系统的总角动量"},{"key":"C","text":"角动量守恒时，转动惯量增大则角速度减小"},{"key":"D","text":"角动量守恒时转动动能一定守恒"}]',
 'ABC','内力矩成对抵消，故总角动量只由外力矩改变；L = Iω 不变意味着 I 与 ω 此消彼长。D 错：Ek = L²/(2I)，I 变化时动能随之改变，滑冰选手收臂时动能就增加了。',8),
(106,'multi','关于刚体定轴转动的基本规律，下列说法正确的有？',
 '[{"key":"A","text":"转动定律 M = Iα 与牛顿第二定律 F = ma 形式相对应"},{"key":"B","text":"转动动能 Ek 等于 (1/2) I ω²"},{"key":"C","text":"力矩是改变刚体转动状态的原因"},{"key":"D","text":"匀速转动的刚体所受合外力矩一定不为零"}]',
 'ABC','转动定律、动能公式、力矩的作用分别对应平动中的 F=ma、动能公式与"力改变运动状态"。D 错：匀速转动时角加速度为零，由 M = Iα 知合外力矩必为零。',8),
(107,'single','一个 100 匝的线圈，穿过它的磁通量在 0.2 s 内由 0.02 Wb 均匀增加到 0.06 Wb，则线圈中的感应电动势大小为？',
 '[{"key":"A","text":"20 V"},{"key":"B","text":"0.2 V"},{"key":"C","text":"2 V"},{"key":"D","text":"200 V"}]',
 'A','由法拉第定律 ε = N·ΔΦ/Δt = 100 × (0.06−0.02)/0.2 = 100 × 0.2 = 20 V。常见错误是漏乘匝数 N 得到 0.2 V，或把变化量算成末值 0.06 而不用增量。',5),
(107,'single','楞次定律的核心内容是？',
 '[{"key":"A","text":"感应电流产生的磁场总是阻碍引起感应电流的磁通量变化"},{"key":"B","text":"感应电流的磁场总是与原磁场方向相同"},{"key":"C","text":"感应电流的大小与磁通量成正比"},{"key":"D","text":"感应电流总是沿顺时针方向"}]',
 'A','关键是"阻碍变化"而非"阻碍磁通量本身"：磁通增加时感应磁场反向抵消增加，磁通减少时感应磁场同向补偿减少。若表述为"与原磁场反向"就只在磁通增大时才碰巧正确。',5),
(107,'single','判断闭合回路中感应电流方向所依据的定律是？',
 '[{"key":"A","text":"楞次定律"},{"key":"B","text":"库仑定律"},{"key":"C","text":"欧姆定律"},{"key":"D","text":"焦耳定律"}]',
 'A','先用楞次定律判断感应磁场方向（阻碍磁通变化），再用安培定则（右手螺旋）确定电流方向；导体切割磁感线时也可直接用右手定则。库仑定律、欧姆定律、焦耳定律分别处理静电力、电流电压关系与热效应。',5),
(107,'single','长度为 L 的直导体以速度 v 在磁感应强度为 B 的匀强磁场中运动，且 B、v、导体三者互相垂直，则导体两端的动生电动势为？',
 '[{"key":"A","text":"BLv"},{"key":"B","text":"BLv 的一半"},{"key":"C","text":"B 除以 (Lv)"},{"key":"D","text":"B²Lv"}]',
 'A','动生电动势 ε = BLv（一般式为 BLv sinθ，θ 为 v 与 B 的夹角），方向由右手定则判断。若导体运动方向与磁感线平行则不切割磁感线，电动势为零。',5),
(107,'single','在 B = 0.5 T 的匀强磁场中，长 0.4 m 的导体棒以 5 m/s 的速度垂直切割磁感线运动，其两端产生的电动势为？',
 '[{"key":"A","text":"1.0 V"},{"key":"B","text":"10 V"},{"key":"C","text":"0.1 V"},{"key":"D","text":"2.0 V"}]',
 'A','ε = BLv = 0.5 × 0.4 × 5 = 1.0 V。三个量都是标准单位（T、m、m/s），直接相乘即可；若导体不垂直切割，还需乘上夹角的正弦。',5),
(107,'single','自感现象中，自感电动势对原电流的作用是？',
 '[{"key":"A","text":"阻碍原电流的变化：电流增大时反向，减小时同向"},{"key":"B","text":"总是与原电流方向相反"},{"key":"C","text":"总是与原电流方向相同"},{"key":"D","text":"与原电流的大小成正比"}]',
 'A','自感电动势 εL = −L·Δi/Δt，负号体现"阻碍变化"：通电时它反推使电流渐增，断电时它维持原方向形成电弧。D 错，它正比于电流的变化率而非电流本身。',5),
(107,'single','某正弦交流电压的表达式为 u = 311 sin(100πt) V，则其有效值约为？',
 '[{"key":"A","text":"220 V"},{"key":"B","text":"311 V"},{"key":"C","text":"380 V"},{"key":"D","text":"110 V"}]',
 'A','峰值 Um = 311 V，正弦量的有效值为 Um/根号 2 ≈ 311/1.414 ≈ 220 V，这正是市电 220 V 与峰值 311 V 的对应关系。380 V 是线电压，别混用。',5),
(107,'single','接上题，表达式 u = 311 sin(100πt) V 所示交流电的频率为？',
 '[{"key":"A","text":"50 Hz"},{"key":"B","text":"100 Hz"},{"key":"C","text":"60 Hz"},{"key":"D","text":"314 Hz"}]',
 'A','角频率 ω = 100π rad/s，而 ω = 2πf，故 f = 100π/(2π) = 50 Hz。100 是 ω/π 的值，314 是 ω 的数值近似，都不是频率。',5),
(107,'single','在纯电阻交流电路中，电压与电流的相位关系是？',
 '[{"key":"A","text":"同相位，二者同时达到最大值与零值"},{"key":"B","text":"电压超前电流 90 度"},{"key":"C","text":"电流超前电压 90 度"},{"key":"D","text":"相位差 180 度"}]',
 'A','电阻元件遵循瞬时欧姆定律 u = Ri，故电压电流同相，功率恒为正（一直耗能）。出现 90° 相位差是电抗元件（电感或电容）的特征，纯电阻电路不会滞后或超前。',5),
(107,'single','在纯电感交流电路中，电压与电流的相位关系是？',
 '[{"key":"A","text":"电压超前电流 90 度，即电流滞后电压"},{"key":"B","text":"电流超前电压 90 度"},{"key":"C","text":"二者同相"},{"key":"D","text":"相位差 180 度"}]',
 'A','电感电压 u = L·di/dt，正弦电流达到最大时其变化率为零，故电压提前四分之一周期到达峰值，即电压超前 90°。纯电容恰好相反，电流超前电压 90°，两者正好相差 180°。',5),
(107,'judge','只要闭合回路中存在磁通量，回路中就一定会产生感应电流。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。产生感应电流的条件是穿过闭合回路的磁通量发生变化（ΔΦ ≠ 0），恒定的强磁场中静止的回路毫无电流。法拉第定律中的 dΦ/dt 强调的正是"变化率"。',5),
(107,'judge','楞次定律本质上是能量守恒定律在电磁感应现象中的具体体现。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。若感应电流的方向是"促进"磁通变化而非阻碍，就会出现微小扰动自发放大、无中生有地产生能量的局面，违背能量守恒。因此阻碍变化是能量守恒的必然要求。',5),
(107,'judge','在纯电容交流电路中，电流的相位超前电压 90 度。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。电容电流 i = C·du/dt，电压变化最快（过零）时电流最大，故电流提前四分之一周期达峰，即超前 90°。它与纯电感（电压超前 90°）恰成互补，也是电容补偿感性负载的依据。',5),
(107,'judge','交流电的有效值等于它在一个周期内的平均值。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。有效值按热效应定义：让交流与直流在相同时间内对同一电阻产生相同热量，该直流值即为有效值；而正弦量一个周期内的平均值为零。二者是不同的概念，不能混用。',5),
(107,'multi','下列哪些情形能够在回路中产生感应电动势？',
 '[{"key":"A","text":"磁场不变、闭合线圈的面积发生变化"},{"key":"B","text":"线圈不动、磁感应强度随时间变化"},{"key":"C","text":"线圈平面在匀强磁场中转动，导致穿过的磁通量改变"},{"key":"D","text":"导体在匀强磁场中沿磁感线方向平动"}]',
 'ABC','三种情形的本质都是穿过回路的磁通量发生变化（对应面积变、B 变、夹角变）。D 错：沿磁感线方向运动不切割磁感线，磁通量不变，因此不产生电动势。',8),
(107,'multi','关于正弦交流电的有效值，下列说法正确的有？',
 '[{"key":"A","text":"有效值按电流的热效应等效来定义"},{"key":"B","text":"正弦量的有效值等于峰值的 1 除以根号 2 倍"},{"key":"C","text":"交流电气设备铭牌上标注的电压一般指有效值"},{"key":"D","text":"有效值等于半个周期内瞬时值的平均"}]',
 'ABC','有效值由"等效发热"定义，正弦量下为峰值的 0.707 倍，仪表读数与铭牌值也都是有效值。D 错：半周期平均值与有效值是两个不同量，对正弦量二者相差约 1.11 倍。',8),
(107,'multi','关于理想变压器，下列说法正确的有？',
 '[{"key":"A","text":"电压比等于匝数比，U1/U2 = n1/n2"},{"key":"B","text":"电流比与匝数比成反比，I1/I2 = n2/n1"},{"key":"C","text":"输入功率等于输出功率"},{"key":"D","text":"它可以改变交流电的频率"}]',
 'ABC','理想变压器无损耗、全耦合：电压按匝数比变换，电流与之成反比，功率守恒。D 错：变压器只改变电压与电流，频率由电源决定，原副边频率始终相同。',8);

-- ---------- rest-prob.js ----------
INSERT INTO question (knowledge_id, type, title, options, answer, analysis, score) VALUES
(27,'single','若随机变量 X 服从二项分布 B(10, 0.3)，则它的数学期望与方差依次是？',
 '[{"key":"A","text":"3 与 2.1"},{"key":"B","text":"3 与 0.21"},{"key":"C","text":"0.3 与 2.1"},{"key":"D","text":"10 与 3"}]',
 'A','二项分布 B(n,p) 的期望为 np = 10×0.3 = 3，方差为 np(1-p) = 10×0.3×0.7 = 2.1。常见错误是把方差记成 np² = 0.9 或把 p(1-p) 漏乘 n 得到 0.21。',5),
(27,'single','设每分钟到达服务台的人数 X 服从参数 λ = 2 的泊松分布，则一分钟内无人到达的概率为？',
 '[{"key":"A","text":"e 的 -2 次方，约 0.1353"},{"key":"B","text":"2 乘以 e 的 -2 次方，约 0.2707"},{"key":"C","text":"1 减去 e 的 -2 次方，约 0.8647"},{"key":"D","text":"0.5"}]',
 'A','泊松分布 P(X=k) = λ^k/k! × e 的 -λ 次方，代入 k=0、λ=2 得 P(X=0) = e 的 -2 次方 ≈ 0.1353。选项 B 是 P(X=1)，选项 C 是 P(X≥1)，别把"无人到达"和"有人到达"搞反。',5),
(27,'single','设 X 服从正态分布 N(1, 4)，则 P(X 小于等于 1) 等于？',
 '[{"key":"A","text":"0.5"},{"key":"B","text":"0.8413"},{"key":"C","text":"0.1587"},{"key":"D","text":"由 σ 决定，无法计算"}]',
 'A','正态密度曲线关于均值 μ=1 对称，故在 μ 左侧的概率恰为 0.5，与方差 4（σ=2）的大小无关。0.8413、0.1587 分别是标准正态在 1、-1 处的分布函数值，属于记混了标准化。',5),
(27,'single','设 X 在区间 (0, 10) 上服从均匀分布，则 P(2 < X < 5) 等于？',
 '[{"key":"A","text":"0.3"},{"key":"B","text":"0.5"},{"key":"C","text":"0.2"},{"key":"D","text":"0.7"}]',
 'A','均匀分布的概率等于"区间长度之比"：(5-2)/(10-0) = 0.3。注意连续型分布中端点取不取等号不影响结果，因为单点概率为 0，所以 P(2<X<5) 与 P(2≤X≤5) 相同。',5),
(27,'single','设 X 服从参数 λ 的指数分布，其无记忆性可写成下列哪一式？',
 '[{"key":"A","text":"P(X > s+t 且已知 X > s) = P(X > t)"},{"key":"B","text":"P(X > s+t) = P(X > s) + P(X > t)"},{"key":"C","text":"P(X < t) = P(X > t)"},{"key":"D","text":"P(X > t) = 1 除以 λ"}]',
 'A','指数分布满足 P(X>s+t | X>s) = P(X>t)，即"已经等了 s 这么久"不影响还要再等多久的分布，这正是它刻画寿命、等待时间的独特之处。B 把概率拆成相加是错的，D 是期望而非尾概率。',5),
(27,'single','当 n 很大、p 很小时，二项分布 B(n, p) 常用泊松分布近似，该泊松分布的参数取？',
 '[{"key":"A","text":"np"},{"key":"B","text":"p"},{"key":"C","text":"n"},{"key":"D","text":"np(1-p)"}]',
 'A','泊松近似要求 np 适中（通常 n≥20、p≤0.05），此时令 λ = np，用 P(λ) 近似 B(n,p)。np 是二项分布的期望，np(1-p) 是方差；只有当 p 不小（如 0.5）时才该用正态近似 N(np, np(1-p))。',5),
(27,'single','设随机变量 X 的分布函数为 F(x)，则 P(a < X 小于等于 b) 等于？',
 '[{"key":"A","text":"F(b) 减去 F(a)"},{"key":"B","text":"F(a) 减去 F(b)"},{"key":"C","text":"F(b)"},{"key":"D","text":"F(b) 加 F(a)"}]',
 'A','由 F(x) = P(X 小于等于 x) 得 P(a < X 小于等于 b) = F(b) - F(a)。对连续型变量，是否含端点 a 不影响结果；但对离散型变量，"a < X" 与 "a 小于等于 X" 会差一个 P(X=a)，不能随意换。',5),
(27,'single','已知离散型随机变量 X 取 0、1、2 的概率分别为 0.2、0.5、0.3，则 E(X 的平方) 等于？',
 '[{"key":"A","text":"1.7"},{"key":"B","text":"1.1"},{"key":"C","text":"0.49"},{"key":"D","text":"2.0"}]',
 'A','E(X²) = 0²×0.2 + 1²×0.5 + 2²×0.3 = 0.5 + 1.2 = 1.7。注意 1.1 是 E(X)，0.49 是方差 D(X) = E(X²) - [E(X)]² = 1.7 - 1.21，三者是不同概念，别直接把 E(X) 平方当作 E(X²)。',5),
(27,'single','设 X 服从标准正态分布，且已知 Φ(1.96) = 0.975，则 P(|X| < 1.96) 等于？',
 '[{"key":"A","text":"0.95"},{"key":"B","text":"0.975"},{"key":"C","text":"0.05"},{"key":"D","text":"0.025"}]',
 'A','P(|X|<1.96) = Φ(1.96) - Φ(-1.96) = 2Φ(1.96) - 1 = 2×0.975 - 1 = 0.95。这里用到了标准正态的对称性 Φ(-z) = 1 - Φ(z)；只取单侧 0.975 就漏掉了左尾。',5),
(27,'judge','连续型随机变量取任意一个事先指定的实数（例如 X 恰好等于 1.5）的概率恒为 0。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。连续型变量在单点上的概率等于密度函数在该点的一个"零宽度"积分，恒为 0，所以 P(X=1.5)=0。由此可得 P(X≤a)=P(X<a)。但概率为 0 不等于不可能发生，这是"几乎处处"的概念，不要与"空事件"混淆。',5),
(27,'judge','若 X 服从二项分布 B(n, p)，则其方差 D(X) 等于 n 乘以 p 的平方。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。正确公式是 D(X) = np(1-p)，只有期望才是 E(X) = np。把方差写成 np² 会低估离散程度，例如 n=10、p=0.3 时正确值为 2.1，而不是 0.9。',5),
(27,'judge','分布函数 F(x) 必定单调不减、右连续，且满足 x 趋于负无穷时极限为 0、趋于正无穷时极限为 1。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。这三条加上右连续性正是分布函数的充要特征，可用来判断一个函数能否作为某随机变量的分布函数。注意"单调不减"允许有平台段（对应无概率的区间）与跳跃点（离散型变量的取值点）。',5),
(27,'judge','对服从泊松分布的随机变量，其数学期望与方差一定相等。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。泊松分布只有一个参数 λ，且 E(X) = D(X) = λ，这也是实际中"样本均值≈样本方差"可作为数据是否来自泊松模型的粗略检验。二项分布则不满足：E=np 而 D=np(1-p)，只有当 p 极小时二者才近似相等。',5),
(27,'multi','关于正态分布 N(μ, σ²)，下列说法正确的有？',
 '[{"key":"A","text":"概率密度曲线关于直线 x = μ 对称"},{"key":"B","text":"μ 决定分布的中心位置，σ 决定曲线的陡缓"},{"key":"C","text":"P(X = μ) = 0.5"},{"key":"D","text":"在 μ 加减 3σ 范围内取值的概率约为 0.9973"}]',
 'ABD','正态曲线以 x=μ 为对称轴，μ 平移位置、σ 越大曲线越扁平，这就是"3σ 原则"下 P(|X-μ|<3σ)≈0.9973 的依据。C 错：正态是连续型分布，X 恰等于 μ 的概率为 0，0.5 是 P(X 小于等于 μ)。',8),
(27,'multi','设 X 服从参数为 λ 的指数分布，下列说法正确的有？',
 '[{"key":"A","text":"E(X) = 1 除以 λ"},{"key":"B","text":"D(X) = 1 除以 λ 的平方"},{"key":"C","text":"P(X > 1 除以 λ) = e 的 -1 次方"},{"key":"D","text":"X 可以取负值"}]',
 'ABC','指数分布的密度为 λe 的 -λx 次方（x 大于等于 0），由此 E(X)=1/λ、D(X)=1/λ²，且尾概率 P(X>t)=e 的 -λt 次方，取 t=1/λ 即得 e 的 -1 次方 ≈ 0.368。D 错：它的取值范围是非负实数，负值部分密度为 0，这是它与正态分布的关键区别。',8),
(28,'single','设 X1 到 X100 独立同分布，方差为 4，记样本均值为 X 拔，则由中心极限定理，X 拔 近似服从的正态分布方差为？',
 '[{"key":"A","text":"0.04"},{"key":"B","text":"4"},{"key":"C","text":"0.4"},{"key":"D","text":"40"}]',
 'A','样本均值的方差为 σ²/n = 4/100 = 0.04（标准差即标准误为 0.2）。常见错误是把总体方差 σ²=4 直接当成 X 拔 的方差，忘了除以样本量；正是这个"除以 n"让均值比单个观测更集中。',5),
(28,'single','棣莫弗—拉普拉斯中心极限定理指出，当 n 很大时二项分布 B(n, p) 可近似为哪种正态分布？',
 '[{"key":"A","text":"N(np, np(1-p))"},{"key":"B","text":"N(p, p(1-p))"},{"key":"C","text":"N(n, np)"},{"key":"D","text":"N(np, np²)"}]',
 'A','二项分布可看作 n 个伯努利变量之和，故近似正态的均值为 np、方差为 np(1-p)。第二项是方差而非标准差，写区间时别忘了开方：X 大致落在 np 加减 z 倍根号下 np(1-p) 内。',5),
(28,'single','用中心极限定理估计：掷一枚均匀硬币 100 次，正面次数落在 40 到 60 之间的概率约为？（已知 Φ(2) = 0.9772）',
 '[{"key":"A","text":"0.954"},{"key":"B","text":"0.683"},{"key":"C","text":"0.997"},{"key":"D","text":"0.5"}]',
 'A','正面次数 X 近似服从 N(50, 25)，σ=5，故 40 与 60 分别对应 -2 和 +2 个标准差，概率≈2Φ(2)-1 = 2×0.9772-1 = 0.9544。0.683 是正负 1σ 的概率，0.997 是正负 3σ，别记混。',5),
(28,'single','林德伯格—列维中心极限定理要求随机变量序列满足什么条件？',
 '[{"key":"A","text":"独立同分布，且数学期望与方差都存在（方差非零有限）"},{"key":"B","text":"只需同分布，不必独立"},{"key":"C","text":"只需两两独立，方差可以无穷大"},{"key":"D","text":"必须本身服从正态分布"}]',
 'A','该定理的条件是独立同分布且方差有限非零，结论是标准化和依分布收敛到 N(0,1)。若方差不存在（如柯西分布）结论失效；若总体本就是正态，则无需"近似"——样本均值对任意 n 都精确正态。',5),
(28,'single','设 X1 到 X12 独立同分布于 (0,1) 上的均匀分布，S 为它们的和，则由中心极限定理 S 近似服从？',
 '[{"key":"A","text":"均值 6、方差 1 的正态分布"},{"key":"B","text":"均值 6、方差 12 的正态分布"},{"key":"C","text":"均值 0.5、方差 1 的正态分布"},{"key":"D","text":"均值 6、方差 1/12 的正态分布"}]',
 'A','单个均匀变量 E=0.5、D=1/12，故 S 的期望为 12×0.5=6，方差为 12×(1/12)=1。这正是"12 个均匀随机数之和减 6 近似标准正态"这一经典模拟技巧的来源，也说明 n=12 时近似已相当好用。',5),
(28,'single','下列表述中，属于中心极限定理（而不是大数定律）的结论是？',
 '[{"key":"A","text":"(X 拔 − μ) 除以 (σ 除以根号 n) 的分布趋于标准正态分布"},{"key":"B","text":"样本均值依概率收敛于总体均值 μ"},{"key":"C","text":"样本均值几乎必然收敛于 μ"},{"key":"D","text":"事件发生的频率依概率收敛于其概率"}]',
 'A','中心极限定理给出的是"分布形状"的极限：标准化后的样本均值近似 N(0,1)，可用于算概率；大数定律只给出收敛性（B、C、D），不提供分布信息，因而无法直接估计概率。',5),
(28,'single','设 X 服从 B(10000, 0.5)，用正态近似估计 P(X > 5100) 约为？（已知 Φ(2) = 0.9772）',
 '[{"key":"A","text":"0.0228"},{"key":"B","text":"0.0456"},{"key":"C","text":"0.9772"},{"key":"D","text":"0.1587"}]',
 'A','近似分布为 N(5000, 2500)，σ=50，(5100-5000)/50 = 2，故 P(X>5100) ≈ 1-Φ(2) = 0.0228。若求双侧 P(|X-5000|>100) 才是 0.0456，做题时先看清是单侧还是双侧。',5),
(28,'single','独立但不必同分布的随机变量序列也能用中心极限定理，其所需的关键条件是？',
 '[{"key":"A","text":"林德伯格条件：任一单个变量对总和的影响都可忽略"},{"key":"B","text":"辛钦条件：各变量期望相同"},{"key":"C","text":"切比雪夫条件：各变量两两不相关"},{"key":"D","text":"马尔可夫条件：方差之和除以 n 的平方趋于常数"}]',
 'A','林德伯格条件要求没有任何一个变量在方差贡献上"一家独大"，这正是列维—林德伯格定理的核心。辛钦条件对应大数定律（只要求期望存在），马尔可夫条件也是大数定律的判据，二者都不保证正态极限。',5),
(28,'single','用正态分布近似二项分布时，为使近似效果较好，通常要求满足？',
 '[{"key":"A","text":"np 大于等于 5 且 n(1-p) 大于等于 5"},{"key":"B","text":"n 大于等于 30 即可，与 p 无关"},{"key":"C","text":"p 恰等于 0.5"},{"key":"D","text":"np 大于等于 1"}]',
 'A','经验法则是 np 与 n(1-p) 都至少为 5，因为 p 太接近 0 或 1 时二项分布严重右偏或左偏，正态近似很差，此时应改用泊松近似。n≥30 的门槛对偏斜严重的情形并不够。',5),
(28,'judge','中心极限定理要求参与求和的随机变量本身必须服从正态分布。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。恰恰相反，中心极限定理的价值就在于总体可以是任意分布（均匀、指数、伯努利等），只要独立同分布且方差有限，和的标准化形式就趋于正态。若总体本就是正态，结论是精确的而非渐近的。',5),
(28,'judge','棣莫弗—拉普拉斯定理可看作林德伯格—列维定理在二项分布情形下的特例。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。二项变量可分解为 n 个独立同分布的伯努利变量之和，套用林德伯格—列维定理即得 (X-np)/根号下 np(1-p) 趋于 N(0,1)，这正是棣莫弗—拉普拉斯定理，历史上它也确实是最早被证明的中心极限定理。',5),
(28,'judge','中心极限定理表明，当 n 趋于无穷时样本均值 X 拔 自身的分布趋于 N(μ, σ²)，方差并不随 n 缩小。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。X 拔 的极限分布是 N(μ, σ²/n)，方差随 n 增大而缩小并趋于 0，因此 X 拔 会越来越集中在 μ 附近（这已是大数定律的直观）；趋于 N(μ, σ²) 的说法把样本均值与单个观测混为一谈。',5),
(28,'judge','中心极限定理给出的是近似分布，它并不能说明样本均值随 n 增大而趋于某个常数。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','这句话的前半对、后半错。中心极限定理确实给出渐近分布（可用于算概率），但"样本均值趋于常数 μ"本身也是成立的，它正是大数定律的内容，且可由中心极限定理的方差 σ²/n 趋于 0 看出来。二者并不矛盾：一个说"分布像正态"，一个说"散布越来越窄"。',5),
(28,'multi','关于中心极限定理的实际应用，下列说法正确的有？',
 '[{"key":"A","text":"可用于近似计算大量独立随机变量之和落在某区间的概率"},{"key":"B","text":"要求各随机变量相互独立且个体方差不太悬殊"},{"key":"C","text":"要求总体必须是正态分布"},{"key":"D","text":"样本量 n 越大，正态近似通常越精确"}]',
 'ABD','中心极限定理的用途正是把"和或均值的概率"转化为正态概率来算，前提是独立性且没有个别项方差异常大（林德伯格条件），n 越大误差越小。C 错：总体为正态时无需近似，定理的意义恰在于总体可以非正态。',8),
(28,'multi','设 X1 到 Xn 独立同分布，E(X) = μ，D(X) = σ²，则由中心极限定理可得？',
 '[{"key":"A","text":"和 ΣX 近似服从 N(nμ, nσ²)"},{"key":"B","text":"样本均值 X 拔 近似服从 N(μ, σ²/n)"},{"key":"C","text":"(X 拔 − μ) 除以 (σ/根号 n) 近似服从 N(0,1)"},{"key":"D","text":"样本均值精确服从 N(μ, σ²/n)"}]',
 'ABC','三条说法等价：和的均值方差分别为 nμ、nσ²，除以 n 后得到 X 拔 的 N(μ, σ²/n)，再标准化即 N(0,1)。D 错在"精确"——只有总体本身正态时才精确成立，一般情况下只是 n 很大时的近似。',8),
(60,'single','使用全概率公式时，对划分事件 B1 到 Bn 的基本要求是？',
 '[{"key":"A","text":"两两互斥且并集为全集，且每个 P(Bi) 大于 0"},{"key":"B","text":"只需两两独立"},{"key":"C","text":"只需并集为全集"},{"key":"D","text":"两两互斥即可，概率可以为 0"}]',
 'A','全概率公式要求 B1 到 Bn 构成完备事件组：互不相交、覆盖全部可能，并且每项概率为正（否则条件概率 P(A|Bi) 无定义）。仅有独立性或仅有覆盖性都不能保证 P(A) = ΣP(Bi)P(A|Bi)。',5),
(60,'single','甲、乙两厂分别供应某零件的 60% 与 40%，次品率依次为 0.01 与 0.03。随机抽取一件零件，它是次品的概率为？',
 '[{"key":"A","text":"0.018"},{"key":"B","text":"0.04"},{"key":"C","text":"0.02"},{"key":"D","text":"0.012"}]',
 'A','由全概率公式：0.6×0.01 + 0.4×0.03 = 0.006 + 0.012 = 0.018。这是"由因求果"：先按供货比例加权各厂次品率。直接把 0.01 与 0.03 求平均得到 0.02 就忽略了供货份额不同。',5),
(60,'single','甲、乙两厂分别供应某零件的 60% 与 40%，次品率依次为 0.01 与 0.03。若抽到的一件是次品，它来自甲厂的概率约为？',
 '[{"key":"A","text":"0.333"},{"key":"B","text":"0.6"},{"key":"C","text":"0.018"},{"key":"D","text":"0.01"}]',
 'A','贝叶斯公式：P(甲|次品) = 0.6×0.01 / 0.018 = 0.006/0.018 ≈ 0.333。虽然甲厂供货占六成，但它的次品率低，所以在"次品"这个条件下份额反而降到三分之一，这就是后验相对先验的修正。',5),
(60,'single','某病在人群中的患病率为 0.001，检测的灵敏度（患者呈阳性）为 0.99，假阳性率（健康人呈阳性）为 0.02。某人检测呈阳性，其真正患病的概率约为？',
 '[{"key":"A","text":"约 4.7%"},{"key":"B","text":"约 99%"},{"key":"C","text":"约 0.1%"},{"key":"D","text":"约 47%"}]',
 'A','P(病|阳) = 0.001×0.99 / (0.001×0.99 + 0.999×0.02) = 0.00099 / 0.02097 ≈ 0.047。这是著名的"基础比率忽视"陷阱：检测准确率高达 99% 并不等于阳性者患病概率 99%，因为海量健康人的少量假阳性数量远超真正的患者。',5),
(60,'single','在贝叶斯公式 P(Bi|A) = P(Bi)P(A|Bi) / P(A) 中，通常把 P(Bi) 称为什么？',
 '[{"key":"A","text":"先验概率，即看到证据 A 之前对 Bi 的估计"},{"key":"B","text":"后验概率"},{"key":"C","text":"似然度"},{"key":"D","text":"条件概率 P(A|Bi)"}]',
 'A','P(Bi) 是先验概率（拿到新证据前的判断），P(A|Bi) 是似然，二者乘积归一化后得到的 P(Bi|A) 才是后验概率。把先验当成后验是贝叶斯推断中最常见的概念混淆。',5),
(60,'single','三个外形相同的盒子：1 号装 2 白 1 黑，2 号装 1 白 2 黑，3 号装 3 白。先等可能选一个盒子，再从中摸出一球为白球，则该球来自 3 号盒的概率为？',
 '[{"key":"A","text":"1/2"},{"key":"B","text":"1/3"},{"key":"C","text":"2/3"},{"key":"D","text":"1/6"}]',
 'A','总的摸到白球概率为 (2/3 + 1/3 + 1)/3 = 2/3，3 号盒的贡献为 1/3×1 = 1/3，故后验概率为 (1/3)/(2/3) = 1/2。可见摸到白球这一证据把 3 号盒的概率从先验 1/3 抬高到 1/2。',5),
(60,'single','在用贝叶斯公式求后验概率 P(Bi|A) 时，分母 P(A) 通常如何处理？',
 '[{"key":"A","text":"用全概率公式展开为 Σ P(Bj)P(A|Bj)"},{"key":"B","text":"直接取 1"},{"key":"C","text":"取 P(Bi) 的值"},{"key":"D","text":"用 P(A|Bi) 代替"}]',
 'A','分母 P(A) 对所有 Bi 是公共的归一化常数，一般用全概率公式按同一完备事件组展开求和。由于它与 i 无关，只比较不同 Bi 的后验大小时也可只比较分子 P(Bi)P(A|Bi)。',5),
(60,'single','某病患病率 0.001，检测灵敏度 0.99、假阳性率 0.02。若同一人用同种方法独立复查一次仍呈阳性，则患病概率约为？',
 '[{"key":"A","text":"约 71%"},{"key":"B","text":"约 4.7%"},{"key":"C","text":"约 50%"},{"key":"D","text":"必然为 100%"}]',
 'A','两次独立阳性：分子 0.001×0.99² ≈ 0.00098，分母再加 0.999×0.02² ≈ 0.00040，后验 ≈ 0.00098/0.00138 ≈ 0.71。独立复查大幅提高可信度，但只要假阳性率不为 0，后验就永远达不到 100%。',5),
(60,'single','若事件 A、B 满足 P(A|B) = P(A)，则由贝叶斯公式可推出什么？',
 '[{"key":"A","text":"P(B|A) = P(B)，即 A 与 B 相互独立"},{"key":"B","text":"A 与 B 互斥"},{"key":"C","text":"P(B) = 0"},{"key":"D","text":"A 必然发生"}]',
 'A','把 P(A|B)=P(A) 代入得 P(B|A) = P(B)P(A)/P(A) = P(B)，说明 A 的发生不改变 B 的概率，正是独立性的含义。独立性说的是"信息不带来更新"，与互斥（A、B 不能同时发生）完全是两回事。',5),
(60,'single','全概率公式 P(A) 的正确展开形式是？',
 '[{"key":"A","text":"Σ P(Bi)P(A|Bi)，i 从 1 到 n"},{"key":"B","text":"Σ P(Bi)P(A)，i 从 1 到 n"},{"key":"C","text":"Σ P(A|Bi)，i 从 1 到 n"},{"key":"D","text":"Π P(Bi)P(A|Bi)（各项相乘）"}]',
 'A','全概率公式是"按原因加权平均"：每个原因 Bi 的概率乘以该原因下 A 发生的条件概率，再求和。B 会得到 P(A)（因 ΣP(Bi)=1），C 忽略了原因的权重，D 用了乘法——这些都是典型错写。',5),
(60,'judge','应用全概率公式时，各划分事件必须两两互斥且其并集为全集。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。互斥保证"各条路径不重叠"，并集为全集保证"没有遗漏任何路径"，两者缺一不可。若事件有重叠，ΣP(Bi)P(A|Bi) 会把交集部分重复计入，结果偏大。',5),
(60,'judge','条件概率 P(A|B) 与 P(B|A) 的数值总是相等，可以直接互换使用。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。二者一般不等，例如患病率 0.001 时 P(阳性|患病)=0.99，而 P(患病|阳性) 仅约 4.7%。把二者混同就是"检察官谬误"，贝叶斯公式的作用正是借助先验概率在两者之间正确转换。',5),
(60,'judge','在疾病检测中，即使检测的准确率极高，只要疾病的基础发病率很低，一个阳性结果对应的真实患病概率仍可能不高。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。后验概率同时受先验（发病率）与似然（准确率）共同影响：当发病率极低时，大量健康人的假阳性人数会淹没少数真阳性，使后验概率大幅下降。这也是筛查罕见病时强调"二次复检"的原因。',5),
(60,'judge','后验概率 P(B|A) 只由似然 P(A|B) 决定，与先验概率 P(B) 无关。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。贝叶斯公式的分子正是 P(B)P(A|B)，先验是必备因子。忽略先验、只凭似然下结论，就是基础比率忽视，会把罕见事件的概率严重高估。',5),
(60,'multi','关于全概率公式与贝叶斯公式，下列说法正确的有？',
 '[{"key":"A","text":"贝叶斯公式可由条件概率定义与全概率公式推导得到"},{"key":"B","text":"全概率公式是\\"由因求果\\"，贝叶斯公式是\\"执果索因\\""},{"key":"C","text":"使用贝叶斯公式要求各先验概率 P(Bi) 大于 0"},{"key":"D","text":"贝叶斯公式只适用于两个事件的情形"}]',
 'ABC','由 P(Bi|A) = P(Bi∩A)/P(A) 与 P(Bi∩A) = P(Bi)P(A|Bi) 即得贝叶斯公式，方向上是把"原因→结果"反过来用。D 错：它对有限个（n≥2）划分事件同样成立，只需对 i 求和或逐项计算。',8),
(60,'multi','要正确评估"检测呈阳性者真正患病"的概率，需要用到下列哪些量？',
 '[{"key":"A","text":"疾病在人群中的基础患病率"},{"key":"B","text":"灵敏度 P(阳性|患病)"},{"key":"C","text":"假阳性率 P(阳性|未患病)"},{"key":"D","text":"被检测者的身高与体重"}]',
 'ABC','三者分别提供先验、患者侧的似然和健康人侧的似然，缺任一项都无法完成贝叶斯计算。身高体重与检测机制无关，属无关信息；只给灵敏度和特异度而不给患病率，是题目无法求解的典型原因。',8),
(60,'multi','下列情形中，适合用全概率公式求 P(A) 的有？',
 '[{"key":"A","text":"A 的发生可分解为若干互斥原因 Bi 下的发生"},{"key":"B","text":"已知各 P(Bi) 以及相应的 P(A|Bi)"},{"key":"C","text":"已知 P(A) 要去反推 P(Bi|A)"},{"key":"D","text":"A 与所有 Bi 都相互独立"}]',
 'AB','全概率公式适用于"原因已知、求结果概率"的结构：存在完备事件组且已知各条件概率。C 属于执果索因，应使用贝叶斯公式；D 中若 A 与所有 Bi 独立，则 P(A|Bi)=P(A)，用全概率公式只是恒等验证，并无简化作用。',8),
(61,'single','切比雪夫大数定律要求随机变量序列满足的条件是？',
 '[{"key":"A","text":"两两不相关（或独立）且方差存在并有公共上界"},{"key":"B","text":"独立同分布"},{"key":"C","text":"必须服从同一正态分布"},{"key":"D","text":"方差必须趋于 0"}]',
 'A','切比雪夫大数定律只要求序列两两不相关（独立是不相关的充分条件）且方差一致有界，并不要求同分布。独立同分布且期望存在是辛钦大数定律的条件，二者不要张冠李戴。',5),
(61,'single','伯努利大数定律说明，在 n 次独立重复试验中事件 A 发生的频率 fn(A) 与概率 p 的关系是？',
 '[{"key":"A","text":"fn(A) 依概率收敛于 p"},{"key":"B","text":"fn(A) 随 n 增大单调地趋近 p"},{"key":"C","text":"n 足够大时 fn(A) 必然等于 p"},{"key":"D","text":"fn(A) 的方差等于 p"}]',
 'A','结论是依概率收敛：偏差超过任意给定 ε 的概率随 n 增大趋于 0。它不保证单调（频率可以忽上忽下），也不保证某次试验恰好相等；fn(A) 的方差为 p(1-p)/n，随 n 减小。',5),
(61,'single','辛钦大数定律要求随机变量序列满足什么条件？',
 '[{"key":"A","text":"独立同分布且数学期望存在"},{"key":"B","text":"独立同分布且方差存在"},{"key":"C","text":"只需两两不相关且方差有界"},{"key":"D","text":"必须服从正态分布"}]',
 'A','辛钦大数定律的特点是不要求方差存在，只要求独立同分布且期望 μ 有限，因此适用范围比切比雪夫大数定律在同分布情形下更宽。B 是更强的条件，C 是切比雪夫大数定律的条件。',5),
(61,'single','设随机变量 X 的方差为 1，用切比雪夫不等式估计 P(|X − E(X)| 大于等于 3) 的上界是？',
 '[{"key":"A","text":"1/9"},{"key":"B","text":"1/3"},{"key":"C","text":"1/6"},{"key":"D","text":"0.01"}]',
 'A','切比雪夫不等式给出 P(|X−E(X)| 大于等于 ε) 小于等于 D(X)/ε² = 1/9。注意它是"上界"而非精确值：若 X 服从正态分布，真实概率仅约 0.0027，远小于 1/9，这就是该不等式"宽松"的特点。',5),
(61,'single','切比雪夫不等式的一般形式为 P(|X − E(X)| 大于等于 ε) 小于等于？',
 '[{"key":"A","text":"D(X) 除以 ε 的平方"},{"key":"B","text":"D(X) 除以 ε"},{"key":"C","text":"ε 的平方 除以 D(X)"},{"key":"D","text":"D(X) 乘 ε"}]',
 'A','由马尔可夫不等式作用于 (X−E(X))² 即得 P 小于等于 D(X)/ε²。分母是 ε²（与方差同量纲），写成 ε 会得到量纲错误的结论；该不等式对任意分布成立，是证明大数定律的基本工具。',5),
(61,'single','掷一枚均匀硬币 10000 次，用切比雪夫不等式估计"正面频率与 0.5 的偏差不小于 0.05"的概率上界为？',
 '[{"key":"A","text":"0.01"},{"key":"B","text":"0.05"},{"key":"C","text":"0.0025"},{"key":"D","text":"0.25"}]',
 'A','频率的方差为 p(1-p)/n = 0.25/10000 = 0.000025，故上界为 0.000025/0.05² = 0.000025/0.0025 = 0.01。可见次数越多上界越小，这正是频率稳定性的定量表达。',5),
(61,'single','随机变量序列 Xn 依概率收敛于 X 的定义是？',
 '[{"key":"A","text":"对任意 ε 大于 0，当 n 趋于无穷时 P(|Xn − X| 大于等于 ε) 趋于 0"},{"key":"B","text":"Xn 的期望趋于 X 的期望"},{"key":"C","text":"Xn 的方差趋于 0"},{"key":"D","text":"存在 N 使得 n 大于 N 后 Xn 恒等于 X"}]',
 'A','依概率收敛只要求"偏离超过 ε 的概率趋于 0"，并不要求期望收敛，也不要求从某项起恒等（那是几乎必然更强的性质）。方差趋于 0 只是充分条件之一，不能作为定义。',5),
(61,'single','马尔可夫大数定律成立的判别条件是？',
 '[{"key":"A","text":"(1/n²) 乘以 D(X1 加到 Xn) 趋于 0"},{"key":"B","text":"各 Xi 同分布"},{"key":"C","text":"各 Xi 服从正态分布"},{"key":"D","text":"每个 D(Xi) 都趋于 0"}]',
 'A','对互不相关的序列，只要和的方差增长慢于 n²（即 (1/n²)D(ΣXi) 趋于 0），均值就依概率收敛于期望均值。当方差一致有界时该条件自动满足，从而推出切比雪夫大数定律。',5),
(61,'single','所谓"频率稳定性"，其准确含义是？',
 '[{"key":"A","text":"大量重复试验中频率在概率附近作小幅摆动，且试验次数越多摆幅越小"},{"key":"B","text":"频率随试验次数增大单调趋于概率"},{"key":"C","text":"少量试验中频率必定接近概率"},{"key":"D","text":"频率的极限等于概率的平方"}]',
 'A','稳定性指"围绕概率的波动随 n 增大而变小"（标准误为根号下 p(1-p)/n），不是单调逼近，更不保证小样本下接近。把稳定性理解成"下次一定反过来补偿"就是赌徒谬误。',5),
(61,'single','若 Xn 依概率收敛于常数 c，则对任意 ε 大于 0，n 趋于无穷时 P(|Xn − c| 小于 ε) 趋于？',
 '[{"key":"A","text":"1"},{"key":"B","text":"0"},{"key":"C","text":"0.5"},{"key":"D","text":"c"}]',
 'A','依概率收敛的定义等价于对立事件概率 P(|Xn−c| 大于等于 ε) 趋于 0，故 P(|Xn−c| 小于 ε) 趋于 1。它不表示 Xn 一定等于 c，也不涉及具体的收敛速度。',5),
(61,'judge','大数定律说明随着试验次数增加，频率与概率的偏差会单调地越来越小。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。大数定律给出的是依概率收敛，即"大偏差出现的概率越来越小"，并不排除某些时刻偏差反而变大（例如连续开出多次正面）。把依概率收敛理解成单调逼近是常见误读。',5),
(61,'judge','切比雪夫不等式只要求随机变量的方差存在，对分布的具体形式没有任何要求。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。这正是它被称为"弱条件、强通用"的原因：无论是离散还是连续、对称还是严重偏斜都成立。代价是给出的上界通常很宽松，只适合做定性证明（如大数定律），不适合精确计算概率。',5),
(61,'judge','辛钦大数定律不要求方差存在，只要求数学期望存在。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。辛钦大数定律的条件是独立同分布且 E(X)=μ 存在，因此在方差发散（如某些重尾分布）时仍可使用。这也是它比"用切比雪夫不等式证明"的版本适用范围更广的原因。',5),
(61,'judge','大数定律保证当试验次数足够多时，事件发生的频率必然等于其概率。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。频率是随机变量，任何有限次试验中它都可能与概率有偏差，大数定律只保证偏差大的可能性越来越小。"必然等于"把随机性抹掉了，实际中掷 10000 次硬币正面恰好 5000 次反而是小概率事件。',5),
(61,'multi','关于大数定律，下列说法正确的有？',
 '[{"key":"A","text":"伯努利大数定律可看作切比雪夫大数定律的特例"},{"key":"B","text":"它刻画的是依概率收敛，而非必然相等"},{"key":"C","text":"它为\\"用频率估计概率、用样本均值估计期望\\"提供理论依据"},{"key":"D","text":"它说明样本均值精确等于总体均值"}]',
 'ABC','伯努利情形对应取值 0/1 的独立变量，方差 p(1-p) 有界，故可由切比雪夫大数定律推出。D 错：样本均值是估计量，一般并不精确等于 μ，只是随 n 增大依概率靠近。',8),
(61,'multi','关于切比雪夫不等式，下列说法正确的有？',
 '[{"key":"A","text":"只要求随机变量的方差存在"},{"key":"B","text":"给出的是概率上界，通常比真实概率大得多"},{"key":"C","text":"要求随机变量服从正态分布"},{"key":"D","text":"可用于证明切比雪夫大数定律"}]',
 'ABD','把不等式用在样本均值上，其方差为 σ²/n，代入即得均值偏离 μ 超过 ε 的概率小于等于 σ²/(nε²)，令 n 趋于无穷便证得大数定律。C 错：若已知正态，可直接查表得到远比它紧的界限。',8),
(61,'multi','关于依概率收敛，下列说法正确的有？',
 '[{"key":"A","text":"Xn 依概率收敛于 X 记作 Xn 依概率趋于 X"},{"key":"B","text":"若 Xn 依概率收敛于常数 c，则对任意 ε 大于 0 有 P(|Xn − c| 大于等于 ε) 趋于 0"},{"key":"C","text":"依概率收敛无需额外条件就能推出期望收敛"},{"key":"D","text":"大数定律中的收敛一般指依概率收敛"}]',
 'ABD','前两条正是定义的两种等价写法，大数定律（弱大数律）的表述即依概率收敛。C 错：依概率收敛不保证期望收敛，需要一致可积等额外条件，否则可能出现小概率的巨大取值主导期望的反例。',8),
(104,'single','设总体服从 N(μ, σ²) 且 σ² 已知，样本容量为 n，则 μ 的 95% 置信区间为？',
 '[{"key":"A","text":"X 拔 加减 1.96 乘 σ 除以根号 n"},{"key":"B","text":"X 拔 加减 1.96 乘 σ"},{"key":"C","text":"X 拔 加减 σ 除以根号 n"},{"key":"D","text":"μ 加减 1.96 乘 σ 除以根号 n"}]',
 'A','标准化后 (X 拔−μ)/(σ/根号 n) 服从 N(0,1)，双侧 95% 对应分位数 1.96，故区间为 X 拔 ± 1.96σ/根号 n。区间必须以样本统计量 X 拔 为中心（μ 未知，D 无法计算），忘除根号 n 是常见错误。',5),
(104,'single','矩估计法的基本思想是？',
 '[{"key":"A","text":"用样本矩替换相应的总体矩，再解出待估参数"},{"key":"B","text":"使似然函数取最大值"},{"key":"C","text":"使估计量的方差最小"},{"key":"D","text":"取样本中位数作为参数值"}]',
 'A','矩估计把总体矩（如 E(X)）表示为参数的函数，再用样本矩（如 X 拔）代入并解方程，例如对 U(0,θ) 由 X 拔 = θ/2 得 θ 的矩估计为 2 倍 X 拔。它不需知道分布的具体形式，但一般不保证无偏或最有效。',5),
(104,'single','设样本方差 S² = 1/(n−1) 乘以 Σ(Xi − X 拔)²，则它作为总体方差 σ² 的估计量是？',
 '[{"key":"A","text":"无偏估计"},{"key":"B","text":"有偏估计，偏差为 σ²/n"},{"key":"C","text":"极大似然估计"},{"key":"D","text":"相合但一定无效的估计"}]',
 'A','因为用 X 拔 代替真均值损失了 1 个自由度，Σ(Xi−X 拔)² 的期望为 (n−1)σ²，除以 n−1 后 E(S²)=σ²，故为无偏估计。若除以 n 则期望为 (n−1)σ²/n，会系统性地偏小。',5),
(104,'single','若用 1/n 乘以 Σ(Xi − X 拔)² 去估计总体方差 σ²，则该估计量的期望为？',
 '[{"key":"A","text":"(n−1)σ² 除以 n"},{"key":"B","text":"σ²"},{"key":"C","text":"(n+1)σ² 除以 n"},{"key":"D","text":"σ² 除以 (n−1)"}]',
 'A','由于 Σ(Xi−X 拔)² 的期望是 (n−1)σ²，再乘 1/n 得 (n−1)σ²/n，比 σ² 小 σ²/n，属于系统性低估。样本量很小时偏差显著，这正是标准差公式要除以 n−1 的原因。',5),
(104,'single','极大似然估计法的基本思想是？',
 '[{"key":"A","text":"选择使已观测到的这组样本出现可能性最大的参数值"},{"key":"B","text":"使估计量的方差达到最小"},{"key":"C","text":"让样本矩等于总体矩"},{"key":"D","text":"取样本的中位数"}]',
 'A','把样本的联合密度（或概率）看成参数的函数即似然函数，令其最大化（常取对数求导）即得估计。它需要已知分布形式；矩估计（C）则不需要，这是两者的主要区别。',5),
(104,'single','估计量的无偏性是指？',
 '[{"key":"A","text":"估计量的数学期望等于被估参数真值"},{"key":"B","text":"估计量依概率收敛于真值"},{"key":"C","text":"估计量的方差在所有估计中最小"},{"key":"D","text":"估计量的取值必定等于真值"}]',
 'A','无偏性定义为 E(θ 帽) = θ，指的是"反复抽样平均而言没有系统偏差"。B 是相合性，C 是有效性，D 不可能做到；无偏并不排除单次估计离真值很远。',5),
(104,'single','在两个都是无偏的估计量之间作取舍时，通常优先选择？',
 '[{"key":"A","text":"方差更小的那一个（更有效）"},{"key":"B","text":"计算更简便的那一个"},{"key":"C","text":"取值更大的那一个"},{"key":"D","text":"用到样本点更少的那一个"}]',
 'A','同为无偏时，方差越小说明估计值越集中在真值附近、精度越高，这一标准称为有效性。计算简便度是工程考量而非统计标准；用到样本点少一般只会损失信息、增大方差。',5),
(104,'single','置信水平 1−α 的正确含义是？',
 '[{"key":"A","text":"反复抽样构造的众多区间中，约有 100(1−α)% 的比例覆盖真值"},{"key":"B","text":"真值落在已算出的这个区间内的概率为 1−α"},{"key":"C","text":"估计量的误差不超过 α"},{"key":"D","text":"样本均值落在区间内的概率为 1−α"}]',
 'A','随机性来自区间本身（每次抽样得到不同区间），真值是固定常数，所以置信度描述的是"方法的长期覆盖率"。区间一旦算出就已确定，只能说它属于那 95% 的区间之一，不能再谈概率。',5),
(104,'single','其它条件不变，要使总体均值的置信区间长度缩短为原来的一半，样本容量应变为原来的？',
 '[{"key":"A","text":"4 倍"},{"key":"B","text":"2 倍"},{"key":"C","text":"根号 2 倍"},{"key":"D","text":"16 倍"}]',
 'A','区间长度正比于 1/根号 n，要减半必须让根号 n 翻倍，即 n 变为 4 倍。这说明靠增加样本量来压缩误差的代价是平方级的，样本量翻倍只能让区间缩短到约 0.707 倍。',5),
(104,'single','设总体 X 服从 (0, θ) 上的均匀分布，样本为 X1 到 Xn，则 θ 的矩估计量为？',
 '[{"key":"A","text":"2 倍的 X 拔"},{"key":"B","text":"X 拔"},{"key":"C","text":"样本最大值"},{"key":"D","text":"X 拔 的一半"}]',
 'A','总体一阶矩 E(X) = θ/2，令其等于样本均值 X 拔，解得 θ 帽 = 2 倍 X 拔。样本最大值是 θ 的极大似然估计（且偏小），容易与矩估计混淆，两者是不同的估计方法。',5),
(104,'judge','无偏估计量一定比有偏估计量更接近参数真值。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。无偏只保证期望等于真值，若方差很大，单次估计仍可能远离真值；相反，一个略有偏差但方差很小的估计量（如 ridge 类收缩估计）均方误差可能更小。评价估计好坏要看均方误差，而不只看偏差。',5),
(104,'judge','样本均值 X 拔 既是总体均值 μ 的无偏估计，也是相合（一致）估计。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。E(X 拔) = μ 说明无偏；由大数定律 X 拔 依概率收敛于 μ，且方差 σ²/n 随 n 增大趋于 0，故它还是相合估计。这也是实践中用样本均值估计总体均值的理论依据。',5),
(104,'judge','把置信水平由 95% 提高到 99%，同一组数据算出的置信区间会更窄。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。置信水平提高意味着要求更高的覆盖率，临界值由 1.96 增大到 2.576，区间反而更宽。精度与可靠度不可兼得：想同时提高置信度又缩短区间，只能增大样本量。',5),
(104,'judge','极大似然估计一定存在，并且一定唯一。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。似然函数可能无最大值（如对 U(0,θ) 需在边界取 max Xi 才存在）、可能有多个极大点，也可能在参数空间内部无解。存在性与唯一性都需针对具体模型验证。',5),
(104,'multi','关于点估计的评价标准，下列说法正确的有？',
 '[{"key":"A","text":"无偏性刻画估计量期望与真值的系统偏离"},{"key":"B","text":"有效性是在无偏估计中比较方差大小"},{"key":"C","text":"相合性要求估计量随样本量增大依概率收敛于真值"},{"key":"D","text":"无偏估计一定相合"}]',
 'ABC','三者分别对应偏差、精度与极限行为。D 错：无偏与相合互不蕴含，例如取"只用第一个观测 X1"估计 μ 是无偏的，但其方差恒为 σ² 不随 n 缩小，因而不相合。',8),
(104,'multi','关于置信区间，下列说法正确的有？',
 '[{"key":"A","text":"置信水平越高，区间通常越宽"},{"key":"B","text":"样本量越大，区间通常越窄"},{"key":"C","text":"总体方差越大，区间通常越宽"},{"key":"D","text":"区间算出后真值落在其中的概率就是 1−α"}]',
 'ABC','前三条可由区间半长 z 乘 σ/根号 n 直接读出：z 随置信水平增大、区间随 σ 增大、随 n 增大而变窄。D 是典型误解：真值固定、区间随机，覆盖率描述的是抽样过程而非某一个已实现的区间。',8),
(104,'multi','关于矩估计与极大似然估计，下列说法正确的有？',
 '[{"key":"A","text":"矩估计用样本矩替换总体矩，计算通常较简单"},{"key":"B","text":"极大似然估计需要事先知道总体的分布形式"},{"key":"C","text":"极大似然估计具有不变性：θ 帽 的函数就是对应参数函数 g(θ) 的极大似然估计"},{"key":"D","text":"矩估计一定比极大似然估计更有效"}]',
 'ABC','矩估计不依赖具体分布、只需矩存在；极大似然必须写出似然函数，故依赖分布假设，且具备函数变换下的不变性。D 错：矩估计通常效率较低（如正态总体中不如 MLE 有效），不存在"一定更有效"。',8),
(105,'single','假设检验中的第一类错误是指？',
 '[{"key":"A","text":"原假设 H0 为真却被拒绝（弃真）"},{"key":"B","text":"原假设 H0 为假却未被拒绝（取伪）"},{"key":"C","text":"备择假设为真却被拒绝"},{"key":"D","text":"样本量太小导致无法计算"}]',
 'A','第一类错误即"弃真"，其概率由显著性水平 α 控制；第二类错误是"取伪"，概率记为 β。记住口诀：H0 真而拒之为一类，H0 假而纳之为二类。',5),
(105,'single','假设检验中的第二类错误是指？',
 '[{"key":"A","text":"原假设 H0 不真却没有被拒绝（取伪）"},{"key":"B","text":"原假设 H0 为真却被拒绝"},{"key":"C","text":"拒绝了正确的备择假设"},{"key":"D","text":"把显著性水平设得太大"}]',
 'A','取伪概率 β 依赖真值与 H0 的差距、样本量以及 α；H0 越接近真值越难被发现，β 越大。检验的功效定义为 1−β，即能正确识别出 H0 为假的能力。',5),
(105,'single','显著性水平 α 的准确含义是？',
 '[{"key":"A","text":"在原假设为真时拒绝 H0 的概率上界"},{"key":"B","text":"原假设为真的概率"},{"key":"C","text":"备择假设为真的概率"},{"key":"D","text":"犯第二类错误的概率"}]',
 'A','α 是研究者事先设定的、能容忍的弃真风险，例如 α=0.05 表示 H0 为真时约有 5% 的概率落入拒绝域。它不是 H0 为真的概率（频率派视参数固定），那是 P 值常见的误解之一。',5),
(105,'single','在样本量固定时，把显著性水平 α 由 0.05 减小到 0.01，第二类错误概率 β 通常会？',
 '[{"key":"A","text":"增大"},{"key":"B","text":"减小"},{"key":"C","text":"保持不变"},{"key":"D","text":"变为 0"}]',
 'A','拒绝域缩小后更难拒绝 H0，于是弃真风险降低、取伪风险上升，二者在固定样本量下此消彼长。若想同时压低 α 与 β，唯一有效手段是增大样本量。',5),
(105,'single','假设检验中 P 值（p-value）的含义是？',
 '[{"key":"A","text":"在原假设成立的前提下，出现当前样本结果或更极端结果的概率"},{"key":"B","text":"原假设为真的概率"},{"key":"C","text":"备择假设为假的概率"},{"key":"D","text":"犯第二类错误的概率"}]',
 'A','P 值是条件概率 P(数据或更极端 | H0 成立)，越小说明数据在 H0 下越"反常"。它绝不是 H0 为真的概率：把 P(数据|H0) 当成 P(H0|数据) 正是最经典的统计误读。',5),
(105,'single','若计算得到 P 值 = 0.03，而事先设定 α = 0.05，则检验结论应为？',
 '[{"key":"A","text":"在 0.05 水平下拒绝 H0"},{"key":"B","text":"接受 H0"},{"key":"C","text":"把 α 改为 0.03 再重新检验"},{"key":"D","text":"样本量不足，无法判断"}]',
 'A','判别规则是 P 值小于等于 α 则拒绝 H0。α 必须在看数据之前设定，看到 P 值后再调 α（C）属于数据窥探，会破坏检验的错误率控制。',5),
(105,'single','要检验"新工艺是否改变了产品平均强度"，且不预设变大或变小的方向，应采用？',
 '[{"key":"A","text":"双侧检验"},{"key":"B","text":"左侧检验"},{"key":"C","text":"右侧检验"},{"key":"D","text":"无法检验"}]',
 'A','备择假设为 μ 不等于 μ0，两侧都有拒绝域，故用双侧检验；只有研究目的明确指向"提高"或"降低"时才用单侧。切忌看到数据后再改成单侧，那会人为抬高显著性。',5),
(105,'single','总体方差 σ² 已知时，检验 H0: μ = μ0 所用的检验统计量及其分布是？',
 '[{"key":"A","text":"U = (X 拔 − μ0) 除以 (σ 除以根号 n)，服从标准正态分布"},{"key":"B","text":"t = (X 拔 − μ0) 除以 (S 除以根号 n)，服从 t(n−1)"},{"key":"C","text":"卡方统计量，服从卡方(n)"},{"key":"D","text":"F 统计量，服从 F 分布"}]',
 'A','方差已知时标准化后精确服从 N(0,1)，称为 U 检验；σ 未知且用小样本时要用样本标准差 S 代替并改用 t 分布。卡方与 F 统计量分别用于检验方差与方差齐性。',5),
(105,'single','总体方差未知、样本量较小（如 n = 16）且总体近似正态时，检验 H0: μ = μ0 应使用？',
 '[{"key":"A","text":"t = (X 拔 − μ0) 除以 (S 除以根号 n)，自由度为 n−1"},{"key":"B","text":"U 检验，用 σ 代替 S"},{"key":"C","text":"直接用样本均值与 μ0 比较即可"},{"key":"D","text":"卡方检验"}]',
 'A','σ 未知时用 S 估计，标准化量的分布由正态变为 t(n−1)，其尾部更厚、临界值更大，检验更保守。若仍按正态临界值判断，会高估显著性、增大弃真风险。',5),
(105,'single','检验 H0: μ = 100 对 H1: μ > 100，已知 σ = 10，n = 25，样本均值 X 拔 = 104，取 α = 0.05（临界值 1.645），结论是？',
 '[{"key":"A","text":"拒绝 H0，认为平均指标显著高于 100"},{"key":"B","text":"不拒绝 H0"},{"key":"C","text":"接受 H0，证明 μ = 100"},{"key":"D","text":"需先增大样本量才能判断"}]',
 'A','U = (104−100)/(10/5) = 2 > 1.645，落入拒绝域。注意结论只能说"拒绝 H0"，不能说"接受并证明 H0"（C）；不拒绝也不等于证明 H0 成立。',5),
(105,'judge','假设检验中"不拒绝 H0"等价于"证明了 H0 为真"。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。检验的逻辑是反证：数据未提供足够证据时才不拒绝，这可能是因为 H0 真，也可能是样本量不足、检验功效低。正确表述是"在给定水平下没有充分证据拒绝 H0"。',5),
(105,'judge','显著性水平 α 就是原假设 H0 为真的概率。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。在频率派框架下 H0 要么真要么假，不是随机变量，谈不上概率；α 是 H0 为真时拒绝它的概率上界，二者完全不同。把 α 当成"H0 成立的可能性"会导致结论严重误读。',5),
(105,'judge','增大样本量可以在保持 α 不变的同时降低第二类错误概率 β，从而提高检验功效。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。样本量增大使标准误 σ/根号 n 缩小，检验统计量的分布更分散于备择假设一侧，真值与 H0 的差距更容易被识别，故 β 下降、功效 1−β 上升。这也是"样本量估算"的理论基础。',5),
(105,'judge','P 值越小，说明原假设为真的概率越小。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。P 值是在 H0 成立的假定下算出的 P(数据或更极端 | H0)，描述的是数据与 H0 的相容程度，而不是 H0 本身的概率。要谈"H0 为真的概率"必须引入先验，那是贝叶斯方法。',5),
(105,'multi','关于两类错误，下列说法正确的有？',
 '[{"key":"A","text":"α 是犯第一类错误的概率，即 H0 真而被拒绝"},{"key":"B","text":"β 是犯第二类错误的概率，即 H0 假而未被拒绝"},{"key":"C","text":"样本量固定时 α 与 β 一般此消彼长"},{"key":"D","text":"α 与 β 之和恒等于 1"}]',
 'ABC','α 由研究者设定，β 由真值、样本量与 α 共同决定，固定样本量下减小一个必然放大另一个。D 错：二者并无互补关系，α+β=1 是凭直觉编造的恒等式。',8),
(105,'multi','关于 P 值与显著性水平，下列说法正确的有？',
 '[{"key":"A","text":"P 值小于等于 α 时，在水平 α 下拒绝 H0"},{"key":"B","text":"P 值是在 H0 成立下出现当前结果或更极端结果的概率"},{"key":"C","text":"P 值表示 H0 为真的概率"},{"key":"D","text":"α 应在分析数据之前由研究者事先确定"}]',
 'ABD','P 值提供了"在 H0 下数据有多极端"的度量，与预先设定的 α 比较后作出决策；事先固定 α 才能控制长期错误率。C 是最常见的误读，正确说法是"若 H0 为真，则看到这样数据的概率为 P 值"。',8),
(105,'multi','建立假设检验时，下列说法正确的有？',
 '[{"key":"A","text":"等号（如 μ = μ0）通常写在原假设 H0 中"},{"key":"B","text":"拒绝域由显著性水平与检验统计量的分布共同确定"},{"key":"C","text":"检验功效等于 1 − β，即 H0 为假时正确拒绝的概率"},{"key":"D","text":"备择假设通常写成 μ = μ1 的形式"}]',
 'ABC','H0 必须含有等号才能确定检验统计量的分布（在边界处取分布），拒绝域由 α 与该分布的分位数给出，功效即正确拒绝的概率。D 错：备择假设一般用不等于、大于或小于表示，写成等式会与 H0 的设定方式冲突。',8);

-- ---------- rest-py.js ----------
INSERT INTO question (knowledge_id, type, title, options, answer, analysis, score) VALUES
(81,'single','执行 a = [1, 2, 3, 4, 5]; print(a[1:-2]) 的输出是？',
 '[{"key":"A","text":"[2, 3]"},{"key":"B","text":"[2, 3, 4]"},{"key":"C","text":"[1, 2, 3]"},{"key":"D","text":"[3, 4]"}]',
 'A','负索引 -2 等价于 len(a)-2 = 3，切片 [1:3] 只取下标 1、2，即 2 和 3，右端点不含。常见误区有两个：一是把 -2 当成「倒数第 2 个也要算进去」，二是以为负索引不能与正索引用在同一个切片里。',5),
(81,'single','a = [1, 2, 3] 上分别执行 a.append([4, 5]) 与 a.extend([4, 5])，得到的列表分别是？',
 '[{"key":"A","text":"[1, 2, 3, [4, 5]] 与 [1, 2, 3, 4, 5]"},{"key":"B","text":"[1, 2, 3, 4, 5] 与 [1, 2, 3, [4, 5]]"},{"key":"C","text":"两者都得到 [1, 2, 3, [4, 5]]"},{"key":"D","text":"两者都得到 [1, 2, 3, 4, 5]"}]',
 'A','append 把参数当作一个整体元素追加，列表长度只加 1 且第 4 个元素是子列表；extend 迭代参数并把其中每个元素逐个追加，长度加 2。想合并两个列表要用 extend、+= 或 +，误用 append 会造成嵌套。',5),
(81,'single','a = [0, 1, 2, 3, 4, 5]; a[1:4] = ["x"]; print(len(a), a[1]) 的输出是？',
 '[{"key":"A","text":"4 x"},{"key":"B","text":"6 x"},{"key":"C","text":"4 1"},{"key":"D","text":"3 x"}]',
 'A','切片赋值先用右侧序列替换掉 [1:4) 这 3 个元素，再接上原表剩余部分，所以长度由 6 变成 4，下标 1 处变成 "x"。注意右侧若写成字符串 "x"，它会被当作可迭代对象逐字符展开成三个元素。',5),
(81,'single','执行 a = [3, 1, 2]; b = a.sort(); c = sorted(a) 之后，b 与 c 分别是？',
 '[{"key":"A","text":"None 与 [1, 2, 3]"},{"key":"B","text":"[1, 2, 3] 与 [1, 2, 3]"},{"key":"C","text":"[1, 2, 3] 与 None"},{"key":"D","text":"None 与 None"}]',
 'A','list.sort() 原地排序并返回 None（Python 刻意如此，提醒调用者别把它当表达式用）；sorted() 不改动原对象，返回一个新的已排序列表。写 b = a.sort() 得到 None 是最常见的新手坑。',5),
(81,'single','a = [[1, 2], [3, 4]]; b = a[:]; b[0].append(9); b.append([7, 8])，此时 a 的值是？',
 '[{"key":"A","text":"[[1, 2, 9], [3, 4]]"},{"key":"B","text":"[[1, 2], [3, 4]]"},{"key":"C","text":"[[1, 2, 9], [3, 4], [7, 8]]"},{"key":"D","text":"[[1, 2], [3, 4], [7, 8]]"}]',
 'A','切片是浅拷贝：只复制了外层容器，内层列表仍是同一批对象，所以 b[0].append 会改动 a[0]；而 b.append 只改外层容器本身，a 不受影响。需要完全独立时用 copy.deepcopy。',5),
(81,'single','用 m = [[0] * 3] * 3 创建 3 行 3 列矩阵后执行 m[0][0] = 1，结果是？',
 '[{"key":"A","text":"三行的第 0 列都变成 1"},{"key":"B","text":"只有第 0 行第 0 列变成 1"},{"key":"C","text":"抛出 IndexError"},{"key":"D","text":"第 0 行整行都变成 1"}]',
 'A','外层的 * 3 只是把同一个内层列表的引用复制了 3 份，三行指向同一个对象，改任意一行都会波及另外两行。正确写法是 [[0] * 3 for _ in range(3)]，每次循环新建一行。注意 [0] * 3 本身安全，因为数字不可变。',5),
(81,'single','表达式 [x * 2 for x in range(5) if x % 2] 的结果是？',
 '[{"key":"A","text":"[2, 6]"},{"key":"B","text":"[0, 2, 4, 6, 8]"},{"key":"C","text":"[0, 4, 8]"},{"key":"D","text":"[1, 3]"}]',
 'A','写在 for 之后的 if 是过滤条件，只保留 x % 2 为真的元素（即 1 和 3），再各自乘 2 得 [2, 6]。若把 if 写在 for 之前，则变成三元表达式，必须配 else，且每个元素都会产出一项。',5),
(81,'single','表达式 [y for x in [[1, 2], [3, 4]] for y in x] 的结果是？',
 '[{"key":"A","text":"[1, 2, 3, 4]"},{"key":"B","text":"[[1, 2], [3, 4]]"},{"key":"C","text":"[[1, 3], [2, 4]]"},{"key":"D","text":"[1, 3, 2, 4]"}]',
 'A','多个 for 从左到右构成嵌套关系，等价于先遍历每个子列表再遍历其元素，起到展平一层的作用。若想保持二维结构，应写成 [[y for y in x] for x in 外层]，括号的嵌套位置决定结果结构。',5),
(81,'single','a = [1, 2, 3, 4, 5]; print(a[::-2]) 的输出是？',
 '[{"key":"A","text":"[5, 3, 1]"},{"key":"B","text":"[1, 3, 5]"},{"key":"C","text":"[4, 2]"},{"key":"D","text":"[5, 4, 3, 2, 1]"}]',
 'A','步长为负表示从右往左取：起点缺省为最右端下标 4，每次减 2，依次取 4、2、0，得 [5, 3, 1]。误区是以为负步长只是「把结果再倒过来一遍」，从而误选 [1, 3, 5]。',5),
(81,'judge','判断下列说法是否正确：对列表 a 执行 a[10] 会抛出 IndexError，而执行 a[10:] 只会得到空列表，不会报错。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。单个下标访问越界立即抛 IndexError；切片则先把下标夹紧到合法范围，越界部分被忽略，结果可能为空列表。正因如此 a[:] 能安全复制、a[5:] 能安全取尾部。',5),
(81,'judge','判断下列说法是否正确：列表的 += 与加号赋值在语义上完全等价，两者都会生成新的列表对象。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。a += b 走 __iadd__，对 list 是原地扩展，a 的身份（id）不变，其它引用同一对象的变量也会看到变化；a = a + b 才先生成新列表再重新绑定名字。对 tuple 这种不可变对象，+= 才会新建对象。',5),
(81,'judge','判断下列说法是否正确：在 for 循环中按条件调用 list.remove() 删除元素会漏删，因为删除后元素左移而循环下标继续递增。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。删掉下标 i 后其后的元素整体左移，而迭代器仍前进到 i+1，原来位于 i+1 的元素被跳过。安全做法是遍历副本（for x in a[:]）、用推导式重建，或用 while 手动控制下标。',5),
(81,'judge','判断下列说法是否正确：list.remove(x) 会删除列表中所有等于 x 的元素。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。remove 只删第一个匹配的元素，一个都没找到时抛 ValueError。要删除全部需用循环配合 while，或用推导式过滤重建；按位置删除则用 pop(i) 或 del a[i]。',5),
(81,'multi','下列哪些写法会把原列表原地清空（其它引用同一对象的变量也会看到空列表）？',
 '[{"key":"A","text":"a.clear()"},{"key":"B","text":"a[:] = []"},{"key":"C","text":"del a[:]"},{"key":"D","text":"a = []"},{"key":"E","text":"a = list()"}]',
 'ABC','clear()、a[:] = [] 与 del a[:] 都是对原对象做原地修改，任何指向同一列表的变量都会一起变空；而 a = [] 与 a = list() 只是把名字重新绑定到一个新列表，原对象及其其它引用不受影响。',8),
(81,'multi','关于列表推导式与生成器表达式，下列说法正确的有？',
 '[{"key":"A","text":"把外层的方括号换成圆括号就变成生成器表达式，改为惰性求值"},{"key":"B","text":"Python 3 中推导式有独立作用域，循环变量不会泄漏到外部"},{"key":"C","text":"推导式中可以出现多个 for 与多个 if"},{"key":"D","text":"推导式内部不能再嵌套其它推导式"},{"key":"E","text":"推导式的执行速度通常快于等价的 for 加 append 写法"}]',
 'ABCE','Python 3 为推导式建立了独立作用域，循环变量不会像 Python 2 那样污染外部；它支持多个 for 和多个 if；把 [] 换成 () 得到生成器表达式，惰性产出且只能遍历一次；推导式可以任意嵌套，例如矩阵转置。CPython 把推导式编译成专门的 LIST_APPEND 指令，通常比手写 for 加 append 更快。',8),
(82,'single','定义 def f(x, lst=[]): lst.append(x); return lst，连续调用 f(1) 与 f(2) 的返回值分别是？',
 '[{"key":"A","text":"[1] 与 [1, 2]"},{"key":"B","text":"[1] 与 [2]"},{"key":"C","text":"[1, 2] 与 [1, 2]"},{"key":"D","text":"第二次调用抛出 TypeError"}]',
 'A','默认参数在函数定义时求值一次并保存在 __defaults__ 中，之后所有调用共用同一个列表对象，所以第二次调用时 lst 里已经有 1。正确写法是把默认值设为 None，在函数体内判断后再新建列表。',5),
(82,'single','定义 def f(a, *args, b, **kw)，调用 f(1, 2, b=3, c=4) 时 a、args、b、kw 分别是？',
 '[{"key":"A","text":"1、(2,)、3、{\\"c\\": 4}"},{"key":"B","text":"1、(2, 3)、None、{\\"c\\": 4}"},{"key":"C","text":"1、(2,)、3、{\\"b\\": 3, \\"c\\": 4}"},{"key":"D","text":"报错，因为 *args 之后不能再有参数"}]',
 'A','*args 收集多余的位置参数，写在它后面的 b 成为仅关键字参数，必须用名字传入；多余的键值对进 **kw。若调用时不写 b=3，会抛 TypeError 提示缺少必需的仅关键字参数。',5),
(82,'single','使用 @decorator 装饰一个函数时，装饰器函数本身在什么时候被调用？',
 '[{"key":"A","text":"在 def 语句执行时（模块加载阶段）立即调用一次"},{"key":"B","text":"每次调用被装饰的函数时调用"},{"key":"C","text":"第一次调用被装饰的函数时调用"},{"key":"D","text":"程序退出时才调用"}]',
 'A','@decorator 等价于 func = decorator(func)，这条赋值在 def 语句执行时就完成，因此装饰器只运行一次；此后被调用的是它返回的包装函数。误区是以为每次调用函数都会重新装饰一遍。',5),
(82,'single','编写装饰器时忘记使用 functools.wraps，最直接的后果是？',
 '[{"key":"A","text":"被装饰函数的 __name__、__doc__ 等元信息被包装函数覆盖"},{"key":"B","text":"装饰器失效，函数行为完全不变"},{"key":"C","text":"调用函数时抛出异常"},{"key":"D","text":"无法用 *args 接收任意参数"}]',
 'A','不加 wraps 时 wrapper 取代了原函数，help()、日志、按函数名注册路由的框架看到的都是 wrapper 及其文档。wraps 本质上把原函数的 __module__、__name__、__qualname__、__doc__、__dict__ 复制过来，并不影响调用行为。',5),
(82,'single','funcs = [lambda: i for i in range(3)]; print([f() for f in funcs]) 的输出是？',
 '[{"key":"A","text":"[2, 2, 2]"},{"key":"B","text":"[0, 1, 2]"},{"key":"C","text":"[0, 0, 0]"},{"key":"D","text":"抛出 NameError"}]',
 'A','lambda 体中的 i 是自由变量，调用时才去闭包里查找，而循环结束时 i 的值已是 2，所以三个函数都返回 2（闭包延迟绑定）。修正办法是写成 lambda i=i: i，用默认参数在定义时就把当前值绑定下来。',5),
(82,'single','函数中写 return 1, 2，实际返回的对象类型是？',
 '[{"key":"A","text":"tuple"},{"key":"B","text":"list"},{"key":"C","text":"两个相互独立的返回值"},{"key":"D","text":"生成器"}]',
 'A','逗号构成的是元组，return 1, 2 返回一个 tuple，所谓多返回值其实是元组打包，调用处用 a, b = f() 解包。要返回列表必须显式写 return [1, 2]。',5),
(82,'single','要在内层函数中给外层函数的局部变量重新赋值，应使用哪个关键字？',
 '[{"key":"A","text":"nonlocal"},{"key":"B","text":"global"},{"key":"C","text":"不需要任何关键字"},{"key":"D","text":"static"}]',
 'A','global 声明的是模块层级的全局变量；nonlocal 用于在内层函数中绑定外层函数的局部变量。只读取不赋值时两者都不需要，但只要函数体内出现对该名字的赋值语句，Python 就会默认把它当局部变量，导致读值时报 UnboundLocalError。',5),
(82,'single','定义 def f(x, y): x += 1; y.append(1)，执行 a, b = 1, []; f(a, b) 后 a 与 b 分别是？',
 '[{"key":"A","text":"1 与 [1]"},{"key":"B","text":"2 与 [1]"},{"key":"C","text":"1 与 []"},{"key":"D","text":"2 与 []"}]',
 'A','Python 传的是对象引用：对不可变对象做 x += 1 会新建对象并重新绑定局部名，外部 a 不变；对可变对象调用 append 是原地修改，外部 b 随之改变。误区是以为 Python 对不同类型有值传递与引用传递两套规则。',5),
(82,'single','已有 def add(a, b, c)，调用 add(*[1, 2, 3]) 与 add(**{"a": 1, "b": 2, "c": 3}) 的效果是？',
 '[{"key":"A","text":"两者都正确，结果都是 6"},{"key":"B","text":"前者正确，后者报错"},{"key":"C","text":"后者正确，前者报错"},{"key":"D","text":"两者都会报错"}]',
 'A','单个 * 把序列解包成位置参数，** 把映射解包成关键字参数，键名必须与形参名一致。注意解包后不能对同一个形参既给位置值又给关键字值，否则抛 TypeError 提示重复赋值。',5),
(82,'judge','判断下列说法是否正确：装饰器的返回值必须是可调用对象，否则被装饰的名字之后无法被调用。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。@d 等价于 func = d(func)，此后该名字指向的就是 d 的返回值；若 d 返回 None 或普通对象，再调用就会抛「对象不可调用」的 TypeError。这也是装饰器内部必须定义并返回 wrapper 的原因。',5),
(82,'judge','判断下列说法是否正确：函数中用 *args 收集位置参数时，args 是一个列表，可以直接对它调用 append。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。*args 收集到的是 tuple（元组），不可变，没有 append 方法，需要修改时应先 list(args) 转换；**kw 收集到的才是 dict。',5),
(82,'judge','判断下列说法是否正确：Python 3 中的类型注解会在运行时检查参数类型，传入错误类型时解释器会拒绝调用。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。注解只是记录在 __annotations__ 中，供文档、IDE 与静态检查工具使用，运行时不做任何校验，传错类型照样执行。需要运行时校验要自己写 isinstance 判断，或借助 pydantic 之类的库。',5),
(82,'judge','判断下列说法是否正确：带参数的装饰器 @retry(times=3) 需要三层嵌套结构：外层接收参数、中层接收函数、内层完成包装调用。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。@retry(times=3) 会先调用 retry(times=3) 得到真正的装饰器，再用它包装下面的函数，因此比无参装饰器多一层。只写两层的话，第二层只能接收函数，拿不到 times 这个配置值。',5),
(82,'multi','关于函数默认参数，下列说法正确的有？',
 '[{"key":"A","text":"默认值在函数定义时求值一次并保存下来"},{"key":"B","text":"不应把默认值写成列表、字典、集合这类可变对象"},{"key":"C","text":"常见写法是把默认值设为 None，再在函数体内创建"},{"key":"D","text":"默认值写成 [] 时，每次调用都会得到新的空列表"},{"key":"E","text":"默认值可以引用同签名中靠前的形参"}]',
 'ABC','默认值在定义时求值一次并存入 __defaults__，用可变对象会让多次调用互相污染，所以标准写法是默认 None 再在函数体内新建。注意默认值表达式在定义时就要能求值，引用同签名的其它形参会直接抛 NameError。',8),
(82,'multi','下列做法中，能让被装饰函数保留原有元信息（__name__、__doc__）的有？',
 '[{"key":"A","text":"在 wrapper 上再加 @functools.wraps(func)"},{"key":"B","text":"在 wrapper 内手动赋值 wrapper.__name__ = func.__name__"},{"key":"C","text":"调用 functools.update_wrapper(wrapper, func)"},{"key":"D","text":"在 wrapper 中 return func(*args, **kwargs) 就会自动保留元信息"},{"key":"E","text":"把装饰器写成类并实现 __call__ 就会自动保留元信息"}]',
 'ABC','wraps 是 update_wrapper 的装饰器形式，两者都把 __module__、__name__、__qualname__、__doc__、__dict__ 复制到包装函数并设置 __wrapped__；手动赋值 __name__ 也有效，只是要复制的字段较多。仅仅正确转调原函数、或改用类实现装饰器，都不会自动搬运元信息。',8),
(83,'single','关于 __new__ 与 __init__，下列说法正确的是？',
 '[{"key":"A","text":"__new__ 负责创建并返回实例，__init__ 只做初始化且不返回值"},{"key":"B","text":"__init__ 负责创建实例"},{"key":"C","text":"两者都必须返回 self"},{"key":"D","text":"__new__ 在 __init__ 之后才被调用"}]',
 'A','__new__ 是静态方法，先被调用并返回一个实例；只有当返回值确属该类时，解释器才会接着调用 __init__ 做初始化。实现单例或继承不可变类型时要重写 __new__；__init__ 必须返回 None，返回其它值会抛 TypeError。',5),
(83,'single','类 A 中定义了 @classmethod 方法 cm(cls, x) 与 @staticmethod 方法 sm(x)，用实例 a 调用 a.cm(1) 与 a.sm(1) 时，第一个参数分别是什么？',
 '[{"key":"A","text":"cm 收到类 A 本身，sm 只收到 1"},{"key":"B","text":"两者都收到实例 a"},{"key":"C","text":"两者都只收到 1"},{"key":"D","text":"cm 收到实例 a，sm 收到类 A"}]',
 'A','classmethod 的第一个参数由解释器自动绑定为类对象（即使通过实例调用也是类），常用于工厂方法与继承多态；staticmethod 不做任何绑定，就是挂在类命名空间下的普通函数，参数原样传入。',5),
(83,'single','print(obj) 与在交互式环境中直接输入 obj 回车，分别调用的魔术方法是？',
 '[{"key":"A","text":"__str__ 与 __repr__"},{"key":"B","text":"__repr__ 与 __str__"},{"key":"C","text":"两者都调用 __str__"},{"key":"D","text":"两者都调用 __repr__"}]',
 'A','print() 与 str() 走 __str__，交互式回显与 repr() 走 __repr__。只定义 __repr__ 时 __str__ 会退化为调用它，反之则不成立。另外打印列表等容器时，元素显示用的是元素的 __repr__ 而非 __str__。',5),
(83,'single','在子类方法中写 super().__init__() 的作用是？',
 '[{"key":"A","text":"按 MRO 顺序调用下一个类的方法，而未必是直接父类"},{"key":"B","text":"调用 object 的 __init__"},{"key":"C","text":"调用本类的 __init__ 造成递归"},{"key":"D","text":"等价于 self.__class__.__init__(self)"}]',
 'A','Python 3 的无参 super() 等价于 super(当前类, self)，它按实例类型的 MRO 找到当前类之后的那个类，因此在多重继承与钻石继承中能正确协作并避免重复初始化。手写父类名调用会破坏 MRO，还可能在协作式多重继承中漏掉某些类。',5),
(83,'single','在类中定义 __slots__ = ("x", "y") 的主要作用是？',
 '[{"key":"A","text":"禁止实例生成 __dict__，限制可赋值的属性名并节省内存"},{"key":"B","text":"把属性变成外部不可访问的私有属性"},{"key":"C","text":"让属性自动变成只读"},{"key":"D","text":"自动为类创建 x、y 两个属性并初始化为 None"}]',
 'A','__slots__ 让解释器改用固定槽位存储指定名称的属性，实例不再生成 __dict__，能省内存并防止拼错属性名；但它不是访问控制（仍可读写），且子类若未声明 __slots__ 仍会生成 __dict__。',5),
(83,'single','用 @property 定义只读属性 radius 后，要让 obj.radius = 5 生效，必须？',
 '[{"key":"A","text":"再定义同名的 @radius.setter"},{"key":"B","text":"再定义 @radius.deleter"},{"key":"C","text":"把属性名改成下划线开头"},{"key":"D","text":"让类继承 object"}]',
 'A','@property 只生成 getter，直接赋值会抛 AttributeError（属性不可设置）；要可写必须再定义同名的 @x.setter，要支持 del 则定义 @x.deleter。这样做的好处是赋值时可以校验，而调用语法保持不变。',5),
(83,'single','自定义类中只重写了 __eq__ 而没有重写 __hash__，其实例会？',
 '[{"key":"A","text":"变成不可哈希，放进 set 或作 dict 键时抛 TypeError"},{"key":"B","text":"仍可哈希，哈希值按 id 计算"},{"key":"C","text":"解释器自动按 __eq__ 生成哈希"},{"key":"D","text":"无法被实例化"}]',
 'A','Python 3 中定义 __eq__ 会把 __hash__ 置为 None，实例因此不可哈希。原因是哈希契约要求相等的对象必须有相等的哈希值，而默认按 id 的哈希会破坏该契约。需要放进 set 时应同时实现 __hash__（如 hash((self.a, self.b))），并尽量让对象不可变。',5),
(83,'single','类中写 self.__x = 1 后，在类外部访问该属性的正确形式是？',
 '[{"key":"A","text":"obj._类名__x"},{"key":"B","text":"obj.__x"},{"key":"C","text":"obj.private__x"},{"key":"D","text":"完全无法访问"}]',
 'A','双下划线前缀会触发名称改写（name mangling），实际属性名变为 _类名__x，所以 obj.__x 会抛 AttributeError。改写的目的只是避免子类意外覆盖父类属性，并非强制私有；单下划线才是约定意义上的内部属性。',5),
(83,'single','一个类只定义了 __len__ 且返回 0，用 if obj: 判断时结果是？',
 '[{"key":"A","text":"False"},{"key":"B","text":"True，因为没有定义 __bool__"},{"key":"C","text":"抛出 TypeError"},{"key":"D","text":"取决于是否定义了 __eq__"}]',
 'A','真值测试先找 __bool__，未定义时退而求其次用 __len__：返回 0 视为假，非 0 视为真。两者都没定义时任何实例都为真。因此容器类只要实现 __len__，就能自然地用于 if 判断与 bool()。',5),
(83,'single','定义 class A: items = []，然后 a1, a2 = A(), A(); a1.items.append(1)，此时 a2.items 的值是？',
 '[{"key":"A","text":"[1]，因为类属性被所有实例共享"},{"key":"B","text":"[]，因为每个实例有独立副本"},{"key":"C","text":"None"},{"key":"D","text":"抛出 AttributeError"}]',
 'A','类体中定义的 items 属于类对象，实例通过属性查找链读到的是同一个列表，a1.items.append 原地修改了共享对象，所以 a2.items 也是 [1]。要每个实例独立，应在 __init__ 中写 self.items = []（赋值到 self 才会创建实例属性）。',5),
(83,'judge','判断下列说法是否正确：Python 3 中所有类都隐式继承 object，object 的 __eq__ 默认实现是比较对象身份，等价于 is。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。Python 3 的类统一继承 object，默认 __eq__ 走身份比较，所以不重写 __eq__ 时，两个字段完全相同的自定义对象并不相等；默认 __hash__ 也基于 id。',5),
(83,'judge','判断下列说法是否正确：通过实例访问方法时会先绑定到实例，因此 obj.m(1) 与 类.m(obj, 1) 的效果相同。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。函数是描述符，通过实例访问会触发 __get__ 返回绑定方法，self 自动绑定到 obj。反过来，若把普通函数赋给实例属性，它就不会再被自动绑定，调用时必须自己传 self。',5),
(83,'judge','判断下列说法是否正确：多重继承时属性查找遵循 MRO（C3 线性化）顺序，可通过 类名.__mro__ 查看。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。C3 线性化保证单调性：任何类的 MRO 中，父类都排在其所有子类之后。若继承关系无法线性化（如继承顺序自相矛盾），定义类时会直接抛 TypeError。',5),
(83,'judge','判断下列说法是否正确：__del__ 一定会在对象不再被引用时立即调用，因此适合用来关闭数据库连接。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。__del__ 的调用时机依赖垃圾回收与引用计数，解释器退出时甚至可能不执行，其中的异常也会被忽略。资源释放应使用上下文管理器（with）或 try/finally 以保证确定性。',5),
(83,'multi','要让自定义对象支持 obj[key] 取值、obj[key] = v 赋值与 del obj[key] 删除，需要实现哪些魔术方法？',
 '[{"key":"A","text":"__getitem__"},{"key":"B","text":"__setitem__"},{"key":"C","text":"__delitem__"},{"key":"D","text":"__contains__"},{"key":"E","text":"__iter__"}]',
 'ABC','__getitem__ 负责取值、__setitem__ 负责赋值、__delitem__ 负责删除，三者分别对应三种下标语法。__contains__ 服务于 in 运算符，__iter__ 服务于迭代，dict 子类还可实现 __missing__ 处理键缺失。',8),
(83,'multi','关于 Python 的继承与多态，下列说法正确的有？',
 '[{"key":"A","text":"子类可重写父类方法，super() 用于在子类中调用父类实现"},{"key":"B","text":"Python 支持多重继承，属性查找按 MRO 顺序"},{"key":"C","text":"isinstance 会考虑继承关系，而 type(x) is C 只判断精确类型"},{"key":"D","text":"双下划线私有属性提供强制访问控制，外部完全无法访问"},{"key":"E","text":"抽象基类应继承 abc.ABC 并用 @abstractmethod 标记抽象方法"}]',
 'ABCE','前三项与最后一项都是标准结论：继承重写与 super、MRO 查找、isinstance 与 type 的差别、abc 模块的抽象基类机制。双下划线只是名称改写为 _类名__x，仍可从外部访问，属于约定而非强制。',8),
(84,'single','要让自定义对象能被 for 循环遍历，必须实现的方法是？',
 '[{"key":"A","text":"__iter__ 返回迭代器，该迭代器再实现 __next__"},{"key":"B","text":"只需实现 __next__"},{"key":"C","text":"只需实现 __getitem__"},{"key":"D","text":"只需实现 __len__"}]',
 'A','可迭代对象实现 __iter__ 返回一个迭代器，迭代器自身实现 __iter__（返回 self）与 __next__，耗尽时抛 StopIteration。for 循环就是反复调用 next() 直到捕获 StopIteration 为止。',5),
(84,'single','g = (x for x in range(3)); a = list(g); b = list(g)，a 与 b 分别是？',
 '[{"key":"A","text":"[0, 1, 2] 与 []"},{"key":"B","text":"[0, 1, 2] 与 [0, 1, 2]"},{"key":"C","text":"[] 与 [0, 1, 2]"},{"key":"D","text":"第二次抛出 StopIteration"}]',
 'A','生成器是一次性的：第一次 list() 把它消耗完，第二次只能得到空列表（list 会静默捕获 StopIteration）。需要重复遍历就得重新创建生成器，或用 itertools.tee，或先物化成列表。',5),
(84,'single','调用一个含有 yield 的生成器函数时会发生什么？',
 '[{"key":"A","text":"立即返回生成器对象，函数体一句都不执行"},{"key":"B","text":"立即执行到第一个 yield 并返回产出的值"},{"key":"C","text":"像普通函数一样执行完毕后返回"},{"key":"D","text":"抛出 SyntaxError"}]',
 'A','yield 让函数变成生成器函数：调用只创建生成器对象，函数体在第一次 next() 时才开始执行，遇到 yield 暂停并保留局部变量，下次从暂停处继续。这正是生成器能惰性求值、节省内存的原因。',5),
(84,'single','对已经耗尽的迭代器继续调用 next(it) 会发生什么？',
 '[{"key":"A","text":"抛出 StopIteration 异常"},{"key":"B","text":"返回 None"},{"key":"C","text":"返回最后一个元素"},{"key":"D","text":"自动从头重新开始"}]',
 'A','StopIteration 是耗尽信号，for 循环会静默捕获；手写 next() 时可传默认值 next(it, default) 避免异常。生成器里 return 的值会挂在 StopIteration.value 上，普通循环拿不到，只有手动捕获或 yield from 才能取到。',5),
(84,'single','yield from 最主要的作用是？',
 '[{"key":"A","text":"把内层可迭代对象的元素逐个直接产出，并自动转发 send 与 throw"},{"key":"B","text":"等同于 yield 一个列表对象"},{"key":"C","text":"把生成器变成列表"},{"key":"D","text":"提前终止生成器"}]',
 'A','yield from it 在效果上类似 for x in it: yield x，但它还会自动转发 send()、throw() 与 close()，是编写协程与递归展平嵌套结构的标准写法。只写 yield it 会把整个对象作为一个值产出。',5),
(84,'single','enumerate(["a", "b"], start=1) 依次产出的内容是？',
 '[{"key":"A","text":"(1, \\"a\\") 与 (2, \\"b\\")"},{"key":"B","text":"(0, \\"a\\") 与 (1, \\"b\\")"},{"key":"C","text":"只有 \\"a\\" 与 \\"b\\""},{"key":"D","text":"[1, \\"a\\"] 与 [2, \\"b\\"]"}]',
 'A','enumerate 产出 (下标, 元素) 形式的二元组，start 默认为 0，这里显式设为 1 所以从 1 开始。它返回的是迭代器而非列表，需要列表时用 list() 物化；常用于既要下标又不想写 range(len(...)) 的场景。',5),
(84,'single','处理超大日志文件时用生成器逐行读取，相比 readlines() 一次性读入的主要优势是？',
 '[{"key":"A","text":"内存占用与文件大小无关，且可以边读边处理"},{"key":"B","text":"读取速度一定更快"},{"key":"C","text":"可以随机访问任意一行"},{"key":"D","text":"能自动纠正编码错误"}]',
 'A','生成器一次只保留一行，内存 O(1)，还能边读边处理、中途提前 break；代价是只能顺序访问一次、不能 len() 也不能随机取行。速度上未必更快，因为 I/O 次数与普通读取相同。',5),
(84,'single','在生成器函数内部手动 raise StopIteration，Python 3.7 及以后会？',
 '[{"key":"A","text":"被转换成 RuntimeError: generator raised StopIteration"},{"key":"B","text":"正常结束该生成器"},{"key":"C","text":"被静默忽略"},{"key":"D","text":"抛出 StopAsyncIteration"}]',
 'A','按 PEP 479，生成器内部逃逸出的 StopIteration 会被替换为 RuntimeError，以免与「正常耗尽」混淆而掩盖 bug。要提前结束生成器应直接 return，或让函数体自然执行完毕。',5),
(84,'single','能证明「列表是可迭代对象但不是迭代器」的一项是？',
 '[{"key":"A","text":"列表没有 __next__ 方法，须由 iter() 取得迭代器"},{"key":"B","text":"列表不能被 for 遍历"},{"key":"C","text":"列表没有 __len__ 方法"},{"key":"D","text":"列表不支持切片"}]',
 'A','可迭代对象实现 __iter__，迭代器还须实现 __next__ 并在耗尽时抛 StopIteration。list 每次 iter() 都返回一个全新的迭代器，所以能被反复遍历；而文件对象既是可迭代对象又是自身的迭代器，读完一次就空了。',5),
(84,'judge','判断下列说法是否正确：生成器表达式比等价的列表推导式更省内存，因为元素是在需要时才计算产出的。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。列表推导式一次性构造完整列表，内存 O(n)；生成器表达式只保存计算状态，产出一个就丢弃一个，内存 O(1)。代价是只能用一次、不能 len() 也不能按下标访问。',5),
(84,'judge','判断下列说法是否正确：对生成器调用 close() 之后，再调用 next() 会抛出 StopIteration。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。close() 会在生成器暂停处抛出 GeneratorExit 使其终止，此后生成器处于已关闭状态，再次 next() 抛 StopIteration。生成器内的 finally 块可用于在关闭时释放资源。',5),
(84,'judge','判断下列说法是否正确：iter(callable, sentinel) 这种双参数形式会不断调用 callable 直到返回哨兵值为止，常用于按固定大小分块读文件。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。iter(f, sentinel) 每次调用 f() 并产出结果，一旦结果等于哨兵值就停止（哨兵值本身不产出）。典型用法是 iter(lambda: f.read(4096), "") 逐块读取文件，比手写 while 循环更简洁。',5),
(84,'judge','判断下列说法是否正确：生成器函数在 yield 处暂停后，其局部变量会被销毁，下次继续执行时重新初始化。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。生成器暂停时保留整个栈帧，局部变量的值与执行位置都被原样保存，下一次 next() 从 yield 之后继续，变量仍是上次的值。正因如此，生成器才能用来实现协程与状态机。',5),
(84,'multi','下列哪些对象本身既是可迭代对象又是自己的迭代器（即 iter(x) is x 成立）？',
 '[{"key":"A","text":"生成器对象"},{"key":"B","text":"open() 返回的文件对象"},{"key":"C","text":"iter(list) 的返回值"},{"key":"D","text":"列表 list"},{"key":"E","text":"zip() 的返回值"}]',
 'ABCE','生成器、文件对象、zip/map/filter 返回的惰性对象以及 iter() 产生的迭代器都满足 iter(x) is x，遍历一次即耗尽；列表、字符串、字典这类容器每次 iter() 都新建迭代器，所以能被反复遍历。',8),
(84,'multi','关于生成器的 send() 方法，下列说法正确的有？',
 '[{"key":"A","text":"send(v) 会把 v 作为当前 yield 表达式的值，并推进到下一个 yield"},{"key":"B","text":"首次启动生成器必须先 send(None) 或使用 next()"},{"key":"C","text":"生成器被唤醒后若不再 yield，则抛出 StopIteration"},{"key":"D","text":"send 可以给生成器内的任意局部变量赋值"},{"key":"E","text":"send 会让生成器从头重新执行"}]',
 'ABC','yield 是表达式，send(v) 使 (yield) 求值为 v 并把生成器推进到下一个 yield；刚创建的生成器还停在函数开头、没有可接收的 yield，所以第一次只能 send(None)。若推进后函数结束则抛 StopIteration。send 只能改变 yield 表达式的值，不能随意给局部变量赋值。',8),
(85,'single','int("abc") 与 1 / 0 分别抛出的异常类型是？',
 '[{"key":"A","text":"ValueError 与 ZeroDivisionError"},{"key":"B","text":"TypeError 与 ValueError"},{"key":"C","text":"ValueError 与 ArithmeticError"},{"key":"D","text":"KeyError 与 ZeroDivisionError"}]',
 'A','int() 可以接收字符串参数，只是内容不合法，属于 ValueError（类型对、值不对）；类型本身不对（如 int([1])）才是 TypeError。除零抛 ZeroDivisionError，它虽是 ArithmeticError 的子类，但捕获时应写最具体的类型。',5),
(85,'single','多个 except 子句并存时，排列顺序应遵循什么原则？',
 '[{"key":"A","text":"子类在前、父类在后"},{"key":"B","text":"父类在前、子类在后"},{"key":"C","text":"按异常名首字母排序"},{"key":"D","text":"顺序无关紧要"}]',
 'A','匹配时自上而下取第一个 isinstance 命中的分支；若把 Exception 写在前面，后面的具体异常永远轮不到。正确做法是先写具体异常，最后用 Exception 兜底记录日志。',5),
(85,'single','try/except/else/finally 结构中，else 块执行的条件是？',
 '[{"key":"A","text":"try 块没有抛出任何异常时才执行"},{"key":"B","text":"无论是否发生异常都执行"},{"key":"C","text":"捕获到异常时执行"},{"key":"D","text":"仅在 finally 之后执行"}]',
 'A','else 只在 try 顺利结束时执行，适合放「成功后才做的事」，从而把可能出错的代码范围缩到最小；finally 则无论异常、return 还是 break 都会执行，用于释放资源。',5),
(85,'single','函数中 try 块里写 return 1，finally 块里写 return 2，调用该函数的返回值是？',
 '[{"key":"A","text":"2，finally 的 return 覆盖了前者"},{"key":"B","text":"1"},{"key":"C","text":"抛出 SyntaxError"},{"key":"D","text":"返回元组 (1, 2)"}]',
 'A','finally 中的 return 会丢弃此前待返回的值，还会吞掉尚未处理的异常，是严重的代码坏味道。应坚决避免在 finally 里写 return 或 raise。',5),
(85,'single','自定义类要支持 with 语句，必须实现的方法是？',
 '[{"key":"A","text":"__enter__ 与 __exit__"},{"key":"B","text":"__enter__ 与 __close__"},{"key":"C","text":"__open__ 与 __close__"},{"key":"D","text":"__with__"}]',
 'A','__enter__ 的返回值绑定到 as 后的变量；__exit__ 接收异常类型、异常值与回溯三元组，返回 True 表示异常已处理（不再向外传播），返回 False 或 None 则继续抛出。with 保证两者在异常路径下也会被调用。',5),
(85,'single','用 @contextlib.contextmanager 编写上下文管理器时，yield 的位置代表什么？',
 '[{"key":"A","text":"yield 之前相当于 __enter__，之后相当于 __exit__"},{"key":"B","text":"yield 处暂停并抛出异常"},{"key":"C","text":"yield 用于产出资源供外部重复获取"},{"key":"D","text":"yield 表示资源已经释放"}]',
 'A','该装饰器把生成器函数转成上下文管理器：yield 之前做准备工作，yield 的值交给 as 变量，yield 之后做清理。若 with 体内抛异常，装饰器会把异常 throw 到 yield 处，所以清理逻辑必须用 try/finally 包裹才能保证执行。',5),
(85,'single','在 except 块中写 raise NewError() from e 的作用是？',
 '[{"key":"A","text":"抛出新异常并保留原异常作为 __cause__，形成异常链"},{"key":"B","text":"同时抛出两个互不相关的异常"},{"key":"C","text":"先抛原异常再抛新异常"},{"key":"D","text":"彻底抑制原异常"}]',
 'A','from e 会把原异常设为新异常的 __cause__，回溯信息中会显示直接的因果链，便于定位根因。只想抛出新异常、不显示上下文时用 raise NewError() from None；在 except 中裸写 raise 则是原样重新抛出当前异常并保留原始回溯。',5),
(85,'single','自定义业务异常类时，推荐的做法是？',
 '[{"key":"A","text":"继承 Exception 或其合适的子类，不要继承 BaseException"},{"key":"B","text":"直接继承 BaseException"},{"key":"C","text":"继承 object 即可"},{"key":"D","text":"必须继承 RuntimeError 且强制传入参数"}]',
 'A','BaseException 还包含 SystemExit、KeyboardInterrupt 这类控制信号，若继承它，except Exception 就捕获不到，程序行为会很怪。业务异常应继承 Exception，必要时先定义一个项目基类再派生具体异常，方便调用方统一捕获。',5),
(85,'single','关于 assert 语句，下列说法正确的是？',
 '[{"key":"A","text":"使用 -O 选项运行时断言会被整体移除，因此不能用于校验用户输入"},{"key":"B","text":"assert 是处理运行时错误的推荐方式"},{"key":"C","text":"断言失败会抛出 ValueError"},{"key":"D","text":"断言总能执行，不受启动参数影响"}]',
 'A','assert 仅在内置变量 __debug__ 为真时生效，-O 会将其置假并跳过全部断言，所以不能用来做输入校验或权限检查（这类场景应显式 raise）。断言用于「内部不可能发生」的自检，失败抛 AssertionError。',5),
(85,'judge','判断下列说法是否正确：except 子句中用 as e 绑定的异常变量，在该子句结束后会被自动删除。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。Python 3 在 except 块结束时隐式执行 del e，若之后还要使用该异常对象，必须在块内另存到一个普通变量。这样设计是为了避免异常对象与其回溯形成引用环而迟迟不能回收。',5),
(85,'judge','判断下列说法是否正确：with 语句中 __exit__ 返回 True 时，with 体内抛出的异常会被抑制，程序继续往下执行。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。__exit__ 返回真值表示异常已被处理，解释器不再向外传播，contextlib.suppress 正是利用这一点。返回 False 或 None 则异常继续抛出；不建议无条件吞掉所有异常，否则会掩盖真实错误。',5),
(85,'judge','判断下列说法是否正确：try 块中发生未被任何 except 捕获的异常时，finally 块仍会执行，之后异常继续向外传播。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'A','正确。finally 的语义就是无论如何都执行，包括未捕获异常、return、break、continue 等情形；它执行完后异常照常向上抛，因此适合关闭文件、释放锁而不改变异常传播路径。',5),
(85,'judge','判断下列说法是否正确：捕获异常时写不带类型的裸 except: 是推荐写法，能确保程序绝不崩溃。',
 '[{"key":"A","text":"正确"},{"key":"B","text":"错误"}]',
 'B','错误。裸 except 会连 KeyboardInterrupt、SystemExit 一起捕获，掩盖真正的 bug 并让用户无法用 Ctrl+C 退出程序。应捕获具体的异常类型，最宽也只到 Exception，并记录日志或重新抛出。',5),
(85,'multi','下列哪些内置异常属于 LookupError 的子类？',
 '[{"key":"A","text":"IndexError"},{"key":"B","text":"KeyError"},{"key":"C","text":"ValueError"},{"key":"D","text":"TypeError"},{"key":"E","text":"ZeroDivisionError"}]',
 'AB','IndexError（下标越界）与 KeyError（字典键不存在）都继承自 LookupError，所以 except LookupError 能同时覆盖二者；ValueError 与 TypeError 是另外的分支，ZeroDivisionError 属于 ArithmeticError。',8),
(85,'multi','关于用 with 同时管理多个资源，下列说法正确的有？',
 '[{"key":"A","text":"可以写成 with open(a) as f1, open(b) as f2:"},{"key":"B","text":"Python 3.10 起可用圆括号把多个上下文管理器写成多行"},{"key":"C","text":"它等价于嵌套 with，若后者的 __enter__ 失败，已进入的资源仍会被正常关闭"},{"key":"D","text":"多个资源管理器的退出顺序与进入顺序相同"},{"key":"E","text":"with 只能管理实现了 __enter__ 的对象，生成器函数无法使用"}]',
 'ABC','逗号形式等价于嵌套 with；若后一个资源的 __enter__ 抛异常，前一个已获得的资源会先被关闭。退出顺序与进入顺序相反（后进先出）。用 @contextmanager 装饰的生成器函数同样是合法的上下文管理器，同样能用在 with 中。',8);
